    self.window_manager.finishWorkspaceActivationFromProtocol();
}

fn xdgActivationRequested(
    context: *anyopaque,
    surface_id: Surface.Id,
    proven_interaction: bool,
) void {
    const self: *Self = @ptrCast(@alignCast(context));
    if (!self.window_manager_initialized) return;
    const allow_focus = proven_interaction and !self.session_lock.isLocked();
    if (self.window_manager.activationRequested(surface_id, allow_focus)) {
        self.refreshKeyboardFocusReplacingGenerated();
        requestRepaint(self);
    }
}

fn sessionLockStateChanged(context: *anyopaque, locked: bool) void {
    const self: *Self = @ptrCast(@alignCast(context));
    if (!locked) self.session_lock_keyboard_focus = null;
    if (self.window_manager_initialized) self.window_manager.setSessionLocked(locked);
    if (locked) {
        finishAllWindowTransitions(self);
        finishAllWorkspaceTransitions(self);
    }
    self.refreshIdleInhibition();
    self.reconcileOutputCursors();
    if (locked) self.xwayland_keyboard_grab.cancelAll();
    if (self.window_manager_initialized and self.endCompositorPointerGrab(false)) {
        requestRepaint(self);
    }
    self.seat.setCompositorCursor(null);
    self.pointer_constraints.deactivateAll();
    self.data_device.cancelDrag();
    self.tablet.cancelFocus();
    self.cancelSeatTouches(&self.seat);
    self.seat.suppressPointerFocus(true);
    self.xdg_shell_core.dismissPopupGrab();
    if (locked) {
        self.virtual_keyboard.setInhibited(true);
        self.input_method.setInhibited(true);
        if (self.generated_input_method_observer) |observer| observer.set_inhibited(observer.context, true);
        _ = self.seat.applyMatureKeyboardFocus(null);
    } else {
        _ = self.seat.applyMatureKeyboardFocus(null);
        self.input_method.setInhibited(false);
        if (self.generated_input_method_observer) |observer| observer.set_inhibited(observer.context, false);
        self.virtual_keyboard.setInhibited(false);
        if (self.seat.pointerPosition()) |position| {
            const route = self.pointerRoute(position.x, position.y);
            self.seat.pointerEnter(position.x, position.y, route.focus);
            self.updateResizeCursor(route.root, position.x, position.y);
            self.pointer_constraints.syncFocus();
        }
    }
}

fn sessionLockRepaint(context: *anyopaque) void {
    const self: *Self = @ptrCast(@alignCast(context));
    self.reconcileGeneratedPointerTopology();
    requestRepaint(self);
}

fn sessionLockKeyboardFocus(self: *Self) ?Surface.Id {
    if (self.session_lock_keyboard_focus) |focus| {
        if (self.session_lock_core.ownsMappedSurface(focus)) return focus;
    }
    const focus = self.session_lock_core.firstMappedSurface();
    self.session_lock_keyboard_focus = focus;
    return focus;
}

fn sessionLockPointerPressed(self: *Self, surface: ?Surface.Id) void {
    const candidate = surface orelse return;
    const focus = self.headless_surface_forest.compoundRoot(candidate) orelse
        self.subcompositor.rootSurface(candidate);
    if (!self.session_lock_core.ownsMappedSurface(focus)) return;
    self.session_lock_keyboard_focus = focus;
    requestRepaint(self);
}

fn sessionLockClientDisconnected(context: *anyopaque, client: ClientRegistry.Id) void {
