    const output: *RenderOutput = @ptrCast(@alignCast(context));
    const self = output.server;
    const route = tabletAxesRoute(output, axes);
    self.observeIdleActivity(self.seatForDevice(device_id));
    self.tablet.button(
        device_id,
        tool_id,
        time,
        route.focus,
        route.axes,
        button,
        pressed,
    ) catch self.terminate();
}

