fn dataDeviceExternalDragStart(context: *anyopaque) ?NeutralDataDevice.ExternalDragStart {
    const self: *Self = @ptrCast(@alignCast(context));
    if (!self.seat.dataDeviceAuthority().hasPointerButtons()) return null;
    const focus = self.seat.maturePointerFocus() orelse return null;
    const client = self.seat.matureSurfaceOwner(focus.surface_id) orelse return null;
    const position = self.seat.pointerPosition() orelse return null;
    return .{
        .target = .{ .surface = focus.surface_id, .client = client, .x = focus.x, .y = focus.y },
        .global_x = position.x,
        .global_y = position.y,
    };
}

fn dataDeviceClientDisconnected(context: *anyopaque, client: ClientRegistry.Id) void {
    const data_device: *NeutralDataDevice = @ptrCast(@alignCast(context));
    data_device.clientDisconnected(client);
}

fn textInputClientDisconnected(context: *anyopaque, client: ClientRegistry.Id) void {
    const text_input: *NeutralTextInput = @ptrCast(@alignCast(context));
    text_input.clientDisconnected(client);
}

fn textInputKeyboardFocusChanged(context: *anyopaque, _: ?*wl.Client) void {
    const self: *Self = @ptrCast(@alignCast(context));
    if (self.seat.textInputFocus()) |focus| {
        self.neutral_text_input.setKeyboardFocus(focus.surface, focus.client) catch {
            self.neutral_text_input.setKeyboardFocus(null, null) catch unreachable;
        };
    } else self.neutral_text_input.setKeyboardFocus(null, null) catch unreachable;
}

fn dataDeviceDragChanged(context: *anyopaque) void {
    const self: *Self = @ptrCast(@alignCast(context));
    if (self.data_device.dragIsExternal()) {
        if (self.seat.maturePointerFocus()) |focus| {
            if (self.seat.matureSurfaceOwner(focus.surface_id)) |client| {
                if (self.seat.pointerPosition()) |position| self.data_device.setExternalPointerDelivery(.{
                    .surface = focus.surface_id,
                    .client = client,
                    .x = focus.x,
                    .y = focus.y,
                }, position.x, position.y);
            }
        }
    }
    self.mature_data_device.neutralDragChanged();
    requestRepaint(self);
}

fn generatedDragIconInfo(self: *Self) ?struct { surface_id: SurfaceRegistry.Id, x: i32, y: i32 } {
    if (self.mature_data_device.iconInfo() != null) return null;
    const icon = self.data_device.dragIcon() orelse return null;
    if (!self.headless_surface_forest.isDragIconRole(icon.surface)) return null;
    const position = self.seat.pointerPosition() orelse return null;
    return .{
        .surface_id = icon.surface,
        .x = capture_geometry.floorToI32(position.x + @as(f64, @floatFromInt(icon.offset_x))),
        .y = capture_geometry.floorToI32(position.y + @as(f64, @floatFromInt(icon.offset_y))),
    };
}

fn dragStarted(context: *anyopaque) void {
    const self: *Self = @ptrCast(@alignCast(context));
    if (self.endCompositorPointerGrab(false)) requestRepaint(self);
    self.seat.setCompositorCursor(null);
    self.pointer_constraints.deactivateAll();
    if (self.xwm_initialized) self.xwm.dragStarted();
    self.reconcileOutputCursors();
    self.seat.dissolvePointerGrab();
    const position = self.seat.pointerPosition() orelse return;
    const route = self.dragPointerRoute(position.x, position.y);
    if (!self.data_device.dragIsExternal()) self.seat.suppressPointerFocus(true);
    self.routeActiveDrag(0, route, position.x, position.y, false);
}

fn endCompositorPointerGrab(self: *Self, commit: bool) bool {
    const ended = self.window_manager.endCompositorPointerGrab(commit);
    if (ended) self.seat.setCompositorCursor(null);
    return ended;
}

fn updateResizeCursor(self: *Self, root: ?Surface.Id, x: f64, y: f64) void {
    if (!self.window_manager_initialized) {
        self.seat.setCompositorCursor(null);
        return;
    }
    const shape = self.window_manager.resizeCursorShapeAt(root, x, y) orelse {
        self.seat.setCompositorCursor(null);
        return;
    };
    self.seat.setCompositorCursor(self.cursor_shape.cursorImage(shape));
}

fn xdgToplevelDragBegin(
    context: *anyopaque,
    window_id: NeutralXdgShell.WindowId,
    pointer_x: f64,
    pointer_y: f64,
    x_offset: i32,
    y_offset: i32,
    use_offset_hint: bool,
) bool {
    const self: *Self = @ptrCast(@alignCast(context));
    return self.window_manager.beginToplevelDrag(
        window_id,
        pointer_x,
        pointer_y,
        x_offset,
        y_offset,
        use_offset_hint,
    );
}

fn xdgToplevelDragMotion(context: *anyopaque, x: f64, y: f64) void {
    const self: *Self = @ptrCast(@alignCast(context));
    self.window_manager.updateToplevelDrag(x, y);
}

fn xdgToplevelDragEnd(context: *anyopaque) void {
    const self: *Self = @ptrCast(@alignCast(context));
    self.window_manager.endToplevelDrag();
}

fn dragEnded(context: *anyopaque) void {
    const self: *Self = @ptrCast(@alignCast(context));
    if (self.xwm_initialized) self.xwm.physicalDragEnded();
    self.reconcileOutputCursors();
    self.restoreSeatPointerFocus(&self.seat);
}

fn restoreSeatPointerFocus(self: *Self, seat: *Seat) void {
    const position = seat.pointerPosition() orelse return;
    const route = self.pointerRoute(position.x, position.y);
    seat.pointerEnter(
        position.x,
        position.y,
        if (seat == &self.seat) route.focus else maturePointerFocus(route.focus),
    );
    if (seat != &self.seat or self.session_lock.isLocked()) return;
    if (!self.xdg_shell_core.hasPopupGrab()) {
        self.window_manager.pointerMoved(route.root);
        self.updateResizeCursor(route.root, position.x, position.y);
    }
    self.pointer_constraints.syncFocus();
}

fn dragExternalSourceDestroyed(context: *anyopaque, generation: u64) void {
    const self: *Self = @ptrCast(@alignCast(context));
    if (self.xwm_initialized) self.xwm.dragSourceDestroyed(generation);
}

fn routeActiveDrag(
    self: *Self,
    time: u32,
    route: PointerRoute,
    x: f64,
    y: f64,
    motion: bool,
) void {
    if (self.xwm_initialized) {
        if (self.data_device.dragIsExternal()) {
            if (route.root) |surface_id| if (self.xwaylandWindowForSurface(surface_id) != null) {
                self.data_device.leave();
                self.xwm.routeExternalDragOverXwayland(true);
                return;
            };
            self.xwm.routeExternalDragOverXwayland(false);
        } else {
            if (route.root) |surface_id| if (self.xwaylandWindowForSurface(surface_id)) |window_id| {
                self.data_device.leave();
                self.xwm.dragMotion(window_id, time, x, y);
                return;
            };
            self.xwm.dragLeft();
        }
    }
    const target: ?NeutralDataDevice.Target = if (route.generated) |focus|
        .{ .surface = focus.surface_id, .client = focus.client, .x = focus.x, .y = focus.y }
    else if (maturePointerFocus(route.focus)) |focus| mature: {
        const client = self.seat.matureSurfaceOwner(focus.surface_id) orelse break :mature null;
        break :mature .{ .surface = focus.surface_id, .client = client, .x = focus.x, .y = focus.y };
    } else null;
    if (target) |value| {
        self.data_device.enter(value) catch |err| switch (err) {
            error.OutOfMemory => {},
            else => {},
        };
        if (motion) self.data_device.motion(time, value.x, value.y);
    } else self.data_device.leave();
}

