fn touchDown(context: *anyopaque, time: u32, id: i32, x: f64, y: f64) void {
    const output: *RenderOutput = @ptrCast(@alignCast(context));
    const self = output.server;
    if (self.window_transitions.items.len != 0) {
        finishAllWindowTransitions(self);
        requestRepaint(self);
    }
    self.observeIdleActivity(&self.seat);
    const point = output.globalPoint(x, y);
    const route = self.pointerRoute(point.x, point.y);
    const focus = route.focus;
    const first_touch = !self.seat.touchSequenceActive();
    if (self.session_lock.isLocked()) {
        if (focus) |target| {
            self.sessionLockPointerPressed(self.subcompositor.rootSurface(target.surface_id));
        }
        self.seat.touchDown(time, id, point.x, point.y, focus) catch {
            log.err("failed to store touch point", .{});
            self.terminate();
        };
        return;
    }
    if (focus != null and focus.?.generated == null) {
        const target = focus.?;
        const root = self.subcompositor.rootSurface(target.surface_id);
        const replace_generated = self.seat.generatedKeyboardFocus() != null;
        self.window_manager.pointerButton(root, .pressed);
        self.layer_shell.pointerPressed(root);
        if (replace_generated) self.refreshKeyboardFocusReplacingGenerated();
        requestRepaint(self);
    } else if (route.generated) |generated| {
        self.window_manager.pointerButton(null, .pressed);
        self.layer_shell.pointerPressed(generated.root);
        if (first_touch and self.managedGeneratedPopup(generated.root) == null and
            !self.isGeneratedInputPopup(generated.root) and
            self.exactEligibleGeneratedLayerRoot(generated.root) == null)
            _ = self.focusGeneratedSurface(generated.root);
        requestRepaint(self);
    } else {
        self.window_manager.pointerButton(null, .pressed);
        if (self.xdg_shell_core.hasPopupGrab()) self.xdg_shell_core.dismissPopupGrab();
    }
    self.seat.touchDown(time, id, point.x, point.y, focus) catch {
        log.err("failed to store touch point", .{});
        self.terminate();
    };
}

fn touchUp(context: *anyopaque, time: u32, id: i32) void {
