fn removeXwaylandWindow(self: *Self, window_id: Xwm.WindowId) void {
    const removed = self.xwayland_windows.fetchRemove(window_id) orelse return;
    self.scene.removeWindow(removed.value.scene_id);
    syncXwaylandClientStacking(self);
    if (self.xwayland_override_redirect_focus) |current| {
        if (std.meta.eql(current, removed.value.surface_id)) {
            self.xwayland_override_redirect_focus = null;
            refreshKeyboardFocus(self);
        }
    }
}

fn xwaylandWindowForSurface(self: *Self, surface_id: Surface.Id) ?Xwm.WindowId {
    var windows = self.xwayland_windows.iterator();
    while (windows.next()) |entry| {
        if (std.meta.eql(entry.value_ptr.surface_id, surface_id)) return entry.key_ptr.*;
    }
    return null;
}

fn syncXwaylandFocus(self: *Self, surface_id: ?Surface.Id) void {
    if (!self.xwm_initialized) return;
    const target: ?Xwm.WindowId = if (surface_id) |surface| target: {
        var windows = self.xwayland_windows.iterator();
        while (windows.next()) |entry| {
            if (std.meta.eql(entry.value_ptr.surface_id, surface)) break :target entry.key_ptr.*;
        }
        break :target null;
    } else null;
    self.xwm.focusWindow(target) catch {
        log.err("failed to update X11 input focus", .{});
        self.terminate();
    };
}

fn captureImage(
    context: *anyopaque,
    target: ImageCopyCapture.Target,
    paint_cursors: bool,
    pixel_buffer: render.PixelBuffer,
) ImageCopyCapture.CaptureError!ImageCopyCapture.CaptureResult {
    const self: *Self = @ptrCast(@alignCast(context));
    const completion_fd = switch (target) {
        .source => |source| switch (source) {
            .output => |output_id| self.captureOutput(
                output_id,
                paint_cursors,
                pixel_buffer,
            ) catch return error.Failed,
            .toplevel => |window_id| toplevel: {
                if (self.session_lock.isLocked()) return error.Failed;
                break :toplevel self.captureToplevel(window_id, pixel_buffer) catch |err| switch (err) {
                    error.Stopped => return error.Stopped,
                    else => return error.Failed,
                };
            },
        },
        .cursor => |cursor| self.captureCursor(cursor, pixel_buffer) catch return error.Failed,
    };
    return .{
        .timestamp = presentation.Info.now(self.io).timestamp,
        .completion_fd = completion_fd,
    };
}

fn captureScreencopy(
    context: *anyopaque,
    target: Screencopy.Target,
    overlay_cursor: bool,
    pixel_buffer: render.PixelBuffer,
) Screencopy.CaptureError!Screencopy.CaptureResult {
    const self: *Self = @ptrCast(@alignCast(context));
    const completion_fd = self.captureOutputRegion(
        target.output,
        target.region,
        overlay_cursor,
        pixel_buffer,
    ) catch return error.Failed;
    return .{
        .timestamp = presentation.Info.now(self.io).timestamp,
        .completion_fd = completion_fd,
    };
}

fn captureImageDmabuf(
    context: *anyopaque,
    target: ImageCopyCapture.Target,
    paint_cursors: bool,
    buffer: *LinuxDmabuf.Buffer,
) ImageCopyCapture.CaptureError!presentation.Timestamp {
    const self: *Self = @ptrCast(@alignCast(context));
    const access = self.renderer.dmabufAccess() orelse return error.Failed;
    const capture_target = buffer.captureTarget(access) catch return error.Failed;
    const completion = switch (target) {
        .source => |source| switch (source) {
            .output => |output_id| self.captureFullOutputTarget(
                output_id,
                paint_cursors,
                .{ .dmabuf = capture_target },
            ) catch return error.Failed,
            .toplevel => |window_id| toplevel: {
                if (self.session_lock.isLocked()) return error.Failed;
                break :toplevel self.captureToplevelTarget(
                    window_id,
                    .{ .dmabuf = capture_target },
                ) catch |err| switch (err) {
                    error.Stopped => return error.Stopped,
                    else => return error.Failed,
                };
            },
        },
        .cursor => |cursor| self.captureCursorTarget(
            cursor,
            .{ .dmabuf = capture_target },
        ) catch return error.Failed,
    };
    finishDmabufCapture(buffer, completion) catch return error.Failed;
    return presentation.Info.now(self.io).timestamp;
}

fn captureScreencopyDmabuf(
    context: *anyopaque,
    target: Screencopy.Target,
    overlay_cursor: bool,
    buffer: *LinuxDmabuf.Buffer,
) Screencopy.CaptureError!presentation.Timestamp {
    const self: *Self = @ptrCast(@alignCast(context));
    const access = self.renderer.dmabufAccess() orelse return error.Failed;
    const capture_target = buffer.captureTarget(access) catch return error.Failed;
    const completion = self.captureOutputTarget(
        target.output,
        target.region,
        overlay_cursor,
        .{ .dmabuf = capture_target },
    ) catch return error.Failed;
    finishDmabufCapture(buffer, completion) catch return error.Failed;
    return presentation.Info.now(self.io).timestamp;
}

fn finishDmabufCapture(
    buffer: *LinuxDmabuf.Buffer,
    completion: Renderer.FrameCompletion,
) error{CaptureSyncFailed}!void {
    const sync_file_fd = completion.sync_file_fd orelse return;
    defer _ = std.c.close(sync_file_fd);
    if (buffer.importWriteFence(sync_file_fd)) return;
    var poll_fds = [_]std.posix.pollfd{.{
        .fd = sync_file_fd,
        .events = std.posix.POLL.IN,
        .revents = 0,
    }};
    if ((std.posix.poll(&poll_fds, -1) catch return error.CaptureSyncFailed) != 1 or
        poll_fds[0].revents & std.posix.POLL.IN == 0 or
        poll_fds[0].revents &
            (std.posix.POLL.ERR | std.posix.POLL.HUP | std.posix.POLL.NVAL) != 0)
    {
        return error.CaptureSyncFailed;
    }
}

fn completeCaptureReadback(
    context: *anyopaque,
    source: render.PixelBuffer,
    destination: ?render.PixelBuffer,
) bool {
    const self: *Self = @ptrCast(@alignCast(context));
    self.renderer.completeFrameReadback(source, destination) catch |err| {
        log.err("screen capture readback completion failed: {t}", .{err});
        return false;
    };
    return destination != null;
}

const CursorCaptureState = struct {
    cursor: Seat.CursorInfo,
    bounds: render.Rect,
    scale: render.Scale,
    size: render.Size,
    position: render.Position,
    hotspot: render.Position,
    entered: bool,
};

fn captureCursorInfo(
    context: *anyopaque,
    target: ImageCopyCapture.CursorTarget,
) ?ImageCopyCapture.CursorInfo {
    const self: *Self = @ptrCast(@alignCast(context));
    const state = self.cursorCaptureState(target) orelse return null;
    return .{
        .entered = state.entered,
        .position = state.position,
        .hotspot = state.hotspot,
    };
}

fn cursorCaptureState(
    self: *Self,
    target: ImageCopyCapture.CursorTarget,
) ?CursorCaptureState {
    const source_bounds, const scale, const cursor = switch (target.source) {
        .output => |output_id| output: {
            const render_output = self.renderOutputForProtocol(output_id) orelse return null;
            const output = self.outputs.get(output_id) orelse return null;
            const cursor = self.seatCursorInfo(
                target.seat,
                self.session_lock.isLocked(),
            ) orelse return null;
            break :output .{
                output.logicalRect(),
                render_output.backend.renderScale(),
                cursor,
            };
        },
        .toplevel => |window_id| toplevel: {
            if (self.session_lock.isLocked()) return null;
            const bounds = self.toplevelCaptureBounds(window_id) orelse return null;
            const cursor = self.seatCursorInfo(target.seat, false) orelse return null;
            break :toplevel .{ bounds, render.Scale{}, cursor };
        },
    };
    const pointer = target.seat.pointerPosition() orelse return null;
    const pointer_x = capture_geometry.floorToI32(pointer.x);
    const pointer_y = capture_geometry.floorToI32(pointer.y);
    const bounds = self.cursorBounds(cursor) orelse return null;
    const size = scale.apply(.{ .width = bounds.width, .height = bounds.height }) catch
        return null;
    if (size.width == 0 or size.height == 0) return null;
    const position: render.Position = .{
        .x = capture_geometry.scaleCoordinate(@as(i64, pointer_x) - source_bounds.x, scale),
        .y = capture_geometry.scaleCoordinate(@as(i64, pointer_y) - source_bounds.y, scale),
    };
    const image_origin: render.Position = .{
        .x = capture_geometry.scaleCoordinate(@as(i64, bounds.x) - source_bounds.x, scale),
        .y = capture_geometry.scaleCoordinate(@as(i64, bounds.y) - source_bounds.y, scale),
    };
    return .{
        .cursor = cursor,
        .bounds = bounds,
        .scale = scale,
        .size = size,
        .position = position,
        .hotspot = .{
            .x = position.x -| image_origin.x,
            .y = position.y -| image_origin.y,
        },
        .entered = bounds.intersection(source_bounds) != null,
    };
}

fn captureCursor(
    self: *Self,
    target: ImageCopyCapture.CursorTarget,
    pixel_buffer: render.PixelBuffer,
) Renderer.Error!?std.posix.fd_t {
    const completion = try self.captureCursorTarget(target, .{ .pixels = pixel_buffer });
    return completion.sync_file_fd;
}

fn captureCursorTarget(
    self: *Self,
    target: ImageCopyCapture.CursorTarget,
    render_target: render.Target,
) Renderer.Error!Renderer.FrameCompletion {
    const state = self.cursorCaptureState(target) orelse return error.InvalidTarget;
    if (!std.meta.eql(render_target.size(), state.size)) return error.InvalidTarget;
    const render_output = switch (target.source) {
        .output => |output_id| self.renderOutputForProtocol(output_id),
        .toplevel => self.firstRenderOutput(),
    } orelse return error.InvalidTarget;
    const output = self.outputs.get(render_output.protocol_id) orelse return error.InvalidTarget;
    try self.renderer.beginFrame(
        render_target,
        state.scale,
        .{ .x = state.bounds.x, .y = state.bounds.y },
        null,
        .{},
    );
    var renderer_frame_active = true;
    errdefer if (renderer_frame_active) self.renderer.cancelFrame();
    var next_backdrop_capture_id: u32 = 1;
    const frame: OutputFrame = .{
        .render_output = render_output,
        .output = output,
        .visible_rect = state.bounds,
        .track_visibility = false,
        .next_backdrop_capture_id = &next_backdrop_capture_id,
    };
    const clear_command = [_]render.Command{.{ .clear = render.Color.rgba(0, 0, 0, 0) }};
    try self.renderCommands(&frame, &clear_command);
    try self.renderCursor(&frame, state.cursor);
    renderer_frame_active = false;
    return self.finishCaptureTarget(render_target);
}

fn finishCaptureTarget(
    self: *Self,
    target: render.Target,
) Renderer.Error!Renderer.FrameCompletion {
    return switch (target) {
        .pixels => self.renderer.finishFrameReadback(),
        .dmabuf => self.renderer.finishFrameScanout(null),
        .offscreen => error.InvalidTarget,
    };
}

test "output capture uses pixel dimensions at fractional scale" {
    const server = try Self.createWithVirtualOutput(
        std.testing.allocator,
        std.testing.io,
        .cpu,
        .headless,
        null,
        .{
            .size = .{ .width = 6, .height = 3 },
            .scale = .{ .numerator = 180 },
        },
    );
    defer server.destroy();
    const output = server.primaryRenderOutput();

    try std.testing.expectEqual(
        render.Size{ .width = 6, .height = 3 },
        captureSourceConstraints(server, .{ .output = output.protocol_id }).?.size,
    );
    try std.testing.expectEqual(
        render.Size{ .width = 6, .height = 3 },
        screencopyConstraints(server, .{ .output = output.protocol_id }).?,
    );

    var pixels: [18]u32 = undefined;
    _ = try server.captureOutput(output.protocol_id, false, .{
        .size = .{ .width = 6, .height = 3 },
        .stride_pixels = 6,
        .pixels = &pixels,
    });
    const background = renderColor(server.palette.desktop_background).argb8888();
    for (pixels) |pixel| try std.testing.expectEqual(background, pixel);
}

test "promoted overlay damage remains stale for the next frame" {
    var damage = Region.init();
    defer damage.deinit();
    preservePromotedDamage(
        &damage,
        .{ .x = 10, .y = 20, .width = 30, .height = 40 },
        .{ .width = 100, .height = 100 },
    );
    try std.testing.expect(damage.coversRectangle(10, 20, 30, 40));
}

fn captureOutput(
    self: *Self,
    output_id: OutputLayout.Id,
    paint_cursors: bool,
    pixel_buffer: render.PixelBuffer,
) Renderer.Error!?std.posix.fd_t {
    return self.captureOutputRegion(output_id, null, paint_cursors, pixel_buffer);
}

fn captureOutputRegion(
    self: *Self,
    output_id: OutputLayout.Id,
    local_region: ?render.Rect,
    paint_cursors: bool,
    pixel_buffer: render.PixelBuffer,
) Renderer.Error!?std.posix.fd_t {
    const completion = try self.captureOutputTarget(
        output_id,
        local_region,
        paint_cursors,
        .{ .pixels = pixel_buffer },
    );
    return completion.sync_file_fd;
}

fn captureFullOutputTarget(
    self: *Self,
    output_id: OutputLayout.Id,
    paint_cursors: bool,
    render_target: render.Target,
) Renderer.Error!Renderer.FrameCompletion {
    return self.captureOutputTarget(output_id, null, paint_cursors, render_target);
}

fn captureOutputTarget(
    self: *Self,
    output_id: OutputLayout.Id,
    local_region: ?render.Rect,
    paint_cursors: bool,
    render_target: render.Target,
) Renderer.Error!Renderer.FrameCompletion {
    const render_output = self.renderOutputForProtocol(output_id) orelse
        return error.InvalidTarget;
    const output = self.outputs.get(output_id) orelse return error.InvalidTarget;
    const scale = render_output.backend.renderScale();
    const output_size = render_output.backend.modeSize();
    const source_region = if (local_region) |region|
        capture_geometry.scaledRegion(region, scale, output_size) orelse
            return error.InvalidTarget
    else
        null;
    const expected_size = if (source_region) |region|
        render.Size{ .width = region.width, .height = region.height }
    else
        output_size;
    if (!std.meta.eql(render_target.size(), expected_size)) return error.InvalidTarget;
    if (self.composed_capture_source) |source| {
        if (std.meta.eql(source.output, output_id) and
            self.composedCaptureMatchesCursors(
                source,
                output.logicalRect(),
                local_region,
                paint_cursors,
            ))
        {
            const copied = self.renderer.copyComposedFrame(
                source.target,
                source_region,
                render_target,
                .{},
            ) catch |err| copied: {
                log.warn("composed screen capture copy failed; rerendering: {t}", .{err});
                break :copied null;
            };
            if (copied) |completion| return completion;
        }
    }
    const output_rect = output.logicalRect();
    const visible_rect = capture_geometry.logicalRect(output_rect, local_region);
    try self.renderer.beginFrame(
        render_target,
        scale,
        .{ .x = visible_rect.x, .y = visible_rect.y },
        null,
        .{},
    );
    var renderer_frame_active = true;
    errdefer if (renderer_frame_active) self.renderer.cancelFrame();
    var next_backdrop_capture_id: u32 = 1;
    const frame: OutputFrame = .{
        .render_output = render_output,
        .output = output,
        .visible_rect = visible_rect,
        .track_visibility = false,
        .next_backdrop_capture_id = &next_backdrop_capture_id,
    };
    const clear_command = [_]render.Command{.{
        .clear = outputClearColor(self.palette, self.session_lock.isLocked()),
    }};
    try self.renderCommands(&frame, &clear_command);
    if (self.session_lock.isLocked()) {
        try self.renderSessionLockContents(&frame, paint_cursors, paint_cursors);
    } else {
        _ = try self.renderDesktopContents(&frame, paint_cursors, paint_cursors);
    }
    renderer_frame_active = false;
    return self.finishCaptureTarget(render_target);
}

fn composedCaptureMatchesCursors(
    self: *Self,
    source: ComposedCaptureSource,
    output_rect: render.Rect,
    local_region: ?render.Rect,
    paint_cursors: bool,
) bool {
    const capture_rect = capture_geometry.logicalRect(output_rect, local_region);
    const locked = self.session_lock.isLocked();
    if (source.primary_cursor_painted != paint_cursors) {
        if (self.seatCursorInfo(&self.seat, locked)) |cursor| {
            if (capture_geometry.cursorMismatchAffects(
                source.primary_cursor_painted,
                paint_cursors,
                self.cursorBounds(cursor),
                capture_rect,
            )) return false;
        }
    }
    if (source.tablet_cursors_painted != paint_cursors) {
        var cursors = self.tablet.cursorIterator();
        while (cursors.next()) |info| {
            if (!self.tabletCursorVisible(info.focus_surface, locked)) continue;
            if (capture_geometry.cursorMismatchAffects(
                source.tablet_cursors_painted,
                paint_cursors,
                self.cursorBounds(info.cursor),
                capture_rect,
            )) return false;
        }
    }
    return true;
}

const ToplevelCaptureError = Renderer.Error || error{Stopped};

fn captureToplevel(
    self: *Self,
    window_id: NeutralXdgShell.WindowId,
    pixel_buffer: render.PixelBuffer,
) ToplevelCaptureError!?std.posix.fd_t {
    const completion = try self.captureToplevelTarget(window_id, .{ .pixels = pixel_buffer });
    return completion.sync_file_fd;
}

fn captureToplevelTarget(
    self: *Self,
    window_id: NeutralXdgShell.WindowId,
    render_target: render.Target,
) ToplevelCaptureError!Renderer.FrameCompletion {
    const info = self.xdg_shell_core.windowInfo(window_id) orelse return error.Stopped;
    if (!info.mapped or !info.scene_presentation_enabled) return error.Stopped;
    const surface_id = self.xdg_shell_core.windowSurface(window_id) orelse return error.Stopped;
    const position = self.scene.surfacePosition(surface_id) orelse return error.Stopped;
    const bounds = self.toplevelCaptureBounds(window_id) orelse return error.Stopped;
    if (!std.meta.eql(render_target.size(), render.Size{
        .width = bounds.width,
        .height = bounds.height,
    })) return error.InvalidTarget;
    const render_output = self.firstRenderOutput() orelse return error.InvalidTarget;
    const output = self.outputs.get(render_output.protocol_id) orelse return error.InvalidTarget;
    try self.renderer.beginFrame(
        render_target,
        .{},
        .{ .x = bounds.x, .y = bounds.y },
        null,
        .{},
    );
    var renderer_frame_active = true;
    errdefer if (renderer_frame_active) self.renderer.cancelFrame();
    var next_backdrop_capture_id: u32 = 1;
    const frame: OutputFrame = .{
        .render_output = render_output,
        .output = output,
        .visible_rect = bounds,
        .track_visibility = false,
        .next_backdrop_capture_id = &next_backdrop_capture_id,
    };
    const clear_command = [_]render.Command{.{ .clear = render.Color.rgba(0, 0, 0, 0) }};
    try self.renderCommands(&frame, &clear_command);
    try self.renderSurfaceTree(
        &frame,
        surface_id,
        position.x,
        position.y,
        null,
        null,
    );
    renderer_frame_active = false;
    return self.finishCaptureTarget(render_target);
}

fn renderOutputForProtocol(self: *Self, output_id: OutputLayout.Id) ?*RenderOutput {
    var outputs = self.render_outputs.iterator();
    while (outputs.next()) |entry| {
        const render_output = entry.value.*;
        if (std.meta.eql(render_output.protocol_id, output_id)) return render_output;
    }
    return null;
}

fn firstRenderOutput(self: *Self) ?*RenderOutput {
    var outputs = self.render_outputs.iterator();
    const entry = outputs.next() orelse return null;
    return entry.value.*;
}

fn toplevelCaptureBounds(self: *Self, window_id: NeutralXdgShell.WindowId) ?render.Rect {
    const info = self.xdg_shell_core.windowInfo(window_id) orelse return null;
    if (!info.mapped or !info.scene_presentation_enabled) return null;
    const surface_id = self.xdg_shell_core.windowSurface(window_id) orelse return null;
    const position = self.scene.surfacePosition(surface_id) orelse return null;
    var bounds: ?render.Rect = null;
    self.addSurfaceTreeBounds(surface_id, position.x, position.y, &bounds) catch return null;
    return bounds;
}

fn addSurfaceTreeBounds(
    self: *Self,
    surface_id: Surface.Id,
    x: i32,
    y: i32,
    bounds: *?render.Rect,
) error{Overflow}!void {
    if (self.sceneGeneratedCompound(surface_id)) {
        const subtree = self.headless_surface_forest.subtreeBounds(surface_id) orelse return;
        const rect = subtree.translated(x, y);
        bounds.* = if (bounds.*) |current|
            try capture_geometry.unionBounds(current, rect)
        else
            rect;
        return;
    }
    if (Surface.currentBuffer(self.compositor.surfaceStore(), surface_id) == null) return;
    var stack = self.subcompositor.stackIterator(surface_id);
    while (stack.next()) |entry| switch (entry) {
        .parent => {
            const buffer = Surface.currentBuffer(
                self.compositor.surfaceStore(),
                surface_id,
            ) orelse continue;
            const rect: render.Rect = .{
                .x = x,
                .y = y,
                .width = buffer.logical_size.width,
                .height = buffer.logical_size.height,
            };
            bounds.* = if (bounds.*) |current|
                try capture_geometry.unionBounds(current, rect)
            else
                rect;
        },
        .child => |child| try self.addSurfaceTreeBounds(
            child.surface_id,
            x +| child.position.x,
            y +| child.position.y,
            bounds,
        ),
    };
}

fn handleRenderTimer(output_context: *RenderOutput) c_int {
    handleScheduledRender(output_context);
    return 0;
}

fn handleFrameCallbackTimer(output_context: *RenderOutput) c_int {
    output_context.frame_callback_scheduled = false;
    if (!output_context.backend.powered()) return 0;

    const now = nowNanoseconds(output_context.server.io);
    const timestamp = presentation.Timestamp.fromNanoseconds(now);
    const output = output_context.server.outputs.get(output_context.protocol_id).?;
    if (output.sendCallbackOnlyFrameCallbacks(timestamp.milliseconds())) {
        log.debug("completed callback-only frame callbacks for {s}", .{output.name()});
    }
    if (output_context.server.completeGeneratedCallbackOnlyFrames(
        output,
        output_context.protocol_id,
        timestamp.milliseconds(),
    )) {
        log.debug("completed generated callback-only frame callbacks for {s}", .{output.name()});
    }
    return 0;
}

fn completeGeneratedCallbackOnlyFrames(
    self: *Self,
    output: *Output,
    output_id: OutputLayout.Id,
    timestamp_ms: u32,
) bool {
    var completed = false;
    var iterator = self.headless_surface_forest.nodeIterator();
    while (iterator.next()) |node| {
        if (!node.frame_demand or !output.containsSurface(node.id)) continue;
        const root = self.headless_surface_forest.compoundRoot(node.id) orelse continue;
        const lock_output = self.exactEligibleGeneratedSessionLockRoot(root);
        if ((!self.exactEligibleGeneratedRoot(root) and !self.exactEligibleGeneratedPopupRoot(root) and
            self.exactEligibleGeneratedLayerRoot(root) == null and
            (lock_output == null or !std.meta.eql(lock_output.?, output_id))) or
            !self.headless_surface_forest.mappedInCompound(node.id, root)) continue;
        completed = self.headless_surface_forest.completeCallbackOnlyFrame(node.id, timestamp_ms) or completed;
    }
    return completed;
}

fn scheduleGeneratedCallbackOnlyFrames(self: *Self, render_output: *RenderOutput) void {
    const output = self.outputs.get(render_output.protocol_id) orelse return;
    var iterator = self.headless_surface_forest.nodeIterator();
    while (iterator.next()) |node| {
        if (!node.frame_demand or !output.containsSurface(node.id) or
            !self.headless_surface_forest.hasCallbackOnlyFrameDemand(node.id)) continue;
        const root = self.headless_surface_forest.compoundRoot(node.id) orelse continue;
        const lock_output = self.exactEligibleGeneratedSessionLockRoot(root);
        if ((!self.exactEligibleGeneratedRoot(root) and !self.exactEligibleGeneratedPopupRoot(root) and
            self.exactEligibleGeneratedLayerRoot(root) == null and
            (lock_output == null or !std.meta.eql(lock_output.?, render_output.protocol_id))) or
            !self.headless_surface_forest.mappedInCompound(node.id, root)) continue;
        self.scheduleFrameCallback(render_output);
        return;
    }
}

fn handleRenderIdle(output_context: *RenderOutput) void {
    std.debug.assert(output_context.repaint_idle != null);
    output_context.repaint_idle = null;
    handleScheduledRender(output_context);
}

fn handleScheduledRender(output_context: *RenderOutput) void {
    const self = output_context.server;
    output_context.render_scheduled = false;
    if (!output_context.repaint_needed or !output_context.backend.ready()) return;
    std.debug.assert(!output_context.damage.isEmpty());
    output_context.repaint_needed = false;
    self.renderFrame(output_context) catch |err| {
        log.err("output frame failed: {t}", .{err});
        self.terminate();
    };
    self.scheduleRepaint(output_context);
}

fn expandBackdropBlurDamage(
    self: *Self,
    render_output: *const RenderOutput,
    output: *const Output,
    damage: *Region,
    source_root: ?Surface.Id,
) (Region.Error || error{UnresolvedBlurSource})!void {
    const surface_blur = Scene.background_blur;
    var changed = true;
    while (changed) {
        changed = false;
        const surfaces = self.compositor.surfaceStore();
        var surface_iterator = surfaces.iterator();
        while (surface_iterator.next()) |surface_entry| {
            const region = Surface.currentBlurRegion(surfaces, surface_entry.id) orelse continue;
            const buffer = Surface.currentBuffer(surfaces, surface_entry.id) orelse continue;
            if (surfaceFullyOpaque(surfaces, surface_entry.id, buffer)) continue;
            const root = self.subcompositor.rootSurface(surface_entry.id);
            if (source_root) |source| {
                // A tree is painted after its backdrop capture, so its own commits
                // cannot change that capture. A lower top-level node cannot depend
                // on a commit above it; other surface categories remain conservative.
                if (std.meta.eql(root, source)) continue;
                if (self.scene.surfaceNodeAbove(root, source)) |above| {
                    if (!above) continue;
                }
            }
            if (!self.scene.surfaceMapped(root)) {
                // Blur roots rendered outside the scene (input method popups,
                // drag icons, session lock surfaces) cannot be resolved here,
                // so callers must repaint the whole output.
                if (!self.scene.surfaceTracked(root)) return error.UnresolvedBlurSource;
                continue;
            }
            const root_position = self.scene.surfacePosition(root) orelse
                return error.UnresolvedBlurSource;
            const offset = self.subcompositor.surfaceOffset(surface_entry.id);
            var rectangles = region.rectangleIterator();
            while (rectangles.next()) |rectangle| {
                const local = surfaceEffectRect(rectangle, buffer.logical_size) orelse continue;
                const blur = backdrop_blur_damage.areaForOutput(
                    local.translated(
                        root_position.x +| offset.x,
                        root_position.y +| offset.y,
                    ),
                    output.logicalRect(),
                    render_output.backend.renderScale(),
                    render_output.backend.modeSize(),
                    surface_blur.radius,
                    surface_blur.downsample_level,
                ) orelse continue;
                changed = try backdrop_blur_damage.propagate(
                    damage,
                    blur,
                    render_output.backend.modeSize(),
                ) or changed;
            }
        }
        var nodes = self.scene.nodeIterator();
        while (nodes.next()) |node| switch (node) {
            .window => |entry| {
                if (!entry.window.mapped or
                    self.managedGeneratedWindow(entry.window.surface_id) == null) continue;
                if (source_root) |source| {
                    if (std.meta.eql(entry.window.surface_id, source)) continue;
                    if (self.scene.surfaceNodeAbove(entry.window.surface_id, source)) |above| {
                        if (!above) continue;
                    }
                }
                const root_position = self.scene.surfacePosition(entry.window.surface_id) orelse
                    return error.UnresolvedBlurSource;
                var subtree = self.headless_surface_forest.subtreeRenderIterator(
                    entry.window.surface_id,
                );
                while (subtree.next()) |surface_entry| {
                    const render_state = self.surface_registry.renderState(surface_entry.id) orelse
                        return error.UnresolvedBlurSource;
                    std.debug.assert(std.meta.eql(
                        surface_entry.mapped_size,
                        render_state.logical_size,
                    ));
                    if (renderStateFullyOpaque(render_state)) continue;
                    const region = render_state.blur_region orelse continue;
                    var rectangles = region.rectangleIterator();
                    while (rectangles.next()) |rectangle| {
                        const local = surfaceEffectRect(
                            rectangle,
                            render_state.logical_size,
                        ) orelse continue;
                        const blur = backdrop_blur_damage.areaForOutput(
                            local.translated(
                                root_position.x +| surface_entry.position.x,
                                root_position.y +| surface_entry.position.y,
                            ),
                            output.logicalRect(),
                            render_output.backend.renderScale(),
                            render_output.backend.modeSize(),
                            surface_blur.radius,
                            surface_blur.downsample_level,
                        ) orelse continue;
                        changed = try backdrop_blur_damage.propagate(
                            damage,
                            blur,
                            render_output.backend.modeSize(),
                        ) or changed;
                    }
                }
            },
            .shell_surface => {},
        };
    }
}

fn renderFrame(self: *Self, render_output: *RenderOutput) Renderer.Error!void {
    // Frame production starts here: transition processing below may render
    // window snapshots, so the repaint-delay budget must include it.
    const render_start_nanoseconds = nowNanoseconds(self.io);
    self.animation_now = render_start_nanoseconds;
    if (self.reduced_motion or self.session_lock.isLocked() or
        self.xdg_shell_core.hasPopupGrab() or self.window_manager.directManipulationActive())
    {
        finishAllWindowTransitions(self);
        finishAllWorkspaceTransitions(self);
    } else {
        var transition_index: usize = 0;
        while (transition_index < self.window_transitions.items.len) {
            const transition = self.window_transitions.items[transition_index];
            if (windowTransitionHasPopup(self, transition.scene_id)) {
                destroyWindowTransition(self, transition_index);
                continue;
            }
            switch (transition.phase) {
                .waiting => {
                    if (transition.kind == .disappearance) {
                        const start = if (self.windowReflowIndex(
                            transition.output_id,
                            transition.old_rect,
                            .absorbed,
                        )) |reflow_index| start: {
                            const reflow = self.window_transitions.items[reflow_index];
                            if (reflow.phase == .waiting) {
                                transition_index += 1;
                                continue;
                            }
                            break :start reflow.start;
                        } else self.animation_now;
                        self.window_transitions.items[transition_index].phase = .animating;
                        self.window_transitions.items[transition_index].start = start;
                    }
                    transition_index += 1;
                },
                .target_pending => switch (startWindowTransition(self, transition_index)) {
                    .started => transition_index += 1,
                    .removed => {},
                    .not_ready => {
                        if (self.animation_now - transition.start >= WindowAnimation.target_wait_nanoseconds) {
                            destroyWindowTransition(self, transition_index);
                        } else transition_index += 1;
                    },
                },
                .animating => {
                    if (WindowAnimation.linearProgress(
                        transition.start,
                        self.animation_now,
                        transition.duration,
                    ) == std.math.maxInt(u32)) {
                        destroyWindowTransition(self, transition_index);
                    } else if (transition.target_dirty) {
                        if (refreshWindowTransitionTarget(self, transition_index)) {
                            transition_index += 1;
                        }
                    } else {
                        transition_index += 1;
                    }
                },
            }
        }
        var workspace_index: usize = 0;
        while (workspace_index < self.workspace_transitions.items.len) {
            const transition = self.workspace_transitions.items[workspace_index];
            if (hasMappedClientPopup(self) or
                (transition.phase == .animating and WindowAnimation.linearProgress(
                    transition.start,
                    self.animation_now,
                    WindowAnimation.fade_duration_nanoseconds,
                ) == std.math.maxInt(u32)))
            {
                destroyWorkspaceTransition(self, workspace_index);
            } else {
                workspace_index += 1;
            }
        }
    }
    const force_composed_cursor = self.needsComposedCursorFrame(render_output.protocol_id);
    self.prepareOutputCursorFrame(render_output, force_composed_cursor);
    const paint_primary_cursor = render_output.cursor_state == .software or
        render_output.cursor_state == .deactivating;
    const render_target = render_output.backend.acquire() orelse {
        increment(&render_output.frame_statistics.acquire_retries);
        render_output.repaint_needed = true;
        return;
    };
    errdefer render_output.backend.cancel();
    render_output.beginFrame(render_start_nanoseconds);
    errdefer render_output.clearPendingFrame();
    const output = self.outputs.get(render_output.protocol_id).?;
    output.beginFrame();
    errdefer output.cancelFrame();
    const position = output.logicalPosition();
    var frame_damage = Region.init();
    defer frame_damage.deinit();
    try frame_damage.copyFrom(&render_output.damage);
    render_output.damage.clear();
    // CPU captures read the live persistent target, so every dependency must
    // be repainted. Vulkan reuses captures keyed by preceding scene content.
    if (!self.renderer.supportsBackdropCaptureReuse()) {
        self.expandBackdropBlurDamage(render_output, output, &frame_damage, null) catch |err| switch (err) {
            error.OutOfMemory => return error.OutOfMemory,
            error.UnresolvedBlurSource => {
                const size = render_output.backend.modeSize();
                frame_damage.setRectangle(0, 0, size.width, size.height);
            },
        };
    }
    // Buffer-age repair must retain the post-effect damage as this frame's new
    // damage while adding only the acquired buffer's backlog to the redraw.
    try render_output.backend.repairDamage(&frame_damage);
    const damage = if (render_output.backend.persistentRenderTarget() and
        self.renderer.supportsPartialDamage())
        try self.outputDamageRectangles(render_output, &frame_damage)
    else
        null;
    const scale = render_output.backend.renderScale();
    const origin: render.Position = .{ .x = position.x, .y = position.y };
    self.renderer.beginFrame(
        render_target,
        scale,
        origin,
        damage,
        render_output.color_description,
    ) catch |err| {
        log.err(
            "output renderer setup failed for {d}x{d} target: {t}",
            .{ render_target.size().width, render_target.size().height, err },
        );
        return err;
    };
    var renderer_frame_active = true;
    errdefer if (renderer_frame_active) self.renderer.cancelFrame();
    var next_backdrop_capture_id: u32 = 1;
    const frame: OutputFrame = .{
        .render_output = render_output,
        .output = output,
        .visible_rect = output.logicalRect(),
        .track_visibility = true,
        .presentation_damage = &frame_damage,
        .next_backdrop_capture_id = &next_backdrop_capture_id,
    };
    const clear_command = [_]render.Command{.{
        .clear = outputClearColor(self.palette, self.session_lock.isLocked()),
    }};
    try self.renderCommands(&frame, &clear_command);
    if (self.session_lock.isLocked()) {
        try self.renderSessionLockContents(&frame, paint_primary_cursor, true);
        try self.selectFrameOutputColorDescription(render_output, null);
        self.scheduleCursorFallbackAfterColorChange(render_output);
        renderer_frame_active = false;
        const completion = self.renderer.finishFrameScanout(
            outputStatisticsTag(render_output.protocol_id),
        ) catch |err| {
            log.err("session-lock renderer frame completion failed: {t}", .{err});
            return err;
        };
        render_output.frame_statistics.addFrameCompletion(completion);
        self.collectGpuTimings();
        const render_fence_fd = completion.sync_file_fd;
        defer if (render_fence_fd) |fd| {
            _ = std.c.close(fd);
        };
        return self.presentSessionLockFrame(
            &frame,
            render_fence_fd,
            .{
                .output = render_output.protocol_id,
                .target = render_target,
                .primary_cursor_painted = paint_primary_cursor,
                .tablet_cursors_painted = true,
            },
        );
    }

    const desktop_contents = self.renderDesktopContents(&frame, paint_primary_cursor, true) catch |err| {
        log.err("desktop frame assembly failed: {t}", .{err});
        return err;
    };
    const top_fullscreen = desktop_contents.top_fullscreen;
    try self.selectFrameOutputColorDescription(
        render_output,
        self.renderer.preferredOutputTransfer(),
    );
    self.scheduleCursorFallbackAfterColorChange(render_output);
    const fifo_barrier = Surface.hasFifoBarrierForOutput(
        self.compositor.surfaceStore(),
        output,
    );
    const allow_tearing = if (top_fullscreen) |window_id|
        if (self.scene.windowSurface(window_id)) |surface_id|
            Surface.currentPresentationHint(
                self.compositor.surfaceStore(),
                surface_id,
            ) == .async and !fifo_barrier
        else
            false
    else
        false;
    var presented: ?presentation.Info = null;
    var direct_scanout = false;
    if (!force_composed_cursor) switch (self.renderer.directScanoutCandidate()) {
        .candidate => |candidate| {
            increment(&render_output.frame_statistics.direct_scanout_candidates);
            switch (render_output.backend.tryDirectScanout(candidate, allow_tearing)) {
                .accepted => {
                    self.renderer.finishFrameDirectScanout();
                    renderer_frame_active = false;
                    direct_scanout = true;
                    const scanout_format = render.DmabufFormat.fromFourcc(
                        candidate.dmabuf.?.format,
                    ) orelse unreachable;
                    render_output.commitFrame(
                        .direct_scanout,
                        &frame_damage,
                        scanout_format,
                        null,
                    );
                },
                .rejected => |reason| render_output.frame_statistics.rejectDirectScanout(reason),
            }
        },
        .rejected => |reason| render_output.frame_statistics.rejectDirectScanout(reason),
    };
    var overlay_destination: ?render.Rect = null;
    if (!direct_scanout) {
        if (!force_composed_cursor) switch (self.renderer.overlayScanoutCandidate()) {
            .candidate => |candidate| {
                increment(&render_output.frame_statistics.overlay_scanout_candidates);
                switch (render_output.backend.validateOverlayScanout(candidate)) {
                    .accepted => overlay_destination = candidate.destination,
                    .rejected => |reason| {
                        render_output.frame_statistics.rejectOverlayScanout(reason);
                    },
                }
            },
            .rejected => |reason| render_output.frame_statistics.rejectOverlayScanout(reason),
        };
        renderer_frame_active = false;
        const gpu_sample_tag = outputStatisticsTag(render_output.protocol_id);
        const completion = (if (overlay_destination != null)
            self.renderer.finishFrameScanoutWithoutTopmost(gpu_sample_tag)
        else
            self.renderer.finishFrameScanout(gpu_sample_tag)) catch |err| {
            log.err(
                "renderer frame completion failed (overlay={any}): {t}",
                .{ overlay_destination != null, err },
            );
            return err;
        };
        render_output.frame_statistics.addFrameCompletion(completion);
        self.collectGpuTimings();
        const render_fence_fd = completion.sync_file_fd;
        defer if (render_fence_fd) |fd| {
            _ = std.c.close(fd);
        };
        presented = if (overlay_destination) |destination| overlay_presented: {
            const result = render_output.backend.presentValidatedOverlay(
                &frame_damage,
                render_fence_fd,
                allow_tearing,
            ) catch |err| switch (err) {
                error.OutputColorFallback => {
                    render_output.discardFrame();
                    output.cancelFrame();
                    try self.refreshRenderOutputColorDescription(render_output);
                    self.damageFullOutput(render_output);
                    return;
                },
                error.OutputBusy => {
                    if (!render_output.retryOutputBusy()) return error.InvalidTarget;
                    render_output.backend.cancel();
                    render_output.discardFrame();
                    output.cancelFrame();
                    self.damageFullOutput(render_output);
                    return;
                },
                error.OverlayCommitFailed => {
                    render_output.discardFrame();
                    output.cancelFrame();
                    render_output.frame_statistics.rejectOverlayScanout(.page_flip_failed);
                    self.damageFullOutput(render_output);
                    return;
                },
                else => {
                    log.err("validated overlay presentation failed: {t}", .{err});
                    return error.InvalidTarget;
                },
            };
            preservePromotedDamage(
                &render_output.damage,
                destination,
                render_output.backend.modeSize(),
            );
            break :overlay_presented result;
        } else render_output.backend.present(
            &frame_damage,
            render_fence_fd,
            allow_tearing,
        ) catch |err| switch (err) {
            error.OutputColorFallback => {
                render_output.discardFrame();
                output.cancelFrame();
                try self.refreshRenderOutputColorDescription(render_output);
                self.damageFullOutput(render_output);
                return;
            },
            error.OutputBusy => {
                if (!render_output.retryOutputBusy()) return error.InvalidTarget;
                render_output.backend.cancel();
                render_output.discardFrame();
                output.cancelFrame();
                self.damageFullOutput(render_output);
                return;
            },
            else => {
                log.err("composited output presentation failed: {t}", .{err});
                return error.InvalidTarget;
            },
        };
        render_output.commitFrame(
            if (overlay_destination != null) .overlay_scanout else .composited,
            &frame_damage,
            render_output.backend.compositedScanoutFormat(),
            render_fence_fd,
        );
    }
    self.rememberSampledSurfaces(render_output);
    output.endFrame();
    self.completeSampledHeadlessFrames(render_output.protocol_id);
    self.completeSampledGeneratedCursorFrames();
    self.scheduleGeneratedCallbackOnlyFrames(render_output);
    self.color_management.refreshPreferred();
    self.foreign_toplevel_list.syncOutput(render_output.protocol_id);

    if (!desktop_contents.lower_layers_occluded) {
        self.submitLayerSurfaces(output, .background);
        self.submitLayerSurfaces(output, .bottom);
        if (top_fullscreen != null) self.submitLayerSurfaces(output, .top);
    }
    var fullscreen_reached = top_fullscreen == null;
    var nodes = self.scene.nodeIterator();
    while (nodes.next()) |entry| switch (entry) {
        .window => |window_entry| {
            if (!window_entry.window.mapped) continue;
            if (top_fullscreen) |id| {
                if (!std.meta.eql(window_entry.id, id)) continue;
                fullscreen_reached = true;
            }
            if (transitionIndex(self, window_entry.id)) |index| {
                const transition = self.window_transitions.items[index];
                if (transition.phase == .animating and !transition.target_dirty and
                    std.meta.eql(transition.output_id, render_output.protocol_id))
                {
                    self.submitCapturedWindowDecorations(output, window_entry.id, .below);
                    self.submitCapturedSurfaceTree(output, window_entry.window.surface_id);
                    self.submitCapturedWindowDecorations(output, window_entry.id, .above);
                }
            } else {
                self.submitWindowDecorations(output, window_entry.id, .below);
                self.submitSurfaceTree(output, window_entry.window.surface_id);
                self.submitWindowDecorations(output, window_entry.id, .above);
                self.submitWindowPopups(output, window_entry.id);
            }
        },
        .shell_surface => |shell_entry| {
            if (!fullscreen_reached or !shell_entry.shell_surface.mapped) continue;
            self.submitSurfaceTree(output, shell_entry.shell_surface.surface_id);
        },
    };
    if (top_fullscreen == null) self.submitLayerSurfaces(output, .top);
    self.submitLayerSurfaces(output, .overlay);
    self.submitLayerPopups(output);
    var input_popups = self.input_method.popupIterator();
    while (input_popups.next()) |popup| self.submitSurfaceTree(output, popup.surface_id);
    const drag_icon = self.mature_data_device.iconInfo();
    if (drag_icon) |info| self.submitSurfaceTree(output, info.surface_id);
    const generated_drag_icon = self.generatedDragIconInfo();
    if (generated_drag_icon) |info| self.submitGeneratedCompound(output, info.surface_id);
    if (paint_primary_cursor) self.submitSeatCursor(output, &self.seat, false);
    self.submitTabletCursors(output, false);
    const callback_timestamp = presentation.Timestamp.fromNanoseconds(nowNanoseconds(self.io));
    try Surface.sendSubmittedFrameCallbacks(
        self.compositor.surfaceStore(),
        self.allocator,
        output,
        callback_timestamp.milliseconds(),
    );
    try Surface.clearFifoBarriersForOutput(
        self.compositor.surfaceStore(),
        self.allocator,
        output,
    );
    self.finishRepaintIfIdle();
    if (presented) |info| outputPresented(render_output, info);
    self.captureOutputFrame(
        render_output.protocol_id,
        if (!direct_scanout and overlay_destination == null) .{
            .output = render_output.protocol_id,
            .target = render_target,
            .primary_cursor_painted = paint_primary_cursor,
            .tablet_cursors_painted = true,
        } else null,
    );
    for (self.window_transitions.items) |transition| {
        if (std.meta.eql(transition.output_id, render_output.protocol_id)) {
            self.damageFullOutput(render_output);
            break;
        }
    }
    if (workspaceTransitionIndex(self, render_output.protocol_id) != null) {
        self.damageFullOutput(render_output);
    }
    self.refreshKeyboardFocus();
}

fn needsComposedCursorFrame(self: *Self, output_id: OutputLayout.Id) bool {
    const cursor = self.seatCursorInfo(&self.seat, self.session_lock.isLocked()) orelse
        return false;
    const output = self.outputs.get(output_id) orelse return false;
    const output_rect = output.logicalRect();
    const local_bounds = if (self.cursorBounds(cursor)) |bounds| local: {
        const clipped = bounds.intersection(output_rect) orelse return false;
        break :local clipped.translated(0 -| output_rect.x, 0 -| output_rect.y);
    } else null;
    return (self.image_copy_capture_initialized and
        self.image_copy_capture.needsComposedCursorFrame(output_id)) or
        (self.screencopy_initialized and
            self.screencopy.needsComposedCursorFrame(output_id, local_bounds));
}

fn captureOutputFrame(
    self: *Self,
    output_id: OutputLayout.Id,
    source: ?ComposedCaptureSource,
) void {
    std.debug.assert(self.composed_capture_source == null);
    self.composed_capture_source = source;
    defer self.composed_capture_source = null;
    if (self.image_copy_capture_initialized) self.image_copy_capture.captureOutput(output_id);
    if (self.screencopy_initialized) self.screencopy.captureOutput(output_id);
}

fn selectFrameOutputColorDescription(
    self: *Self,
    render_output: *RenderOutput,
    transfer: ?render.TransferFunction,
) !void {
    _ = render_output.backend.selectOutputTransfer(transfer);
    try self.refreshRenderOutputColorDescription(render_output);
    self.renderer.setOutputColorDescription(render_output.color_description);
    self.renderer.setOutputCalibration(render_output.output_calibration);
}

const DesktopContents = struct {
    top_fullscreen: ?Scene.Id,
    lower_layers_occluded: bool,
};

fn renderDesktopContents(
    self: *Self,
    frame: *const OutputFrame,
    paint_primary_cursor: bool,
    paint_tablet_cursors: bool,
) Renderer.Error!DesktopContents {
    const fullscreen_entry = self.topFullscreenForOutput(frame.visible_rect);
    const top_fullscreen = if (fullscreen_entry) |entry| entry.id else null;
    const lower_layers_occluded = if (fullscreen_entry) |entry|
        self.fullscreenOccludesLowerLayers(entry.window, frame.visible_rect)
    else
        false;
    if (!lower_layers_occluded) {
        try self.renderLayerSurfaces(frame, .background);
        if (self.hasBackgroundEffect()) {
            const blur = Scene.background_blur;
            const cache_command = [_]render.Command{.{ .backdrop_capture = .{
                .id = try allocateBackdropCaptureId(frame),
                .rect = frame.visible_rect,
                .radius = blur.radius,
                .downsample_level = blur.downsample_level,
                .finish = blur.finish,
                .base = true,
            } }};
            try self.renderCommands(frame, &cache_command);
        }
        try self.renderLayerSurfaces(frame, .bottom);
        try self.renderHeadlessSurfaces(frame);
        if (top_fullscreen != null) try self.renderLayerSurfaces(frame, .top);
    }
    var fullscreen_reached = top_fullscreen == null;
    var nodes = self.scene.nodeIterator();
    while (nodes.next()) |entry| switch (entry) {
        .window => |window_entry| {
            if (!window_entry.window.mapped) continue;
            if (top_fullscreen) |id| {
                if (!std.meta.eql(window_entry.id, id)) continue;
                fullscreen_reached = true;
            }
            try self.renderWindow(frame, window_entry.id, window_entry.window);
        },
        .shell_surface => |shell_entry| {
            if (!fullscreen_reached or !shell_entry.shell_surface.mapped) continue;
            try self.renderSurfaceTree(
                frame,
                shell_entry.shell_surface.surface_id,
                shell_entry.shell_surface.position.x,
                shell_entry.shell_surface.position.y,
                null,
                null,
            );
        },
    };
    if (top_fullscreen == null) {
        try self.renderDetachedWindowTransitions(frame);
        try self.renderTilingDragPreview(frame);
        try self.renderLayerSurfaces(frame, .top);
    }
    try self.renderLayerSurfaces(frame, .overlay);
    try self.renderLayerPopups(frame);

    self.input_method.refreshPopups();
    var input_popups = self.input_method.popupIterator();
    while (input_popups.next()) |popup| {
        try self.renderSurfaceTree(
            frame,
            popup.surface_id,
            popup.position.x,
            popup.position.y,
            null,
            null,
        );
    }
    if (self.generated_input_method_observer) |observer| {
        observer.refresh_popups(observer.context);
        for (self.generated_input_popups.items) |popup| {
            if (!popup.mapped) continue;
            try self.renderGeneratedCompound(frame, popup.surface_id, popup.position.x, popup.position.y);
        }
    }

    const drag_icon = self.mature_data_device.iconInfo();
    if (drag_icon) |info| {
        try self.renderSurfaceTree(
            frame,
            info.surface_id,
            info.x,
            info.y,
            null,
            null,
        );
    }
    const generated_drag_icon = self.generatedDragIconInfo();
    if (generated_drag_icon) |info| {
        try self.renderGeneratedCompound(frame, info.surface_id, info.x, info.y);
    }

    try self.renderWorkspaceTransition(frame);
    if (paint_primary_cursor) try self.renderSeatCursor(frame, &self.seat, false);
    if (paint_tablet_cursors) try self.renderTabletCursors(frame, false);
    return .{
        .top_fullscreen = top_fullscreen,
        .lower_layers_occluded = lower_layers_occluded,
    };
}

fn fullscreenOccludesLowerLayers(
    self: *Self,
    window: *const Scene.Window,
    output_rect: render.Rect,
) bool {
    const render_state = self.surface_registry.renderState(window.surface_id) orelse return false;
    return window_geometry.fullscreenRootOccludesOutput(
        window,
        render_state.logical_size,
        renderStateFullyOpaque(render_state),
        output_rect,
    );
}

fn hasBackgroundEffect(self: *Self) bool {
    const surfaces = self.compositor.surfaceStore();
    var iterator = surfaces.iterator();
    while (iterator.next()) |entry| {
        if (Surface.currentBlurRegion(surfaces, entry.id) == null) continue;
        const buffer = Surface.currentBuffer(surfaces, entry.id) orelse continue;
        if (!surfaceFullyOpaque(surfaces, entry.id, buffer)) return true;
    }
    return false;
}

fn presentSessionLockFrame(
    self: *Self,
    frame: *const OutputFrame,
    render_fence_fd: ?std.posix.fd_t,
    capture_source: ?ComposedCaptureSource,
) Renderer.Error!void {
    const lock_surface = self.session_lock.surfaceForOutput(frame.render_output.protocol_id);
    const presented = frame.render_output.backend.present(
        frame.presentation_damage.?,
        render_fence_fd,
        false,
    ) catch |err| switch (err) {
        error.OutputColorFallback => {
            frame.render_output.discardFrame();
            frame.output.cancelFrame();
            try self.refreshRenderOutputColorDescription(frame.render_output);
            self.damageFullOutput(frame.render_output);
            return;
        },
        error.OutputBusy => {
            if (!frame.render_output.retryOutputBusy()) return error.InvalidTarget;
            frame.render_output.backend.cancel();
            frame.render_output.discardFrame();
            frame.output.cancelFrame();
            self.damageFullOutput(frame.render_output);
            return;
        },
        else => {
            log.err("session-lock output presentation failed: {t}", .{err});
            return error.InvalidTarget;
        },
    };
    frame.render_output.commitFrame(
        .composited,
        frame.presentation_damage.?,
        frame.render_output.backend.compositedScanoutFormat(),
        render_fence_fd,
    );
    frame.render_output.lock_frame_pending = true;
    self.rememberSampledSurfaces(frame.render_output);
    frame.output.endFrame();
    self.completeSampledHeadlessFrames(frame.render_output.protocol_id);
    self.completeSampledGeneratedCursorFrames();
    self.scheduleGeneratedCallbackOnlyFrames(frame.render_output);
    self.color_management.refreshPreferred();
    self.foreign_toplevel_list.syncOutput(frame.render_output.protocol_id);
    if (lock_surface) |info| {
        if (self.headless_surface_forest.presentationClass(info.surface_id) != .session_lock)
            self.submitSurfaceTree(frame.output, info.surface_id);
    }
    if (frame.render_output.cursor_state == .software or
        frame.render_output.cursor_state == .deactivating)
        self.submitSeatCursor(frame.output, &self.seat, true);
    self.submitTabletCursors(frame.output, true);
    const callback_timestamp = presentation.Timestamp.fromNanoseconds(nowNanoseconds(self.io));
    try Surface.sendSubmittedFrameCallbacks(
        self.compositor.surfaceStore(),
        self.allocator,
        frame.output,
        callback_timestamp.milliseconds(),
    );
    try Surface.clearFifoBarriersForOutput(
        self.compositor.surfaceStore(),
        self.allocator,
        frame.output,
    );
    self.finishRepaintIfIdle();
    if (presented) |info| outputPresented(frame.render_output, info);
    self.captureOutputFrame(frame.render_output.protocol_id, capture_source);
    self.refreshKeyboardFocus();
}

fn renderSessionLockContents(
    self: *Self,
    frame: *const OutputFrame,
    paint_primary_cursor: bool,
    paint_tablet_cursors: bool,
) Renderer.Error!void {
    const lock_surface = self.session_lock.surfaceForOutput(frame.render_output.protocol_id);
    if (lock_surface) |info| {
        if (self.headless_surface_forest.presentationClass(info.surface_id) == .session_lock) {
            if (self.exactEligibleGeneratedSessionLockRootForOutput(frame.render_output.protocol_id)) |root|
                try self.renderGeneratedCompound(frame, root, info.position.x, info.position.y);
        } else try self.renderSurfaceTree(
            frame,
            info.surface_id,
            info.position.x,
            info.position.y,
            null,
            null,
        );
    }

    if (paint_primary_cursor) try self.renderSeatCursor(frame, &self.seat, true);
    if (paint_tablet_cursors) try self.renderTabletCursors(frame, true);
}

fn refreshKeyboardFocus(self: *Self) void {
    self.refreshKeyboardFocusWithGeneratedRetention(true);
}

fn refreshKeyboardFocusReplacingGenerated(self: *Self) void {
    self.refreshKeyboardFocusWithGeneratedRetention(false);
}

fn refreshKeyboardFocusWithGeneratedRetention(self: *Self, retain_generated: bool) void {
    if (self.session_lock.isLocked()) {
        const focus = self.sessionLockKeyboardFocus();
        if (focus) |surface| {
            if (self.headless_surface_forest.presentationClass(surface) == .session_lock) {
                if (self.exactEligibleGeneratedSessionLockRoot(surface) == null) {
                    self.applyMatureKeyboardFocus(null);
                    self.syncXwaylandFocus(null);
                    return;
                }
                const owner = self.seat.generatedSurfaceOwner(surface) orelse unreachable;
                _ = self.seat.applyGeneratedKeyboardFocus(.{ .surface = surface, .client = owner }, null);
            } else self.applyMatureKeyboardFocus(surface);
        } else self.applyMatureKeyboardFocus(null);
        self.syncXwaylandFocus(null);
        return;
    }
    const popup_focus = self.xdg_shell_core.popupKeyboardFocus();
    const layer_focus = self.layer_shell.keyboardFocus(popup_focus);
    if (layer_focus) |surface| {
        if (self.generatedLayerKeyboardFocus(surface)) |focus| {
            _ = self.seat.applyGeneratedKeyboardFocus(focus, null);
            self.syncXwaylandFocus(null);
            return;
        }
    }
    if (popup_focus) |root| {
        if (self.xdg_shell_core.popupRootLayerSurface(root) == null) if (self.managedGeneratedPopup(root)) |popup| {
            _ = self.seat.applyGeneratedKeyboardFocus(.{ .surface = root, .client = popup.client }, null);
            self.syncXwaylandFocus(null);
            return;
        };
    }
    const default_focus = layer_focus orelse
        self.xwayland_override_redirect_focus orelse
        self.window_manager.focusedSurface() orelse self.scene.focusedSurface();
    if (retain_generated and generatedFocusPolicyAllows(
        false,
        self.xdg_shell_core.hasPopupGrab(),
        layer_focus != null,
        self.xwayland_override_redirect_focus != null,
    )) if (self.seat.generatedKeyboardFocus()) |focus| {
        const root = self.headless_surface_forest.compoundRoot(focus.surface);
        if (root != null and std.meta.eql(root.?, focus.surface) and
            self.headless_surface_forest.presentationClass(root.?) == .background and
            self.headless_surface_forest.state(root.?).?.mapped_size != null and
            std.meta.eql(self.seat.generatedSurfaceOwner(root.?), focus.client))
        {
            _ = self.seat.applyGeneratedKeyboardFocus(focus, default_focus);
            self.syncXwaylandFocus(null);
            return;
        }
    };
    if (generatedFocusPolicyAllows(
        false,
        self.xdg_shell_core.hasPopupGrab(),
        layer_focus != null,
        self.xwayland_override_redirect_focus != null,
    )) if (self.window_manager.focusedSurface()) |root| {
        if (self.seat.generatedSurfaceOwner(root)) |client| {
            if (self.generatedManagedRootEligible(root, client)) {
                _ = self.seat.applyGeneratedKeyboardFocus(
                    .{ .surface = root, .client = client },
                    null,
                );
                self.syncXwaylandFocus(null);
                return;
            }
        }
    };
    self.applyMatureKeyboardFocus(default_focus);
    self.syncXwaylandFocus(default_focus);
}

fn generatedLayerKeyboardFocus(self: *Self, surface: SurfaceRegistry.Id) ?Seat.GeneratedKeyboardFocus {
    if (self.exactEligibleGeneratedLayerRoot(surface) != null) {
        return .{ .surface = surface, .client = self.seat.generatedSurfaceOwner(surface) orelse return null };
    }
    const popup = self.managedGeneratedPopup(surface) orelse return null;
    const layer_scene = self.xdg_shell_core.popupRootLayerSurface(surface) orelse return null;
    const layer_root = (self.scene.layerSurface(layer_scene) orelse return null).surface_id;
    if (self.exactEligibleGeneratedLayerRoot(layer_root) == null) return null;
    return .{ .surface = surface, .client = popup.client };
}

fn maturePolicyKeyboardFocus(self: *Self) ?Surface.Id {
    return self.layer_shell.keyboardFocus(
        self.xdg_shell_core.popupKeyboardFocus(),
    ) orelse
        self.xwayland_override_redirect_focus orelse
        self.window_manager.focusedSurface() orelse self.scene.focusedSurface();
}

fn applyMatureKeyboardFocus(self: *Self, requested: ?Surface.Id) void {
    _ = self.seat.applyMatureKeyboardFocus(requested);
}

fn focusGeneratedSurface(self: *Self, requested_root: SurfaceRegistry.Id) bool {
    if (!wayringPresentationEnabled(self.primaryRenderOutput().backend.backendKind())) return false;
    if (!generatedFocusPolicyAllows(
        self.session_lock.isLocked(),
        self.xdg_shell_core.hasPopupGrab(),
        self.layer_shell.keyboardFocus(self.xdg_shell_core.popupKeyboardFocus()) != null,
        self.xwayland_override_redirect_focus != null,
    )) return false;
    const root = self.headless_surface_forest.compoundRoot(requested_root) orelse return false;
    const state = self.headless_surface_forest.state(root) orelse return false;
    if (state.mapped_size == null) return false;
    const client = self.seat.generatedSurfaceOwner(root) orelse return false;
    const changed = self.seat.applyGeneratedKeyboardFocus(
        .{ .surface = root, .client = client },
        self.maturePolicyKeyboardFocus(),
    );
    self.refreshKeyboardFocus();
    return changed;
}

fn generatedFocusPolicyAllows(
    locked: bool,
    popup_grab: bool,
    layer_focus: bool,
    override_redirect_focus: bool,
) bool {
    return !locked and !popup_grab and !layer_focus and !override_redirect_focus;
}

test "generated focus cannot bypass mature shell and security policy" {
    try std.testing.expect(generatedFocusPolicyAllows(false, false, false, false));
    try std.testing.expect(!generatedFocusPolicyAllows(true, false, false, false));
    try std.testing.expect(!generatedFocusPolicyAllows(false, true, false, false));
    try std.testing.expect(!generatedFocusPolicyAllows(false, false, true, false));
    try std.testing.expect(!generatedFocusPolicyAllows(false, false, false, true));
}

fn renderSeatCursor(
    self: *Self,
    frame: *const OutputFrame,
    seat: *Seat,
    locked: bool,
) Renderer.Error!void {
    const info = self.seatCursorInfo(seat, locked) orelse return;
    try self.renderCursor(frame, info);
}

fn renderTabletCursors(
    self: *Self,
    frame: *const OutputFrame,
    locked: bool,
) Renderer.Error!void {
    var cursors = self.tablet.cursorIterator();
    while (cursors.next()) |info| {
        if (!self.tabletCursorVisible(info.focus_surface, locked)) continue;
        try self.renderCursor(frame, info.cursor);
    }
}

fn renderCursor(
    self: *Self,
    frame: *const OutputFrame,
    info: Seat.CursorInfo,
) Renderer.Error!void {
    switch (info) {
        .generated => |generated| {
            var iterator = self.headless_surface_forest.subtreeRenderIterator(generated.surface_id);
            while (iterator.next()) |entry| {
                const render_state = self.surface_registry.renderState(entry.id) orelse continue;
                std.debug.assert(std.meta.eql(entry.mapped_size, render_state.logical_size));
                const command = [_]render.Command{.{ .image = imageFromRenderState(
                    render_state,
                    .{
                        .position = .{
                            .x = generated.x +| entry.position.x,
                            .y = generated.y +| entry.position.y,
                        },
                        .rounded_clip = null,
                        .clip = null,
                    },
                    surfaceSampleTag(entry.id),
                ) }};
                try self.renderCommands(frame, &command);
            }
        },
        .surface => |surface| try self.renderSurfaceTree(
            frame,
            surface.surface_id,
            surface.x,
            surface.y,
            null,
            null,
        ),
        .shape => |shape| {
            const command = [_]render.Command{.{ .image = .{
                .x = shape.x,
                .y = shape.y,
                .size = shape.buffer.size,
                .buffer = shape.buffer,
            } }};
            try self.renderCommands(frame, &command);
        },
    }
}

fn submitSeatCursor(self: *Self, output: *Output, seat: *Seat, locked: bool) void {
    const info = self.seatCursorInfo(seat, locked) orelse return;
    self.submitCursor(output, info);
}

fn submitTabletCursors(self: *Self, output: *Output, locked: bool) void {
    var cursors = self.tablet.cursorIterator();
    while (cursors.next()) |info| {
        if (!self.tabletCursorVisible(info.focus_surface, locked)) continue;
        self.submitCursor(output, info.cursor);
    }
}

fn submitCursor(self: *Self, output: *Output, info: Seat.CursorInfo) void {
    switch (info) {
        .generated => {},
        .surface => |surface| self.submitSurfaceTree(output, surface.surface_id),
        .shape => {},
    }
}

fn seatCursorInfo(self: *Self, seat: *Seat, locked: bool) ?Seat.CursorInfo {
    if (locked) {
        const surface_id = seat.pointerFocusedSurface() orelse return null;
        const root = self.headless_surface_forest.compoundRoot(surface_id) orelse
            self.subcompositor.rootSurface(surface_id);
        if (!self.session_lock.ownsSurface(root)) return null;
    }
    return seat.cursorInfo();
}

fn tabletCursorVisible(self: *Self, focus_surface: Surface.Id, locked: bool) bool {
    if (!locked) return true;
    const root = self.headless_surface_forest.compoundRoot(focus_surface) orelse
        self.subcompositor.rootSurface(focus_surface);
    return self.session_lock.ownsSurface(root);
}

fn finishRepaintIfIdle(self: *Self) void {
    var render_outputs = self.render_outputs.iterator();
    while (render_outputs.next()) |entry| {
        const render_output = entry.value.*;
        if (render_output.repaint_needed or render_output.render_scheduled) return;
    }
    self.fractional_scale.refresh();
    self.refreshSurfaceOutputPreferences();
    Surface.discardUnsubmittedFeedback(
        self.compositor.surfaceStore(),
        self.allocator,
    ) catch self.terminate();
}

fn refreshSurfaceOutputPreferences(self: *Self) void {
    const default_scale = self.outputs.get(self.primaryRenderOutput().protocol_id).?.clientScale();
    const surfaces = self.compositor.surfaceStore();
    var surface_iterator = surfaces.iterator();
    while (surface_iterator.next()) |surface_entry| {
        var preferred_scale = default_scale;
        var found = false;
        var outputs = self.outputs.iterator();
        while (outputs.next()) |output_entry| {
            if (!output_entry.output.containsSurface(surface_entry.id)) continue;
            const output_scale = output_entry.output.clientScale();
            if (!found or output_scale > preferred_scale) preferred_scale = output_scale;
            found = true;
        }
        Surface.setPreferredBufferScale(surfaces, surface_entry.id, preferred_scale);
    }
}

fn renderLayerSurfaces(
    self: *Self,
    frame: *const OutputFrame,
    layer: Scene.Layer,
) Renderer.Error!void {
    var surfaces = self.scene.layerSurfaceIterator(layer);
    while (surfaces.next()) |entry| {
        const layer_surface = entry.layer_surface;
        if (!layer_surface.mapped) continue;
        const capture_id = try self.renderSurfaceTreeCapture(frame, layer_surface.surface_id, layer_surface.position.x, layer_surface.position.y, null, null);
        try self.renderSurfaceTreeContents(
            frame,
            layer_surface.surface_id,
            layer_surface.position.x,
            layer_surface.position.y,
            null,
            null,
            capture_id,
        );
    }
}

fn renderHeadlessSurfaces(self: *Self, frame: *const OutputFrame) Renderer.Error!void {
    if (!frame.render_output.backend.isHeadless()) return;
    var iterator = self.headless_surface_forest.renderIterator();
    while (iterator.next()) |entry| {
        if (self.headless_surface_forest.isCursorRole(entry.id)) continue;
        if (self.headless_surface_forest.isDragIconRole(entry.id)) continue;
        const mapped_size = entry.mapped_size;
        const render_state = self.surface_registry.renderState(entry.id) orelse continue;
        std.debug.assert(std.meta.eql(mapped_size, render_state.logical_size));
        const surface_rect: render.Rect = .{
            .x = entry.position.x,
            .y = entry.position.y,
            .width = mapped_size.width,
            .height = mapped_size.height,
        };
        if (surface_rect.intersection(frame.visible_rect) == null) continue;
        if (frame.track_visibility) try frame.output.markSurfaceVisible(entry.id);

        const capture_id: ?u32 = if (renderStateBlurBounds(
            frame,
            render_state,
            entry.position.x,
            entry.position.y,
            null,
            null,
        )) |rect| capture: {
            const blur = Scene.background_blur;
            const id = try allocateBackdropCaptureId(frame);
            const command = [_]render.Command{.{ .backdrop_capture = .{
                .id = id,
                .rect = rect,
                .radius = blur.radius,
                .downsample_level = blur.downsample_level,
                .finish = blur.finish,
            } }};
            try self.renderCommands(frame, &command);
            break :capture id;
        } else null;
        try self.renderSurfaceBackgroundEffect(
            frame,
            render_state,
            entry.position.x,
            entry.position.y,
            null,
            null,
            capture_id,
        );
        const command = [_]render.Command{.{ .image = imageFromRenderState(
            render_state,
            .{
                .position = .{ .x = entry.position.x, .y = entry.position.y },
                .rounded_clip = null,
                .clip = null,
            },
            surfaceSampleTag(entry.id),
        ) }};
        try self.renderCommands(frame, &command);
    }
}

/// Paints one scanner-backed compound from generated topology. The caller
/// owns its global translation; no mature Surface tree or Scene node is used.
fn renderGeneratedCompound(
    self: *Self,
    frame: *const OutputFrame,
    root: SurfaceRegistry.Id,
    x: i32,
    y: i32,
) Renderer.Error!void {
    var iterator = self.headless_surface_forest.subtreeRenderIterator(root);
    while (iterator.next()) |entry| {
        const render_state = self.surface_registry.renderState(entry.id) orelse continue;
        std.debug.assert(std.meta.eql(entry.mapped_size, render_state.logical_size));
        const entry_x = x +| entry.position.x;
        const entry_y = y +| entry.position.y;
        const bounds: render.Rect = .{
            .x = entry_x,
            .y = entry_y,
            .width = entry.mapped_size.width,
            .height = entry.mapped_size.height,
        };
        if (bounds.intersection(frame.visible_rect) == null) continue;
        if (frame.track_visibility) try frame.output.markSurfaceVisible(entry.id);
        const command = [_]render.Command{.{ .image = imageFromRenderState(
            render_state,
            .{
                .position = .{ .x = entry_x, .y = entry_y },
                .rounded_clip = null,
                .clip = null,
            },
            surfaceSampleTag(entry.id),
        ) }};
        try self.renderCommands(frame, &command);
    }
}

fn renderTilingDragPreview(
    self: *Self,
    frame: *const OutputFrame,
) Renderer.Error!void {
    const preview = self.window_manager.tilingDragPreview() orelse return;
    const command = [_]render.Command{tilingDragPreviewCommand(.{
        .x = preview.x,
        .y = preview.y,
        .width = preview.size.width,
        .height = preview.size.height,
    }, self.palette.tiling_drag_preview)};
    try self.renderCommands(frame, &command);
}

fn tilingDragPreviewCommand(rect: render.Rect, color: Config.Color) render.Command {
    std.debug.assert(rect.width > 0 and rect.height > 0);
    return .{ .shadow = .{
        .rect = rect,
        .corner_radius = 12,
        .blur_radius = 20,
        .spread = 0,
        .color = renderColor(color),
    } };
}

fn outputClearColor(palette: theme.Palette, locked: bool) render.Color {
    if (locked) return render.Color.rgba(0, 0, 0, 0xff);
    return renderColor(palette.desktop_background);
}

fn submitLayerSurfaces(self: *Self, output: *Output, layer: Scene.Layer) void {
    var surfaces = self.scene.layerSurfaceIterator(layer);
    while (surfaces.next()) |entry| {
        if (entry.layer_surface.mapped) {
            if (self.exactEligibleGeneratedLayerRoot(entry.layer_surface.surface_id) != null)
                self.submitGeneratedCompound(output, entry.layer_surface.surface_id)
            else
                self.submitSurfaceTree(output, entry.layer_surface.surface_id);
        }
    }
}

fn renderLayerPopups(self: *Self, frame: *const OutputFrame) Renderer.Error!void {
    inline for (.{
        Scene.Layer.background,
        Scene.Layer.bottom,
        Scene.Layer.top,
        Scene.Layer.overlay,
    }) |layer| {
        var roots = self.scene.layerSurfaceIterator(layer);
        while (roots.next()) |root| {
            var popups = self.scene.layerPopupIterator(root.id);
            while (popups.next()) |entry| {
                if (!entry.popup.mapped) continue;
                const generated = self.managedGeneratedPopup(entry.popup.surface_id) != null;
                const size = if (generated)
                    (self.headless_surface_forest.state(entry.popup.surface_id) orelse continue).mapped_size orelse continue
                else
                    (Surface.currentBuffer(self.compositor.surfaceStore(), entry.popup.surface_id) orelse continue).logical_size;
                const geometry = entry.popup.content_geometry orelse Scene.ContentGeometry{ .size = size };
                try self.renderSurfaceTree(
                    frame,
                    entry.popup.surface_id,
                    entry.position.x -| geometry.offset.x,
                    entry.position.y -| geometry.offset.y,
                    null,
                    null,
                );
            }
        }
    }
}

fn submitLayerPopups(self: *Self, output: *Output) void {
    inline for (.{
        Scene.Layer.background,
        Scene.Layer.bottom,
        Scene.Layer.top,
        Scene.Layer.overlay,
    }) |layer| {
        var roots = self.scene.layerSurfaceIterator(layer);
        while (roots.next()) |root| {
            var popups = self.scene.layerPopupIterator(root.id);
            while (popups.next()) |entry| {
                if (!entry.popup.mapped) continue;
                if (self.exactEligibleGeneratedPopupRoot(entry.popup.surface_id))
                    self.submitGeneratedCompound(output, entry.popup.surface_id)
                else
                    self.submitSurfaceTree(output, entry.popup.surface_id);
            }
        }
    }
}

fn renderCommands(
    self: *Self,
    frame: *const OutputFrame,
    commands: []const render.Command,
) Renderer.Error!void {
    _ = frame;
    try self.renderer.append(commands);
}

fn scalePremultipliedColor(color: render.Color, opacity: u32) render.Color {
    const maximum: u64 = std.math.maxInt(u32);
    return .{
        .red = @intCast((@as(u64, color.red) * opacity + maximum / 2) / maximum),
        .green = @intCast((@as(u64, color.green) * opacity + maximum / 2) / maximum),
        .blue = @intCast((@as(u64, color.blue) * opacity + maximum / 2) / maximum),
        .alpha = @intCast((@as(u64, color.alpha) * opacity + maximum / 2) / maximum),
    };
}

fn effectsWithOpacity(effects: Scene.Effects, opacity: u32) Scene.Effects {
    var result = effects;
    if (result.ambient_shadow) |*shadow| {
        shadow.color = scalePremultipliedColor(shadow.color, opacity);
    }
    if (result.key_shadow) |*shadow| {
        shadow.color = scalePremultipliedColor(shadow.color, opacity);
    }
    return result;
}

fn bordersWithOpacity(borders: ?Scene.Borders, opacity: u32) ?Scene.Borders {
    var result = borders orelse return null;
    result.color = scalePremultipliedColor(result.color, opacity);
    return result;
}

test "transition opacity scales every premultiplied color component" {
    const color = render.Color.rgba(180, 90, 45, 128);
    try std.testing.expectEqual(
        render.Color.rgba(0, 0, 0, 0),
        scalePremultipliedColor(color, 0),
    );
    try std.testing.expectEqual(
        color,
        scalePremultipliedColor(color, std.math.maxInt(u32)),
    );
    const half = scalePremultipliedColor(color, std.math.maxInt(u32) / 2);
    try std.testing.expect(half.red <= half.alpha);
    try std.testing.expect(half.green <= half.alpha);
    try std.testing.expect(half.blue <= half.alpha);
    try std.testing.expect(half.alpha >= 63 and half.alpha <= 64);
}

fn renderShadow(
    self: *Self,
    frame: *const OutputFrame,
    rect: render.Rect,
    corner_radius: u32,
    shadow: Scene.Shadow,
    clip: ?render.Rect,
) Renderer.Error!void {
    const shadow_command = [_]render.Command{
        .{ .shadow = .{
            .rect = rect.translated(shadow.offset.x, shadow.offset.y),
            .corner_radius = corner_radius,
            .blur_radius = shadow.blur_radius,
            .spread = shadow.spread,
            .color = shadow.color,
            .cutout = .{
                .rect = rect,
                .radius = corner_radius,
            },
            .clip = clip,
        } },
    };
    try self.renderCommands(frame, &shadow_command);
}

fn renderShadows(
    self: *Self,
    frame: *const OutputFrame,
    rect: render.Rect,
    effects: Scene.Effects,
    borders: ?Scene.Borders,
    clip: ?render.Rect,
) Renderer.Error!void {
    const caster = window_geometry.shadowCaster(rect, borders, effects.corner_radius);
    if (effects.ambient_shadow) |shadow| {
        try self.renderShadow(frame, caster.rect, caster.corner_radius, shadow, clip);
    }
    if (effects.key_shadow) |shadow| {
        try self.renderShadow(frame, caster.rect, caster.corner_radius, shadow, clip);
    }
}

fn renderRetainedSnapshot(
    self: *Self,
    frame: *const OutputFrame,
    source: render.ImageSource,
    destination: render.Rect,
    source_rect: ?render.SourceRect,
    clip: ?render.Rect,
    rounded_clip: ?render.RoundedClip,
) Renderer.Error!void {
    try self.renderCommands(frame, &.{.{ .crossfade = .{
        .destination = destination,
        .old = source,
        .new = source,
        .old_source = source_rect,
        .new_source = source_rect,
        .factor = 0,
        .clip = clip,
        .rounded_clip = rounded_clip,
    } }});
}

fn renderWorkspaceTransition(self: *Self, frame: *const OutputFrame) Renderer.Error!void {
    const index = workspaceTransitionIndex(self, frame.render_output.protocol_id) orelse return;
    const transition = &self.workspace_transitions.items[index];
    try self.renderCommands(frame, &.{.{ .crossfade = .{
        .destination = renderAnimationRect(transition.rect),
        .old = transition.old.source,
        .new = transition.transparent.source,
        .factor = if (transition.phase == .animating)
            WindowAnimation.linearProgress(
                transition.start,
                self.animation_now,
                WindowAnimation.fade_duration_nanoseconds,
            )
        else
            0,
    } }});
}

fn renderElasticGrowthSnapshot(
    self: *Self,
    frame: *const OutputFrame,
    transition: *const WindowTransition,
    animated_destination: render.Rect,
    rounded_clip: ?render.RoundedClip,
) Renderer.Error!void {
    const old = transition.old_rect;
    const target = transition.target_rect;
    const horizontal = target.width > old.width and target.height == old.height;
    const vertical = target.height > old.height and target.width == old.width;
    if (!horizontal and !vertical) {
        try self.renderRetainedSnapshot(
            frame,
            transition.old.source,
            animated_destination,
            null,
            null,
            rounded_clip,
        );
        return;
    }

    const old_start = if (horizontal) old.x else old.y;
    const old_length = if (horizontal) old.width else old.height;
    const animated_start = if (horizontal) animated_destination.x else animated_destination.y;
    const animated_length = if (horizontal) animated_destination.width else animated_destination.height;
    const target_start = if (horizontal) target.x else target.y;
    const target_length = if (horizontal) target.width else target.height;
    const old_end = @as(i64, old_start) + old_length;
    const target_end = @as(i64, target_start) + target_length;
    const moving_end = @abs(target_end - old_end) >=
        @abs(@as(i64, target_start) - old_start);
    const slices = WindowAnimation.growthSlices(
        old_start,
        old_length,
        animated_start,
        animated_length,
        moving_end,
    );
    const source_size = transition.old.source.size();
    const source_axis_length = if (horizontal) source_size.width else source_size.height;
    const source_scale = @as(f64, @floatFromInt(source_axis_length)) /
        @as(f64, @floatFromInt(old_length));
    for (slices.slice()) |slice| {
        const source_start = if (slice.source_start == 0)
            0
        else
            @as(f64, @floatFromInt(slice.source_start)) * source_scale;
        const source_offset_end = slice.source_start + slice.source_length;
        const source_end = if (source_offset_end == old_length)
            @as(f64, @floatFromInt(source_axis_length))
        else
            @as(f64, @floatFromInt(source_offset_end)) * source_scale;
        const source: render.SourceRect = if (horizontal) .{
            .x = source_start,
            .y = 0,
            .width = source_end - source_start,
            .height = @floatFromInt(source_size.height),
        } else .{
            .x = 0,
            .y = source_start,
            .width = @floatFromInt(source_size.width),
            .height = source_end - source_start,
        };
        const destination: render.Rect = if (horizontal) .{
            .x = slice.destination_start,
            .y = animated_destination.y,
            .width = slice.destination_length,
            .height = animated_destination.height,
        } else .{
            .x = animated_destination.x,
            .y = slice.destination_start,
            .width = animated_destination.width,
            .height = slice.destination_length,
        };
        try self.renderRetainedSnapshot(
            frame,
            transition.old.source,
            destination,
            source,
            animated_destination,
            rounded_clip,
        );
    }
}

fn renderWindowTransition(
    self: *Self,
    frame: *const OutputFrame,
    transition: *const WindowTransition,
    configured_effects: Scene.Effects,
    configured_borders: ?Scene.Borders,
    mark_surfaces: bool,
) Renderer.Error!void {
    if (!std.meta.eql(transition.output_id, frame.render_output.protocol_id)) return;
    const factor = if (transition.phase != .waiting)
        WindowAnimation.progress(
            transition.start,
            self.animation_now,
            transition.duration,
            transition.easing,
        )
    else
        0;
    const content_factor = if (transition.phase != .waiting)
        WindowAnimation.contentProgress(
            transition.start,
            self.animation_now,
            transition.duration,
        )
    else
        0;
    const opacity = switch (transition.kind) {
        .reflow => std.math.maxInt(u32),
        .appearance => WindowAnimation.appearanceProgress(
            transition.start,
            self.animation_now,
        ),
        .disappearance => std.math.maxInt(u32) - WindowAnimation.disappearanceProgress(
            transition.start,
            self.animation_now,
            transition.duration,
        ),
    };
    const effects = effectsWithOpacity(configured_effects, opacity);
    const borders = bordersWithOpacity(configured_borders, opacity);
    const animated_rect = WindowAnimation.constrainSplitOuterEdge(
        WindowAnimation.interpolate(transition.old_rect, transition.target_rect, factor),
        transition.old_rect,
        transition.target_rect,
    );
    const animated_destination = renderAnimationRect(animated_rect);
    if (animated_destination.width == 0 or animated_destination.height == 0) return;
    try self.renderShadows(frame, animated_destination, effects, borders, null);
    const rounded_clip: ?render.RoundedClip = if (effects.corner_radius == 0)
        null
    else
        .{ .rect = animated_destination, .radius = effects.corner_radius };
    const target = if (transition.target) |snapshot| snapshot.source else transition.old.source;
    if (transition.kind == .reflow) {
        const old_area = @as(u64, transition.old_rect.width) * transition.old_rect.height;
        const target_area = @as(u64, transition.target_rect.width) * transition.target_rect.height;
        const target_destination = renderAnimationRect(transition.target_rect);
        const shrinking_old_source = if (target_area < old_area)
            WindowAnimation.targetSourceRect(
                transition.old_rect,
                transition.target_rect,
                transition.old.source.size(),
            )
        else
            null;
        if (target_area > old_area) {
            try self.renderElasticGrowthSnapshot(
                frame,
                transition,
                animated_destination,
                rounded_clip,
            );
            if (transition.target) |target_snapshot| {
                const reveal_rect = WindowAnimation.targetReveal(
                    transition.old_rect,
                    transition.target_rect,
                    content_factor,
                );
                const reveal = renderAnimationRect(reveal_rect);
                if (animated_destination.intersection(reveal)) |target_clip| {
                    try self.renderRetainedSnapshot(
                        frame,
                        target_snapshot.source,
                        target_destination,
                        null,
                        target_clip,
                        rounded_clip,
                    );
                }
            }
        } else if (shrinking_old_source) |old_source| {
            const old_destination = renderAnimationRect(transition.old_rect);
            try self.renderRetainedSnapshot(
                frame,
                transition.old.source,
                old_destination,
                null,
                animated_destination,
                rounded_clip,
            );
            const crossfade_factor = content_factor;
            if (crossfade_factor != 0) {
                if (transition.target) |target_snapshot| {
                    if (animated_destination.intersection(target_destination)) |target_clip| {
                        try self.renderCommands(frame, &.{.{ .crossfade = .{
                            .destination = target_destination,
                            .old = transition.old.source,
                            .new = target_snapshot.source,
                            .old_source = old_source,
                            .factor = crossfade_factor,
                            .clip = target_clip,
                            .rounded_clip = rounded_clip,
                        } }});
                    }
                }
            }
        } else {
            try self.renderCommands(frame, &.{.{ .crossfade = .{
                .destination = animated_destination,
                .old = transition.old.source,
                .new = target,
                .factor = content_factor,
                .rounded_clip = rounded_clip,
            } }});
        }
    } else {
        const content_rect = if (transition.kind == .appearance)
            transition.target_rect
        else
            transition.old_rect;
        const content_destination = renderAnimationRect(content_rect);
        const fade_factor = if (transition.kind == .appearance)
            opacity
        else
            std.math.maxInt(u32) - opacity;
        try self.renderCommands(frame, &.{.{ .crossfade = .{
            .destination = content_destination,
            .old = transition.old.source,
            .new = target,
            .factor = fade_factor,
            .clip = animated_destination,
            .rounded_clip = rounded_clip,
        } }});
    }
    try self.renderBorders(
        frame,
        animated_destination,
        borders,
        effects.corner_radius,
        null,
    );
    if (mark_surfaces and frame.track_visibility) {
        try self.markSurfaceTreeVisible(frame.output, transition.root_id);
        var below = self.scene.decorationIterator(transition.scene_id, .below);
        while (below.next()) |entry| if (entry.decoration.mapped)
            try self.markSurfaceTreeVisible(frame.output, entry.decoration.surface_id);
        var above = self.scene.decorationIterator(transition.scene_id, .above);
        while (above.next()) |entry| if (entry.decoration.mapped)
            try self.markSurfaceTreeVisible(frame.output, entry.decoration.surface_id);
    }
}

fn renderDetachedWindowTransitions(
    self: *Self,
    frame: *const OutputFrame,
) Renderer.Error!void {
    for (self.window_transitions.items) |*transition| {
        if (transition.kind != .disappearance or !transition.detached) continue;
        try self.renderWindowTransition(
            frame,
            transition,
            transition.effects orelse .{},
            transition.borders,
            false,
        );
    }
}

fn renderWindow(
    self: *Self,
    frame: *const OutputFrame,
    id: Scene.Id,
    window: *const Scene.Window,
) Renderer.Error!void {
    const root_render_state = self.surface_registry.renderState(window.surface_id) orelse return;
    const content_geometry = window.content_geometry orelse Scene.ContentGeometry{
        .size = root_render_state.logical_size,
    };
    const content_rect = window_geometry.windowContentRect(window, content_geometry.size) orelse return;
    if (transitionIndex(self, id)) |transition_index| {
        const transition = &self.window_transitions.items[transition_index];
        if (transition.kind == .disappearance) return;
        try self.renderWindowTransition(
            frame,
            transition,
            window.effects,
            window.borders,
            true,
        );
        return;
    }
    const window_clip = if (window.clip_box) |clip_box|
        clip_box.translated(window.position.x, window.position.y)
    else
        null;
    const shadow_clip = if (window.shadow_clip_box orelse window.clip_box) |clip_box|
        clip_box.translated(window.position.x, window.position.y)
    else
        null;
    const tree_x = window.position.x -| content_geometry.offset.x;
    const tree_y = window.position.y -| content_geometry.offset.y;
    const rounded_clip: ?render.RoundedClip = if (window.effects.corner_radius == 0)
        null
    else
        .{ .rect = content_rect, .radius = window.effects.corner_radius };
    var content_visible = true;
    var content_clip = if (window.content_clip_box != null) content_rect else null;
    if (window_clip) |clip| {
        if (content_clip) |current| {
            content_clip = current.intersection(clip) orelse no_content: {
                content_visible = false;
                break :no_content null;
            };
        } else {
            content_clip = clip;
        }
    }
    var capture_id: ?u32 = null;
    if (content_visible) {
        capture_id = try self.renderSurfaceTreeCapture(
            frame,
            window.surface_id,
            tree_x,
            tree_y,
            rounded_clip,
            content_clip,
        );
    }
    try self.renderShadows(frame, content_rect, window.effects, window.borders, shadow_clip);
    try self.renderWindowDecorations(frame, id, window, .below, window_clip);
    if (content_visible) {
        try self.renderSurfaceTreeContents(
            frame,
            window.surface_id,
            tree_x,
            tree_y,
            rounded_clip,
            content_clip,
            capture_id,
        );
    }
    try self.renderBorders(
        frame,
        content_rect,
        window.borders,
        window.effects.corner_radius,
        window_clip,
    );
    try self.renderWindowDecorations(frame, id, window, .above, window_clip);
    try self.renderWindowPopups(frame, id);
}

fn renderWindowPopups(
    self: *Self,
    frame: *const OutputFrame,
    window_id: Scene.Id,
) Renderer.Error!void {
    var popups = self.scene.popupIterator(window_id);
    while (popups.next()) |entry| {
        const popup = entry.popup;
        if (!popup.mapped) continue;
        if (self.managedGeneratedPopup(popup.surface_id) != null) {
            const state = self.headless_surface_forest.state(popup.surface_id) orelse continue;
            const content_geometry = popup.content_geometry orelse Scene.ContentGeometry{
                .size = state.mapped_size orelse continue,
            };
            try self.renderSurfaceTree(
                frame,
                popup.surface_id,
                entry.position.x -| content_geometry.offset.x,
                entry.position.y -| content_geometry.offset.y,
                null,
                null,
            );
            continue;
        }
        const buffer = Surface.currentBuffer(
            self.compositor.surfaceStore(),
            popup.surface_id,
        ) orelse continue;
        const content_geometry = popup.content_geometry orelse Scene.ContentGeometry{
            .size = buffer.logical_size,
        };
        try self.renderSurfaceTree(
            frame,
            popup.surface_id,
            entry.position.x -| content_geometry.offset.x,
            entry.position.y -| content_geometry.offset.y,
            null,
            null,
        );
    }
}

fn renderSurfaceTree(
    self: *Self,
    frame: *const OutputFrame,
    surface_id: Surface.Id,
    x: i32,
    y: i32,
    rounded_clip: ?render.RoundedClip,
    clip: ?render.Rect,
) Renderer.Error!void {
    const capture_id = try self.renderSurfaceTreeCapture(frame, surface_id, x, y, rounded_clip, clip);
    try self.renderSurfaceTreeContents(frame, surface_id, x, y, rounded_clip, clip, capture_id);
}

fn renderSurfaceTreeCapture(
    self: *Self,
    frame: *const OutputFrame,
    surface_id: Surface.Id,
    x: i32,
    y: i32,
    rounded_clip: ?render.RoundedClip,
    clip: ?render.Rect,
) Renderer.Error!?u32 {
    if (self.sceneGeneratedCompound(surface_id)) {
        if (self.generatedManagedBlurBounds(
            frame,
            surface_id,
            x,
            y,
            rounded_clip,
            clip,
        )) |rect| {
            const blur = Scene.background_blur;
            const capture_id = try allocateBackdropCaptureId(frame);
            const command = [_]render.Command{.{ .backdrop_capture = .{
                .id = capture_id,
                .rect = rect,
                .radius = blur.radius,
                .downsample_level = blur.downsample_level,
                .finish = blur.finish,
            } }};
            try self.renderCommands(frame, &command);
            return capture_id;
        }
        return null;
    }
    if (self.surfaceTreeBlurBounds(frame, surface_id, x, y, rounded_clip, clip)) |rect| {
        const blur = Scene.background_blur;
        const capture_id = try allocateBackdropCaptureId(frame);
        const command = [_]render.Command{.{ .backdrop_capture = .{
            .id = capture_id,
            .rect = rect,
            .radius = blur.radius,
            .downsample_level = blur.downsample_level,
            .finish = blur.finish,
        } }};
        try self.renderCommands(frame, &command);
        return capture_id;
    }
    return null;
}

fn renderSurfaceTreeContents(
    self: *Self,
    frame: *const OutputFrame,
    surface_id: Surface.Id,
    x: i32,
    y: i32,
    rounded_clip: ?render.RoundedClip,
    clip: ?render.Rect,
    capture_id: ?u32,
) Renderer.Error!void {
    if (self.sceneGeneratedCompound(surface_id)) {
        var iterator = self.headless_surface_forest.subtreeRenderIterator(surface_id);
        while (iterator.next()) |entry| {
            const render_state = self.surface_registry.renderState(entry.id) orelse continue;
            std.debug.assert(std.meta.eql(entry.mapped_size, render_state.logical_size));
            const entry_x = x +| entry.position.x;
            const entry_y = y +| entry.position.y;
            const surface_rect: render.Rect = .{
                .x = entry_x,
                .y = entry_y,
                .width = render_state.logical_size.width,
                .height = render_state.logical_size.height,
            };
            const visible_rect = surface_rect.intersection(frame.visible_rect) orelse continue;
            if (clip) |clip_rect| {
                if (visible_rect.intersection(clip_rect) == null) continue;
            }
            if (frame.track_visibility) try frame.output.markSurfaceVisible(entry.id);
            try self.renderSurfaceBackgroundEffect(
                frame,
                render_state,
                entry_x,
                entry_y,
                rounded_clip,
                clip,
                capture_id,
            );
            const image_command = [_]render.Command{.{ .image = imageFromRenderState(
                render_state,
                .{
                    .position = .{ .x = entry_x, .y = entry_y },
                    .rounded_clip = rounded_clip,
                    .clip = clip,
                },
                surfaceSampleTag(entry.id),
            ) }};
            try self.renderCommands(frame, &image_command);
        }
        return;
    }
    if (self.surface_registry.renderState(surface_id) == null) return;

    var stack = self.subcompositor.stackIterator(surface_id);
    while (stack.next()) |entry| switch (entry) {
        .parent => {
            const render_state = self.surface_registry.renderState(surface_id) orelse continue;
            const surface_rect: render.Rect = .{
                .x = x,
                .y = y,
                .width = render_state.logical_size.width,
                .height = render_state.logical_size.height,
            };
            const visible_rect = surface_rect.intersection(frame.visible_rect) orelse continue;
            if (clip) |clip_rect| {
                if (visible_rect.intersection(clip_rect) == null) continue;
            }
            if (frame.track_visibility) {
                try frame.output.markSurfaceVisible(surface_id);
                Surface.markFifoBarrierVisible(
                    self.compositor.surfaceStore(),
                    surface_id,
                    frame.output,
                );
            }
            try self.renderSurfaceBackgroundEffect(
                frame,
                render_state,
                x,
                y,
                rounded_clip,
                clip,
                capture_id,
            );
            const image_command = [_]render.Command{
                .{ .image = imageFromRenderState(render_state, .{
                    .position = .{ .x = x, .y = y },
                    .rounded_clip = rounded_clip,
                    .clip = clip,
                }, surfaceSampleTag(surface_id)) },
            };
            try self.renderCommands(frame, &image_command);
        },
        .child => |child| try self.renderSurfaceTreeContents(
            frame,
            child.surface_id,
            x +| child.position.x,
            y +| child.position.y,
            rounded_clip,
            clip,
            capture_id,
        ),
    };
}

fn generatedManagedBlurBounds(
    self: *Self,
    frame: *const OutputFrame,
    root: SurfaceRegistry.Id,
    x: i32,
    y: i32,
    rounded_clip: ?render.RoundedClip,
    clip: ?render.Rect,
) ?render.Rect {
    var result: ?render.Rect = null;
    var iterator = self.headless_surface_forest.subtreeRenderIterator(root);
    while (iterator.next()) |entry| {
        const render_state = self.surface_registry.renderState(entry.id) orelse continue;
        std.debug.assert(std.meta.eql(entry.mapped_size, render_state.logical_size));
        if (renderStateBlurBounds(
            frame,
            render_state,
            x +| entry.position.x,
            y +| entry.position.y,
            rounded_clip,
            clip,
        )) |rect| result = if (result) |old| old.unionWith(rect) else rect;
    }
    return result;
}

fn surfaceTreeBlurBounds(
    self: *Self,
    frame: *const OutputFrame,
    surface_id: Surface.Id,
    x: i32,
    y: i32,
    rounded_clip: ?render.RoundedClip,
    clip: ?render.Rect,
) ?render.Rect {
    if (self.surface_registry.renderState(surface_id) == null) return null;
    var result: ?render.Rect = null;
    var stack = self.subcompositor.stackIterator(surface_id);
    while (stack.next()) |entry| switch (entry) {
        .parent => {
            const render_state = self.surface_registry.renderState(surface_id) orelse continue;
            if (renderStateBlurBounds(
                frame,
                render_state,
                x,
                y,
                rounded_clip,
                clip,
            )) |rect| result = if (result) |old| old.unionWith(rect) else rect;
        },
        .child => |child| {
            if (self.surfaceTreeBlurBounds(
                frame,
                child.surface_id,
                x +| child.position.x,
                y +| child.position.y,
                rounded_clip,
                clip,
            )) |child_rect| result = if (result) |old| old.unionWith(child_rect) else child_rect;
        },
    };
    return result;
}

fn renderStateBlurBounds(
    frame: *const OutputFrame,
    render_state: SurfaceRegistry.RenderState,
    x: i32,
    y: i32,
    rounded_clip: ?render.RoundedClip,
    clip: ?render.Rect,
) ?render.Rect {
    if (renderStateFullyOpaque(render_state)) return null;
    const region = render_state.blur_region orelse return null;
    var result: ?render.Rect = null;
    var rectangles = region.rectangleIterator();
    while (rectangles.next()) |rectangle| {
        var effect = (surfaceEffectRect(rectangle, render_state.logical_size) orelse continue)
            .translated(x, y);
        effect = effect.intersection(frame.visible_rect) orelse continue;
        if (rounded_clip) |rounded| effect = effect.intersection(rounded.rect) orelse continue;
        if (clip) |clip_rect| effect = effect.intersection(clip_rect) orelse continue;
        result = if (result) |old| old.unionWith(effect) else effect;
    }
    return result;
}

fn renderSurfaceBackgroundEffect(
    self: *Self,
    frame: *const OutputFrame,
    render_state: SurfaceRegistry.RenderState,
    x: i32,
    y: i32,
    rounded_clip: ?render.RoundedClip,
    clip: ?render.Rect,
    capture_id: ?u32,
) Renderer.Error!void {
    const blur = Scene.background_blur;
    if (renderStateFullyOpaque(render_state)) return;
    const region = render_state.blur_region orelse return;
    var rectangles = region.rectangleIterator();
    while (rectangles.next()) |rectangle| {
        var effect_rect = surfaceEffectRect(rectangle, render_state.logical_size) orelse continue;
        effect_rect = effect_rect.translated(x, y);
        if (effect_rect.intersection(frame.visible_rect) == null) continue;
        if (clip) |clip_rect| {
            if (effect_rect.intersection(clip_rect) == null) continue;
        }
        var corner_radius: u32 = 0;
        if (rounded_clip) |rounded| {
            effect_rect = effect_rect.intersection(rounded.rect) orelse continue;
            if (std.meta.eql(effect_rect, rounded.rect)) corner_radius = rounded.radius;
        }
        const backdrop_capture_id = capture_id orelse return error.InvalidTarget;
        const command = [_]render.Command{.{ .backdrop_blur = .{
            .capture_id = backdrop_capture_id,
            .rect = effect_rect,
            .corner_radius = corner_radius,
            .radius = blur.radius,
            .downsample_level = blur.downsample_level,
            .finish = blur.finish,
            .clip = clip,
        } }};
        try self.renderCommands(frame, &command);
    }
}

const ImagePlacement = struct {
    position: render.Position,
    rounded_clip: ?render.RoundedClip,
    clip: ?render.Rect,
};

fn imageFromRenderState(
    render_state: SurfaceRegistry.RenderState,
    placement: ImagePlacement,
    sample_tag: ?u64,
) render.Image {
    return .{
        .x = placement.position.x,
        .y = placement.position.y,
        .size = render_state.logical_size,
        .buffer = render_state.buffer,
        .sample_tag = sample_tag,
        .source = render_state.source,
        .transform = render_state.transform,
        .rounded_clip = placement.rounded_clip,
        .clip = placement.clip,
        .is_opaque = renderStateFullyOpaque(render_state),
        .opaque_region = renderStateOpaqueRegion(render_state, placement),
        .alpha_multiplier = render_state.alpha_multiplier,
    };
}

fn renderStateFullyOpaque(render_state: SurfaceRegistry.RenderState) bool {
    if (render_state.alpha_multiplier != std.math.maxInt(u32)) return false;
    if (render_state.force_opaque) return true;
    const region = render_state.opaque_region orelse return false;
    return region.coversRectangle(
        0,
        0,
        render_state.logical_size.width,
        render_state.logical_size.height,
    );
}

fn renderStateOpaqueRegion(
    render_state: SurfaceRegistry.RenderState,
    placement: ImagePlacement,
) render.OpaqueRegion {
    var result: render.OpaqueRegion = .{};
    if (render_state.alpha_multiplier != std.math.maxInt(u32) or
        placement.rounded_clip != null or render_state.force_opaque)
    {
        return result;
    }
    const region = render_state.opaque_region orelse return result;
    if (region.coversRectangle(
        0,
        0,
        render_state.logical_size.width,
        render_state.logical_size.height,
    )) return result;
    var rectangles = region.rectangleIterator();
    while (rectangles.next()) |rectangle| {
        var opaque_rect = (surfaceEffectRect(
            rectangle,
            render_state.logical_size,
        ) orelse continue).translated(placement.position.x, placement.position.y);
        if (placement.clip) |clip_rect| {
            opaque_rect = opaque_rect.intersection(clip_rect) orelse continue;
        }
        if (!result.append(opaque_rect)) break;
    }
    return result;
}

fn expectImagesEquivalent(expected: render.Image, actual: render.Image) !void {
    try std.testing.expectEqual(expected.x, actual.x);
    try std.testing.expectEqual(expected.y, actual.y);
    try std.testing.expectEqual(expected.size, actual.size);
    try std.testing.expect(std.meta.eql(expected.buffer, actual.buffer));
    try std.testing.expectEqual(expected.sample_tag, actual.sample_tag);
    try std.testing.expectEqual(expected.source, actual.source);
    try std.testing.expectEqual(expected.transform, actual.transform);
    try std.testing.expectEqual(expected.rounded_clip, actual.rounded_clip);
    try std.testing.expectEqual(expected.clip, actual.clip);
    try std.testing.expectEqual(expected.is_opaque, actual.is_opaque);
    try std.testing.expectEqualSlices(
        render.Rect,
        expected.opaque_region.slice(),
        actual.opaque_region.slice(),
    );
    try std.testing.expectEqual(expected.alpha_multiplier, actual.alpha_multiplier);
}

test "reproducible scene: render-state surface images preserve mature commands and scanout" {
    const DmabufCallbacks = struct {
        fn retain(_: *anyopaque) void {}
        fn release(_: *anyopaque) void {}
        fn beginCpuRead(_: *anyopaque) bool {
            return true;
        }
        fn endCpuRead(_: *anyopaque) bool {
            return true;
        }
        fn exportReadFence(_: *anyopaque, _: u8) ?std.posix.fd_t {
            return null;
        }
    };

    const sample_tag: u64 = 0x9abc_def0_1234_5678;
    var copied_xrgb_pixels = [_]u32{
        0xff10_2030,
        0xff40_5060,
        0xff70_8090,
        0xffa0_b0c0,
    };
    const copied_xrgb_damage = [_]render.Rect{.{
        .x = 1,
        .y = 0,
        .width = 1,
        .height = 2,
    }};
    const copied_xrgb: render.PixelBuffer = .{
        .size = .{ .width = 2, .height = 2 },
        .stride_pixels = 2,
        .pixels = &copied_xrgb_pixels,
        .source_cache = .{ .id = 41, .version = 7 },
        .source_damage = &copied_xrgb_damage,
    };
    const rounded_placement: ImagePlacement = .{
        .position = .{ .x = -4, .y = 9 },
        .rounded_clip = .{
            .rect = .{ .x = -4, .y = 9, .width = 2, .height = 2 },
            .radius = 1,
        },
        .clip = .{ .x = -3, .y = 9, .width = 1, .height = 2 },
    };
    try expectImagesEquivalent(.{
        .x = -4,
        .y = 9,
        .size = .{ .width = 2, .height = 2 },
        .buffer = copied_xrgb,
        .sample_tag = sample_tag,
        .rounded_clip = rounded_placement.rounded_clip,
        .clip = rounded_placement.clip,
        .is_opaque = true,
    }, imageFromRenderState(.{
        .buffer = copied_xrgb,
        .logical_size = .{ .width = 2, .height = 2 },
        .force_opaque = true,
    }, rounded_placement, sample_tag));

    var partial_opaque = Region.init();
    defer partial_opaque.deinit();
    try partial_opaque.add(-2, 1, 4, 4);
    var copied_argb_pixels = [_]u32{0x8010_2030} ** 48;
    const copied_argb_damage = [_]render.Rect{
        .{ .x = 0, .y = 1, .width = 3, .height = 2 },
        .{ .x = 6, .y = 4, .width = 2, .height = 2 },
    };
    const p3: render.ColorDescription = .{
        .primaries = render.display_p3_chromaticities,
        .named_primaries = .display_p3,
        .transfer_function = .srgb,
        .max_luminance = 120,
        .reference_luminance = 100,
    };
    const copied_argb: render.PixelBuffer = .{
        .size = .{ .width = 8, .height = 6 },
        .stride_pixels = 8,
        .pixels = &copied_argb_pixels,
        .color_description = p3,
        .source_cache = .{ .id = 52, .version = 9 },
        .source_damage = &copied_argb_damage,
    };
    const crop: render.SourceRect = .{
        .x = 0.25,
        .y = 0.5,
        .width = 5.5,
        .height = 3.5,
    };
    const clipped_placement: ImagePlacement = .{
        .position = .{ .x = 10, .y = 20 },
        .rounded_clip = null,
        .clip = .{ .x = 11, .y = 20, .width = 3, .height = 3 },
    };
    var expected_partial_opaque: render.OpaqueRegion = .{};
    try std.testing.expect(expected_partial_opaque.append(.{
        .x = 11,
        .y = 21,
        .width = 1,
        .height = 2,
    }));
    const transformed_state: SurfaceRegistry.RenderState = .{
        .buffer = copied_argb,
        .logical_size = .{ .width = 4, .height = 3 },
        .source = crop,
        .transform = .flipped_90,
        .opaque_region = &partial_opaque,
    };
    const transformed_expected: render.Image = .{
        .x = 10,
        .y = 20,
        .size = .{ .width = 4, .height = 3 },
        .buffer = copied_argb,
        .sample_tag = sample_tag,
        .source = crop,
        .transform = .flipped_90,
        .clip = clipped_placement.clip,
        .opaque_region = expected_partial_opaque,
    };
    try expectImagesEquivalent(
        transformed_expected,
        imageFromRenderState(transformed_state, clipped_placement, sample_tag),
    );

    var partial_alpha_state = transformed_state;
    partial_alpha_state.alpha_multiplier = 0x8000_0000;
    var partial_alpha_expected = transformed_expected;
    partial_alpha_expected.opaque_region = .{};
    partial_alpha_expected.alpha_multiplier = 0x8000_0000;
    try expectImagesEquivalent(
        partial_alpha_expected,
        imageFromRenderState(partial_alpha_state, clipped_placement, sample_tag),
    );

    var full_opaque = Region.init();
    defer full_opaque.deinit();
    try full_opaque.add(0, 0, 4, 3);
    var full_opaque_state = transformed_state;
    full_opaque_state.opaque_region = &full_opaque;
    var full_opaque_expected = transformed_expected;
    full_opaque_expected.is_opaque = true;
    full_opaque_expected.opaque_region = .{};
    try expectImagesEquivalent(
        full_opaque_expected,
        imageFromRenderState(full_opaque_state, clipped_placement, sample_tag),
    );

    const dmabuf_size: render.Size = .{ .width = 4, .height = 3 };
    var dmabuf_context: u8 = 0;
    const dmabuf_damage = [_]render.Rect{.{
        .x = 0,
        .y = 0,
        .width = 4,
        .height = 1,
    }};
    const dmabuf_buffer: render.PixelBuffer = .{
        .size = dmabuf_size,
        .stride_pixels = dmabuf_size.width,
        .dmabuf = .{
            .context = &dmabuf_context,
            .format = @intFromEnum(render.DmabufFormat.xrgb8888),
            .modifier = 0x1234,
            .planes = .{
                .{
                    .fd = -1,
                    .stride = dmabuf_size.width * @sizeOf(u32),
                    .offset = 32,
                    .required_bytes = 80,
                },
                .{},
                .{},
                .{},
            },
            .plane_count = 1,
            .y_inverted = false,
            .force_opaque = true,
            .retain = DmabufCallbacks.retain,
            .release = DmabufCallbacks.release,
            .begin_cpu_read = DmabufCallbacks.beginCpuRead,
            .end_cpu_read = DmabufCallbacks.endCpuRead,
            .export_read_fence = DmabufCallbacks.exportReadFence,
        },
        .color_description = p3,
        .color_representation = .{
            .coefficients = .identity,
            .range = .full,
        },
        .source_cache = .{ .id = 63, .version = 11 },
        .source_damage = &dmabuf_damage,
    };
    const dmabuf_state: SurfaceRegistry.RenderState = .{
        .buffer = dmabuf_buffer,
        .logical_size = dmabuf_size,
        .force_opaque = true,
    };
    const scanout_placement: ImagePlacement = .{
        .position = .{},
        .rounded_clip = null,
        .clip = null,
    };
    const dmabuf_image: render.Image = imageFromRenderState(
        dmabuf_state,
        scanout_placement,
        sample_tag,
    );
    try expectImagesEquivalent(.{
        .x = 0,
        .y = 0,
        .size = dmabuf_size,
        .buffer = dmabuf_buffer,
        .sample_tag = sample_tag,
        .is_opaque = true,
    }, dmabuf_image);

    var target_pixels = [_]u32{0} ** 12;
    var renderer = try Renderer.init(std.testing.allocator, .cpu);
    defer renderer.deinit();
    try renderer.beginFrame(.{ .pixels = .{
        .size = dmabuf_size,
        .stride_pixels = dmabuf_size.width,
        .pixels = &target_pixels,
    } }, .{}, .{}, null, p3);
    try renderer.append(&.{.{ .image = dmabuf_image }});
    switch (renderer.directScanoutCandidate()) {
        .candidate => |candidate| try std.testing.expect(std.meta.eql(dmabuf_buffer, candidate)),
        .rejected => |reason| {
            std.debug.print("unexpected direct scanout rejection: {t}\n", .{reason});
            return error.TestUnexpectedResult;
        },
    }
    switch (renderer.overlayScanoutCandidate()) {
        .candidate => |candidate| {
            try std.testing.expect(std.meta.eql(dmabuf_buffer, candidate.buffer));
            try std.testing.expectEqual(
                render.Rect{ .x = 0, .y = 0, .width = 4, .height = 3 },
                candidate.destination,
            );
        },
        .rejected => |reason| {
            std.debug.print("unexpected overlay scanout rejection: {t}\n", .{reason});
            return error.TestUnexpectedResult;
        },
    }
    renderer.cancelFrame();
}

fn surfaceFullyOpaque(
    surfaces: *Surface.Store,
    surface_id: Surface.Id,
    buffer: *const Surface.BufferSnapshot,
) bool {
    return Surface.currentAlphaMultiplier(surfaces, surface_id) == std.math.maxInt(u32) and
        (buffer.force_opaque or Surface.currentOpaqueCoversBuffer(surfaces, surface_id));
}

fn surfaceEffectRect(rectangle: Region.Rectangle, size: render.Size) ?render.Rect {
    return (render.Rect{
        .x = rectangle.x,
        .y = rectangle.y,
        .width = rectangle.width,
        .height = rectangle.height,
    }).clipTo(size);
}

test "background effect rectangles are clipped to the surface" {
    try std.testing.expectEqual(
        render.Rect{ .x = 0, .y = 4, .width = 6, .height = 4 },
        surfaceEffectRect(
            .{ .x = -2, .y = 4, .width = 8, .height = 10 },
            .{ .width = 10, .height = 8 },
        ).?,
    );
    try std.testing.expectEqual(
        @as(?render.Rect, null),
        surfaceEffectRect(
            .{ .x = 10, .y = 0, .width = 1, .height = 1 },
            .{ .width = 10, .height = 8 },
        ),
    );
}

fn renderBorders(
    self: *Self,
    frame: *const OutputFrame,
    content_rect: render.Rect,
    borders: ?Scene.Borders,
    corner_radius: u32,
    clip: ?render.Rect,
) Renderer.Error!void {
    const configured = borders orelse return;
    var commands: [4]render.Command = undefined;
    const border_commands = window_geometry.makeBorderCommands(
        content_rect,
        configured,
        corner_radius,
        clip,
        &commands,
    );
    try self.renderCommands(frame, border_commands);
}

fn renderWindowDecorations(
    self: *Self,
    frame: *const OutputFrame,
    window_id: Scene.Id,
    window: *const Scene.Window,
    layer: Scene.DecorationLayer,
    clip: ?render.Rect,
) Renderer.Error!void {
    var decorations = self.scene.decorationIterator(window_id, layer);
    while (decorations.next()) |entry| {
        if (!entry.decoration.mapped) continue;
        try self.renderSurfaceTree(
            frame,
            entry.decoration.surface_id,
            window.position.x +| entry.decoration.offset.x,
            window.position.y +| entry.decoration.offset.y,
            null,
            clip,
        );
    }
}

fn submitSurfaceTree(self: *Self, output: *Output, surface_id: Surface.Id) void {
    // Generated popup presentation and frame completion are owned by the
    // accepted sampled-headless path; they intentionally have no mature
    // Surface buffer or presentation feedback to submit here.
    if (self.exactEligibleGeneratedPopupRoot(surface_id)) return;
    if (Surface.currentBuffer(self.compositor.surfaceStore(), surface_id) == null) return;

    var stack = self.subcompositor.stackIterator(surface_id);
    while (stack.next()) |entry| switch (entry) {
        .parent => if (output.containsSurface(surface_id) and
            self.renderer.wasSampled(surfaceSampleTag(surface_id)))
        {
            Surface.submitPresentationFor(self.compositor.surfaceStore(), surface_id, output);
        },
        .child => |child| self.submitSurfaceTree(output, child.surface_id),
    };
}

/// Generated surfaces have no mature presentation feedback to submit. This
/// traversal deliberately mirrors generated rendering so output membership
/// and sampled tags remain the sole acceptance criteria; sampled frame demand
/// is completed by completeSampledHeadlessFrames after the frame is accepted.
fn submitGeneratedCompound(self: *Self, output: *Output, root: SurfaceRegistry.Id) void {
    var iterator = self.headless_surface_forest.subtreeRenderIterator(root);
    while (iterator.next()) |entry| {
        if (!output.containsSurface(entry.id)) continue;
        _ = self.renderer.wasSampled(surfaceSampleTag(entry.id));
    }
}

fn submitCapturedSurfaceTree(self: *Self, output: *Output, surface_id: Surface.Id) void {
    if (Surface.currentBuffer(self.compositor.surfaceStore(), surface_id) == null) return;

    var stack = self.subcompositor.stackIterator(surface_id);
    while (stack.next()) |entry| switch (entry) {
        .parent => if (output.containsSurface(surface_id)) {
            Surface.submitPresentationFor(self.compositor.surfaceStore(), surface_id, output);
        },
        .child => |child| self.submitCapturedSurfaceTree(output, child.surface_id),
    };
}

fn submitWindowDecorations(
    self: *Self,
    output: *Output,
    window_id: Scene.Id,
    layer: Scene.DecorationLayer,
) void {
    var decorations = self.scene.decorationIterator(window_id, layer);
    while (decorations.next()) |entry| {
        if (!entry.decoration.mapped) continue;
        self.submitSurfaceTree(output, entry.decoration.surface_id);
    }
}

fn submitCapturedWindowDecorations(
    self: *Self,
    output: *Output,
    window_id: Scene.Id,
    layer: Scene.DecorationLayer,
) void {
    var decorations = self.scene.decorationIterator(window_id, layer);
    while (decorations.next()) |entry| {
        if (!entry.decoration.mapped) continue;
        self.submitCapturedSurfaceTree(output, entry.decoration.surface_id);
    }
}

fn submitWindowPopups(self: *Self, output: *Output, window_id: Scene.Id) void {
    var popups = self.scene.popupIterator(window_id);
    while (popups.next()) |entry| {
        if (!entry.popup.mapped) continue;
        self.submitSurfaceTree(output, entry.popup.surface_id);
    }
}

const SyntheticSurfaceProvider = struct {
    pixel: u32,
    logical_size: render.Size,
    available: bool = true,
    force_opaque: bool = true,
    blur_region: ?*const Region = null,
    dmabuf: bool = false,
    version: u64 = 1,
    render_calls: usize = 0,

    fn provider(self: *SyntheticSurfaceProvider) SurfaceRegistry.Provider {
        return .{ .context = self, .render_state = renderState };
    }

    fn renderState(context: *anyopaque) ?SurfaceRegistry.RenderState {
        const self: *SyntheticSurfaceProvider = @ptrCast(@alignCast(context));
        self.render_calls += 1;
        if (!self.available) return null;
        const buffer: render.PixelBuffer = if (self.dmabuf) .{
            .size = self.logical_size,
            .stride_pixels = self.logical_size.width,
            .dmabuf = .{
                .context = self,
                .format = @intFromEnum(render.DmabufFormat.xrgb8888),
                .modifier = 0,
                .planes = .{
                    .{
                        .fd = -1,
                        .stride = self.logical_size.width * @sizeOf(u32),
                        .required_bytes = @as(u64, self.logical_size.width) *
                            self.logical_size.height * @sizeOf(u32),
                    },
                    .{},
                    .{},
                    .{},
                },
                .plane_count = 1,
                .y_inverted = false,
                .force_opaque = true,
                .retain = dmabufRetain,
                .release = dmabufRelease,
                .begin_cpu_read = dmabufBeginCpuRead,
                .end_cpu_read = dmabufEndCpuRead,
                .export_read_fence = dmabufExportReadFence,
            },
            .source_cache = .{ .id = @intFromPtr(self), .version = self.version },
        } else .{
            .size = .{ .width = 1, .height = 1 },
            .stride_pixels = 1,
            .pixels = @as([*]u32, @ptrCast(&self.pixel))[0..1],
            .source_cache = .{ .id = @intFromPtr(self), .version = self.version },
        };
        return .{
            .buffer = buffer,
            .logical_size = self.logical_size,
            .force_opaque = self.force_opaque,
            .blur_region = self.blur_region,
        };
    }

    fn dmabufRetain(_: *anyopaque) void {}
    fn dmabufRelease(_: *anyopaque) void {}
    fn dmabufBeginCpuRead(_: *anyopaque) bool {
        return true;
    }
    fn dmabufEndCpuRead(_: *anyopaque) bool {
        return true;
    }
    fn dmabufExportReadFence(_: *anyopaque, _: u8) ?std.posix.fd_t {
        return null;
    }
};

const TestGeneratedSeatSink = struct {
    const KeyboardTag = std.meta.Tag(SeatDelivery.KeyboardEvent);
    const PointerTag = std.meta.Tag(SeatDelivery.PointerEvent);
    const TouchTag = std.meta.Tag(SeatDelivery.TouchEvent);

    clients: *ClientRegistry,
    client: ClientRegistry.Id,
    other_client: ?ClientRegistry.Id = null,
    other_surface: ?SurfaceRegistry.Id = null,
    event_count: usize = 0,
    next_serial: u32 = 1,
    keyboard_event_count: usize = 0,
    keyboard_events: [64]KeyboardTag = undefined,
    keyboard_clients: [64]ClientRegistry.Id = undefined,
    keyboard_surfaces: [64]SurfaceRegistry.Id = undefined,
    keyboard_serials: [64]u32 = undefined,
    keyboard_states: [64]?SeatDelivery.KeyState = undefined,
    keyboard_pressed_keys: [64][8]u32 = undefined,
    keyboard_pressed_key_counts: [64]usize = undefined,
    pointer_event_count: usize = 0,
    pointer_events: [64]PointerTag = undefined,
    pointer_surfaces: [64]SurfaceRegistry.Id = undefined,
    last_button_serial: ?ClientRegistry.Serial = null,
    touch_max_resource_generation: ?SeatDelivery.ResourceGeneration = null,
    touch_event_count: usize = 0,
    touch_events: [64]TouchTag = undefined,
    touch_clients: [64]ClientRegistry.Id = undefined,
    touch_surfaces: [64]?SurfaceRegistry.Id = undefined,
    touch_serials: [64]?ClientRegistry.Serial = undefined,
    touch_ids: [64]?i32 = undefined,
    touch_x: [64]?i32 = undefined,
    touch_y: [64]?i32 = undefined,
    touch_cutoffs: [64]?SeatDelivery.ResourceGeneration = undefined,

    fn sink(self: *TestGeneratedSeatSink) SeatDelivery.Sink {
        return .{
            .context = self,
            .owner_for_surface = ownerForSurface,
            .surface_accepts_input = surfaceAcceptsInput,
            .issue_serial = issueSerial,
            .terminalize = terminalize,
            .touch_target = touchTarget,
            .assign_cursor_role = assignCursorRole,
            .capabilities = capabilities,
            .keyboard_state = keyboardState,
            .keyboard = keyboard,
            .pointer = pointer,
            .touch = touch,
            .touch_frame = TestGeneratedSeatSink.touchFrame,
        };
    }

    fn ownerForSurface(
        context: *anyopaque,
        surface: SurfaceRegistry.Id,
    ) ?ClientRegistry.Id {
        const self: *TestGeneratedSeatSink = @ptrCast(@alignCast(context));
        if (self.other_client != null and self.other_surface != null and
            std.meta.eql(self.other_surface.?, surface) and
            self.clients.domainOf(self.other_client.?) == .wayring_server)
        {
            return self.other_client;
        }
        return if (self.clients.domainOf(self.client) == .wayring_server)
            self.client
        else
            null;
    }

    fn surfaceAcceptsInput(
        _: *anyopaque,
        _: SurfaceRegistry.Id,
        _: f64,
        _: f64,
    ) bool {
        return true;
    }

    fn issueSerial(context: *anyopaque, client: ClientRegistry.Id) ?ClientRegistry.Serial {
        const self: *TestGeneratedSeatSink = @ptrCast(@alignCast(context));
        if ((!std.meta.eql(client, self.client) and
            (self.other_client == null or !std.meta.eql(client, self.other_client.?))) or
            !self.clients.contains(client)) return null;
        const value = self.next_serial;
        self.next_serial += 1;
        return .{ .domain = .wayring_server, .value = value };
    }

    fn terminalize(_: *anyopaque, _: ClientRegistry.Id, _: SeatDelivery.TerminalReason) void {}

    fn assignCursorRole(
        context: *anyopaque,
        client: ClientRegistry.Id,
        _: SurfaceRegistry.Id,
    ) SeatDelivery.CursorRoleResult {
        const self: *TestGeneratedSeatSink = @ptrCast(@alignCast(context));
        return if (std.meta.eql(client, self.client)) .assigned else .wrong_client;
    }

    fn touchTarget(context: *anyopaque, surface: SurfaceRegistry.Id) ?SeatDelivery.TouchTarget {
        const self: *TestGeneratedSeatSink = @ptrCast(@alignCast(context));
        const max_resource_generation = self.touch_max_resource_generation orelse return null;
        const client = ownerForSurface(self, surface) orelse return null;
        return .{
            .client = client,
            .max_resource_generation = max_resource_generation,
        };
    }

    fn capabilities(_: *anyopaque, _: SeatDelivery.CapabilitySnapshot) void {}
    fn keyboardState(_: *anyopaque, _: SeatDelivery.KeyboardStateEvent) void {}

    fn keyboard(
        context: *anyopaque,
        client: ClientRegistry.Id,
        surface: SurfaceRegistry.Id,
        event: SeatDelivery.KeyboardEvent,
    ) void {
        const self: *TestGeneratedSeatSink = @ptrCast(@alignCast(context));
        std.debug.assert(self.keyboard_event_count < self.keyboard_events.len);
        const index = self.keyboard_event_count;
        self.keyboard_events[index] = event;
        self.keyboard_clients[index] = client;
        self.keyboard_surfaces[index] = surface;
        self.keyboard_states[index] = if (event == .key) event.key.state else null;
        self.keyboard_pressed_key_counts[index] = 0;
        self.keyboard_serials[index] = switch (event) {
            .enter => |enter| blk: {
                const count = @min(enter.pressed_keys.len, self.keyboard_pressed_keys[index].len);
                @memcpy(self.keyboard_pressed_keys[index][0..count], enter.pressed_keys[0..count]);
                self.keyboard_pressed_key_counts[index] = count;
                break :blk enter.serial.value;
            },
            .leave => |leave| leave.serial,
            .key => |key| key.serial.value,
            .modifiers => |modifiers| modifiers.serial,
        };
        self.keyboard_event_count += 1;
        self.event_count += 1;
    }

    fn pointer(
        context: *anyopaque,
        _: ClientRegistry.Id,
        surface: SurfaceRegistry.Id,
        event: SeatDelivery.PointerEvent,
    ) void {
        const self: *TestGeneratedSeatSink = @ptrCast(@alignCast(context));
        std.debug.assert(self.pointer_event_count < self.pointer_events.len);
        self.pointer_events[self.pointer_event_count] = event;
        self.pointer_surfaces[self.pointer_event_count] = surface;
        if (event == .button) self.last_button_serial = event.button.serial;
        self.pointer_event_count += 1;
        self.event_count += 1;
    }

    fn touch(
        context: *anyopaque,
        client: ClientRegistry.Id,
        event: SeatDelivery.TouchEvent,
    ) void {
        const self: *TestGeneratedSeatSink = @ptrCast(@alignCast(context));
        std.debug.assert(self.touch_event_count < self.touch_events.len);
        const index = self.touch_event_count;
        self.touch_events[index] = event;
        self.touch_clients[index] = client;
        self.touch_surfaces[index] = if (event == .down) event.down.surface else null;
        self.touch_serials[index] = switch (event) {
            .down => |value| value.serial,
            .up => |value| value.serial,
            else => null,
        };
        self.touch_ids[index] = switch (event) {
            .down => |value| value.id,
            .up => |value| value.id,
            .motion => |value| value.id,
            .shape => |value| value.id,
            .orientation => |value| value.id,
            .frame, .cancel => null,
        };
        self.touch_x[index] = switch (event) {
            .down => |value| value.x,
            .motion => |value| value.x,
            .shape => |value| value.major,
            .orientation => |value| value.orientation,
            else => null,
        };
        self.touch_y[index] = switch (event) {
            .down => |value| value.y,
            .motion => |value| value.y,
            .shape => |value| value.minor,
            else => null,
        };
        self.touch_cutoffs[index] = switch (event) {
            .down => |value| value.max_resource_generation,
            .up => |value| value.max_resource_generation,
            .motion => |value| value.max_resource_generation,
            .cancel => |value| value.max_resource_generation,
            .shape => |value| value.max_resource_generation,
            .orientation => |value| value.max_resource_generation,
            .frame => null,
        };
        self.touch_event_count += 1;
        self.event_count += 1;
    }

    fn touchFrame(context: *anyopaque) void {
        const self: *TestGeneratedSeatSink = @ptrCast(@alignCast(context));
        touch(context, self.client, .frame);
    }
};

fn resetTestOutputDamage(output: *RenderOutput) void {
    output.damage.clear();
    output.repaint_needed = false;
}

fn captureSinglePixel(server: *Self) Renderer.Error!u32 {
    var pixel: [1]u32 = undefined;
    _ = try server.captureOutput(server.primaryRenderOutput().protocol_id, false, .{
        .size = .{ .width = 1, .height = 1 },
        .stride_pixels = 1,
        .pixels = &pixel,
    });
    return pixel[0];
}

const TestFrameCompletion = struct {
    count: usize = 0,
    ids: [8]SurfaceRegistry.Id = undefined,
    timestamps_ms: [8]u32 = undefined,
    forest: ?*HeadlessSurfaceForest = null,
    demand_cleared_before_call: bool = true,
    callback_only: bool = false,

    fn frameCompletion(self: *TestFrameCompletion) SurfaceFrameCompletion {
        return .{
            .context = self,
            .complete = complete,
            .has_callback_only = hasCallbackOnly,
            .complete_callback_only = completeCallbackOnly,
        };
    }

    fn complete(context: *anyopaque, id: SurfaceRegistry.Id, timestamp_ms: u32) void {
        const self: *TestFrameCompletion = @ptrCast(@alignCast(context));
        std.debug.assert(self.count < self.ids.len);
        if (self.forest) |forest| {
            self.demand_cleared_before_call = self.demand_cleared_before_call and
                !forest.state(id).?.frame_demand;
        }
        self.ids[self.count] = id;
        self.timestamps_ms[self.count] = timestamp_ms;
        self.count += 1;
    }

    fn hasCallbackOnly(context: *anyopaque, _: SurfaceRegistry.Id) bool {
        const self: *TestFrameCompletion = @ptrCast(@alignCast(context));
        return self.callback_only;
    }

    fn completeCallbackOnly(
        context: *anyopaque,
        id: SurfaceRegistry.Id,
        timestamp_ms: u32,
    ) SurfaceFrameCompletion.CallbackOnlyResult {
        const self: *TestFrameCompletion = @ptrCast(@alignCast(context));
        if (!self.callback_only) return .none;
        self.callback_only = false;
        complete(self, id, timestamp_ms);
        return .drained;
    }
};

const TestSessionLockEndpoint = struct {
    acquired_count: usize = 0,
    finished_count: usize = 0,
    configure_count: usize = 0,
    last_configure: ?NeutralSessionLock.ConfigureToken = null,

    fn lockEndpoint(self: *TestSessionLockEndpoint) NeutralSessionLock.LockEndpoint {
        return .{ .context = self, .acquired = acquired, .finished = finished };
    }

    fn surfaceEndpoint(self: *TestSessionLockEndpoint) NeutralSessionLock.SurfaceEndpoint {
        return .{ .context = self, .configure = configure };
    }

    fn acquired(context: *anyopaque) void {
        const self: *TestSessionLockEndpoint = @ptrCast(@alignCast(context));
        self.acquired_count += 1;
    }

    fn finished(context: *anyopaque) void {
        const self: *TestSessionLockEndpoint = @ptrCast(@alignCast(context));
        self.finished_count += 1;
    }

    fn configure(
        context: *anyopaque,
        _: u32,
        _: u32,
        token: NeutralSessionLock.ConfigureToken,
    ) error{OutOfMemory}!void {
        const self: *TestSessionLockEndpoint = @ptrCast(@alignCast(context));
        self.configure_count += 1;
        self.last_configure = token;
    }
};

fn renderPendingTestOutput(server: *Self, output: *RenderOutput) Renderer.Error!void {
    std.debug.assert(output.repaint_needed);
    std.debug.assert(!output.damage.isEmpty());
    output.render_scheduled = false;
    output.repaint_needed = false;
    try server.renderFrame(output);
}

test "generated session lock subtree has exact rendering damage and callback eligibility" {
    const server = try Self.createWithVirtualOutput(std.testing.allocator, std.testing.io, .cpu, .headless, null, .{
        .size = .{ .width = 8, .height = 4 },
    });
    defer server.destroy();
    const output = server.primaryRenderOutput();
    const client = try server.client_registry.register(.wayring_server);
    defer server.client_registry.unregister(client);
    var sink: TestGeneratedSeatSink = .{ .clients = &server.client_registry, .client = client };
    server.setGeneratedSeatDeliverySink(sink.sink());
    defer server.clearGeneratedSeatDeliverySink(&sink);

    var completion: TestFrameCompletion = .{ .forest = &server.headless_surface_forest };
    var root_provider: SyntheticSurfaceProvider = .{ .pixel = 0xff11_2233, .logical_size = .{ .width = 8, .height = 4 } };
    var child_provider: SyntheticSurfaceProvider = .{ .pixel = 0xff44_5566, .logical_size = .{ .width = 2, .height = 2 } };
    const root = try server.surface_registry.add(root_provider.provider());
    const child = try server.surface_registry.add(child_provider.provider());
    try server.addHeadlessSurface(root, completion.frameCompletion());
    try server.addHeadlessSurface(child, completion.frameCompletion());
    defer {
        server.removeHeadlessSurface(child);
        server.surface_registry.remove(child);
        server.removeHeadlessSurface(root);
        server.surface_registry.remove(root);
    }
    try std.testing.expect(server.headless_surface_forest.setRootPresentationClass(root, .session_lock));
    const initial_stack = [_]WayringCompositor.AppliedStackEntry{ .parent, .{ .child = .{ .id = child, .position = .{ .x = 1, .y = 1 } } } };
    server.applyHeadlessBatch(.{
        .surfaces = &.{
            .{ .id = root, .mapped_size = root_provider.logical_size, .callbacks_committed = true },
            .{ .id = child, .mapped_size = child_provider.logical_size, .callbacks_committed = true },
        },
        .parents = &.{.{ .id = root, .stack = &initial_stack }},
    });

    var endpoint: TestSessionLockEndpoint = .{};
    const lock = try server.session_lock_core.createLock(client, endpoint.lockEndpoint());
    const lock_surface = try server.session_lock_core.createSurface(lock, client, root, client, output.protocol_id, endpoint.surfaceEndpoint());
    const token = try server.session_lock_core.configure(lock_surface, 8, 4);
    try server.session_lock_core.ackConfigure(lock_surface, token);
    try server.session_lock_core.map(lock_surface, 8, 4);
    defer {
        if (server.session_lock_core.isLocked()) server.session_lock_core.unlockAndDestroy(lock) catch {};
        server.session_lock_core.destroySurface(lock_surface);
        server.session_lock_core.destroyLock(lock);
    }

    try renderPendingTestOutput(server, output);
    try std.testing.expect(server.renderer.wasSampled(surfaceSampleTag(root)));
    try std.testing.expect(server.renderer.wasSampled(surfaceSampleTag(child)));
    var generic = server.headless_surface_forest.renderIterator();
    while (generic.next()) |node| {
        try std.testing.expect(!std.meta.eql(node.id, root));
        try std.testing.expect(!std.meta.eql(node.id, child));
    }
    resetTestOutputDamage(output);
    const moved_stack = [_]WayringCompositor.AppliedStackEntry{ .parent, .{ .child = .{ .id = child, .position = .{ .x = 4, .y = 1 } } } };
    server.applyHeadlessBatch(.{ .surfaces = &.{}, .parents = &.{.{ .id = root, .stack = &moved_stack }} });
    try std.testing.expect(output.damage.coversRectangle(1, 1, 2, 2));
    try std.testing.expect(output.damage.coversRectangle(4, 1, 2, 2));

    resetTestOutputDamage(output);
    server.commitHeadlessSurface(child, null, false);
    try std.testing.expect(output.damage.coversRectangle(4, 1, 2, 2));
    server.commitHeadlessSurface(child, child_provider.logical_size, true);
    try std.testing.expect(output.damage.coversRectangle(4, 1, 2, 2));
    try renderPendingTestOutput(server, output);
    const completed = completion.count;
    completion.callback_only = true;
    root_provider.available = false;
    server.applyHeadlessBatch(.{
        .surfaces = &.{.{ .id = root, .mapped_size = root_provider.logical_size, .callbacks_committed = true }},
        .parents = &.{},
    });
    const protocol_output = server.outputs.get(output.protocol_id).?;
    protocol_output.beginFrame();
    try protocol_output.markSurfaceVisible(root);
    try protocol_output.markSurfaceVisible(child);
    protocol_output.endFrame();
    server.scheduleGeneratedCallbackOnlyFrames(output);
    try std.testing.expect(output.frame_callback_timer != null);
    try std.testing.expect(server.completeGeneratedCallbackOnlyFrames(server.outputs.get(output.protocol_id).?, output.protocol_id, 77));
    try std.testing.expectEqual(completed + 1, completion.count);
    server.session_lock_core.unmap(lock_surface);
    server.applyHeadlessBatch(.{
        .surfaces = &.{.{ .id = root, .mapped_size = root_provider.logical_size, .callbacks_committed = true }},
        .parents = &.{},
    });
    try std.testing.expect(!server.completeGeneratedCallbackOnlyFrames(server.outputs.get(output.protocol_id).?, output.protocol_id, 78));
    try std.testing.expectEqual(completed + 1, completion.count);
}

test "retiring generated session lock output reconciles input focus and neutral ownership" {
    const server = try Self.createWithVirtualOutput(std.testing.allocator, std.testing.io, .cpu, .headless, null, .{
        .size = .{ .width = 4, .height = 4 },
    });
    defer server.destroy();
    const surviving = server.primaryRenderOutput();
    const retiring_id = try server.addRenderOutput(std.testing.io, .{
        .kind = .headless,
        .size = .{ .width = 4, .height = 4 },
        .position = .{ .x = 4 },
        .name = "HEADLESS-RETIRING-LOCK",
        .description = "Keywork retiring session lock test output",
        .model = "headless",
    });
    var retiring_live = true;
    defer if (retiring_live) std.debug.assert(server.removeRenderOutput(retiring_id));
    const retiring = server.render_outputs.get(retiring_id).?.*;
    const client = try server.client_registry.register(.wayring_server);
    defer server.client_registry.unregister(client);
    var sink: TestGeneratedSeatSink = .{
        .clients = &server.client_registry,
        .client = client,
        .touch_max_resource_generation = 9,
    };
    server.setGeneratedSeatDeliverySink(sink.sink());
    defer server.clearGeneratedSeatDeliverySink(&sink);
    server.seat.setPointerAvailable(true);
    server.seat.setTouchAvailable(true);
    defer {
        server.seat.setTouchAvailable(false);
        server.seat.setPointerAvailable(false);
    }

    var survivor_provider: SyntheticSurfaceProvider = .{ .pixel = 0xff10_2030, .logical_size = .{ .width = 4, .height = 4 } };
    var retired_provider: SyntheticSurfaceProvider = .{ .pixel = 0xff40_5060, .logical_size = .{ .width = 4, .height = 4 } };
    var child_provider: SyntheticSurfaceProvider = .{ .pixel = 0xff70_8090, .logical_size = .{ .width = 2, .height = 2 } };
    const survivor_root = try server.surface_registry.add(survivor_provider.provider());
    const retired_root = try server.surface_registry.add(retired_provider.provider());
    const retired_child = try server.surface_registry.add(child_provider.provider());
    try server.addHeadlessSurface(survivor_root, null);
    try server.addHeadlessSurface(retired_root, null);
    try server.addHeadlessSurface(retired_child, null);
    defer {
        server.removeHeadlessSurface(retired_child);
        server.surface_registry.remove(retired_child);
        server.removeHeadlessSurface(retired_root);
        server.surface_registry.remove(retired_root);
        server.removeHeadlessSurface(survivor_root);
        server.surface_registry.remove(survivor_root);
    }
    try std.testing.expect(server.headless_surface_forest.setRootPresentationClass(survivor_root, .session_lock));
    try std.testing.expect(server.headless_surface_forest.setRootPresentationClass(retired_root, .session_lock));
    const retired_stack = [_]WayringCompositor.AppliedStackEntry{ .parent, .{ .child = .{ .id = retired_child, .position = .{ .x = 1, .y = 1 } } } };
    server.applyHeadlessBatch(.{
        .surfaces = &.{
            .{ .id = survivor_root, .mapped_size = survivor_provider.logical_size, .callbacks_committed = false },
            .{ .id = retired_root, .mapped_size = retired_provider.logical_size, .callbacks_committed = false },
            .{ .id = retired_child, .mapped_size = child_provider.logical_size, .callbacks_committed = false },
        },
        .parents = &.{.{ .id = retired_root, .stack = &retired_stack }},
    });
    var endpoint: TestSessionLockEndpoint = .{};
    const lock = try server.session_lock_core.createLock(client, endpoint.lockEndpoint());
    const survivor_surface = try server.session_lock_core.createSurface(lock, client, survivor_root, client, surviving.protocol_id, endpoint.surfaceEndpoint());
    const retired_surface = try server.session_lock_core.createSurface(lock, client, retired_root, client, retiring.protocol_id, endpoint.surfaceEndpoint());
    for ([_]NeutralSessionLock.LockSurfaceId{ survivor_surface, retired_surface }) |surface| {
        const token = try server.session_lock_core.configure(surface, 4, 4);
        try server.session_lock_core.ackConfigure(surface, token);
        try server.session_lock_core.map(surface, 4, 4);
    }
    defer {
        if (server.session_lock_core.isLocked()) server.session_lock_core.unlockAndDestroy(lock) catch {};
        server.session_lock_core.destroySurface(retired_surface);
        server.session_lock_core.destroySurface(survivor_surface);
        server.session_lock_core.destroyLock(lock);
    }
    try server.session_lock_core.outputPresented(surviving.protocol_id);
    try server.session_lock_core.outputPresented(retiring.protocol_id);
    try std.testing.expectEqual(@as(usize, 1), endpoint.acquired_count);

    const retired_focus: Seat.PointerFocus = .{
        .surface_id = retired_child,
        .x = 0.5,
        .y = 0.5,
        .generated = .{ .root = retired_root, .client = client },
    };
    server.seat.pointerEnter(5.5, 1.5, retired_focus);
    pointerButton(retiring, 2, linux_button_left, .pressed);
    try std.testing.expect(server.seat.implicitPointerGrabActive());
    const press_serial = sink.last_button_serial.?;
    try std.testing.expect(server.seat.authority.acceptsAction(client, press_serial));
    try server.seat.touchDown(3, 17, 5.5, 1.5, retired_focus);
    _ = server.seat.applyGeneratedKeyboardFocus(.{ .surface = retired_root, .client = client }, null);
    server.session_lock_keyboard_focus = retired_root;
    const pointer_before = sink.pointer_event_count;
    const touch_before = sink.touch_event_count;

    try std.testing.expect(server.removeRenderOutput(retiring_id));
    retiring_live = false;
    try std.testing.expect(!server.session_lock_core.ownsMappedSurface(retired_root));
    try std.testing.expect(server.session_lock_core.ownsMappedSurface(survivor_root));
    try std.testing.expect(server.session_lock_core.snapshot(retired_surface) != null);
    try std.testing.expect(!server.seat.implicitPointerGrabActive());
    try std.testing.expect(!server.seat.authority.acceptsAction(client, press_serial));
    try std.testing.expectEqual(TestGeneratedSeatSink.TouchTag.cancel, sink.touch_events[touch_before]);
    try std.testing.expect(sink.pointer_event_count > pointer_before);
    try std.testing.expectEqual(TestGeneratedSeatSink.PointerTag.leave, sink.pointer_events[pointer_before]);
    try std.testing.expectEqual(survivor_root, server.seat.generatedKeyboardFocus().?.surface);
    try std.testing.expectEqual(survivor_root, server.session_lock_keyboard_focus.?);

    const retired_pointer_events = sink.pointer_event_count;
    const retired_touch_events = sink.touch_event_count;
    pointerMotion(surviving, 4, 1, 1);
    pointerAxis(surviving, 5, .vertical_scroll, wl.Fixed.fromInt(1));
    touchMotion(surviving, 6, 17, 1, 1);
    touchUp(surviving, 7, 17);
    try std.testing.expectEqual(retired_touch_events, sink.touch_event_count);
    for (sink.pointer_surfaces[retired_pointer_events..sink.pointer_event_count]) |surface|
        try std.testing.expect(!std.meta.eql(surface, retired_child) and !std.meta.eql(surface, retired_root));
    try renderPendingTestOutput(server, surviving);
    try std.testing.expect(server.renderer.wasSampled(surfaceSampleTag(survivor_root)));
}

test "applied nested topology paints exact order and completes only sampled child tags" {
    const server = try Self.createWithVirtualOutput(
        std.testing.allocator,
        std.testing.io,
        .cpu,
        .headless,
        null,
        .{ .size = .{ .width = 3, .height = 1 } },
    );
    defer server.destroy();
    const output = server.primaryRenderOutput();
    var sampled_completion: TestFrameCompletion = .{ .forest = &server.headless_surface_forest };
    var hidden_completion: TestFrameCompletion = .{ .forest = &server.headless_surface_forest };
    var root: SyntheticSurfaceProvider = .{
        .pixel = 0xffff_0000,
        .logical_size = .{ .width = 3, .height = 1 },
    };
    var below: SyntheticSurfaceProvider = .{
        .pixel = 0xff00_ff00,
        .logical_size = .{ .width = 1, .height = 1 },
    };
    var above: SyntheticSurfaceProvider = .{
        .pixel = 0xff00_00ff,
        .logical_size = .{ .width = 1, .height = 1 },
    };
    var grandchild: SyntheticSurfaceProvider = .{
        .pixel = 0xffff_ff00,
        .logical_size = .{ .width = 1, .height = 1 },
    };
    var outside: SyntheticSurfaceProvider = .{
        .pixel = 0xff00_ffff,
        .logical_size = .{ .width = 2, .height = 1 },
    };
    const root_id = try server.surface_registry.add(root.provider());
    const below_id = try server.surface_registry.add(below.provider());
    const above_id = try server.surface_registry.add(above.provider());
    const grandchild_id = try server.surface_registry.add(grandchild.provider());
    const outside_id = try server.surface_registry.add(outside.provider());
    try server.addHeadlessSurface(root_id, null);
    try server.addHeadlessSurface(below_id, null);
    try server.addHeadlessSurface(above_id, sampled_completion.frameCompletion());
    try server.addHeadlessSurface(grandchild_id, sampled_completion.frameCompletion());
    try server.addHeadlessSurface(outside_id, hidden_completion.frameCompletion());
    server.commitHeadlessSurface(root_id, root.logical_size, false);
    server.commitHeadlessSurface(below_id, below.logical_size, false);
    server.commitHeadlessSurface(above_id, above.logical_size, true);
    server.commitHeadlessSurface(grandchild_id, grandchild.logical_size, true);
    server.commitHeadlessSurface(outside_id, outside.logical_size, true);

    const root_stack = [_]WayringCompositor.AppliedStackEntry{
        .{ .child = .{ .id = below_id, .position = .{} } },
        .parent,
        .{ .child = .{ .id = above_id, .position = .{ .x = 1 } } },
        .{ .child = .{ .id = outside_id, .position = .{ .x = -2 } } },
    };
    const above_stack = [_]WayringCompositor.AppliedStackEntry{
        .parent,
        .{ .child = .{ .id = grandchild_id, .position = .{ .x = -1 } } },
    };
    const parents = [_]WayringCompositor.AppliedParentState{
        .{ .id = root_id, .stack = &root_stack },
        .{ .id = above_id, .stack = &above_stack },
    };
    server.applyHeadlessBatch(.{ .surfaces = &.{}, .parents = &parents });
    try renderPendingTestOutput(server, output);

    const target = switch (output.backend.acquire().?) {
        .pixels => |pixels| pixels,
        else => return error.ExpectedCpuHeadlessTarget,
    };
    try std.testing.expectEqualSlices(u32, &.{ grandchild.pixel, above.pixel, root.pixel }, target.pixels);
    try std.testing.expect(!server.renderer.wasSampled(surfaceSampleTag(below_id)));
    try std.testing.expect(server.renderer.wasSampled(surfaceSampleTag(root_id)));
    try std.testing.expect(server.renderer.wasSampled(surfaceSampleTag(above_id)));
    try std.testing.expect(server.renderer.wasSampled(surfaceSampleTag(grandchild_id)));
    try std.testing.expect(!server.renderer.wasSampled(surfaceSampleTag(outside_id)));
    try std.testing.expectEqual(@as(usize, 2), sampled_completion.count);
    try std.testing.expectEqual(@as(usize, 0), hidden_completion.count);
    try std.testing.expect(server.headless_surface_forest.state(outside_id).?.frame_demand);
    try std.testing.expect(surfaceSampleTag(above_id) != surfaceSampleTag(grandchild_id));

    // Recursive mapping hides descendants without consuming their demand.
    server.commitHeadlessSurface(grandchild_id, grandchild.logical_size, true);
    server.commitHeadlessSurface(root_id, null, false);
    try renderPendingTestOutput(server, output);
    try std.testing.expectEqual(@as(usize, 2), sampled_completion.count);
    try std.testing.expect(server.headless_surface_forest.state(grandchild_id).?.frame_demand);
    server.commitHeadlessSurface(root_id, root.logical_size, false);
    try renderPendingTestOutput(server, output);
    try std.testing.expectEqual(@as(usize, 3), sampled_completion.count);
    try std.testing.expectEqual(grandchild_id, sampled_completion.ids[2]);

    // A partially intersecting child becomes visible without clipping to its
    // parent, and its previously hidden demand completes on the exact tag.
    const moved_stack = [_]WayringCompositor.AppliedStackEntry{
        .{ .child = .{ .id = below_id, .position = .{} } },
        .parent,
        .{ .child = .{ .id = above_id, .position = .{ .x = 1 } } },
        .{ .child = .{ .id = outside_id, .position = .{ .x = -1 } } },
    };
    const moved_parents = [_]WayringCompositor.AppliedParentState{.{
        .id = root_id,
        .stack = &moved_stack,
    }};
    server.applyHeadlessBatch(.{ .surfaces = &.{}, .parents = &moved_parents });
    try renderPendingTestOutput(server, output);
    try std.testing.expectEqual(@as(usize, 1), hidden_completion.count);
    try std.testing.expectEqual(outside_id, hidden_completion.ids[0]);
    try std.testing.expect(server.renderer.wasSampled(surfaceSampleTag(outside_id)));
    const partial_target = switch (output.backend.acquire().?) {
        .pixels => |pixels| pixels,
        else => return error.ExpectedCpuHeadlessTarget,
    };
    try std.testing.expectEqual(outside.pixel, partial_target.pixels[0]);

    // Reusing the provider slot for another child cannot alias the sampled
    // tag or revive stale completion demand.
    const stale_tag = surfaceSampleTag(outside_id);
    server.removeHeadlessSurface(outside_id);
    server.surface_registry.remove(outside_id);
    var replacement: SyntheticSurfaceProvider = .{
        .pixel = 0xffff_00ff,
        .logical_size = .{ .width = 1, .height = 1 },
    };
    const replacement_id = try server.surface_registry.add(replacement.provider());
    try std.testing.expectEqual(outside_id.index, replacement_id.index);
    try std.testing.expect(outside_id.generation != replacement_id.generation);
    try server.addHeadlessSurface(replacement_id, null);
    server.commitHeadlessSurface(replacement_id, replacement.logical_size, false);
    const replacement_stack = [_]WayringCompositor.AppliedStackEntry{
        .{ .child = .{ .id = below_id, .position = .{} } },
        .parent,
        .{ .child = .{ .id = above_id, .position = .{ .x = 1 } } },
        .{ .child = .{ .id = replacement_id, .position = .{ .x = 2 } } },
    };
    const replacement_parents = [_]WayringCompositor.AppliedParentState{.{
        .id = root_id,
        .stack = &replacement_stack,
    }};
    server.applyHeadlessBatch(.{ .surfaces = &.{}, .parents = &replacement_parents });
    try renderPendingTestOutput(server, output);
    try std.testing.expect(!server.renderer.wasSampled(stale_tag));
    try std.testing.expect(server.renderer.wasSampled(surfaceSampleTag(replacement_id)));
    try std.testing.expectEqual(@as(usize, 1), hidden_completion.count);

    try std.testing.expectEqual(@as(?SurfaceRegistry.Id, null), server.scene.focusedSurface());
    try std.testing.expectEqual(@as(?SurfaceRegistry.Id, null), server.scene.topWindowSurface());
    try std.testing.expect(!server.scene.surfaceTracked(grandchild_id));
    try std.testing.expectEqual(@as(?Seat.PointerFocus, null), server.pointerFocus(0, 0));
    try std.testing.expect(server.outputs.get(output.protocol_id).?.containsSurface(grandchild_id));

    server.removeHeadlessSurface(root_id);
    server.surface_registry.remove(root_id);
    server.removeHeadlessSurface(below_id);
    server.surface_registry.remove(below_id);
    server.removeHeadlessSurface(above_id);
    server.surface_registry.remove(above_id);
    server.removeHeadlessSurface(grandchild_id);
    server.surface_registry.remove(grandchild_id);
    server.removeHeadlessSurface(replacement_id);
    server.surface_registry.remove(replacement_id);
}

test "generated cursor subtree paints stack and completes callbacks only while sampled" {
    const server = try Self.createWithVirtualOutput(
        std.testing.allocator,
        std.testing.io,
        .cpu,
        .headless,
        null,
        .{ .size = .{ .width = 3, .height = 1 } },
    );
    defer server.destroy();
    const output = server.primaryRenderOutput();
    var completion: TestFrameCompletion = .{ .forest = &server.headless_surface_forest };
    var root: SyntheticSurfaceProvider = .{
        .pixel = 0xffff_0000,
        .logical_size = .{ .width = 3, .height = 1 },
    };
    var child: SyntheticSurfaceProvider = .{
        .pixel = 0xff00_ff00,
        .logical_size = .{ .width = 1, .height = 1 },
    };
    const root_id = try server.surface_registry.add(root.provider());
    const child_id = try server.surface_registry.add(child.provider());
    try server.addHeadlessSurface(root_id, completion.frameCompletion());
    try server.addHeadlessSurface(child_id, completion.frameCompletion());
    server.commitHeadlessSurface(root_id, root.logical_size, true);
    server.commitHeadlessSurface(child_id, child.logical_size, true);
    const root_stack = [_]WayringCompositor.AppliedStackEntry{
        .parent,
        .{ .child = .{ .id = child_id, .position = .{ .x = 1 } } },
    };
    server.applyHeadlessBatch(.{
        .surfaces = &.{},
        .parents = &.{.{ .id = root_id, .stack = &root_stack }},
    });

    const generated_client = try server.client_registry.register(.wayring_server);
    var sink: TestGeneratedSeatSink = .{
        .clients = &server.client_registry,
        .client = generated_client,
    };
    server.setGeneratedSeatDeliverySink(sink.sink());
    server.seat.setPointerAvailable(true);
    pointerMotion(output, 1, 1, 0);
    try std.testing.expectEqual(child_id, server.seat.pointerFocus().?.surface_id);
    try std.testing.expect(server.headless_surface_forest.setRootPresentationClass(root_id, .cursor));
    try std.testing.expectEqual(SeatDelivery.CursorRequestResult.accepted, server.seat.setGeneratedCursor(.{
        .client = generated_client,
        .resource_generation = 1,
        .capability_generation = server.seat.deliverySnapshot().capabilities.pointer.generation,
        .serial = .{ .domain = .wayring_server, .value = 1 },
        .surface = root_id,
        .hotspot_x = 1,
        .hotspot_y = 0,
    }));
    try std.testing.expectEqual(@as(usize, 0), completion.count);
    try renderPendingTestOutput(server, output);
    const target = switch (output.backend.acquire().?) {
        .pixels => |pixels| pixels,
        else => return error.ExpectedCpuHeadlessTarget,
    };
    try std.testing.expectEqualSlices(u32, &.{ root.pixel, child.pixel, root.pixel }, target.pixels);
    try std.testing.expect(server.renderer.wasSampled(surfaceSampleTag(root_id)));
    try std.testing.expect(server.renderer.wasSampled(surfaceSampleTag(child_id)));
    try std.testing.expectEqual(@as(usize, 2), completion.count);
    try std.testing.expect(completion.demand_cleared_before_call);

    // The cursor-role commit re-picks stale pointer focus and clears this
    // cursor. New demand remains pending during headless-plane rendering.
    server.commitHeadlessSurface(root_id, root.logical_size, true);
    server.commitHeadlessSurface(child_id, child.logical_size, true);
    try std.testing.expectEqual(SeatDelivery.CursorRequestResult.ignored, server.seat.setGeneratedCursor(.{
        .client = generated_client,
        .resource_generation = 1,
        .capability_generation = server.seat.deliverySnapshot().capabilities.pointer.generation,
        .serial = .{ .domain = .wayring_server, .value = 1 },
        .surface = null,
        .hotspot_x = 0,
        .hotspot_y = 0,
    }));
    try renderPendingTestOutput(server, output);
    try std.testing.expectEqual(@as(usize, 2), completion.count);
    try std.testing.expect(server.headless_surface_forest.state(root_id).?.frame_demand);
    try std.testing.expect(server.headless_surface_forest.state(child_id).?.frame_demand);

    server.seat.setPointerAvailable(false);
    server.clearGeneratedSeatDeliverySink(&sink);
    server.client_registry.unregister(generated_client);
    server.removeHeadlessSurface(child_id);
    server.surface_registry.remove(child_id);
    server.removeHeadlessSurface(root_id);
    server.surface_registry.remove(root_id);
}

test "applied topology damages old and new compounds for movement stacking mapping detach and removal" {
    const server = try Self.createWithVirtualOutput(
        std.testing.allocator,
        std.testing.io,
        .cpu,
        .headless,
        null,
        .{ .size = .{ .width = 8, .height = 1 } },
    );
    defer server.destroy();
    const output = server.primaryRenderOutput();
    var root: SyntheticSurfaceProvider = .{
        .pixel = 0xffff_0000,
        .logical_size = .{ .width = 1, .height = 1 },
    };
    var first: SyntheticSurfaceProvider = .{
        .pixel = 0xff00_ff00,
        .logical_size = .{ .width = 2, .height = 1 },
    };
    var second: SyntheticSurfaceProvider = .{
        .pixel = 0xff00_00ff,
        .logical_size = .{ .width = 1, .height = 1 },
    };
    const root_id = try server.surface_registry.add(root.provider());
    const first_id = try server.surface_registry.add(first.provider());
    const second_id = try server.surface_registry.add(second.provider());
    try server.addHeadlessSurface(root_id, null);
    try server.addHeadlessSurface(first_id, null);
    try server.addHeadlessSurface(second_id, null);
    server.commitHeadlessSurface(root_id, root.logical_size, false);
    server.commitHeadlessSurface(first_id, first.logical_size, false);
    server.commitHeadlessSurface(second_id, second.logical_size, false);

    const initial_stack = [_]WayringCompositor.AppliedStackEntry{
        .{ .child = .{ .id = second_id, .position = .{ .x = 2 } } },
        .parent,
        .{ .child = .{ .id = first_id, .position = .{ .x = 1 } } },
    };
    const initial_parents = [_]WayringCompositor.AppliedParentState{.{
        .id = root_id,
        .stack = &initial_stack,
    }};
    server.applyHeadlessBatch(.{ .surfaces = &.{}, .parents = &initial_parents });
    try renderPendingTestOutput(server, output);

    resetTestOutputDamage(output);
    const moved_stack = [_]WayringCompositor.AppliedStackEntry{
        .parent,
        .{ .child = .{ .id = second_id, .position = .{ .x = 2 } } },
        .{ .child = .{ .id = first_id, .position = .{ .x = 4 } } },
    };
    const moved_parents = [_]WayringCompositor.AppliedParentState{.{
        .id = root_id,
        .stack = &moved_stack,
    }};
    server.applyHeadlessBatch(.{ .surfaces = &.{}, .parents = &moved_parents });
    try std.testing.expect(output.damage.coversRectangle(0, 0, 3, 1));
    try std.testing.expect(output.damage.coversRectangle(4, 0, 2, 1));
    try std.testing.expect(output.repaint_needed and output.render_scheduled);

    resetTestOutputDamage(output);
    server.commitHeadlessSurface(first_id, null, false);
    try std.testing.expect(output.damage.coversRectangle(4, 0, 2, 1));
    server.commitHeadlessSurface(first_id, first.logical_size, false);
    try std.testing.expect(output.damage.coversRectangle(4, 0, 2, 1));

    resetTestOutputDamage(output);
    server.detachHeadlessSurface(first_id);
    try std.testing.expect(output.damage.coversRectangle(4, 0, 2, 1));
    try std.testing.expectEqual(HeadlessSurfaceForest.Placement.detached, server.headless_surface_forest.state(first_id).?.placement);

    server.applyHeadlessBatch(.{ .surfaces = &.{}, .parents = &moved_parents });
    resetTestOutputDamage(output);
    server.removeHeadlessSurface(first_id);
    try std.testing.expect(output.damage.coversRectangle(4, 0, 2, 1));
    server.surface_registry.remove(first_id);

    server.removeHeadlessSurface(root_id);
    server.surface_registry.remove(root_id);
    server.removeHeadlessSurface(second_id);
    server.surface_registry.remove(second_id);
}

test "sampled accepted headless frame completes callback-only demand once" {
    const server = try Self.createWithVirtualOutput(
        std.testing.allocator,
        std.testing.io,
        .cpu,
        .headless,
        null,
        .{ .size = .{ .width = 1, .height = 1 } },
    );
    defer server.destroy();
    const output = server.primaryRenderOutput();
    var completion: TestFrameCompletion = .{ .forest = &server.headless_surface_forest };
    var provider: SyntheticSurfaceProvider = .{
        .pixel = 0xff12_3456,
        .logical_size = .{ .width = 1, .height = 1 },
    };
    const id = try server.surface_registry.add(provider.provider());
    try server.addHeadlessSurface(id, completion.frameCompletion());
    server.commitHeadlessSurface(id, provider.logical_size, false);
    try renderPendingTestOutput(server, output);
    try std.testing.expectEqual(@as(usize, 0), completion.count);

    server.commitHeadlessSurface(id, provider.logical_size, true);
    try std.testing.expect(output.repaint_needed);
    try std.testing.expect(output.render_scheduled);
    try std.testing.expect(server.headless_surface_forest.state(id).?.frame_demand);

    try std.testing.expectEqual(provider.pixel, try captureSinglePixel(server));
    try std.testing.expect(server.renderer.wasSampled(surfaceSampleTag(id)));
    try std.testing.expectEqual(@as(usize, 0), completion.count);
    try std.testing.expect(server.headless_surface_forest.state(id).?.frame_demand);

    try server.renderer.beginFrame(.{ .offscreen = .{
        .id = 1,
        .size = .{ .width = 1, .height = 1 },
    } }, .{}, .{}, null, .{});
    try server.renderer.append(&.{.{ .image = imageFromRenderState(
        server.surface_registry.renderState(id).?,
        .{ .position = .{}, .rounded_clip = null, .clip = null },
        surfaceSampleTag(id),
    ) }});
    try std.testing.expectError(error.InvalidTarget, server.renderer.finishFrame());
    try std.testing.expectEqual(@as(usize, 0), completion.count);
    try std.testing.expect(server.headless_surface_forest.state(id).?.frame_demand);

    var target_pixels: [1]u32 = undefined;
    try server.renderer.beginFrame(.{ .pixels = .{
        .size = .{ .width = 1, .height = 1 },
        .stride_pixels = 1,
        .pixels = &target_pixels,
    } }, .{}, .{}, null, .{});
    var capture_id: u32 = 1;
    const frame: OutputFrame = .{
        .render_output = output,
        .output = server.outputs.get(output.protocol_id).?,
        .visible_rect = .{ .x = 0, .y = 0, .width = 1, .height = 1 },
        .track_visibility = false,
        .next_backdrop_capture_id = &capture_id,
    };
    try server.renderCommands(&frame, &.{.{ .clear = render.Color.rgba(0, 0, 0, 0) }});
    _ = try server.renderDesktopContents(&frame, false, false);
    server.renderer.cancelFrame();
    try std.testing.expect(!server.renderer.wasSampled(surfaceSampleTag(id)));
    try std.testing.expectEqual(@as(usize, 0), completion.count);
    try std.testing.expect(server.headless_surface_forest.state(id).?.frame_demand);

    try renderPendingTestOutput(server, output);
    try std.testing.expectEqual(@as(usize, 1), completion.count);
    try std.testing.expect(std.meta.eql(id, completion.ids[0]));
    try std.testing.expect(completion.demand_cleared_before_call);
    try std.testing.expect(!server.headless_surface_forest.state(id).?.frame_demand);

    server.commitHeadlessSurface(id, provider.logical_size, false);
    try renderPendingTestOutput(server, output);
    try std.testing.expectEqual(@as(usize, 1), completion.count);

    server.commitHeadlessSurface(id, null, true);
    try renderPendingTestOutput(server, output);
    try std.testing.expectEqual(@as(usize, 1), completion.count);
    try std.testing.expect(server.headless_surface_forest.state(id).?.frame_demand);

    server.commitHeadlessSurface(id, provider.logical_size, false);
    try renderPendingTestOutput(server, output);
    try std.testing.expectEqual(@as(usize, 2), completion.count);
    try std.testing.expect(std.meta.eql(id, completion.ids[1]));
    try std.testing.expect(!server.headless_surface_forest.state(id).?.frame_demand);

    server.removeHeadlessSurface(id);
    server.surface_registry.remove(id);
}

test "scale-only logical resize damages bounds samples and completes frame demand" {
    const server = try Self.createWithVirtualOutput(
        std.testing.allocator,
        std.testing.io,
        .cpu,
        .headless,
        null,
        .{ .size = .{ .width = 4, .height = 2 } },
    );
    defer server.destroy();
    const output = server.primaryRenderOutput();
    var completion: TestFrameCompletion = .{ .forest = &server.headless_surface_forest };
    var provider: SyntheticSurfaceProvider = .{
        .pixel = 0xff12_3456,
        .logical_size = .{ .width = 4, .height = 2 },
    };
    const id = try server.surface_registry.add(provider.provider());
    try server.addHeadlessSurface(id, completion.frameCompletion());
    server.commitHeadlessSurface(id, provider.logical_size, false);
    try renderPendingTestOutput(server, output);

    resetTestOutputDamage(output);
    provider.logical_size = .{ .width = 2, .height = 1 };
    server.commitHeadlessSurface(id, provider.logical_size, true);

    try std.testing.expect(output.damage.coversRectangle(0, 0, 4, 2));
    try std.testing.expect(output.damage.coversRectangle(0, 0, 2, 1));
    try std.testing.expect(output.repaint_needed);
    try std.testing.expect(output.render_scheduled);
    try std.testing.expect(server.headless_surface_forest.state(id).?.frame_demand);
    try std.testing.expectEqual(provider.logical_size, server.headless_surface_forest.state(id).?.mapped_size.?);
    const state = server.surface_registry.renderState(id).?;
    try std.testing.expectEqual(provider.logical_size, state.logical_size);
    try std.testing.expectEqual(@as(u64, 1), state.buffer.source_cache.?.version);

    try renderPendingTestOutput(server, output);
    try std.testing.expect(server.renderer.wasSampled(surfaceSampleTag(id)));
    try std.testing.expectEqual(@as(usize, 1), completion.count);
    try std.testing.expect(std.meta.eql(id, completion.ids[0]));
    try std.testing.expect(completion.demand_cleared_before_call);
    try std.testing.expect(!server.headless_surface_forest.state(id).?.frame_demand);

    const target = switch (output.backend.acquire().?) {
        .pixels => |pixels| pixels,
        else => return error.ExpectedCpuHeadlessTarget,
    };
    var expected: [8]u32 = @splat(renderColor(server.palette.desktop_background).argb8888());
    expected[0] = provider.pixel;
    expected[1] = provider.pixel;
    try std.testing.expectEqualSlices(u32, &expected, target.pixels);

    server.removeHeadlessSurface(id);
    server.surface_registry.remove(id);
}

