    var client: MatureSessionLockClient = .{ .runtime_directory = runtime_directory, .display_name = socket_name, .command_fd = command_fd };
    const thread = try std.Thread.spawn(.{}, MatureSessionLockClient.run, .{&client});
    var joined = false;
