    defer std.testing.allocator.free(runtime_directory);
    if (linux.errno(linux.mkdir(runtime_directory.ptr, 0o700)) != .SUCCESS) return error.TestDirectoryCreationFailed;
    defer _ = linux.rmdir(runtime_directory.ptr);
    const previous_runtime = if (libc.getenv("XDG_RUNTIME_DIR")) |value| try std.testing.allocator.dupeZ(u8, std.mem.span(value)) else null;
    defer {
        if (previous_runtime) |value| {
            _ = libc.setenv("XDG_RUNTIME_DIR", value, 1);
            std.testing.allocator.free(value);
        } else _ = libc.unsetenv("XDG_RUNTIME_DIR");
    }
    if (libc.setenv("XDG_RUNTIME_DIR", runtime_directory, 1) != 0) return error.RuntimeEnvironmentFailed;

    const server = try Self.createWithVirtualOutput(std.testing.allocator, std.testing.io, .cpu, .headless, null, .{ .size = .{ .width = 64, .height = 64 }, .refresh_millihertz = 1 });
    defer server.destroy();
    const socket_name = try server.listen();
    const client_baseline = server.client_registry.len();
    const notification_baseline = server.idle_notification.len();
    const raw_command = linux.eventfd(0, linux.EFD.CLOEXEC);
    if (linux.errno(raw_command) != .SUCCESS) return error.EventFdFailed;
    const command_fd: std.posix.fd_t = @intCast(raw_command);
    defer _ = linux.close(command_fd);
    const fd_baseline = try countMatureDataDeviceFds();
    var client: MatureIdleNotifyClient = .{
        .runtime_directory = runtime_directory,
        .display_name = socket_name,
        .command_fd = command_fd,
    };
    const thread = try std.Thread.spawn(.{}, MatureIdleNotifyClient.run, .{&client});
    var joined = false;
    defer if (!joined) {
        client.shutdown();
        thread.join();
    };

    try waitForMatureIdleNotifyStage(server, &client, .idled);
    try std.testing.expectEqual(client_baseline + 1, server.client_registry.len());
    try std.testing.expectEqual(notification_baseline + 1, server.idle_notification.len());
    try std.testing.expectEqual(@as(usize, 1), client.notifier_global_count);
    try std.testing.expectEqual(@as(u32, 2), client.notifier_global_version);
    try std.testing.expectEqual(@as(u8, 1), client.idled_count);

    const output = server.primaryRenderOutput();
    pointerMotion(output, 1, 0.5, 0.5);
    pointerFrame(output);
    try signalWayringCommand(command_fd);
    try waitForMatureIdleNotifyStage(server, &client, .resumed);
    try std.testing.expectEqual(@as(u8, 1), client.resumed_count);

    try signalWayringCommand(command_fd);
    try waitForMatureIdleNotifyStage(server, &client, .reidled);
    try std.testing.expectEqual(@as(u8, 2), client.idled_count);
    try std.testing.expectEqual(notification_baseline + 1, server.idle_notification.len());

    try signalWayringCommand(command_fd);
    try waitForMatureIdleNotifyStage(server, &client, .destroyed);
    try std.testing.expectEqual(notification_baseline, server.idle_notification.len());
    try signalWayringCommand(command_fd);
    try waitForMatureIdleNotifyStage(server, &client, .disconnected);
    thread.join();
    joined = true;
    for (0..2_000) |_| {
        if (server.client_registry.len() == client_baseline) break;
        try server.eventLoop().dispatch(1);
        server.display.flushClients();
    } else return error.MatureIdleNotifyCleanupTimedOut;
    try std.testing.expectEqual(notification_baseline, server.idle_notification.len());
    try std.testing.expectEqual(fd_baseline, try countMatureDataDeviceFds());
}

test "production mature ext workspace v1 snapshots activates and survives child destruction" {
    const linux = std.os.linux;
    var marker: u8 = 0;
    const runtime_directory = try std.fmt.allocPrintSentinel(std.testing.allocator, "/tmp/keywork-mature-workspace-{d}-{x}", .{ linux.getpid(), @intFromPtr(&marker) }, 0);
    defer std.testing.allocator.free(runtime_directory);
    if (linux.errno(linux.mkdir(runtime_directory.ptr, 0o700)) != .SUCCESS) return error.TestDirectoryCreationFailed;
    defer _ = linux.rmdir(runtime_directory.ptr);
    const previous_runtime = if (libc.getenv("XDG_RUNTIME_DIR")) |value| try std.testing.allocator.dupeZ(u8, std.mem.span(value)) else null;
    defer {
        if (previous_runtime) |value| {
            _ = libc.setenv("XDG_RUNTIME_DIR", value, 1);
            std.testing.allocator.free(value);
        } else _ = libc.unsetenv("XDG_RUNTIME_DIR");
    }
    if (libc.setenv("XDG_RUNTIME_DIR", runtime_directory, 1) != 0) return error.RuntimeEnvironmentFailed;
    const server = try Self.createWithVirtualOutput(std.testing.allocator, std.testing.io, .cpu, .headless, null, .{ .size = .{ .width = 320, .height = 240 }, .refresh_millihertz = 1 });
    defer server.destroy();
    const socket_name = try server.listen();
    const raw_command = linux.eventfd(0, linux.EFD.CLOEXEC);
    if (linux.errno(raw_command) != .SUCCESS) return error.EventFdFailed;
    const command_fd: std.posix.fd_t = @intCast(raw_command);
    defer _ = linux.close(command_fd);
    const fd_baseline = try countMatureDataDeviceFds();
    var client: MatureWorkspaceClient = .{ .runtime_directory = runtime_directory, .display_name = socket_name, .command_fd = command_fd };
    const thread = try std.Thread.spawn(.{}, MatureWorkspaceClient.run, .{&client});
    var joined = false;
    defer if (!joined) {
        client.shutdown();
        thread.join();
    };

    try waitForMatureWorkspaceStage(server, &client, .initial);
    try std.testing.expectEqual(@as(usize, 1), client.manager_global_count);
    try std.testing.expectEqual(@as(u32, 1), client.manager_global_version);
    try std.testing.expectEqual(@as(usize, 1), client.group_count);
    try std.testing.expectEqual(@as(usize, 1), client.output_enter_count);
    try std.testing.expectEqual(@as(usize, 1), client.workspace_count);
    try std.testing.expectEqual(@as(usize, 1), client.done_count);
    try std.testing.expectEqualStrings("1", client.names[0][0..client.name_lens[0]]);
    try std.testing.expectEqual(@as(u32, 0), client.coordinates[0]);
    try std.testing.expect(client.active[0] and client.activate_capable[0]);

    try signalWayringCommand(command_fd);
    try waitForMatureWorkspaceStage(server, &client, .mapped);
    server.window_manager.settleConfigureTransactionForTest();
    const focused_surface = server.window_manager.focusedSurface() orelse return error.MatureWorkspaceFocusMissing;
    const output = server.primaryRenderOutput().protocol_id;
    try std.testing.expect(server.neutral_workspace.snapshot(output).?.occupied[0]);

    server.window_manager.switchWorkspace(2);
    try renderPendingTestOutput(server, server.primaryRenderOutput());
    try renderPendingTestOutput(server, server.primaryRenderOutput());
    try signalWayringCommand(command_fd);
    try waitForMatureWorkspaceStage(server, &client, .second_workspace);
    try std.testing.expectEqual(@as(usize, 2), client.workspace_count);
    try std.testing.expectEqualStrings("2", client.names[1][0..client.name_lens[1]]);
    try std.testing.expectEqual(@as(u8, 2), server.neutral_workspace.snapshot(server.primaryRenderOutput().protocol_id).?.active);
    try std.testing.expect(client.active[1]);
    try std.testing.expect(server.window_manager.focusedSurface() == null);
    try signalWayringCommand(command_fd);
    try waitForMatureWorkspaceStage(server, &client, .activated);
    try std.testing.expectEqual(@as(u8, 1), server.neutral_workspace.snapshot(output).?.active);
    try std.testing.expect(client.active[0] and client.removed[1]);
    try std.testing.expectEqual(focused_surface, server.window_manager.focusedSurface().?);
    try signalWayringCommand(command_fd);
    try waitForMatureWorkspaceStage(server, &client, .child_destroyed);
    // The child was destroyed before this canonical update. Reconciliation must
    // never retain or call its dead resource. Occupied workspace 1 gets a fresh
    // handle generation, as does previously removed workspace 2.
    server.window_manager.switchWorkspace(2);
    try renderPendingTestOutput(server, server.primaryRenderOutput());
    try renderPendingTestOutput(server, server.primaryRenderOutput());
    try signalWayringCommand(command_fd);
    try waitForMatureWorkspaceStage(server, &client, .readvertised);
    try std.testing.expectEqual(@as(usize, 4), client.workspace_count);
    try std.testing.expectEqual(@as(u8, 2), server.neutral_workspace.snapshot(output).?.active);
    try std.testing.expect(client.active[3]);
    try signalWayringCommand(command_fd);
    try waitForMatureWorkspaceStage(server, &client, .finished);
    try signalWayringCommand(command_fd);
    try waitForMatureWorkspaceStage(server, &client, .disconnected);
    thread.join();
    joined = true;
    for (0..2_000) |_| {
        if (server.client_registry.len() == 0 and
            try countMatureDataDeviceFds() == fd_baseline) break;
        try server.eventLoop().dispatch(1);
    } else return error.MatureWorkspaceCleanupTimedOut;
    try std.testing.expectEqual(fd_baseline, try countMatureDataDeviceFds());
}

test "production mature data device v3 serves two canonical socket clients" {
    const linux = std.os.linux;
    var marker: u8 = 0;
    const runtime_directory = try std.fmt.allocPrintSentinel(
        std.testing.allocator,
        "/tmp/keywork-mature-data-device-{d}-{x}",
        .{ linux.getpid(), @intFromPtr(&marker) },
        0,
    );
    defer std.testing.allocator.free(runtime_directory);
    if (linux.errno(linux.mkdir(runtime_directory.ptr, 0o700)) != .SUCCESS)
        return error.TestDirectoryCreationFailed;
    defer _ = linux.rmdir(runtime_directory.ptr);
    const previous_runtime = if (libc.getenv("XDG_RUNTIME_DIR")) |value|
        try std.testing.allocator.dupeZ(u8, std.mem.span(value))
    else
        null;
    defer {
        if (previous_runtime) |value| {
            _ = libc.setenv("XDG_RUNTIME_DIR", value, 1);
            std.testing.allocator.free(value);
        } else {
            _ = libc.unsetenv("XDG_RUNTIME_DIR");
        }
    }
    if (libc.setenv("XDG_RUNTIME_DIR", runtime_directory, 1) != 0)
        return error.RuntimeEnvironmentFailed;
    const server = try Self.createWithVirtualOutput(
        std.testing.allocator,
        std.testing.io,
        .cpu,
        .headless,
        null,
        .{ .size = .{ .width = 640, .height = 480 }, .refresh_millihertz = 1 },
    );
    defer server.destroy();
    const socket_name = try server.listen();
    const output = server.primaryRenderOutput();
    const surface_baseline = server.compositor.surfaceStore().len();
    const registry_baseline = server.surface_registry.len();
    const resource_baseline = server.dataDeviceResourceSnapshot();
    try std.testing.expectEqual(
        NeutralDataDevice.ResourceCounts{ .sources = 0, .devices = 0, .offers = 0 },
        resource_baseline.neutral,
    );
    try std.testing.expectEqual(
        WaylandDataDevice.ResourceCounts{ .sources = 0, .devices = 0, .offers = 0 },
        resource_baseline.mature,
    );
    try std.testing.expect(!resource_baseline.has_selection and !resource_baseline.dragging);

    const keymap_fd = try std.posix.memfd_create("keywork-mature-data-keymap", linux.MFD.CLOEXEC);
    const keymap = "keymap\x00\x00";
    if (linux.errno(linux.ftruncate(keymap_fd, keymap.len)) != .SUCCESS)
        return error.KeymapResizeFailed;
    if (std.c.pwrite(keymap_fd, keymap.ptr, keymap.len, 0) != keymap.len)
        return error.KeymapWriteFailed;
    server.seat.setKeymap(.xkb_v1, keymap_fd, keymap.len);
    server.seat.setRepeatInfo(0, 500);
    server.seat.setKeyboardAvailable(true);
    server.seat.setPointerAvailable(true);

    const raw_source_command = linux.eventfd(0, linux.EFD.CLOEXEC);
    const raw_target_command = linux.eventfd(0, linux.EFD.CLOEXEC);
    if (linux.errno(raw_source_command) != .SUCCESS or linux.errno(raw_target_command) != .SUCCESS)
        return error.EventFdFailed;
    const source_command: std.posix.fd_t = @intCast(raw_source_command);
    const target_command: std.posix.fd_t = @intCast(raw_target_command);
    defer _ = linux.close(source_command);
    defer _ = linux.close(target_command);
    const fd_baseline = try countMatureDataDeviceFds();
    var source: MatureDataDeviceClient = .{
        .runtime_directory = runtime_directory,
        .display_name = socket_name,
        .command_fd = source_command,
        .role = .source,
    };
    var target: MatureDataDeviceClient = .{
        .runtime_directory = runtime_directory,
        .display_name = socket_name,
        .command_fd = target_command,
        .role = .target,
    };
    const source_thread = try std.Thread.spawn(.{}, MatureDataDeviceClient.run, .{&source});
    const target_thread = try std.Thread.spawn(.{}, MatureDataDeviceClient.run, .{&target});
    var source_joined = false;
    var target_joined = false;
    defer if (!source_joined) {
        source.shutdown();
        source_thread.join();
    };
    defer if (!target_joined) {
        target.shutdown();
        target_thread.join();
    };
    try waitForMatureDataDeviceStage(server, &source, .ready);
    try waitForMatureDataDeviceStage(server, &target, .ready);
    try std.testing.expectEqual(@as(usize, 2), server.client_registry.len());

    var source_surface: ?Surface.Id = null;
    var target_surface: ?Surface.Id = null;
    var surfaces = server.compositor.surfaceStore().iterator();
    while (surfaces.next()) |entry| {
        const state = server.surface_registry.renderState(entry.id) orelse continue;
        if (state.buffer.pixels.len != 1) continue;
        if (state.buffer.pixels[0] == 0xff22_4466) source_surface = entry.id;
        if (state.buffer.pixels[0] == 0xff66_4422) target_surface = entry.id;
    }
    const source_id = source_surface orelse return error.SourceSurfaceMissing;
    const target_id = target_surface orelse return error.TargetSurfaceMissing;
    const source_scene = try server.scene.addShellSurface(source_id);
    errdefer server.scene.removeShellSurface(source_scene);
    const target_scene = try server.scene.addShellSurface(target_id);
    errdefer server.scene.removeShellSurface(target_scene);
    server.scene.setShellSurfacePosition(source_scene, .{ .x = 10, .y = 10 });
    server.scene.setShellSurfacePosition(target_scene, .{ .x = 30, .y = 10 });
    server.scene.setShellSurfaceMapped(source_scene, true);
    server.scene.setShellSurfaceMapped(target_scene, true);

    _ = server.seat.applyMatureKeyboardFocus(source_id);
    try server.seat.parentKeyboardEnter(&.{});
    pointerMotion(output, 10, 10.5, 10.5);
    pointerFrame(output);
    try signalWayringCommand(source_command);
    try waitForMatureDataDeviceStage(server, &source, .selection_set);
    const selected = server.dataDeviceResourceSnapshot();
    try std.testing.expect(selected.has_selection);
    try std.testing.expect(target.offer == null);
    try std.testing.expectEqual(@as(usize, 1), selected.neutral.sources);
    try std.testing.expectEqual(@as(usize, 2), selected.neutral.devices);
    try signalWayringCommand(target_command);
    try waitForMatureDataDeviceStage(server, &target, .control_selection_ready);
    try std.testing.expect(target.offer == null);
    try signalWayringCommand(source_command);
    try waitForMatureDataDeviceStage(server, &source, .late_mime_offered);
    try signalWayringCommand(target_command);
    try waitForMatureDataDeviceStage(server, &target, .late_mime_received);
    try std.testing.expect(target.controlEventIndex(.data_offer).? < target.controlEventIndex(.initial_mime).?);
    try std.testing.expect(target.controlEventIndex(.initial_mime).? < target.controlEventIndex(.selection).?);
    try std.testing.expect(target.controlEventIndex(.selection).? < target.controlEventIndex(.late_mime).?);

    _ = server.seat.applyMatureKeyboardFocus(target_id);
    try server.seat.parentKeyboardEnter(&.{});
    try signalWayringCommand(target_command);
    try signalWayringCommand(source_command);
    try waitForMatureDataDeviceStage(server, &source, .selection_sent);
    try waitForMatureDataDeviceStage(server, &target, .selection_received);
    try std.testing.expect(source.eventIndex(.send).? < source.event_count);
    try std.testing.expect(target.eventIndex(.data_offer).? < target.eventIndex(.offer_mime).?);
    try std.testing.expect(target.eventIndex(.offer_mime).? < target.eventIndex(.selection).?);

    try signalWayringCommand(target_command);
    try waitForMatureDataDeviceStage(server, &target, .selection_replaced);
    const replacement = server.dataDeviceResourceSnapshot();
    try std.testing.expect(replacement.selection_generation > selected.selection_generation);
    try signalWayringCommand(source_command);
    try waitForMatureDataDeviceStage(server, &source, .stale_mime_offered);
    try signalWayringCommand(target_command);
    try waitForMatureDataDeviceStage(server, &target, .stale_mime_checked);
    try std.testing.expect(!target.control_stale_mime_seen);
    try signalWayringCommand(source_command);
    try waitForMatureDataDeviceStage(server, &source, .stale_clear_checked);
    const after_stale_clear = server.dataDeviceResourceSnapshot();
    try std.testing.expectEqual(replacement.selection_generation, after_stale_clear.selection_generation);
    try std.testing.expect(after_stale_clear.has_selection);
    try std.testing.expect(source.eventIndex(.send).? < source.eventIndex(.cancelled).?);

    try signalWayringCommand(target_command);
    try waitForMatureDataDeviceStage(server, &target, .selection_cleared);
    try signalWayringCommand(source_command);
    try waitForMatureDataDeviceStage(server, &source, .selection_cleared);
    const cleared = server.dataDeviceResourceSnapshot();
    try std.testing.expect(!cleared.has_selection);
    try std.testing.expect(cleared.selection_generation > replacement.selection_generation);

    const source_drag_event_start = source.event_count;
    const target_drag_event_start = target.event_count;
    _ = server.seat.applyMatureKeyboardFocus(source_id);
    try server.seat.parentKeyboardEnter(&.{});
    pointerMotion(output, 20, 10.5, 10.5);
    pointerButton(output, 21, linux_button_left, .pressed);
    pointerFrame(output);
    try signalWayringCommand(source_command);
    try waitForMatureDataDeviceStage(server, &source, .drag_rejected);
    try std.testing.expect(!server.dataDeviceResourceSnapshot().dragging);
    try std.testing.expect(server.mature_data_device.iconInfo() == null);
    try signalWayringCommand(source_command);
    try waitForMatureDataDeviceStage(server, &source, .drag_started);
    try std.testing.expect(server.dataDeviceResourceSnapshot().dragging);
    try std.testing.expect(server.mature_data_device.iconInfo() != null);
    try signalWayringCommand(source_command);
    try waitForMatureDataDeviceStage(server, &source, .icon_destroyed);
    try std.testing.expect(server.dataDeviceResourceSnapshot().dragging);
    try std.testing.expect(server.mature_data_device.iconInfo() == null);

    pointerMotion(output, 22, 30.5, 10.5);
    pointerFrame(output);
    try signalWayringCommand(target_command);
    try signalWayringCommand(source_command);
    try waitForMatureDataDeviceStage(server, &source, .drag_received);
    try waitForMatureDataDeviceStage(server, &target, .drag_received);
    const target_data_offer = target.eventIndexAfter(.data_offer, target_drag_event_start).?;
    const target_offer_mime = target.eventIndexAfter(.offer_mime, target_drag_event_start).?;
    const target_source_actions = target.eventIndexAfter(.source_actions, target_drag_event_start).?;
    const target_enter = target.eventIndexAfter(.enter, target_drag_event_start).?;
    const target_motion = target.eventIndexAfter(.motion, target_drag_event_start).?;
    const target_action = target.eventIndexAfter(.action, target_drag_event_start).?;
    try std.testing.expect(target_data_offer < target_offer_mime);
    try std.testing.expect(target_offer_mime < target_source_actions);
    try std.testing.expect(target_source_actions < target_action);
    try std.testing.expect(target_action < target_enter);
    try std.testing.expect(target_enter < target_motion);
    const source_target = source.eventIndexAfter(.target, source_drag_event_start).?;
    const source_action = source.eventIndexAfter(.action, source_drag_event_start).?;
    const source_send = source.eventIndexAfter(.send, source_drag_event_start).?;
    try std.testing.expect(source_action < source_target);
    try std.testing.expect(source_target < source_send);
    try std.testing.expectApproxEqAbs(@as(f64, 0.5), target.enter_x, 0.01);
    try std.testing.expectApproxEqAbs(@as(f64, 0.5), target.enter_y, 0.01);
    try std.testing.expectApproxEqAbs(@as(f64, 0.5), target.motion_x, 0.01);
    try std.testing.expectApproxEqAbs(@as(f64, 0.5), target.motion_y, 0.01);

    const canonical_before_offender = server.dataDeviceResourceSnapshot();
    const raw_offender_command = linux.eventfd(0, linux.EFD.CLOEXEC);
    if (linux.errno(raw_offender_command) != .SUCCESS) return error.EventFdFailed;
    const offender_command: std.posix.fd_t = @intCast(raw_offender_command);
    var offender_command_open = true;
    defer if (offender_command_open) {
        _ = linux.close(offender_command);
    };
    var offender: MatureDataDeviceClient = .{
        .runtime_directory = runtime_directory,
        .display_name = socket_name,
        .command_fd = offender_command,
        .role = .offender,
    };
    const offender_thread = try std.Thread.spawn(.{}, MatureDataDeviceClient.run, .{&offender});
    try waitForMatureDataDeviceStage(server, &offender, .offender_ready);
    const offender_identity = server.mature_data_device.uniqueUnboundProtocolSourceIdentity(offender.source_object_id) orelse
        return error.OffenderSourceIdentityMissing;
    expectProtocolErrorForTest(offender_identity.client, "wl_data_source", offender_identity.object_id, 0);
    defer clearExpectedProtocolErrorForTest();
    try signalWayringCommand(offender_command);
    try waitForMatureDataDeviceStage(server, &offender, .disconnected);
    offender_thread.join();
    try closeMatureTransferFd(offender_command);
    offender_command_open = false;
    for (0..1_000) |_| {
        if (server.client_registry.len() == 2) break;
        try server.eventLoop().dispatch(1);
    } else return error.OffenderCleanupTimedOut;
    try finishExpectedProtocolErrorForTest();
    try std.testing.expectEqual(canonical_before_offender, server.dataDeviceResourceSnapshot());

    pointerButton(output, 23, linux_button_left, .released);
    pointerFrame(output);
    try signalWayringCommand(target_command);
    try signalWayringCommand(source_command);
    try waitForMatureDataDeviceStage(server, &target, .drop_finished);
    try waitForMatureDataDeviceStage(server, &source, .drop_finished);
    try signalWayringCommand(source_command);
    try waitForMatureDataDeviceStage(server, &source, .source_finished);
    const source_drop = source.eventIndexAfter(.drop_performed, source_drag_event_start).?;
    const source_finished = source.eventIndexAfter(.finished, source_drag_event_start).?;
    try std.testing.expect(source_send < source_drop);
    try std.testing.expect(source_drop < source_finished);
    try std.testing.expect(target.eventIndexAfter(.drop, target_drag_event_start).? <
        target.eventIndexAfter(.leave, target_drag_event_start).?);

    server.scene.setShellSurfaceMapped(target_scene, false);
    server.scene.setShellSurfaceMapped(source_scene, false);
    server.scene.removeShellSurface(target_scene);
    server.scene.removeShellSurface(source_scene);
    try signalWayringCommand(target_command);
    try signalWayringCommand(source_command);
    try waitForMatureDataDeviceStage(server, &target, .disconnected);
    try waitForMatureDataDeviceStage(server, &source, .disconnected);
    target_thread.join();
    target_joined = true;
    source_thread.join();
    source_joined = true;
    for (0..2_000) |_| {
        const snapshot = server.dataDeviceResourceSnapshot();
        if (server.client_registry.len() == 0 and
            server.compositor.surfaceStore().len() == surface_baseline and
            snapshot.neutral.sources == 0 and snapshot.neutral.devices == 0 and
            snapshot.neutral.offers == 0 and snapshot.mature.sources == 0 and
            snapshot.mature.devices == 0 and snapshot.mature.offers == 0) break;
        try server.eventLoop().dispatch(1);
    } else return error.MatureDataDeviceCleanupTimedOut;
    const final = server.dataDeviceResourceSnapshot();
    try std.testing.expectEqual(resource_baseline.neutral, final.neutral);
    try std.testing.expectEqual(resource_baseline.mature, final.mature);
    try std.testing.expect(!final.has_selection and !final.dragging);
    try std.testing.expect(final.selection_generation >= resource_baseline.selection_generation);
    try std.testing.expectEqual(registry_baseline, server.surface_registry.len());
    try std.testing.expect(server.scene.topWindowSurface() == null);
    try std.testing.expect(server.seat.matureKeyboardFocus() == null);
    try std.testing.expect(server.mature_data_device.iconInfo() == null);
    try std.testing.expectEqual(fd_baseline, try countMatureDataDeviceFds());
}

test "production mature text input v3 and input method v2 transact over canonical clients" {
    const server = try Self.createWithVirtualOutput(std.testing.allocator, std.testing.io, .cpu, .headless, null, .{ .size = .{ .width = 4, .height = 4 } });
    defer server.destroy();
    const baseline = server.neutral_text_input.resourceSnapshot();
    const surfaces = server.compositor.surfaceStore().len();
    const registry = server.surface_registry.len();
    var keymap_pipe: [2]std.posix.fd_t = undefined;
    if (std.c.pipe(&keymap_pipe) != 0) return error.Unexpected;
    defer _ = std.c.close(keymap_pipe[1]);
    server.seat.setKeymap(.xkb_v1, keymap_pipe[0], 8);
    server.seat.setRepeatInfo(25, 500);
    server.seat.setKeyboardAvailable(true);
    defer server.seat.setKeyboardAvailable(false);
    const fds = try countMatureDataDeviceFds();
    var sockets_app: [2]std.posix.fd_t = undefined;
    var sockets_method: [2]std.posix.fd_t = undefined;
    try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM | std.c.SOCK.CLOEXEC, 0, &sockets_app));
    try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM | std.c.SOCK.CLOEXEC, 0, &sockets_method));
    _ = wl.Client.create(server.display, sockets_app[0]) orelse return error.OutOfMemory;
    _ = wl.Client.create(server.display, sockets_method[0]) orelse return error.OutOfMemory;
    var app: MatureTextClient = .{ .fd = sockets_app[1], .role = .application };
    var method: MatureTextClient = .{ .fd = sockets_method[1], .role = .input_method };
    const app_thread = try std.Thread.spawn(.{}, MatureTextClient.run, .{&app});
    const method_thread = try std.Thread.spawn(.{}, MatureTextClient.run, .{&method});
    var app_joined = false;
    var method_joined = false;
    defer if (!app_joined) {
        app.shutdown();
        app_thread.join();
    };
    defer if (!method_joined) {
        method.shutdown();
        method_thread.join();
    };
    try waitForMatureTextStage(server, &app, .ready);
    try waitForMatureTextStage(server, &method, .ready);
    var iterator = server.compositor.surfaceStore().iterator();
    const surface = (iterator.next() orelse return error.MatureSurfaceMissing).id;
    // The shared input-method client also materializes its protocol-authentic
    // popup surface; the application surface remains first in creation order.
    try std.testing.expect(iterator.next() != null);
    try std.testing.expect(iterator.next() == null);
    _ = server.seat.applyMatureKeyboardFocus(surface);
    try server.seat.parentKeyboardEnter(&.{});
    app.proceed.store(true, .release);
    try waitForMatureTextStage(server, &method, .state_received);
    try std.testing.expectEqualSlices(u8, &.{ 1, 2, 3, 4, 5 }, method.method_events[0..method.method_event_count]);
    try std.testing.expectEqual(@as(u32, 2), app.text_manager_version);
    try std.testing.expectEqual(@as(u32, (1 << 0) | (1 << 10) | (1 << 11) | (1 << 12)), method.method_content_hint);
    method.proceed.store(true, .release);
    try waitForMatureTextStage(server, &app, .edit_received);
    try std.testing.expectEqualSlices(MatureTextClient.EditTag, &.{ .preedit, .delete, .commit, .done }, app.edits[0..app.edit_count]);
    try std.testing.expectEqual(@as(u32, 1), app.done_serial);
    try std.testing.expect(method.grab_delivery);
    app.shutdown();
    method.shutdown();
    app_thread.join();
    app_joined = true;
    method_thread.join();
    method_joined = true;
    for (0..2_000) |_| {
        if (server.client_registry.len() == 0 and server.compositor.surfaceStore().len() == surfaces and
            std.meta.eql(server.neutral_text_input.resourceSnapshot(), baseline)) break;
        try server.eventLoop().dispatch(1);
    } else return error.MatureTextCleanupTimedOut;
    try std.testing.expectEqual(registry, server.surface_registry.len());
    try std.testing.expectEqual(fds, try countMatureDataDeviceFds());
}

test "mature keyboard late bind reuses one logical enter serial and authority grant" {
    const KeyboardFocusProbe = struct {
        changes: usize = 0,
        null_changes: usize = 0,
        client: ?*wl.Client = null,

        fn changed(context: *anyopaque, client: ?*wl.Client) void {
            const self: *@This() = @ptrCast(@alignCast(context));
            self.changes += 1;
            if (client == null) self.null_changes += 1;
            self.client = client;
        }
    };
    const server = try Self.createWithVirtualOutput(
        std.testing.allocator,
        std.testing.io,
        .cpu,
        .headless,
        null,
        .{ .size = .{ .width = 4, .height = 4 } },
    );
    defer server.destroy();

    server.seat.parentKeyboardLeave();
    var keymap_pipe: [2]std.posix.fd_t = undefined;
    if (std.c.pipe(&keymap_pipe) != 0) return error.Unexpected;
    defer _ = std.c.close(keymap_pipe[1]);
    server.seat.setKeymap(.xkb_v1, keymap_pipe[0], 8);
    server.seat.setRepeatInfo(25, 500);
    server.seat.setKeyboardAvailable(true);
    defer server.seat.setKeyboardAvailable(false);

    var sockets: [2]std.posix.fd_t = undefined;
    try std.testing.expectEqual(
        @as(c_int, 0),
        std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM | std.c.SOCK.CLOEXEC, 0, &sockets),
    );
    const mature_client = wl.Client.create(server.display, sockets[0]) orelse return error.OutOfMemory;
    const client_id = server.mature_clients.id(mature_client) orelse return error.TestUnexpectedResult;
    var focus_probe: KeyboardFocusProbe = .{};
    try server.seat.addKeyboardFocusListener(.{
        .context = &focus_probe,
        .changed = KeyboardFocusProbe.changed,
    });
    defer server.seat.removeKeyboardFocusListener(&focus_probe);
    const raw_command_fd = std.os.linux.eventfd(0, std.os.linux.EFD.CLOEXEC);
    if (std.os.linux.errno(raw_command_fd) != .SUCCESS) return error.EventFdFailed;
    const command_fd: std.posix.fd_t = @intCast(raw_command_fd);
    defer _ = std.os.linux.close(command_fd);
    var client: MatureKeyboardClient = .{
        .fd = sockets[1],
        .command_fd = command_fd,
    };
    const thread = try std.Thread.spawn(.{}, MatureKeyboardClient.run, .{&client});
    var joined = false;
    defer if (!joined) {
        client.shutdown();
        thread.join();
    };

    try waitForMatureKeyboardStage(server, &client, .resources_bound);
    var surfaces = server.compositor.surfaceStore().iterator();
    const surface = (surfaces.next() orelse return error.MatureSurfaceMissing).id;
    try std.testing.expect(surfaces.next() == null);
    _ = server.seat.applyMatureKeyboardFocus(surface);
    server.seat.setModifiers(1, 2, 4, 3);
    try server.seat.parentKeyboardEnter(&.{30});
    const first_serial = server.seat.authority.latestKeyboardEnterSerial(client_id) orelse
        return error.MatureKeyboardEnterGrantMissing;
    const first_order = server.seat.authority.selectionOrder(client_id, first_serial) orelse
        return error.MatureKeyboardEnterOrderMissing;
    try std.testing.expectEqual(ClientRegistry.SerialDomain.mature_display, first_serial.domain);
    try std.testing.expectEqual(surface, server.seat.matureKeyboardFocus().?);

    try signalWayringCommand(command_fd);
    try waitForMatureKeyboardStage(server, &client, .focused);
    try std.testing.expectEqual(first_serial.value, client.first.enter_serials[0]);

    try signalWayringCommand(command_fd);
    try waitForMatureKeyboardStage(server, &client, .late_bound);
    try std.testing.expectEqual(first_serial.value, client.second.enter_serials[0]);
    try std.testing.expectEqual(@as(usize, 1), client.first.enter_count);
    try std.testing.expectEqual(
        first_order,
        server.seat.authority.selectionOrder(client_id, first_serial).?,
    );
    try std.testing.expectEqual(
        first_serial,
        server.seat.authority.latestKeyboardEnterSerial(client_id).?,
    );

    _ = server.seat.applyMatureKeyboardFocus(null);
    try std.testing.expect(server.seat.authority.latestKeyboardEnterSerial(client_id) == null);
    _ = server.seat.applyMatureKeyboardFocus(surface);
    const second_serial = server.seat.authority.latestKeyboardEnterSerial(client_id) orelse
        return error.MatureKeyboardReenterGrantMissing;
    const second_order = server.seat.authority.selectionOrder(client_id, second_serial) orelse
        return error.MatureKeyboardReenterOrderMissing;
    try std.testing.expect(second_serial.value != first_serial.value);
    try std.testing.expect(second_order > first_order);

    try signalWayringCommand(command_fd);
    try waitForMatureKeyboardStage(server, &client, .reentered);
    try std.testing.expectEqual(second_serial.value, client.first.enter_serials[1]);
    try std.testing.expectEqual(second_serial.value, client.second.enter_serials[1]);

    const GrabProbe = struct {
        fn cancel(_: *anyopaque) void {}
        fn keymap(_: *anyopaque, _: wl.Keyboard.KeymapFormat, _: std.posix.fd_t, _: u32) void {}
        fn key(_: *anyopaque, _: u32, _: u32, _: u32, _: wl.Keyboard.KeyState) void {}
        fn modifiers(_: *anyopaque, _: u32, _: u32, _: u32, _: u32, _: u32) void {}
        fn repeatInfo(_: *anyopaque, _: i32, _: i32) void {}
    };
    var grab_probe: GrabProbe = .{};
    try std.testing.expect(server.seat.setKeyboardGrab(.{
        .context = &grab_probe,
        .token = 1,
        .surface = surface,
        .cancel = GrabProbe.cancel,
        .keymap = GrabProbe.keymap,
        .key = GrabProbe.key,
        .modifiers = GrabProbe.modifiers,
        .repeat_info = GrabProbe.repeatInfo,
    }));
    const grab_serial = server.seat.authority.latestKeyboardEnterSerial(client_id) orelse
        return error.MatureKeyboardGrabEnterGrantMissing;
    const grab_order = server.seat.authority.selectionOrder(client_id, grab_serial) orelse
        return error.MatureKeyboardGrabEnterOrderMissing;
    try std.testing.expect(grab_serial.value != second_serial.value);
    try std.testing.expect(grab_order > second_order);
    _ = server.seat.applyMatureKeyboardFocus(null);
    try std.testing.expectEqual(
        grab_serial,
        server.seat.authority.latestKeyboardEnterSerial(client_id).?,
    );
    try std.testing.expectEqual(mature_client, server.seat.keyboardFocusedClient().?);

    var generated_provider: SyntheticSurfaceProvider = .{
        .pixel = 0xff12_3456,
        .logical_size = .{ .width = 1, .height = 1 },
    };
    const generated_surface = try server.surface_registry.add(generated_provider.provider());
    defer server.surface_registry.remove(generated_surface);
    const disconnecting_generated = try server.client_registry.register(.wayring_server);
    try std.testing.expect(server.seat.applyGeneratedKeyboardFocus(.{
        .surface = generated_surface,
        .client = disconnecting_generated,
    }, null));
    server.client_registry.unregister(disconnecting_generated);
    try std.testing.expectEqual(
        grab_serial,
        server.seat.authority.latestKeyboardEnterSerial(client_id).?,
    );
    try std.testing.expectEqual(mature_client, server.seat.keyboardFocusedClient().?);
    const retiring_generated = try server.client_registry.register(.wayring_server);
    try std.testing.expect(server.seat.applyGeneratedKeyboardFocus(.{
        .surface = generated_surface,
        .client = retiring_generated,
    }, null));
    try std.testing.expect(server.seat.retireGeneratedClient(retiring_generated));
    try std.testing.expectEqual(
        grab_serial,
        server.seat.authority.latestKeyboardEnterSerial(client_id).?,
    );
    try std.testing.expectEqual(mature_client, server.seat.keyboardFocusedClient().?);
    server.client_registry.unregister(retiring_generated);

    try signalWayringCommand(command_fd);
    try waitForMatureKeyboardStage(server, &client, .resource_rebound);
    try std.testing.expectEqual(grab_serial.value, client.third.enter_serials[0]);
    try std.testing.expectEqual(@as(usize, 3), client.first.enter_count);
    try std.testing.expectEqual(
        grab_order,
        server.seat.authority.selectionOrder(client_id, grab_serial).?,
    );
    try std.testing.expectEqual(
        grab_serial,
        server.seat.authority.latestKeyboardEnterSerial(client_id).?,
    );
    _ = server.seat.applyMatureKeyboardFocus(surface);
    server.seat.clearKeyboardGrab(&grab_probe, true);
    try std.testing.expectEqual(surface, server.seat.matureKeyboardFocus().?);
    try std.testing.expectEqual(mature_client, server.seat.keyboardFocusedClient().?);
    const disconnect_serial = server.seat.authority.latestKeyboardEnterSerial(client_id) orelse
        return error.MatureKeyboardDisconnectGrantMissing;
    try std.testing.expect(disconnect_serial.value != grab_serial.value);
    try std.testing.expectEqual(mature_client, focus_probe.client.?);
    const focus_changes_before_disconnect = focus_probe.changes;
    const null_changes_before_disconnect = focus_probe.null_changes;

    try signalWayringCommand(command_fd);
    try waitForMatureKeyboardStage(server, &client, .disconnected);
    thread.join();
    joined = true;
    for (0..1_000) |_| {
        if (server.client_registry.len() == 0) break;
        try server.eventLoop().dispatch(1);
    } else return error.MatureKeyboardClientTimedOut;
    try std.testing.expect(server.seat.matureKeyboardFocus() == null);
    try std.testing.expect(server.seat.authority.latestKeyboardEnterSerial(client_id) == null);
    try std.testing.expect(focus_probe.changes > focus_changes_before_disconnect);
    try std.testing.expect(focus_probe.null_changes > null_changes_before_disconnect);
    try std.testing.expect(focus_probe.client == null);
    try std.testing.expectEqual(@as(usize, 0), server.compositor.surfaceStore().len());
}

test "canonical generated keyboard delivery preserves focus aggregation authority grabs and repeats" {
    const server = try Self.createWithVirtualOutput(
        std.testing.allocator,
        std.testing.io,
        .cpu,
        .headless,
        null,
        .{ .size = .{ .width = 4, .height = 4 } },
    );
    defer server.destroy();
    var provider_a: SyntheticSurfaceProvider = .{
        .pixel = 0xff11_1111,
        .logical_size = .{ .width = 2, .height = 2 },
    };
    var provider_b: SyntheticSurfaceProvider = .{
        .pixel = 0xff22_2222,
        .logical_size = .{ .width = 2, .height = 2 },
    };
    const root_a = try server.surface_registry.add(provider_a.provider());
    const root_b = try server.surface_registry.add(provider_b.provider());
    var surfaces_live = true;
    try server.addHeadlessSurface(root_a, null);
    try server.addHeadlessSurface(root_b, null);
    server.applyHeadlessBatch(.{
        .surfaces = &.{
            .{ .id = root_a, .mapped_size = provider_a.logical_size, .callbacks_committed = false },
            .{ .id = root_b, .mapped_size = provider_b.logical_size, .callbacks_committed = false },
        },
        .parents = &.{},
    });
    defer if (surfaces_live) {
        server.removeHeadlessSurface(root_b);
        server.surface_registry.remove(root_b);
        server.removeHeadlessSurface(root_a);
        server.surface_registry.remove(root_a);
    };

    const client_a = try server.client_registry.register(.wayring_server);
    var client_a_live = true;
    defer if (client_a_live) server.client_registry.unregister(client_a);
    const client_b = try server.client_registry.register(.wayring_server);
    var client_b_live = true;
    defer if (client_b_live) server.client_registry.unregister(client_b);
    var sink: TestGeneratedSeatSink = .{
        .clients = &server.client_registry,
        .client = client_a,
        .other_client = client_b,
        .other_surface = root_b,
    };
    server.setGeneratedSeatDeliverySink(sink.sink());
    defer server.clearGeneratedSeatDeliverySink(&sink);

    var pipe_fds: [2]std.posix.fd_t = undefined;
    if (std.c.pipe(&pipe_fds) != 0) return error.Unexpected;
    defer _ = std.c.close(pipe_fds[1]);
    server.seat.setKeymap(.xkb_v1, pipe_fds[0], 8);
    server.seat.setKeyboardAvailable(true);
    try server.seat.parentKeyboardEnter(&.{30});
    defer server.seat.setKeyboardAvailable(false);
    var virtual_owner: u8 = 0;
    try server.seat.createVirtualKeyboard(&virtual_owner);
    var virtual_owner_live = true;
    defer if (virtual_owner_live) server.seat.destroyVirtualKeyboard(&virtual_owner);
    const virtual_keymap_fd = try std.posix.memfd_create("keywork-seat-virtual-test", std.os.linux.MFD.CLOEXEC);
    const virtual_keymap = "keymap\x00";
    if (std.os.linux.errno(std.os.linux.ftruncate(virtual_keymap_fd, virtual_keymap.len)) != .SUCCESS or
        std.c.pwrite(virtual_keymap_fd, virtual_keymap.ptr, virtual_keymap.len, 0) != virtual_keymap.len)
        return error.VirtualKeymapSetupFailed;
    try server.seat.setVirtualKeyboardKeymap(&virtual_owner, virtual_keymap_fd, virtual_keymap.len);
    var virtual_owner_b: u8 = 0;
    try server.seat.createVirtualKeyboard(&virtual_owner_b);
    var virtual_owner_b_live = true;
    defer if (virtual_owner_b_live) server.seat.destroyVirtualKeyboard(&virtual_owner_b);
    const virtual_keymap_b_fd = try std.posix.memfd_create("keywork-seat-virtual-test-b", std.os.linux.MFD.CLOEXEC);
    if (std.os.linux.errno(std.os.linux.ftruncate(virtual_keymap_b_fd, virtual_keymap.len)) != .SUCCESS or
        std.c.pwrite(virtual_keymap_b_fd, virtual_keymap.ptr, virtual_keymap.len, 0) != virtual_keymap.len)
        return error.VirtualKeymapSetupFailed;
    try server.seat.setVirtualKeyboardKeymap(&virtual_owner_b, virtual_keymap_b_fd, virtual_keymap.len);
    const invalid_keymap_fd = try std.posix.memfd_create("keywork-seat-virtual-invalid", std.os.linux.MFD.CLOEXEC);
    try std.testing.expectError(
        error.InvalidKeymap,
        server.seat.setVirtualKeyboardKeymap(&virtual_owner_b, invalid_keymap_fd, 0),
    );
    try std.testing.expect(std.c.fcntl(invalid_keymap_fd, std.posix.F.GETFD) < 0);

    try std.testing.expect(server.focusGeneratedSurface(root_a));
    try std.testing.expectEqualSlices(TestGeneratedSeatSink.KeyboardTag, &.{.enter}, sink.keyboard_events[0..sink.keyboard_event_count]);
    try std.testing.expectEqual(client_a, sink.keyboard_clients[0]);
    try std.testing.expectEqual(root_a, sink.keyboard_surfaces[0]);
    try std.testing.expectEqual(@as(u32, 1), sink.keyboard_serials[0]);
    try std.testing.expectEqualSlices(u32, &.{30}, sink.keyboard_pressed_keys[0][0..sink.keyboard_pressed_key_counts[0]]);
    const keyboard_snapshot = server.seat.generatedKeyboardResourceSnapshot(
        client_a,
        server.seat.deliverySnapshot().capabilities.keyboard.generation,
    ).?;
    try std.testing.expectEqual(@as(u32, 1), keyboard_snapshot.focus.?.serial.value);
    try std.testing.expectEqualSlices(u32, &.{30}, keyboard_snapshot.focus.?.pressed_keys);
    try std.testing.expectEqual(@as(u32, 2), sink.next_serial);

    server.seat.setModifiers(1, 2, 4, 3);
    try server.seat.key(1, 31, .pressed);
    const press_serial: ClientRegistry.Serial = .{ .domain = .wayring_server, .value = 3 };
    try std.testing.expect(server.seat.authority.acceptsAction(client_a, press_serial));
    try std.testing.expect(server.seat.authority.selectionOrder(client_a, press_serial) != null);
    try server.seat.virtualKey(&virtual_owner, 2, 31, .pressed);
    try server.seat.key(3, 31, .released);
    try std.testing.expectEqual(@as(usize, 3), sink.keyboard_event_count);
    try server.seat.virtualKey(&virtual_owner, 4, 31, .released);
    const release_serial: ClientRegistry.Serial = .{ .domain = .wayring_server, .value = 4 };
    try std.testing.expect(!server.seat.authority.acceptsAction(client_a, release_serial));
    try std.testing.expect(server.seat.authority.selectionOrder(client_a, release_serial) != null);

    const events_before_overlap = sink.keyboard_event_count;
    try server.seat.virtualKey(&virtual_owner, 9, 33, .pressed);
    try server.seat.virtualKey(&virtual_owner_b, 10, 33, .pressed);
    try std.testing.expectEqual(events_before_overlap + 1, sink.keyboard_event_count);
    server.seat.releaseVirtualKeyboard(&virtual_owner_b);
    try std.testing.expectEqual(events_before_overlap + 1, sink.keyboard_event_count);
    try server.seat.virtualKey(&virtual_owner, 11, 33, .released);
    try std.testing.expectEqual(events_before_overlap + 2, sink.keyboard_event_count);

    try server.seat.virtualKey(&virtual_owner, 12, 34, .pressed);
    const events_before_inhibition = sink.keyboard_event_count;
    server.seat.setVirtualKeyboardsInhibited(true);
    try std.testing.expectEqual(events_before_inhibition + 1, sink.keyboard_event_count);
    try server.seat.virtualKey(&virtual_owner, 13, 35, .pressed);
    try std.testing.expectEqual(events_before_inhibition + 1, sink.keyboard_event_count);
    server.seat.setVirtualKeyboardsInhibited(false);

    try server.seat.key(5, 32, .pressed);
    try server.seat.key(6, 32, .repeated);
    const events_after_repeat = sink.keyboard_event_count;
    server.seat.setRepeatInfo(25, 500);
    try server.seat.key(7, 32, .repeated);
    try std.testing.expectEqual(events_after_repeat, sink.keyboard_event_count);
    server.seat.setRepeatInfo(0, 500);
    try server.seat.key(8, 32, .repeated);
    try std.testing.expectEqual(SeatDelivery.KeyState.repeated, sink.keyboard_states[sink.keyboard_event_count - 1].?);

    const GrabProbe = struct {
        key_count: usize = 0,

        fn cancel(_: *anyopaque) void {}
        fn keymap(_: *anyopaque, _: wl.Keyboard.KeymapFormat, _: std.posix.fd_t, _: u32) void {}
        fn key(context: *anyopaque, _: u32, _: u32, _: u32, _: wl.Keyboard.KeyState) void {
            const self: *@This() = @ptrCast(@alignCast(context));
            self.key_count += 1;
        }
        fn modifiers(_: *anyopaque, _: u32, _: u32, _: u32, _: u32, _: u32) void {}
        fn repeatInfo(_: *anyopaque, _: i32, _: i32) void {}
    };
    var grab_probe: GrabProbe = .{};
    try std.testing.expect(server.seat.setKeyboardGrab(.{
        .context = &grab_probe,
        .token = 42,
        .cancel = GrabProbe.cancel,
        .keymap = GrabProbe.keymap,
        .key = GrabProbe.key,
        .modifiers = GrabProbe.modifiers,
        .repeat_info = GrabProbe.repeatInfo,
    }));
    const before_grab_key = sink.keyboard_event_count;
    try server.seat.key(9, 33, .pressed);
    try std.testing.expectEqual(@as(usize, 1), grab_probe.key_count);
    try std.testing.expectEqual(before_grab_key, sink.keyboard_event_count);
    server.seat.clearKeyboardGrab(&grab_probe, true);
    try server.seat.key(10, 33, .released);
    try std.testing.expectEqual(before_grab_key + 1, sink.keyboard_event_count);
    try std.testing.expectEqual(TestGeneratedSeatSink.KeyboardTag.modifiers, sink.keyboard_events[sink.keyboard_event_count - 1]);

    const transition_start = sink.keyboard_event_count;
    try std.testing.expect(server.focusGeneratedSurface(root_b));
    try std.testing.expectEqualSlices(
        TestGeneratedSeatSink.KeyboardTag,
        &.{ .leave, .enter },
        sink.keyboard_events[transition_start..sink.keyboard_event_count],
    );
    try std.testing.expectEqual(client_a, sink.keyboard_clients[transition_start]);
    try std.testing.expectEqual(client_b, sink.keyboard_clients[transition_start + 1]);
    try std.testing.expectEqual(root_a, sink.keyboard_surfaces[transition_start]);
    try std.testing.expectEqual(root_b, sink.keyboard_surfaces[transition_start + 1]);

    const mature_transition = sink.keyboard_event_count;
    server.applyMatureKeyboardFocus(null);
    try std.testing.expectEqual(mature_transition + 1, sink.keyboard_event_count);
    try std.testing.expectEqual(TestGeneratedSeatSink.KeyboardTag.leave, sink.keyboard_events[mature_transition]);
    try std.testing.expectEqual(client_b, sink.keyboard_clients[mature_transition]);
    try std.testing.expect(server.seat.generatedKeyboardFocus() == null);

    try std.testing.expect(server.focusGeneratedSurface(root_b));
    const teardown_start = sink.keyboard_event_count;
    server.seat.setKeyboardAvailable(false);
    server.seat.destroyVirtualKeyboard(&virtual_owner_b);
    virtual_owner_b_live = false;
    try std.testing.expectEqual(teardown_start, sink.keyboard_event_count);
    server.seat.destroyVirtualKeyboard(&virtual_owner);
    virtual_owner_live = false;
    try std.testing.expectEqual(teardown_start + 1, sink.keyboard_event_count);
    try std.testing.expectEqual(TestGeneratedSeatSink.KeyboardTag.leave, sink.keyboard_events[teardown_start]);
    try std.testing.expectEqual(client_b, sink.keyboard_clients[teardown_start]);
    try std.testing.expect(server.seat.deliverySnapshot().capabilities.keyboard.available == false);

    server.client_registry.unregister(client_b);
    client_b_live = false;
    server.client_registry.unregister(client_a);
    client_a_live = false;
    server.removeHeadlessSurface(root_b);
    server.surface_registry.remove(root_b);
    server.removeHeadlessSurface(root_a);
    server.surface_registry.remove(root_a);
    surfaces_live = false;
}

test "headless click and first touch focus compound root with synchronous repair" {
    const server = try Self.createWithVirtualOutput(
        std.testing.allocator,
        std.testing.io,
        .cpu,
        .headless,
        null,
        .{ .size = .{ .width = 4, .height = 4 } },
    );
    defer server.destroy();
    const output = server.primaryRenderOutput();

    var root_provider: SyntheticSurfaceProvider = .{
        .pixel = 0xff11_2233,
        .logical_size = .{ .width = 4, .height = 4 },
    };
    var child_provider: SyntheticSurfaceProvider = .{
        .pixel = 0xff44_5566,
        .logical_size = .{ .width = 2, .height = 2 },
    };
    var top_provider: SyntheticSurfaceProvider = .{
        .pixel = 0xff77_8899,
        .logical_size = .{ .width = 1, .height = 1 },
    };
    const root = try server.surface_registry.add(root_provider.provider());
    const child = try server.surface_registry.add(child_provider.provider());
    const top = try server.surface_registry.add(top_provider.provider());
    var root_live = true;
    var child_live = true;
    var top_live = true;
    try server.addHeadlessSurface(root, null);
    try server.addHeadlessSurface(child, null);
    try server.addHeadlessSurface(top, null);
    defer {
        if (top_live) {
            server.removeHeadlessSurface(top);
            server.surface_registry.remove(top);
        }
        if (root_live) {
            server.removeHeadlessSurface(root);
            server.surface_registry.remove(root);
        }
        if (child_live) {
            server.removeHeadlessSurface(child);
            server.surface_registry.remove(child);
        }
    }

    const root_stack = [_]WayringCompositor.AppliedStackEntry{
        .parent,
        .{ .child = .{ .id = child, .position = .{ .x = 1, .y = 1 } } },
    };
    const mapped = [_]WayringCompositor.AppliedSurfaceState{
        .{ .id = root, .mapped_size = root_provider.logical_size, .callbacks_committed = false },
        .{ .id = child, .mapped_size = child_provider.logical_size, .callbacks_committed = false },
        .{ .id = top, .mapped_size = top_provider.logical_size, .callbacks_committed = false },
    };
    server.applyHeadlessBatch(.{
        .surfaces = &mapped,
        .parents = &.{.{ .id = root, .stack = &root_stack }},
    });

    var generated_client = try server.client_registry.register(.wayring_server);
    var generated_client_live = true;
    defer if (generated_client_live) server.client_registry.unregister(generated_client);
    var sink: TestGeneratedSeatSink = .{
        .clients = &server.client_registry,
        .client = generated_client,
        .touch_max_resource_generation = 7,
    };
    server.setGeneratedSeatDeliverySink(sink.sink());
    defer server.clearGeneratedSeatDeliverySink(&sink);
    server.seat.setPointerAvailable(true);
    server.seat.setTouchAvailable(true);
    defer {
        server.seat.setTouchAvailable(false);
        server.seat.setPointerAvailable(false);
    }

    const child_route = server.pointerRoute(2, 2);
    try std.testing.expectEqual(child, child_route.generated.?.surface_id);
    try std.testing.expectEqual(root, child_route.generated.?.root);
    pointerMotion(output, 1, 2, 2);
    pointerButton(output, 2, linux_button_left, .pressed);
    try std.testing.expectEqual(root, server.seat.generatedKeyboardFocus().?.surface);
    try std.testing.expect(server.seat.implicitPointerGrabActive());
    const press_serial: ClientRegistry.Serial = .{ .domain = .wayring_server, .value = 2 };
    try std.testing.expect(server.seat.authority.acceptsAction(generated_client, press_serial));
    try std.testing.expect(server.seat.authority.selectionOrder(generated_client, press_serial) != null);
    try std.testing.expect(server.seat.authority.acceptsPointerGrab(generated_client, press_serial, child));
    try std.testing.expect(!server.seat.authority.acceptsPointerGrab(generated_client, .{
        .domain = .mature_display,
        .value = press_serial.value,
    }, child));

    // Crossing to another generated compound stays pinned to the pressed
    // surface until release, then performs leave/frame/enter in that order.
    pointerMotion(output, 3, 0.5, 0.5);
    try std.testing.expectEqual(child, server.seat.pointerFocus().?.surface_id);
    try std.testing.expectEqual(root, server.seat.pointerFocus().?.generated.?.root);
    pointerButton(output, 4, linux_button_left, .released);
    try std.testing.expect(!server.seat.implicitPointerGrabActive());
    try std.testing.expect(!server.seat.authority.acceptsPointerGrab(generated_client, press_serial, child));
    try std.testing.expect(server.seat.authority.selectionOrder(generated_client, .{
        .domain = .wayring_server,
        .value = 3,
    }) != null);
    try std.testing.expectEqual(top, server.seat.pointerFocus().?.surface_id);
    try std.testing.expectEqualSlices(TestGeneratedSeatSink.PointerTag, &.{
        .enter,
        .button,
        .motion,
        .button,
        .leave,
        .frame,
        .enter,
    }, sink.pointer_events[0..sink.pointer_event_count]);
    try std.testing.expectEqualSlices(SurfaceRegistry.Id, &.{
        child,
        child,
        child,
        child,
        child,
        child,
        top,
    }, sink.pointer_surfaces[0..sink.pointer_event_count]);

    _ = server.seat.applyMatureKeyboardFocus(null);
    const touch_start = sink.touch_event_count;
    touchDown(output, 5, 10, 2, 2);
    try std.testing.expectEqual(root, server.seat.generatedKeyboardFocus().?.surface);
    touchDown(output, 6, 11, 0.5, 0.5);
    try std.testing.expectEqual(top, server.pointerRoute(0.5, 0.5).generated.?.root);
    try std.testing.expectEqual(root, server.seat.generatedKeyboardFocus().?.surface);
    touchMotion(output, 7, 10, 3, 3);
    touchShape(output, 10, 2, 1);
    touchOrientation(output, 10, 0.5);
    touchFrame(output);
    touchUp(output, 8, 11);
    touchUp(output, 9, 10);
    touchFrame(output);
    try std.testing.expectEqualSlices(TestGeneratedSeatSink.TouchTag, &.{
        .down,
        .down,
        .motion,
        .shape,
        .orientation,
        .frame,
        .up,
        .up,
        .frame,
    }, sink.touch_events[touch_start..sink.touch_event_count]);
    try std.testing.expectEqual(@as(usize, 17), sink.event_count);
    try std.testing.expectEqual(child, sink.touch_surfaces[touch_start].?);
    try std.testing.expectEqual(top, sink.touch_surfaces[touch_start + 1].?);
    try std.testing.expectEqual(@as(?i32, 256), sink.touch_x[touch_start]);
    try std.testing.expectEqual(@as(?i32, 256), sink.touch_y[touch_start]);
    try std.testing.expectEqual(@as(?i32, 512), sink.touch_x[touch_start + 2]);
    try std.testing.expectEqual(@as(?i32, 512), sink.touch_y[touch_start + 2]);
    for (sink.touch_cutoffs[touch_start .. touch_start + 5]) |cutoff|
        try std.testing.expectEqual(@as(?SeatDelivery.ResourceGeneration, 7), cutoff);
    const down_serial = sink.touch_serials[touch_start + 1].?;
    try std.testing.expectEqual(ClientRegistry.SerialDomain.wayring_server, down_serial.domain);
    try std.testing.expect(server.seat.authority.acceptsAction(generated_client, down_serial));
    const up_serial = sink.touch_serials[touch_start + 7].?;
    try std.testing.expect(server.seat.authority.selectionOrder(generated_client, up_serial) != null);

    const invalidation_start = sink.touch_event_count;
    touchDown(output, 10, 12, 2, 2);
    server.commitHeadlessSurface(root, null, false);
    try std.testing.expectEqualSlices(TestGeneratedSeatSink.TouchTag, &.{ .down, .cancel }, sink.touch_events[invalidation_start..sink.touch_event_count]);
    touchMotion(output, 11, 12, 3, 3);
    touchUp(output, 12, 12);
    try std.testing.expectEqual(invalidation_start + 2, sink.touch_event_count);
    try std.testing.expect(server.seat.generatedKeyboardFocus() == null);
    server.commitHeadlessSurface(root, root_provider.logical_size, false);
    try std.testing.expect(server.focusGeneratedSurface(root));

    const top_stack = [_]WayringCompositor.AppliedStackEntry{
        .parent,
        .{ .child = .{ .id = root, .position = .{} } },
    };
    server.applyHeadlessBatch(.{
        .surfaces = &.{},
        .parents = &.{.{ .id = top, .stack = &top_stack }},
    });
    try std.testing.expectEqual(top, server.seat.generatedKeyboardFocus().?.surface);

    server.client_registry.unregister(generated_client);
    generated_client_live = false;
    try std.testing.expect(server.seat.generatedKeyboardFocus() == null);
    generated_client = try server.client_registry.register(.wayring_server);
    generated_client_live = true;
    sink.client = generated_client;
    try std.testing.expect(server.focusGeneratedSurface(top));

    server.removeHeadlessSurface(top);
    server.surface_registry.remove(top);
    top_live = false;
    try std.testing.expect(server.seat.generatedKeyboardFocus() == null);
    try std.testing.expectEqual(HeadlessSurfaceForest.Placement.detached, server.headless_surface_forest.state(root).?.placement);

    server.removeHeadlessSurface(root);
    server.surface_registry.remove(root);
    root_live = false;
    server.removeHeadlessSurface(child);
    server.surface_registry.remove(child);
    child_live = false;
}

test "destroying a mapped generated input popup cancels pointer grab and touches" {
    const server = try Self.createWithVirtualOutput(
        std.testing.allocator,
        std.testing.io,
        .cpu,
        .headless,
        null,
        .{ .size = .{ .width = 4, .height = 4 } },
    );
    defer server.destroy();
    const output = server.primaryRenderOutput();

    var provider: SyntheticSurfaceProvider = .{
        .pixel = 0xff11_2233,
        .logical_size = .{ .width = 2, .height = 2 },
    };
    const surface = try server.surface_registry.add(provider.provider());
    try server.addHeadlessSurface(surface, null);
    defer {
        server.removeHeadlessSurface(surface);
        server.surface_registry.remove(surface);
    }
    server.commitHeadlessSurface(surface, provider.logical_size, false);
    try std.testing.expect(server.headless_surface_forest.setRootPresentationClass(surface, .input_popup));

    const client = try server.client_registry.register(.wayring_server);
    defer server.client_registry.unregister(client);
    var sink: TestGeneratedSeatSink = .{
        .clients = &server.client_registry,
        .client = client,
        .touch_max_resource_generation = 1,
    };
    server.setGeneratedSeatDeliverySink(sink.sink());
    defer server.clearGeneratedSeatDeliverySink(&sink);
    server.seat.setPointerAvailable(true);
    server.seat.setTouchAvailable(true);
    defer {
        server.seat.setTouchAvailable(false);
        server.seat.setPointerAvailable(false);
    }

    const popup_id: NeutralTextInput.PopupId = .{ .index = 1, .generation = 1 };
    try server.generated_input_popups.append(std.testing.allocator, .{
        .id = popup_id,
        .method = .{ .index = 1, .generation = 1 },
        .surface_id = surface,
        .mapped = true,
    });
    pointerMotion(output, 1, 0.5, 0.5);
    pointerButton(output, 2, linux_button_left, .pressed);
    try std.testing.expect(server.seat.implicitPointerGrabActive());
    try std.testing.expectEqual(surface, server.seat.pointerFocus().?.surface_id);
    const touch_start = sink.touch_event_count;
    touchDown(output, 3, 7, 0.5, 0.5);

    generatedInputPopupDestroyed(server, popup_id);
    try std.testing.expectEqual(@as(usize, 0), server.generated_input_popups.items.len);
    try std.testing.expect(!server.seat.implicitPointerGrabActive());
    try std.testing.expect(server.seat.pointerFocus() == null);
    try std.testing.expectEqualSlices(
        TestGeneratedSeatSink.TouchTag,
        &.{ .down, .cancel },
        sink.touch_events[touch_start..sink.touch_event_count],
    );
    touchMotion(output, 4, 7, 1, 1);
    touchUp(output, 5, 7);
    try std.testing.expectEqual(touch_start + 2, sink.touch_event_count);
}

test "generated topology mutation retargets hover and cancels invalid grabs" {
    const server = try Self.createWithVirtualOutput(
        std.testing.allocator,
        std.testing.io,
        .cpu,
        .headless,
        null,
        .{ .size = .{ .width = 4, .height = 4 } },
    );
    defer server.destroy();
    const output = server.primaryRenderOutput();

    var root_a_provider: SyntheticSurfaceProvider = .{
        .pixel = 0xff11_1111,
        .logical_size = .{ .width = 4, .height = 4 },
    };
    var root_b_provider: SyntheticSurfaceProvider = .{
        .pixel = 0xff22_2222,
        .logical_size = .{ .width = 1, .height = 1 },
    };
    var child_provider: SyntheticSurfaceProvider = .{
        .pixel = 0xff33_3333,
        .logical_size = .{ .width = 2, .height = 2 },
    };
    const root_a = try server.surface_registry.add(root_a_provider.provider());
    const root_b = try server.surface_registry.add(root_b_provider.provider());
    const child = try server.surface_registry.add(child_provider.provider());
    var root_a_live = true;
    var root_b_live = true;
    var child_live = true;
    try server.addHeadlessSurface(root_a, null);
    try server.addHeadlessSurface(root_b, null);
    try server.addHeadlessSurface(child, null);
    defer {
        if (child_live) {
            server.removeHeadlessSurface(child);
            server.surface_registry.remove(child);
        }
        if (root_b_live) {
            server.removeHeadlessSurface(root_b);
            server.surface_registry.remove(root_b);
        }
        if (root_a_live) {
            server.removeHeadlessSurface(root_a);
            server.surface_registry.remove(root_a);
        }
    }

    const child_on_a = [_]WayringCompositor.AppliedStackEntry{
        .parent,
        .{ .child = .{ .id = child, .position = .{ .x = 1, .y = 1 } } },
    };
    server.applyHeadlessBatch(.{
        .surfaces = &.{
            .{ .id = root_a, .mapped_size = root_a_provider.logical_size, .callbacks_committed = false },
            .{ .id = root_b, .mapped_size = root_b_provider.logical_size, .callbacks_committed = false },
            .{ .id = child, .mapped_size = child_provider.logical_size, .callbacks_committed = false },
        },
        .parents = &.{.{ .id = root_a, .stack = &child_on_a }},
    });

    const generated_client = try server.client_registry.register(.wayring_server);
    var generated_client_live = true;
    defer if (generated_client_live) server.client_registry.unregister(generated_client);
    var sink: TestGeneratedSeatSink = .{
        .clients = &server.client_registry,
        .client = generated_client,
    };
    server.setGeneratedSeatDeliverySink(sink.sink());
    defer server.clearGeneratedSeatDeliverySink(&sink);
    server.seat.setPointerAvailable(true);
    defer server.seat.setPointerAvailable(false);

    pointerMotion(output, 1, 2, 2);
    try std.testing.expectEqual(child, server.seat.pointerFocus().?.surface_id);
    try std.testing.expectEqual(root_a, server.seat.pointerFocus().?.generated.?.root);
    const first_enter: ClientRegistry.Serial = .{ .domain = .wayring_server, .value = 1 };
    try std.testing.expect(server.seat.authority.acceptsPointerEnter(generated_client, first_enter));
    const enter_snapshot = server.seat.generatedPointerEnterSnapshot(
        generated_client,
        server.seat.deliverySnapshot().capabilities.pointer.generation,
    ).?;
    try std.testing.expectEqual(child, enter_snapshot.surface);
    try std.testing.expectEqual(first_enter, enter_snapshot.serial);
    try std.testing.expectEqual(@as(i32, 256), enter_snapshot.x);
    try std.testing.expectEqual(@as(i32, 256), enter_snapshot.y);

    // Reparenting the live endpoint to another compound is a leave/enter, not
    // continuation of the old root or enter authority.
    sink.pointer_event_count = 0;
    const child_on_b = [_]WayringCompositor.AppliedStackEntry{
        .parent,
        .{ .child = .{ .id = child, .position = .{ .x = 1, .y = 1 } } },
    };
    server.applyHeadlessBatch(.{
        .surfaces = &.{},
        .parents = &.{
            .{ .id = root_a, .stack = &.{.parent} },
            .{ .id = root_b, .stack = &child_on_b },
        },
    });
    try std.testing.expectEqual(child, server.seat.pointerFocus().?.surface_id);
    try std.testing.expectEqual(root_b, server.seat.pointerFocus().?.generated.?.root);
    try std.testing.expect(!server.seat.authority.acceptsPointerEnter(generated_client, first_enter));
    try std.testing.expect(server.seat.authority.acceptsPointerEnter(generated_client, .{
        .domain = .wayring_server,
        .value = 3,
    }));
    try std.testing.expectEqualSlices(TestGeneratedSeatSink.PointerTag, &.{ .leave, .frame, .enter }, sink.pointer_events[0..sink.pointer_event_count]);
    try std.testing.expectEqualSlices(SurfaceRegistry.Id, &.{ child, child, child }, sink.pointer_surfaces[0..sink.pointer_event_count]);

    // Detaching a hovered endpoint retargets synchronously to the exposed root.
    sink.pointer_event_count = 0;
    server.detachHeadlessSurface(child);
    try std.testing.expectEqual(root_a, server.seat.pointerFocus().?.surface_id);
    try std.testing.expectEqualSlices(TestGeneratedSeatSink.PointerTag, &.{ .leave, .frame, .enter }, sink.pointer_events[0..sink.pointer_event_count]);
    try std.testing.expectEqualSlices(SurfaceRegistry.Id, &.{ child, child, root_a }, sink.pointer_surfaces[0..sink.pointer_event_count]);

    // Reattach and begin an exact implicit grab on the child.
    server.applyHeadlessBatch(.{
        .surfaces = &.{},
        .parents = &.{.{ .id = root_b, .stack = &child_on_b }},
    });
    pointerMotion(output, 2, 2, 2);
    try std.testing.expectEqual(child, server.seat.pointerFocus().?.surface_id);

    // A same-compound position mutation also re-picks hover; mere endpoint
    // liveness cannot keep delivery on content no longer under the pointer.
    sink.pointer_event_count = 0;
    const child_moved = [_]WayringCompositor.AppliedStackEntry{
        .parent,
        .{ .child = .{ .id = child, .position = .{ .x = 3, .y = 3 } } },
    };
    server.applyHeadlessBatch(.{
        .surfaces = &.{},
        .parents = &.{.{ .id = root_b, .stack = &child_moved }},
    });
    try std.testing.expectEqual(root_a, server.seat.pointerFocus().?.surface_id);
    try std.testing.expectEqualSlices(TestGeneratedSeatSink.PointerTag, &.{ .leave, .frame, .enter }, sink.pointer_events[0..sink.pointer_event_count]);
    server.applyHeadlessBatch(.{
        .surfaces = &.{},
        .parents = &.{.{ .id = root_b, .stack = &child_on_b }},
    });
    pointerMotion(output, 2, 2, 2);
    try std.testing.expectEqual(child, server.seat.pointerFocus().?.surface_id);
    sink.pointer_event_count = 0;
    pointerButton(output, 3, linux_button_left, .pressed);
    const unmap_press = sink.last_button_serial.?;
    try std.testing.expect(server.seat.implicitPointerGrabActive());
    try std.testing.expect(server.seat.authority.acceptsAction(generated_client, unmap_press));
    sink.pointer_event_count = 0;

    // Unmapping an ancestor invalidates the endpoint: no press/action/grab or
    // old enter survives, and delivery immediately targets the exposed root.
    server.applyHeadlessBatch(.{
        .surfaces = &.{.{ .id = root_b, .mapped_size = null, .callbacks_committed = false }},
        .parents = &.{},
    });
    try std.testing.expectEqual(root_a, server.seat.pointerFocus().?.surface_id);
    try std.testing.expect(!server.seat.implicitPointerGrabActive());
    try std.testing.expect(!server.seat.authority.acceptsAction(generated_client, unmap_press));
    try std.testing.expect(server.seat.authority.selectionOrder(generated_client, unmap_press) == null);
    try std.testing.expect(!server.seat.authority.acceptsPointerGrab(generated_client, unmap_press, child));
    try std.testing.expectEqualSlices(TestGeneratedSeatSink.PointerTag, &.{ .leave, .frame, .enter }, sink.pointer_events[0..sink.pointer_event_count]);
    try std.testing.expectEqualSlices(SurfaceRegistry.Id, &.{ child, child, root_a }, sink.pointer_surfaces[0..sink.pointer_event_count]);
    sink.pointer_event_count = 0;
    server.seat.pointerAxisValue120(.vertical_scroll, 120);
    try std.testing.expectEqualSlices(SurfaceRegistry.Id, &.{root_a}, sink.pointer_surfaces[0..sink.pointer_event_count]);

    // Remap, then remove the hovered endpoint. Later axis delivery cannot use
    // the removed generation.
    server.applyHeadlessBatch(.{
        .surfaces = &.{.{ .id = root_b, .mapped_size = root_b_provider.logical_size, .callbacks_committed = false }},
        .parents = &.{},
    });
    pointerMotion(output, 4, 2, 2);
    try std.testing.expectEqual(child, server.seat.pointerFocus().?.surface_id);
    sink.pointer_event_count = 0;
    server.removeHeadlessSurface(child);
    try std.testing.expectEqual(root_a, server.seat.pointerFocus().?.surface_id);
    try std.testing.expectEqualSlices(TestGeneratedSeatSink.PointerTag, &.{ .leave, .frame, .enter }, sink.pointer_events[0..sink.pointer_event_count]);
    try std.testing.expectEqualSlices(SurfaceRegistry.Id, &.{ child, child, root_a }, sink.pointer_surfaces[0..sink.pointer_event_count]);
    server.surface_registry.remove(child);
    child_live = false;
    sink.pointer_event_count = 0;
    server.seat.pointerAxisValue120(.vertical_scroll, 120);
    try std.testing.expectEqualSlices(SurfaceRegistry.Id, &.{root_a}, sink.pointer_surfaces[0..sink.pointer_event_count]);

    // Removal while grabbed follows the same cancellation path.
    var grabbed_provider: SyntheticSurfaceProvider = .{
        .pixel = 0xff44_4444,
        .logical_size = .{ .width = 2, .height = 2 },
    };
    const grabbed = try server.surface_registry.add(grabbed_provider.provider());
    var grabbed_live = true;
    try server.addHeadlessSurface(grabbed, null);
    defer if (grabbed_live) {
        server.removeHeadlessSurface(grabbed);
        server.surface_registry.remove(grabbed);
    };
    const grabbed_on_b = [_]WayringCompositor.AppliedStackEntry{
        .parent,
        .{ .child = .{ .id = grabbed, .position = .{ .x = 1, .y = 1 } } },
    };
    server.applyHeadlessBatch(.{
        .surfaces = &.{.{ .id = grabbed, .mapped_size = grabbed_provider.logical_size, .callbacks_committed = false }},
        .parents = &.{.{ .id = root_b, .stack = &grabbed_on_b }},
    });
    pointerMotion(output, 5, 2, 2);
    sink.pointer_event_count = 0;
    pointerButton(output, 6, linux_button_left, .pressed);
    const removal_press = sink.last_button_serial.?;
    sink.pointer_event_count = 0;
    server.removeHeadlessSurface(grabbed);
    try std.testing.expectEqual(root_a, server.seat.pointerFocus().?.surface_id);
    try std.testing.expect(!server.seat.implicitPointerGrabActive());
    try std.testing.expect(!server.seat.authority.acceptsAction(generated_client, removal_press));
    try std.testing.expect(server.seat.authority.selectionOrder(generated_client, removal_press) == null);
    try std.testing.expect(!server.seat.authority.acceptsPointerGrab(generated_client, removal_press, grabbed));
    try std.testing.expectEqualSlices(TestGeneratedSeatSink.PointerTag, &.{ .leave, .frame, .enter }, sink.pointer_events[0..sink.pointer_event_count]);
    try std.testing.expectEqualSlices(SurfaceRegistry.Id, &.{ grabbed, grabbed, root_a }, sink.pointer_surfaces[0..sink.pointer_event_count]);
    server.surface_registry.remove(grabbed);
    grabbed_live = false;

    pointerButton(output, 7, linux_button_left, .pressed);
    const retiring_press = sink.last_button_serial.?;
    server.seat.suppressGeneratedPointerFocus(root_a);
    try std.testing.expect(server.seat.pointerFocus() == null);
    try std.testing.expect(server.seat.implicitPointerGrabActive());
    try std.testing.expect(server.seat.authority.acceptsPointerGrab(
        generated_client,
        retiring_press,
        root_a,
    ));
    try std.testing.expect(server.seat.generatedKeyboardFocus() != null);
    const request_sink = server.generatedSeatRequestSink();
    request_sink.client_retiring(request_sink.context, generated_client);
    try std.testing.expect(server.seat.pointerFocus() == null);
    try std.testing.expect(!server.seat.implicitPointerGrabActive());
    try std.testing.expect(!server.seat.hasPressedPointerButtons());
    try std.testing.expect(!server.seat.authority.acceptsAction(generated_client, retiring_press));
    try std.testing.expect(server.seat.generatedKeyboardFocus() == null);
    server.removeHeadlessSurface(root_b);
    server.surface_registry.remove(root_b);
    root_b_live = false;
    server.removeHeadlessSurface(root_a);
    server.surface_registry.remove(root_a);
    root_a_live = false;
    server.client_registry.unregister(generated_client);
    generated_client_live = false;
}

test "headless surface damage respects output geometry and conservative blur dependencies" {
    const server = try Self.createWithVirtualOutput(
        std.testing.allocator,
        std.testing.io,
        .cpu,
        .headless,
        null,
        .{ .size = .{ .width = 8, .height = 8 } },
    );
    defer server.destroy();
    const scaled_id = try server.addRenderOutput(std.testing.io, .{
        .kind = .headless,
        .size = .{ .width = 6, .height = 2 },
        .scale = .{ .numerator = 240 },
        .position = .{ .x = -1 },
        .name = "HEADLESS-SCALED",
        .description = "Keywork scaled test output",
        .model = "headless",
    });
    defer std.debug.assert(server.removeRenderOutput(scaled_id));
    const unrelated_id = try server.addRenderOutput(std.testing.io, .{
        .kind = .headless,
        .size = .{ .width = 2, .height = 2 },
        .position = .{ .x = 20 },
        .name = "HEADLESS-UNRELATED",
        .description = "Keywork unrelated test output",
        .model = "headless",
    });
    defer std.debug.assert(server.removeRenderOutput(unrelated_id));
    const primary = server.primaryRenderOutput();
    const scaled = server.render_outputs.get(scaled_id).?.*;
    const unrelated = server.render_outputs.get(unrelated_id).?.*;
    resetTestOutputDamage(primary);
    resetTestOutputDamage(scaled);
    resetTestOutputDamage(unrelated);

    var blur_region = Region.init();
    defer blur_region.deinit();
    try blur_region.add(0, 0, 2, 2);
    var lower: SyntheticSurfaceProvider = .{
        .pixel = 0xff11_2233,
        .logical_size = .{ .width = 1, .height = 1 },
    };
    var upper: SyntheticSurfaceProvider = .{
        .pixel = 0x8011_2233,
        .logical_size = .{ .width = 2, .height = 2 },
        .force_opaque = false,
        .blur_region = &blur_region,
    };
    const lower_id = try server.surface_registry.add(lower.provider());
    const upper_id = try server.surface_registry.add(upper.provider());
    try server.addHeadlessSurface(lower_id, null);
    try server.addHeadlessSurface(upper_id, null);
    server.commitHeadlessSurface(lower_id, lower.logical_size, false);
    server.commitHeadlessSurface(upper_id, upper.logical_size, false);
    resetTestOutputDamage(primary);
    resetTestOutputDamage(scaled);
    resetTestOutputDamage(unrelated);

    server.commitHeadlessSurface(lower_id, lower.logical_size, false);
    try std.testing.expect(primary.damage.coversRectangle(0, 0, 8, 8));
    try std.testing.expect(scaled.damage.coversRectangle(0, 0, 6, 2));
    try std.testing.expect(unrelated.damage.isEmpty());
    try std.testing.expect(!unrelated.repaint_needed);

    resetTestOutputDamage(primary);
    resetTestOutputDamage(scaled);
    resetTestOutputDamage(unrelated);
    // Mature background/bottom commits enter through damageGlobalRect with a
    // libwayland root and must still invalidate synthetic blur owners above.
    server.damageGlobalRect(
        .{ .x = 0, .y = 0, .width = 1, .height = 1 },
        lower_id,
        null,
    );
    try std.testing.expect(primary.damage.coversRectangle(0, 0, 8, 8));
    try std.testing.expect(scaled.damage.coversRectangle(0, 0, 6, 2));
    try std.testing.expect(unrelated.damage.isEmpty());

    resetTestOutputDamage(primary);
    resetTestOutputDamage(scaled);
    resetTestOutputDamage(unrelated);
    upper.available = false;
    server.commitHeadlessSurface(lower_id, lower.logical_size, false);
    try std.testing.expect(primary.damage.coversRectangle(0, 0, 8, 8));
    try std.testing.expect(scaled.damage.coversRectangle(0, 0, 6, 2));
    try std.testing.expect(unrelated.damage.isEmpty());

    upper.available = true;
    server.removeHeadlessSurface(lower_id);
    server.surface_registry.remove(lower_id);
    server.removeHeadlessSurface(upper_id);
    server.surface_registry.remove(upper_id);
}

