test "Wayring listener rollback removes an unpublished headless entry" {
    const server = try Self.create(std.testing.allocator, std.testing.io, .cpu, .headless, null);
    defer server.destroy();
    var provider: SyntheticSurfaceProvider = .{
        .pixel = 0xff11_2233,
        .logical_size = .{ .width = 1, .height = 1 },
        .available = false,
    };
    const id = try server.surface_registry.add(provider.provider());
    const listener = server.wayringPresentationListener().?;
    const wayring = @import("wayring");
    var protocol_server: wayring.server.Server = .init(std.testing.allocator);
    defer protocol_server.deinit();
    var completion_owner: WayringCompositor = undefined;
    try completion_owner.init(std.testing.allocator, &protocol_server, &server.surface_registry, null);
    defer completion_owner.deinit();
    const Completion = struct {
        fn complete(context: *anyopaque, surface_id: SurfaceRegistry.Id, timestamp_ms: u32) void {
            const compositor: *WayringCompositor = @ptrCast(@alignCast(context));
            compositor.completeFrame(surface_id, timestamp_ms);
        }
    };

    const completion: WayringCompositor.FrameCompletion = .{
        .context = &completion_owner,
        .complete = Completion.complete,
    };
    try listener.added(listener.context, id, completion);
    try std.testing.expectEqual(id, server.headless_surface_forest.rootAt(0).?.id);
    try std.testing.expectEqual(completion, server.headless_surface_forest.rootAt(0).?.frame_completion.?);
    listener.removing(listener.context, id);
    try std.testing.expectEqual(@as(usize, 0), server.headless_surface_forest.len());
    server.surface_registry.remove(id);
}

test "Wayring listener applies XDG presentation progression without detaching managed roots" {
    const server = try Self.create(std.testing.allocator, std.testing.io, .cpu, .headless, null);
    defer server.destroy();
    var provider: SyntheticSurfaceProvider = .{
        .pixel = 0xff11_2233,
        .logical_size = .{ .width = 1, .height = 1 },
        .available = false,
    };
    const id = try server.surface_registry.add(provider.provider());
    defer server.surface_registry.remove(id);
    const listener = server.wayringPresentationListener().?;
    const Completion = struct {
        fn complete(_: *anyopaque, _: SurfaceRegistry.Id, _: u32) void {}
    };
    var completion_context: u8 = 0;
    try listener.added(listener.context, id, .{
        .context = &completion_context,
        .complete = Completion.complete,
    });
    defer listener.removing(listener.context, id);
    const changed = listener.presentation_class.?;

    try std.testing.expectEqual(
        HeadlessSurfaceForest.PresentationClass.background,
        server.headless_surface_forest.presentationClass(id).?,
    );
    changed(listener.context, id, .xdg_reserved);
    try std.testing.expectEqual(
        HeadlessSurfaceForest.PresentationClass.xdg_reserved,
        server.headless_surface_forest.presentationClass(id).?,
    );
    changed(listener.context, id, .background);
    changed(listener.context, id, .xdg_reserved);
    changed(listener.context, id, .managed);
    try std.testing.expectEqual(
        HeadlessSurfaceForest.PresentationClass.managed,
        server.headless_surface_forest.presentationClass(id).?,
    );
    try std.testing.expectEqual(
        HeadlessSurfaceForest.Placement.root,
        server.headless_surface_forest.state(id).?.placement,
    );
}

test "hidden managed publication stays damage-free and mapped overflow repaints fully" {
    const server = try Self.createWithVirtualOutput(
        std.testing.allocator,
        std.testing.io,
        .cpu,
        .headless,
        null,
        .{ .size = .{ .width = 100, .height = 100 } },
    );
    defer server.destroy();
    const output = server.primaryRenderOutput();
    var root_provider: SyntheticSurfaceProvider = .{
        .pixel = 0xff11_2233,
        .logical_size = .{ .width = 1, .height = 1 },
    };
    var child_provider: SyntheticSurfaceProvider = .{
        .pixel = 0xff44_5566,
        .logical_size = .{ .width = 1, .height = 1 },
    };
    var grandchild_provider: SyntheticSurfaceProvider = .{
        .pixel = 0xff77_8899,
        .logical_size = .{ .width = 1, .height = 1 },
    };
    const root = try server.surface_registry.add(root_provider.provider());
    const child = try server.surface_registry.add(child_provider.provider());
    const grandchild = try server.surface_registry.add(grandchild_provider.provider());
    try server.addHeadlessSurface(root, null);
    try server.addHeadlessSurface(child, null);
    try server.addHeadlessSurface(grandchild, null);
    const client: ClientRegistry.Id = .{ .index = 1, .generation = 1 };
    const xdg_surface = try server.xdg_shell_core.createSurface(root, client, undefined);
    const window = try server.xdg_shell_core.createToplevel(xdg_surface, 1);
    try std.testing.expect(server.headless_surface_forest.setRootPresentationClass(root, .managed));
    defer {
        server.xdg_shell_core.destroyToplevel(window);
        server.xdg_shell_core.removeSurface(xdg_surface);
        server.removeHeadlessSurface(root);
        server.removeHeadlessSurface(child);
        server.removeHeadlessSurface(grandchild);
        server.surface_registry.remove(root);
        server.surface_registry.remove(child);
        server.surface_registry.remove(grandchild);
    }

    resetTestOutputDamage(output);
    server.commitHeadlessSurface(root, root_provider.logical_size, false);
    try std.testing.expect(output.damage.isEmpty());
    server.commitHeadlessSurface(root, null, false);
    server.commitHeadlessSurface(root, root_provider.logical_size, false);
    try std.testing.expect(output.damage.isEmpty());

    const scene_id = server.xdg_shell_core.windowInfo(window).?.scene_id;
    server.scene.setContentGeometry(scene_id, .{ .size = root_provider.logical_size });
    server.scene.setMapped(scene_id, true);
    try std.testing.expect(output.damage.contains(0, 0));
    try std.testing.expect(!output.damage.contains(99, 99));
    resetTestOutputDamage(output);
    server.damageHeadlessCompound(root);
    try std.testing.expect(output.damage.contains(0, 0));
    try std.testing.expect(!output.damage.contains(99, 99));

    resetTestOutputDamage(output);
    const root_stack = [_]HeadlessSurfaceForest.AppliedStackEntry{
        .parent,
        .{ .child = .{ .id = child, .position = .{ .x = std.math.maxInt(i32) } } },
    };
    const child_stack = [_]HeadlessSurfaceForest.AppliedStackEntry{
        .parent,
        .{ .child = .{ .id = grandchild, .position = .{ .x = 1 } } },
    };
    server.applyHeadlessBatch(.{
        .surfaces = &.{
            .{ .id = child, .mapped_size = child_provider.logical_size, .callbacks_committed = false },
            .{ .id = grandchild, .mapped_size = grandchild_provider.logical_size, .callbacks_committed = false },
        },
        .parents = &.{
            .{ .id = root, .stack = &root_stack },
            .{ .id = child, .stack = &child_stack },
        },
    });
    try std.testing.expect(output.damage.coversRectangle(0, 0, 100, 100));
}

const WayringXdgServerTest = struct {
    const wayring = @import("wayring");
    const core = @import("wayring-protocol");
    const wire = wayring.wire;

    fn globalCount(host: *const wayring.server.Server) usize {
        var count: usize = 0;
        var iterator = host.iterator();
        while (iterator.next() != null) count += 1;
        return count;
    }

    fn globalName(host: *const wayring.server.Server, name: []const u8) ?u32 {
        var iterator = host.iterator();
        while (iterator.next()) |global| {
            if (std.mem.eql(u8, global.interface().name, name)) return global.name();
        }
        return null;
    }

    fn send(client: *wayring.server.Client, id: u32, opcode: u16, descriptor: *const wire.MessageDescriptor, values: []const wire.Value) !void {
        var output: wire.Output = .init(std.testing.allocator);
        defer output.deinit();
        try output.enqueue(id, opcode, descriptor, values);
        const batch = (try output.beginSend()).?;
        try client.receive(batch.bytes, &.{});
        try output.completeSend(batch.token, batch.bytes.len);
        try client.dispatch();
    }

    fn sendWithFds(client: *wayring.server.Client, id: u32, opcode: u16, descriptor: *const wire.MessageDescriptor, values: []const wire.Value) !void {
        var output: wire.Output = .init(std.testing.allocator);
        defer output.deinit();
        try output.enqueue(id, opcode, descriptor, values);
        const batch = (try output.beginSend()).?;
        var fds: std.ArrayList(wire.FileDescriptor) = .empty;
        defer fds.deinit(std.testing.allocator);
        for (batch.fds) |fd| {
            const duplicate = std.c.fcntl(fd, std.c.F.DUPFD_CLOEXEC, @as(c_int, 0));
            if (duplicate < 0) return error.Unexpected;
            try fds.append(std.testing.allocator, duplicate);
        }
        try client.receive(batch.bytes, fds.items);
        fds.clearRetainingCapacity();
        try output.completeSend(batch.token, batch.bytes.len);
        try client.dispatch();
    }

    fn drain(client: *wayring.server.Client) ![]u8 {
        var bytes: std.ArrayList(u8) = .empty;
        errdefer bytes.deinit(std.testing.allocator);
        while (try client.beginSend()) |batch| {
            try bytes.appendSlice(std.testing.allocator, batch.bytes);
            try client.completeSend(batch.token, batch.bytes.len);
        }
        return bytes.toOwnedSlice(std.testing.allocator);
    }

    fn word(bytes: []const u8, offset: usize) u32 {
        return std.mem.readInt(u32, bytes[offset..][0..4], .native);
    }

    fn eventWord(
        bytes: []const u8,
        object_id: u32,
        opcode: u16,
        argument_offset: usize,
    ) ?u32 {
        var offset: usize = 0;
        while (offset + 8 <= bytes.len) {
            const id = word(bytes, offset);
            const size_opcode = word(bytes, offset + 4);
            const size: usize = @intCast(size_opcode >> 16);
            if (size < 8 or offset + size > bytes.len) return null;
            if (id == object_id and @as(u16, @truncate(size_opcode)) == opcode and
                argument_offset + 4 <= size - 8)
            {
                return word(bytes, offset + 8 + argument_offset);
            }
            offset += size;
        }
        return null;
    }
};

test "unpublished Wayring XDG lifecycle uses the real headless window manager" {
    const T = WayringXdgServerTest;
    const wayring = T.wayring;
    const core = T.core;
    const server = try Self.create(std.testing.allocator, std.testing.io, .cpu, .headless, null);
    defer server.destroy();
    const initial_output = server.primary_render_output;
    const replacement_output = try server.addRenderOutput(std.testing.io, .{
        .kind = .headless,
        .size = .{ .width = 1024, .height = 768 },
        .position = .{ .x = 1920 },
        .name = "HEADLESS-WAVE3-SECOND",
        .description = "Keywork Wave 3 migration test output",
        .model = "headless",
    });
    var host: wayring.server.Server = .init(std.testing.allocator);
    defer host.deinit();
    var clients: WayringClients = undefined;
    clients.init(std.testing.allocator, &server.client_registry);
    defer clients.deinit();
    var compositor: WayringCompositor = undefined;
    try compositor.init(std.testing.allocator, &host, &server.surface_registry, server.wayringPresentationListener());
    defer compositor.deinit();
    var output: WayringOutput = undefined;
    try output.init(std.testing.allocator, &host, &server.outputs, &compositor);
    defer output.deinit();
    var xdg: WayringXdgShell = undefined;
    xdg.init(std.testing.allocator, &host, server.neutralXdgShell(), &clients, &compositor, &output);
    defer xdg.deinit();
    server.seat.setPointerAvailable(true);
    defer server.seat.setPointerAvailable(false);
    var seat_adapter: WayringSeatAdapter = .init(
        std.testing.allocator,
        &host,
        &clients,
        &compositor,
        server.generatedSeatRequestSink(),
        server.generatedSeatName(),
    );
    defer {
        seat_adapter.unpublish();
        server.clearGeneratedSeatDeliverySink(&seat_adapter);
        seat_adapter.deinit();
    }
    server.setGeneratedSeatDeliverySink(seat_adapter.sink());
    try seat_adapter.publish();
    xdg.setSeatAdapter(&seat_adapter);
    const managed = try wayring.server.CoreClient.create(std.testing.allocator, &host, .{});
    const client = managed.client();
    _ = try clients.register(client);
    try seat_adapter.trackClient(client);
    defer {
        seat_adapter.destroyClientResources(client);
        xdg.destroyClientResources(client);
        output.destroyClientResources(client);
        compositor.destroyClientResources(client);
        clients.unregister(client);
        managed.destroy();
    }

    try T.send(client, 1, 1, &core.wl_display.request_messages[1], &.{.{ .new_id = .{ .typed = 2 } }});
    const announced = try T.drain(client);
    std.testing.allocator.free(announced);
    const globals = T.globalCount(&host);
    try std.testing.expect(T.globalName(&host, "xdg_wm_base") == null);

    const compositor_name = T.globalName(&host, "wl_compositor").?;
    try T.send(client, 2, 0, &core.wl_registry.request_messages[0], &.{ .{ .uint = compositor_name }, .{ .new_id = .{ .generic = .{ .interface = "wl_compositor", .version = 1, .id = 3 } } } });
    try T.send(client, 3, 0, &core.wl_compositor.request_messages[0], &.{.{ .new_id = .{ .typed = 4 } }});
    const surface_id = compositor.surfaceId(client, 4).?;
    try std.testing.expectEqual(HeadlessSurfaceForest.PresentationClass.background, server.headless_surface_forest.presentationClass(surface_id).?);
    try xdg.installDirectForTest(client, 5, 7);
    try std.testing.expectEqual(globals, T.globalCount(&host));
    try std.testing.expect(T.globalName(&host, "xdg_wm_base") == null);
    try T.send(client, 5, 2, &core.xdg_wm_base.request_messages[2], &.{ .{ .new_id = .{ .typed = 6 } }, .{ .object = 4 } });
    try std.testing.expectEqual(HeadlessSurfaceForest.PresentationClass.xdg_reserved, server.headless_surface_forest.presentationClass(surface_id).?);
    try T.send(client, 6, 1, &core.xdg_surface.request_messages[1], &.{.{ .new_id = .{ .typed = 7 } }});
    try std.testing.expectEqual(WayringCompositor.XdgRole.toplevel, compositor.permanentXdgRole(surface_id).?);
    try std.testing.expectEqual(HeadlessSurfaceForest.Placement.root, server.headless_surface_forest.state(surface_id).?.placement);

    try T.send(client, 7, 2, &core.xdg_toplevel.request_messages[2], &.{.{ .string = "Wave 3" }});
    try T.send(client, 7, 3, &core.xdg_toplevel.request_messages[3], &.{.{ .string = "dev.keywork.wave3" }});
    try T.send(client, 7, 7, &core.xdg_toplevel.request_messages[7], &.{ .{ .int = 640 }, .{ .int = 480 } });
    try T.send(client, 7, 8, &core.xdg_toplevel.request_messages[8], &.{ .{ .int = 100 }, .{ .int = 80 } });
    try T.send(client, 7, 9, &core.xdg_toplevel.request_messages[9], &.{});
    try T.send(client, 7, 11, &core.xdg_toplevel.request_messages[11], &.{.{ .object = null }});
    var windows = server.xdg_shell_core.windowIterator();
    const window_id = windows.next().?;
    var info = server.xdg_shell_core.windowInfo(window_id).?;
    try std.testing.expectEqualStrings("Wave 3", info.title.?);
    try std.testing.expectEqualStrings("dev.keywork.wave3", info.app_id.?);
    try std.testing.expect(!info.ready and !info.mapped);
    try std.testing.expect(info.requested_state.maximized);
    try std.testing.expect(info.requested_state.fullscreen);
    try std.testing.expect(info.requested_state.fullscreen_output == null);
    try std.testing.expect(!info.requested_state.minimized);

    try T.send(client, 4, 6, &core.wl_surface.request_messages[6], &.{});
    const configure = try T.drain(client);
    defer std.testing.allocator.free(configure);
    const serial = T.word(configure, configure.len - 4);
    try std.testing.expect(serial != 0);
    info = server.xdg_shell_core.windowInfo(window_id).?;
    try std.testing.expect(info.ready);
    try std.testing.expectEqual(NeutralXdgShell.SizeHint{ .width = 100, .height = 80 }, info.min_size);
    try std.testing.expectEqual(NeutralXdgShell.SizeHint{ .width = 640, .height = 480 }, info.max_size);
    try std.testing.expect(info.configuration.maximized);
    try std.testing.expect(info.configuration.fullscreen);
    try std.testing.expect(info.configuration.bounds.width > 0);
    try std.testing.expect(info.configuration.bounds.height > 0);
    try std.testing.expect(!info.configuration.activated);
    try std.testing.expect(server.window_manager.focusedSurface() == null);
    try T.send(client, 6, 4, &core.xdg_surface.request_messages[4], &.{.{ .uint = serial }});

    const shm_name = T.globalName(&host, "wl_shm").?;
    try T.send(client, 2, 0, &core.wl_registry.request_messages[0], &.{ .{ .uint = shm_name }, .{ .new_id = .{ .generic = .{ .interface = "wl_shm", .version = 1, .id = 8 } } } });
    const formats = try T.drain(client);
    std.testing.allocator.free(formats);
    const fd = try std.posix.memfd_create("keywork-xdg-wave3", std.os.linux.MFD.CLOEXEC);
    defer _ = std.c.close(fd);
    if (std.os.linux.errno(std.os.linux.ftruncate(fd, 1600)) != .SUCCESS)
        return error.Unexpected;
    const pixel: u32 = 0xff11_2233;
    if (std.c.write(fd, std.mem.asBytes(&pixel).ptr, 4) != 4) return error.Unexpected;
    try T.sendWithFds(client, 8, 0, &core.wl_shm.request_messages[0], &.{ .{ .new_id = .{ .typed = 9 } }, .{ .fd = fd }, .{ .int = 1600 } });
    try T.send(client, 9, 0, &core.wl_shm_pool.request_messages[0], &.{ .{ .new_id = .{ .typed = 10 } }, .{ .int = 0 }, .{ .int = 20 }, .{ .int = 20 }, .{ .int = 80 }, .{ .uint = @intFromEnum(wayring.server.shm.Format.argb8888) } });
    try T.send(client, 4, 1, &core.wl_surface.request_messages[1], &.{ .{ .object = 10 }, .{ .int = 0 }, .{ .int = 0 } });
    try T.send(client, 4, 6, &core.wl_surface.request_messages[6], &.{});
    info = server.xdg_shell_core.windowInfo(window_id).?;
    try std.testing.expect(info.ready and info.mapped);
    try std.testing.expect(info.scene_presentation_enabled);
    try std.testing.expect(info.interaction_enabled);
    const snapshots = try server.window_manager.windowSnapshots(std.testing.allocator);
    defer std.testing.allocator.free(snapshots);
    try std.testing.expectEqual(@as(usize, 1), snapshots.len);
    var scene_windows = server.scene.iterator();
    try std.testing.expect(scene_windows.next().?.window.mapped);
    try std.testing.expectEqual(HeadlessSurfaceForest.PresentationClass.managed, server.headless_surface_forest.presentationClass(surface_id).?);
    try std.testing.expect(server.headless_surface_forest.subtreeBounds(surface_id) != null);
    try std.testing.expectEqual(@as(usize, 0), server.window_transitions.items.len);
    var rendered_surfaces = server.headless_surface_forest.renderIterator();
    try std.testing.expect(rendered_surfaces.next() == null);
    const capture_bounds = server.toplevelCaptureBounds(window_id).?;
    try std.testing.expectEqual(@as(u32, 20), capture_bounds.width);
    try std.testing.expectEqual(@as(u32, 20), capture_bounds.height);
    var captured_pixels: [400]u32 = undefined;
    const capture_fd = try server.captureToplevel(window_id, .{
        .size = .{ .width = 20, .height = 20 },
        .stride_pixels = 20,
        .pixels = &captured_pixels,
    });
    if (capture_fd) |value| _ = std.c.close(value);
    try std.testing.expectEqual(pixel, captured_pixels[0]);
    const initial_release = try T.drain(client);
    std.testing.allocator.free(initial_release);

    // Generated content obeys the same Scene clipping and rounded-corner
    // visibility as mature content before its exact forest target is picked.
    const scene_id = info.scene_id;
    server.scene.setClipBox(scene_id, .{ .x = 0, .y = 0, .width = 5, .height = 5 });
    var clipped_windows = server.scene.iterator();
    const clipped_window = clipped_windows.next().?.window;
    try std.testing.expect(server.hitTestGeneratedWindow(
        clipped_window,
        @floatFromInt(clipped_window.position.x + 10),
        @floatFromInt(clipped_window.position.y + 10),
    ) == null);
    server.scene.setClipBox(scene_id, null);
    const original_effects = clipped_window.effects;
    var rounded_effects = original_effects;
    rounded_effects.corner_radius = 12;
    server.scene.setEffects(scene_id, rounded_effects);
    var rounded_windows = server.scene.iterator();
    const rounded_window = rounded_windows.next().?.window;
    try std.testing.expect(server.hitTestGeneratedWindow(
        rounded_window,
        @floatFromInt(rounded_window.position.x),
        @floatFromInt(rounded_window.position.y),
    ) == null);
    server.scene.setEffects(scene_id, original_effects);

    try T.send(client, 7, 10, &core.xdg_toplevel.request_messages[10], &.{});
    try T.send(client, 7, 12, &core.xdg_toplevel.request_messages[12], &.{});
    info = server.xdg_shell_core.windowInfo(window_id).?;
    try std.testing.expect(!info.requested_state.maximized);
    try std.testing.expect(!info.requested_state.fullscreen);
    try std.testing.expect(!info.requested_state.minimized);
    const policy_configure = try T.drain(client);
    defer std.testing.allocator.free(policy_configure);
    try T.send(client, 4, 1, &core.wl_surface.request_messages[1], &.{ .{ .object = null }, .{ .int = 0 }, .{ .int = 0 } });
    try T.send(client, 4, 6, &core.wl_surface.request_messages[6], &.{});
    const empty = try server.window_manager.windowSnapshots(std.testing.allocator);
    defer std.testing.allocator.free(empty);
    try std.testing.expectEqual(@as(usize, 0), empty.len);
    try std.testing.expect(!server.xdg_shell_core.windowInfo(window_id).?.mapped);
    try std.testing.expectEqual(HeadlessSurfaceForest.Placement.root, server.headless_surface_forest.state(surface_id).?.placement);

    try T.send(client, 4, 6, &core.wl_surface.request_messages[6], &.{});
    const remap = try T.drain(client);
    defer std.testing.allocator.free(remap);
    const remap_serial = T.word(remap, remap.len - 4);
    try std.testing.expect(remap_serial != serial);
    try T.send(client, 6, 4, &core.xdg_surface.request_messages[4], &.{.{ .uint = remap_serial }});
    try T.send(client, 4, 1, &core.wl_surface.request_messages[1], &.{ .{ .object = 10 }, .{ .int = 0 }, .{ .int = 0 } });
    try T.send(client, 4, 6, &core.wl_surface.request_messages[6], &.{});
    const remapped = try server.window_manager.windowSnapshots(std.testing.allocator);
    defer std.testing.allocator.free(remapped);
    try std.testing.expectEqual(@as(usize, 1), remapped.len);
    try std.testing.expectEqual(surface_id, server.window_manager.focusedSurface().?);
    try std.testing.expectEqual(@as(usize, 0), server.window_transitions.items.len);

    // A real generated wl_pointer press serial authorizes direct manipulation
    // through the unpublished XDG adapter. The physical release still flows
    // through Seat and ends the client-owned grab.
    const seat_name = T.globalName(&host, "wl_seat").?;
    try T.send(client, 2, 0, &core.wl_registry.request_messages[0], &.{ .{ .uint = seat_name }, .{ .new_id = .{ .generic = .{ .interface = "wl_seat", .version = 7, .id = 11 } } } });
    try T.send(client, 11, 0, &core.wl_seat.request_messages[0], &.{.{ .new_id = .{ .typed = 12 } }});
    const seat_events = try T.drain(client);
    std.testing.allocator.free(seat_events);
    var interaction_windows = server.scene.iterator();
    const interaction_window = interaction_windows.next().?.window;
    const content_offset = interaction_window.content_geometry.?.offset;
    const pointer_x: f64 = @as(f64, @floatFromInt(interaction_window.position.x - content_offset.x)) + 10;
    const pointer_y: f64 = @as(f64, @floatFromInt(interaction_window.position.y - content_offset.y)) + 10;
    server.pointerMotionGlobalForSeat(server.primaryRenderOutput(), &server.seat, 10, pointer_x, pointer_y);
    const enter_events = try T.drain(client);
    defer std.testing.allocator.free(enter_events);
    try std.testing.expect(T.eventWord(enter_events, 12, 0, 0) != null);
    server.pointerButtonForSeat(&server.seat, 11, linux_button_left, .pressed);
    const move_press = try T.drain(client);
    defer std.testing.allocator.free(move_press);
    const move_serial = T.eventWord(move_press, 12, 3, 0) orelse return error.Unexpected;
    try T.send(client, 7, 5, &core.xdg_toplevel.request_messages[5], &.{
        .{ .object = 11 }, .{ .uint = move_serial },
    });
    try std.testing.expect(server.window_manager.clientXdgPointerGrabActive());
    server.pointerMotionGlobalForSeat(server.primaryRenderOutput(), &server.seat, 12, pointer_x + 10, pointer_y + 10);
    server.pointerButtonForSeat(&server.seat, 13, linux_button_left, .released);
    try std.testing.expect(!server.window_manager.directManipulationActive());
    try std.testing.expect(!server.seat.hasPressedPointerButtons());
    const move_configures = try T.drain(client);
    defer std.testing.allocator.free(move_configures);

    var moved_windows = server.scene.iterator();
    const moved_window = moved_windows.next().?.window;
    const moved_offset = moved_window.content_geometry.?.offset;
    const moved_x: f64 = @as(f64, @floatFromInt(moved_window.position.x - moved_offset.x)) + 10;
    const moved_y: f64 = @as(f64, @floatFromInt(moved_window.position.y - moved_offset.y)) + 10;
    try std.testing.expect(server.hitTestGeneratedWindow(
        moved_window,
        moved_x,
        moved_y,
    ) != null);
    server.pointerMotionGlobalForSeat(server.primaryRenderOutput(), &server.seat, 14, moved_x, moved_y);
    const disable_move_enter = try T.drain(client);
    defer std.testing.allocator.free(disable_move_enter);
    server.pointerButtonForSeat(&server.seat, 14, linux_button_left, .pressed);
    const disable_move_press = try T.drain(client);
    defer std.testing.allocator.free(disable_move_press);
    const disable_move_serial = T.eventWord(disable_move_press, 12, 3, 0) orelse return error.Unexpected;
    try T.send(client, 7, 5, &core.xdg_toplevel.request_messages[5], &.{
        .{ .object = 11 }, .{ .uint = disable_move_serial },
    });
    try std.testing.expect(server.window_manager.clientXdgPointerGrabActive());
    server.xdg_shell_core.setWindowInteractionEnabled(window_id, false);
    try std.testing.expect(!server.window_manager.directManipulationActive());
    try std.testing.expect(server.seat.hasPressedPointerButtons());
    try std.testing.expect(server.seat.authority.acceptsPointerGrab(
        clients.id(client).?,
        .{ .domain = .wayring_server, .value = disable_move_serial },
        surface_id,
    ));
    server.commitHeadlessSurface(surface_id, .{ .width = 20, .height = 20 }, false);
    try std.testing.expect(server.seat.hasPressedPointerButtons());
    try std.testing.expect(server.seat.authority.acceptsPointerGrab(
        clients.id(client).?,
        .{ .domain = .wayring_server, .value = disable_move_serial },
        surface_id,
    ));
    const disabled_move_position = server.scene.windowPosition(info.scene_id).?;
    server.pointerMotionGlobalForSeat(server.primaryRenderOutput(), &server.seat, 15, moved_x + 20, moved_y + 20);
    try std.testing.expectEqual(disabled_move_position, server.scene.windowPosition(info.scene_id).?);
    server.pointerButtonForSeat(&server.seat, 16, linux_button_left, .released);
    try std.testing.expect(!server.seat.hasPressedPointerButtons());
    server.xdg_shell_core.setWindowInteractionEnabled(window_id, true);

    server.pointerMotionGlobalForSeat(
        server.primaryRenderOutput(),
        &server.seat,
        17,
        moved_x,
        moved_y,
    );
    const resize_enter = try T.drain(client);
    defer std.testing.allocator.free(resize_enter);
    server.pointerButtonForSeat(&server.seat, 18, linux_button_left, .pressed);
    const resize_press = try T.drain(client);
    defer std.testing.allocator.free(resize_press);
    const resize_serial = T.eventWord(resize_press, 12, 3, 0) orelse return error.Unexpected;
    try std.testing.expect(seat_adapter.acceptsXdgPointerGrab(client, 11, resize_serial, surface_id) != null);
    try T.send(client, 7, 6, &core.xdg_toplevel.request_messages[6], &.{
        .{ .object = 11 }, .{ .uint = resize_serial }, .{ .uint = 10 },
    });
    try std.testing.expect(server.window_manager.clientXdgPointerGrabActive());
    server.pointerMotionGlobalForSeat(server.primaryRenderOutput(), &server.seat, 19, moved_x + 20, moved_y + 20);
    server.pointerButtonForSeat(&server.seat, 20, linux_button_left, .released);
    try std.testing.expect(!server.window_manager.directManipulationActive());
    try std.testing.expect(!server.xdg_shell_core.windowInfo(window_id).?.configuration.resizing);
    const resize_configures = try T.drain(client);
    defer std.testing.allocator.free(resize_configures);
    try std.testing.expect(resize_configures.len != 0);

    var presentation_windows = server.scene.iterator();
    const presentation_window = presentation_windows.next().?.window;
    const presentation_offset = presentation_window.content_geometry.?.offset;
    const presentation_x: f64 = @as(f64, @floatFromInt(presentation_window.position.x - presentation_offset.x)) + 10;
    const presentation_y: f64 = @as(f64, @floatFromInt(presentation_window.position.y - presentation_offset.y)) + 10;
    server.pointerMotionGlobalForSeat(server.primaryRenderOutput(), &server.seat, 21, presentation_x, presentation_y);
    const disable_resize_enter = try T.drain(client);
    defer std.testing.allocator.free(disable_resize_enter);
    server.pointerButtonForSeat(&server.seat, 22, linux_button_left, .pressed);
    const disable_resize_press = try T.drain(client);
    defer std.testing.allocator.free(disable_resize_press);
    const disable_resize_serial = T.eventWord(disable_resize_press, 12, 3, 0) orelse return error.Unexpected;
    try T.send(client, 7, 6, &core.xdg_toplevel.request_messages[6], &.{
        .{ .object = 11 }, .{ .uint = disable_resize_serial }, .{ .uint = 10 },
    });
    try std.testing.expect(server.window_manager.clientXdgPointerGrabActive());
    try server.xdg_shell_core.setWindowScenePresentationEnabled(window_id, false);
    try std.testing.expect(!server.window_manager.directManipulationActive());
    try std.testing.expect(server.seat.hasPressedPointerButtons());
    try std.testing.expect(server.seat.authority.acceptsPointerGrab(
        clients.id(client).?,
        .{ .domain = .wayring_server, .value = disable_resize_serial },
        surface_id,
    ));
    server.commitHeadlessSurface(surface_id, .{ .width = 20, .height = 20 }, false);
    try std.testing.expect(server.seat.hasPressedPointerButtons());
    try std.testing.expect(server.seat.authority.acceptsPointerGrab(
        clients.id(client).?,
        .{ .domain = .wayring_server, .value = disable_resize_serial },
        surface_id,
    ));
    const disabled_resize_position = server.scene.windowPosition(info.scene_id).?;
    server.pointerMotionGlobalForSeat(server.primaryRenderOutput(), &server.seat, 23, presentation_x + 20, presentation_y + 20);
    try std.testing.expectEqual(disabled_resize_position, server.scene.windowPosition(info.scene_id).?);
    server.pointerButtonForSeat(&server.seat, 24, linux_button_left, .released);
    try std.testing.expect(!server.seat.hasPressedPointerButtons());
    try server.xdg_shell_core.setWindowScenePresentationEnabled(window_id, true);

    server.pointerMotionGlobalForSeat(server.primaryRenderOutput(), &server.seat, 25, presentation_x, presentation_y);
    const retiring_resize_enter = try T.drain(client);
    defer std.testing.allocator.free(retiring_resize_enter);
    server.pointerButtonForSeat(&server.seat, 26, linux_button_left, .pressed);
    const retiring_resize_press = try T.drain(client);
    defer std.testing.allocator.free(retiring_resize_press);
    const retiring_resize_serial = T.eventWord(retiring_resize_press, 12, 3, 0) orelse return error.Unexpected;
    try T.send(client, 7, 6, &core.xdg_toplevel.request_messages[6], &.{
        .{ .object = 11 }, .{ .uint = retiring_resize_serial }, .{ .uint = 10 },
    });
    try std.testing.expect(server.window_manager.clientXdgPointerGrabActive());
    var before_retiring_resize = server.scene.iterator();
    const retiring_resize_geometry = before_retiring_resize.next().?.window.content_geometry;
    const retiring_client = clients.id(client).?;
    const request_sink = server.generatedSeatRequestSink();
    request_sink.client_retiring(request_sink.context, retiring_client);
    try std.testing.expect(!server.window_manager.directManipulationActive());
    try std.testing.expect(!server.seat.hasPressedPointerButtons());
    try std.testing.expect(server.seat.generatedPointerState() == null);
    try std.testing.expect(!server.seat.authority.acceptsAction(retiring_client, .{
        .domain = .wayring_server,
        .value = retiring_resize_serial,
    }));
    server.pointerMotionGlobalForSeat(server.primaryRenderOutput(), &server.seat, 27, presentation_x + 30, presentation_y + 30);
    var after_retiring_resize = server.scene.iterator();
    try std.testing.expectEqual(retiring_resize_geometry, after_retiring_resize.next().?.window.content_geometry);
    server.pointerButtonForSeat(&server.seat, 28, linux_button_left, .released);

    var resized_windows = server.scene.iterator();
    const resized_window = resized_windows.next().?.window;
    const resized_offset = resized_window.content_geometry.?.offset;
    server.pointerMotionGlobalForSeat(
        server.primaryRenderOutput(),
        &server.seat,
        17,
        @as(f64, @floatFromInt(resized_window.position.x - resized_offset.x)) + 10,
        @as(f64, @floatFromInt(resized_window.position.y - resized_offset.y)) + 10,
    );
    const menu_enter = try T.drain(client);
    defer std.testing.allocator.free(menu_enter);
    server.pointerButtonForSeat(&server.seat, 17, linux_button_left, .pressed);
    const menu_press = try T.drain(client);
    defer std.testing.allocator.free(menu_press);
    const menu_serial = T.eventWord(menu_press, 12, 3, 0) orelse return error.Unexpected;
    try T.send(client, 7, 4, &core.xdg_toplevel.request_messages[4], &.{
        .{ .object = 11 }, .{ .uint = menu_serial }, .{ .int = 0 }, .{ .int = 0 },
    });
    try std.testing.expect(!server.window_manager.directManipulationActive());
    server.pointerButtonForSeat(&server.seat, 18, linux_button_left, .released);
    const menu_release = try T.drain(client);
    defer std.testing.allocator.free(menu_release);

    // Topology loss cancels a client-XDG manipulation before invalidating its
    // exact press grant. A later physical release is harmless bookkeeping.
    var final_windows = server.scene.iterator();
    const final_window = final_windows.next().?.window;
    const final_offset = final_window.content_geometry.?.offset;
    const final_x: f64 = @as(f64, @floatFromInt(final_window.position.x - final_offset.x)) + 10;
    const final_y: f64 = @as(f64, @floatFromInt(final_window.position.y - final_offset.y)) + 10;
    server.pointerMotionGlobalForSeat(server.primaryRenderOutput(), &server.seat, 19, final_x, final_y);
    const topology_enter = try T.drain(client);
    defer std.testing.allocator.free(topology_enter);
    server.pointerButtonForSeat(&server.seat, 20, linux_button_left, .pressed);
    const topology_press = try T.drain(client);
    defer std.testing.allocator.free(topology_press);
    const topology_serial = T.eventWord(topology_press, 12, 3, 0) orelse return error.Unexpected;
    try T.send(client, 7, 5, &core.xdg_toplevel.request_messages[5], &.{
        .{ .object = 11 }, .{ .uint = topology_serial },
    });
    try std.testing.expect(server.window_manager.clientXdgPointerGrabActive());
    server.commitHeadlessSurface(surface_id, null, false);
    try std.testing.expect(!server.window_manager.directManipulationActive());
    try std.testing.expect(!server.seat.hasPressedPointerButtons());
    try std.testing.expect(!server.seat.authority.acceptsAction(clients.id(client).?, .{
        .domain = .wayring_server,
        .value = topology_serial,
    }));
    server.pointerButtonForSeat(&server.seat, 21, linux_button_left, .released);
    server.commitHeadlessSurface(surface_id, .{ .width = 20, .height = 20 }, false);

    // Null-buffer unmap during an active resize discards the disappearing
    // endpoint without publishing an unacknowledgeable final configure.
    server.pointerMotionGlobalForSeat(server.primaryRenderOutput(), &server.seat, 22, final_x, final_y);
    const unmap_enter = try T.drain(client);
    defer std.testing.allocator.free(unmap_enter);
    server.pointerButtonForSeat(&server.seat, 23, linux_button_left, .pressed);
    const unmap_press = try T.drain(client);
    defer std.testing.allocator.free(unmap_press);
    const unmap_serial = T.eventWord(unmap_press, 12, 3, 0) orelse return error.Unexpected;
    try T.send(client, 7, 6, &core.xdg_toplevel.request_messages[6], &.{
        .{ .object = 11 }, .{ .uint = unmap_serial }, .{ .uint = 10 },
    });
    try std.testing.expect(server.window_manager.clientXdgPointerGrabActive());
    const active_resize = try T.drain(client);
    defer std.testing.allocator.free(active_resize);
    try T.send(client, 4, 1, &core.wl_surface.request_messages[1], &.{ .{ .object = null }, .{ .int = 0 }, .{ .int = 0 } });
    try T.send(client, 4, 6, &core.wl_surface.request_messages[6], &.{});
    try std.testing.expect(!server.window_manager.directManipulationActive());
    try std.testing.expect(!server.window_manager.transaction.isInflight());
    const unmap_events = try T.drain(client);
    defer std.testing.allocator.free(unmap_events);
    try std.testing.expect(T.eventWord(unmap_events, 6, 0, 0) == null);
    server.pointerButtonForSeat(&server.seat, 24, linux_button_left, .released);
    try T.send(client, 4, 6, &core.wl_surface.request_messages[6], &.{});
    const final_remap = try T.drain(client);
    defer std.testing.allocator.free(final_remap);
    const final_remap_serial = T.word(final_remap, final_remap.len - 4);
    try T.send(client, 6, 4, &core.xdg_surface.request_messages[4], &.{.{ .uint = final_remap_serial }});
    try T.send(client, 4, 1, &core.wl_surface.request_messages[1], &.{ .{ .object = 10 }, .{ .int = 0 }, .{ .int = 0 } });
    try T.send(client, 4, 6, &core.wl_surface.request_messages[6], &.{});

    // A terminal generated client loses WM manipulation before Seat authority
    // is retired, even while its protocol resources remain allocated for
    // fatal-output draining. Later motion cannot continue either operation.
    var retiring_windows = server.scene.iterator();
    const retiring_window = retiring_windows.next().?.window;
    const retiring_offset = retiring_window.content_geometry.?.offset;
    const retiring_x: f64 = @as(f64, @floatFromInt(retiring_window.position.x - retiring_offset.x)) + 10;
    const retiring_y: f64 = @as(f64, @floatFromInt(retiring_window.position.y - retiring_offset.y)) + 10;

    server.pointerMotionGlobalForSeat(server.primaryRenderOutput(), &server.seat, 30, retiring_x, retiring_y);
    const retiring_move_enter = try T.drain(client);
    defer std.testing.allocator.free(retiring_move_enter);
    server.pointerButtonForSeat(&server.seat, 31, linux_button_left, .pressed);
    const retiring_move_press = try T.drain(client);
    defer std.testing.allocator.free(retiring_move_press);
    const retiring_move_serial = T.eventWord(retiring_move_press, 12, 3, 0) orelse return error.Unexpected;
    try T.send(client, 7, 5, &core.xdg_toplevel.request_messages[5], &.{
        .{ .object = 11 }, .{ .uint = retiring_move_serial },
    });
    try std.testing.expect(server.window_manager.clientXdgPointerGrabActive());
    const retiring_move_position = server.scene.windowPosition(info.scene_id).?;
    request_sink.client_retiring(request_sink.context, retiring_client);
    try std.testing.expect(!server.window_manager.directManipulationActive());
    try std.testing.expect(!server.seat.hasPressedPointerButtons());
    try std.testing.expect(server.seat.generatedPointerState() == null);
    try std.testing.expect(!server.seat.authority.acceptsAction(retiring_client, .{
        .domain = .wayring_server,
        .value = retiring_move_serial,
    }));
    server.pointerMotionGlobalForSeat(server.primaryRenderOutput(), &server.seat, 32, retiring_x + 30, retiring_y + 30);
    try std.testing.expectEqual(retiring_move_position, server.scene.windowPosition(info.scene_id).?);
    server.pointerButtonForSeat(&server.seat, 33, linux_button_left, .released);

    // Losing the final pointer capability performs the same ordered cancel
    // and revokes grants before the device can disappear.
    var capability_windows = server.scene.iterator();
    const capability_window = capability_windows.next().?.window;
    const capability_offset = capability_window.content_geometry.?.offset;
    const capability_x: f64 = @as(f64, @floatFromInt(capability_window.position.x - capability_offset.x)) + 10;
    const capability_y: f64 = @as(f64, @floatFromInt(capability_window.position.y - capability_offset.y)) + 10;
    server.pointerMotionGlobalForSeat(server.primaryRenderOutput(), &server.seat, 38, capability_x, capability_y);
    const capability_enter = try T.drain(client);
    defer std.testing.allocator.free(capability_enter);
    server.pointerButtonForSeat(&server.seat, 39, linux_button_left, .pressed);
    const capability_press = try T.drain(client);
    defer std.testing.allocator.free(capability_press);
    const capability_serial = T.eventWord(capability_press, 12, 3, 0) orelse return error.Unexpected;
    try T.send(client, 7, 5, &core.xdg_toplevel.request_messages[5], &.{
        .{ .object = 11 }, .{ .uint = capability_serial },
    });
    try std.testing.expect(server.window_manager.clientXdgPointerGrabActive());
    pointerAvailable(server.primaryRenderOutput(), false);
    try std.testing.expect(!server.window_manager.directManipulationActive());
    try std.testing.expect(!server.seat.hasPressedPointerButtons());
    try std.testing.expect(!server.seat.authority.acceptsAction(clients.id(client).?, .{
        .domain = .wayring_server,
        .value = capability_serial,
    }));
    server.pointerButtonForSeat(&server.seat, 40, linux_button_left, .released);
    pointerAvailable(server.primaryRenderOutput(), true);

    // A generated popup remains private before its configured buffer handoff.
    try T.send(client, 3, 0, &core.wl_compositor.request_messages[0], &.{.{ .new_id = .{ .typed = 13 } }});
    const popup_surface_id = compositor.surfaceId(client, 13).?;
    try std.testing.expectEqual(
        HeadlessSurfaceForest.PresentationClass.background,
        server.headless_surface_forest.presentationClass(popup_surface_id).?,
    );
    try T.send(client, 13, 1, &core.wl_surface.request_messages[1], &.{ .{ .object = 10 }, .{ .int = 0 }, .{ .int = 0 } });
    try T.send(client, 13, 6, &core.wl_surface.request_messages[6], &.{});
    server.pointerMotionGlobalForSeat(server.primaryRenderOutput(), &server.seat, 28, capability_x, capability_y);
    const background_focus_enter = try T.drain(client);
    defer std.testing.allocator.free(background_focus_enter);
    try std.testing.expectEqual(surface_id, server.seat.pointerFocus().?.generated.?.root);
    try std.testing.expect(server.focusGeneratedSurface(popup_surface_id));
    try std.testing.expectEqual(popup_surface_id, server.seat.generatedKeyboardFocus().?.surface);
    try T.send(client, 13, 1, &core.wl_surface.request_messages[1], &.{ .{ .object = null }, .{ .int = 0 }, .{ .int = 0 } });
    try T.send(client, 13, 6, &core.wl_surface.request_messages[6], &.{});
    try T.send(client, 5, 2, &core.xdg_wm_base.request_messages[2], &.{ .{ .new_id = .{ .typed = 14 } }, .{ .object = 13 } });
    try T.send(client, 5, 1, &core.xdg_wm_base.request_messages[1], &.{.{ .new_id = .{ .typed = 15 } }});
    try T.send(client, 15, 1, &core.xdg_positioner.request_messages[1], &.{ .{ .int = 1 }, .{ .int = 1 } });
    try T.send(client, 15, 2, &core.xdg_positioner.request_messages[2], &.{
        .{ .int = 0 }, .{ .int = 0 }, .{ .int = 1 }, .{ .int = 1 },
    });
    try T.send(client, 14, 2, &core.xdg_surface.request_messages[2], &.{
        .{ .new_id = .{ .typed = 16 } }, .{ .object = 6 }, .{ .object = 15 },
    });
    const popup_id = server.xdg_shell_core.popupForSurface(popup_surface_id).?;
    try std.testing.expect(!server.xdg_shell_core.popupScenePresentationEnabled(popup_id));
    try std.testing.expect(!server.scene.surfaceMapped(popup_surface_id));
    try T.send(client, 13, 6, &core.wl_surface.request_messages[6], &.{});
    const popup_configure = try T.drain(client);
    defer std.testing.allocator.free(popup_configure);
    const popup_serial = T.word(popup_configure, popup_configure.len - 4);
    try T.send(client, 14, 4, &core.xdg_surface.request_messages[4], &.{.{ .uint = popup_serial }});
    try T.send(client, 13, 1, &core.wl_surface.request_messages[1], &.{ .{ .object = 10 }, .{ .int = 0 }, .{ .int = 0 } });
    try T.send(client, 13, 6, &core.wl_surface.request_messages[6], &.{});
    try std.testing.expect(server.xdg_shell_core.popupMapped(popup_id));
    try std.testing.expect(server.xdg_shell_core.popupScenePresentationEnabled(popup_id));
    try std.testing.expect(server.scene.surfaceMapped(popup_surface_id));
    try std.testing.expectEqual(HeadlessSurfaceForest.PresentationClass.managed, server.headless_surface_forest.presentationClass(popup_surface_id).?);
    // Managed generated roots are rendered exactly once through Scene, never
    // duplicated by the global headless forest plane.
    rendered_surfaces = server.headless_surface_forest.renderIterator();
    try std.testing.expect(rendered_surfaces.next() == null);
    const popup_render_output = server.primaryRenderOutput();
    try std.testing.expect(!popup_render_output.damage.isEmpty());
    try renderPendingTestOutput(server, popup_render_output);
    const popup_output = server.outputs.get(popup_render_output.protocol_id).?;
    try std.testing.expect(popup_output.containsSurface(popup_surface_id));
    try std.testing.expect(popup_render_output.damage.isEmpty());
    try T.send(client, 13, 6, &core.wl_surface.request_messages[6], &.{});
    try std.testing.expect(!popup_render_output.damage.isEmpty());
    try std.testing.expectEqual(@as(usize, 0), server.window_transitions.items.len);

    // Null-buffer unmap hides and resets presentation. Reconstruction starts
    // private again before the permanent generated role is republished.
    try T.send(client, 13, 1, &core.wl_surface.request_messages[1], &.{ .{ .object = null }, .{ .int = 0 }, .{ .int = 0 } });
    try T.send(client, 13, 6, &core.wl_surface.request_messages[6], &.{});
    try std.testing.expect(!server.xdg_shell_core.popupMapped(popup_id));
    try std.testing.expect(!server.xdg_shell_core.popupScenePresentationEnabled(popup_id));
    try std.testing.expect(!server.scene.surfaceMapped(popup_surface_id));
    try std.testing.expect(popup_output.containsSurface(popup_surface_id));
    try std.testing.expect(!popup_render_output.damage.isEmpty());
    try renderPendingTestOutput(server, popup_render_output);
    try std.testing.expect(!popup_output.containsSurface(popup_surface_id));
    try std.testing.expect(popup_render_output.damage.isEmpty());
    try T.send(client, 16, 0, &core.xdg_popup.request_messages[0], &.{});
    try T.send(client, 14, 0, &core.xdg_surface.request_messages[0], &.{});
    try T.send(client, 5, 2, &core.xdg_wm_base.request_messages[2], &.{ .{ .new_id = .{ .typed = 17 } }, .{ .object = 13 } });
    try T.send(client, 5, 1, &core.xdg_wm_base.request_messages[1], &.{.{ .new_id = .{ .typed = 18 } }});
    try T.send(client, 18, 1, &core.xdg_positioner.request_messages[1], &.{ .{ .int = 1 }, .{ .int = 1 } });
    try T.send(client, 18, 2, &core.xdg_positioner.request_messages[2], &.{
        .{ .int = 0 }, .{ .int = 0 }, .{ .int = 1 }, .{ .int = 1 },
    });
    try T.send(client, 17, 2, &core.xdg_surface.request_messages[2], &.{
        .{ .new_id = .{ .typed = 19 } }, .{ .object = 6 }, .{ .object = 18 },
    });
    const reconstructed_popup = server.xdg_shell_core.popupForSurface(popup_surface_id).?;
    try std.testing.expect(!server.xdg_shell_core.popupScenePresentationEnabled(reconstructed_popup));
    try T.send(client, 19, 0, &core.xdg_popup.request_messages[0], &.{});
    try T.send(client, 17, 0, &core.xdg_surface.request_messages[0], &.{});
    try T.send(client, 13, 0, &core.wl_surface.request_messages[0], &.{});
    try T.send(client, 15, 0, &core.xdg_positioner.request_messages[0], &.{});
    try T.send(client, 18, 0, &core.xdg_positioner.request_messages[0], &.{});

    // Foreign-toplevel activation is caller-authorized, serialless, and
    // cross-client. It must still reach sole WM policy to unminimize and
    // publish an activated configure; an ungranted generated action remains
    // inert.
    const controller_client = try server.client_registry.register(.mature_display);
    defer server.client_registry.unregister(controller_client);
    server.xdg_shell_core.requestWindow(window_id, .minimize);
    var activation_snapshots = try server.window_manager.windowSnapshots(std.testing.allocator);
    try std.testing.expect(activation_snapshots[0].minimized);
    try std.testing.expect(!activation_snapshots[0].focused);
    std.testing.allocator.free(activation_snapshots);
    server.xdg_shell_core.requestWindow(window_id, .{ .activate = .{
        .client = clients.id(client).?,
        .serial = null,
        .granted = false,
    } });
    activation_snapshots = try server.window_manager.windowSnapshots(std.testing.allocator);
    try std.testing.expect(activation_snapshots[0].minimized);
    try std.testing.expect(!activation_snapshots[0].focused);
    std.testing.allocator.free(activation_snapshots);
    server.xdg_shell_core.requestWindow(window_id, .{ .activate = .{
        .client = controller_client,
        .serial = null,
        .granted = true,
    } });
    activation_snapshots = try server.window_manager.windowSnapshots(std.testing.allocator);
    try std.testing.expect(!activation_snapshots[0].minimized);
    try std.testing.expect(activation_snapshots[0].focused);
    std.testing.allocator.free(activation_snapshots);
    try std.testing.expect(server.xdg_shell_core.windowInfo(window_id).?.configuration.activated);

    // A presented, interactive window migrates output ownership through
    // the same public workspace topology as a mature toplevel.
    server.primary_render_output = replacement_output;
    try std.testing.expect(server.removeRenderOutput(initial_output));
    const migrated_configure = try T.drain(client);
    defer std.testing.allocator.free(migrated_configure);
    const migrated = try server.window_manager.windowSnapshots(std.testing.allocator);
    defer std.testing.allocator.free(migrated);
    try std.testing.expectEqual(@as(usize, 1), migrated.len);
    try std.testing.expectEqual(surface_id, server.window_manager.focusedSurface().?);

    // Leave a real WM configure transaction outstanding; role destruction
    // must remove its participant rather than waiting for an acknowledgement.
    try T.send(client, 7, 9, &core.xdg_toplevel.request_messages[9], &.{});
    try T.send(client, 7, 0, &core.xdg_toplevel.request_messages[0], &.{});
    try T.send(client, 6, 0, &core.xdg_surface.request_messages[0], &.{});
    try T.send(client, 4, 0, &core.wl_surface.request_messages[0], &.{});
    try std.testing.expectEqual(@as(usize, 0), compositor.surfaceCount());
    try std.testing.expectEqual(@as(usize, 0), server.headless_surface_forest.len());
    var remaining_windows = server.xdg_shell_core.windowIterator();
    try std.testing.expect(remaining_windows.next() == null);
}

test "hidden XDG presentation classes synchronously clear generated keyboard focus" {
    const server = try Self.createWithVirtualOutput(
        std.testing.allocator,
        std.testing.io,
        .cpu,
        .headless,
        null,
        .{ .size = .{ .width = 2, .height = 1 } },
    );
    defer server.destroy();
    var reserved_provider: SyntheticSurfaceProvider = .{
        .pixel = 0xff11_2233,
        .logical_size = .{ .width = 1, .height = 1 },
    };
    var managed_provider: SyntheticSurfaceProvider = .{
        .pixel = 0xff44_5566,
        .logical_size = .{ .width = 1, .height = 1 },
    };
    const reserved = try server.surface_registry.add(reserved_provider.provider());
    const managed = try server.surface_registry.add(managed_provider.provider());
    try server.addHeadlessSurface(reserved, null);
    try server.addHeadlessSurface(managed, null);
    server.applyHeadlessBatch(.{
        .surfaces = &.{
            .{ .id = reserved, .mapped_size = reserved_provider.logical_size, .callbacks_committed = false },
            .{ .id = managed, .mapped_size = managed_provider.logical_size, .callbacks_committed = false },
        },
        .parents = &.{},
    });
    defer {
        server.removeHeadlessSurface(managed);
        server.surface_registry.remove(managed);
        server.removeHeadlessSurface(reserved);
        server.surface_registry.remove(reserved);
    }

    const generated_client = try server.client_registry.register(.wayring_server);
    defer server.client_registry.unregister(generated_client);
    var sink: TestGeneratedSeatSink = .{
        .clients = &server.client_registry,
        .client = generated_client,
    };
    server.setGeneratedSeatDeliverySink(sink.sink());
    defer server.clearGeneratedSeatDeliverySink(&sink);
    var pipe_fds: [2]std.posix.fd_t = undefined;
    if (std.c.pipe(&pipe_fds) != 0) return error.Unexpected;
    defer _ = std.c.close(pipe_fds[1]);
    server.seat.setKeymap(.xkb_v1, pipe_fds[0], 8);
    server.seat.setKeyboardAvailable(true);
    defer server.seat.setKeyboardAvailable(false);
    const changed = server.wayringPresentationListener().?.presentation_class.?;

    try std.testing.expect(server.focusGeneratedSurface(reserved));
    changed(server, reserved, .xdg_reserved);
    try std.testing.expect(server.seat.generatedKeyboardFocus() == null);
    const after_reserved = sink.keyboard_event_count;
    try server.seat.key(1, 30, .pressed);
    try std.testing.expectEqual(after_reserved, sink.keyboard_event_count);

    try std.testing.expect(server.focusGeneratedSurface(managed));
    changed(server, managed, .managed);
    try std.testing.expect(server.seat.generatedKeyboardFocus() == null);
    const after_managed = sink.keyboard_event_count;
    try server.seat.key(2, 31, .pressed);
    try std.testing.expectEqual(after_managed, sink.keyboard_event_count);
}

test "Wayring presentation policy excludes DRM and nested sidecars" {
    try std.testing.expect(wayringPresentationEnabled(.headless));
    try std.testing.expect(!wayringPresentationEnabled(.drm));
    try std.testing.expect(!wayringPresentationEnabled(.nested));
}

const WayringHeadlessClient = struct {
    const Stage = enum(u8) {
        starting,
        initial_released,
        initial_done,
        replacement_released,
        transformed_committed,
        transformed_done,
        scale_buffer_released,
        viewport_committed,
        viewport_destroyed,
        scaled_committed,
        scaled_done,
        damage_buffer_committed,
        damage_buffer_done,
        offset_attachment_released,
        offset_attachment_done,
        offset_only_committed,
        offset_only_done,
        unmapped,
        unmapped_no_done,
        remapped_released,
        remapped_done,
        default_replaced,
        outstanding_callback,
        disconnected,
        failed,
    };

    runtime_directory: []const u8,
    display_name: []const u8,
    command_fd: std.posix.fd_t,
    stage: std.atomic.Value(u8) = .init(@intFromEnum(Stage.starting)),
    wake_fd: std.atomic.Value(i32) = .init(-1),
    failure: ?anyerror = null,
    compositor: ?*wayland.client.wl.Compositor = null,
    shm: ?*wayland.client.wl.Shm = null,
    output: ?*wayland.client.wl.Output = null,
    viewporter: ?*wayland.client.wp.Viewporter = null,
    fractional_scale_manager: ?*wayland.client.wp.FractionalScaleManagerV1 = null,
    cursor_shape_manager: ?*wayland.client.wp.CursorShapeManagerV1 = null,
    compositor_version: std.atomic.Value(u32) = .init(0),
    global_count: usize = 0,
    globals_exact: bool = true,
    text_input_global_seen: bool = false,
    input_method_global_seen: bool = false,
    output_globals: u8 = 0,
    output_version: u32 = 0,
    output_name_valid: bool = false,
    output_mode_width: i32 = 0,
    output_mode_height: i32 = 0,
    output_scale: i32 = 0,
    output_done_count: u8 = 0,
    release_count: std.atomic.Value(u8) = .init(0),
    frame_done_count: std.atomic.Value(u8) = .init(0),
    last_frame_timestamp_ms: std.atomic.Value(u32) = .init(0),
    preferred_buffer_scale_count: std.atomic.Value(u8) = .init(0),
    preferred_buffer_scale: std.atomic.Value(i32) = .init(0),
    preferred_buffer_transform_count: std.atomic.Value(u8) = .init(0),
    preferred_buffer_transform: std.atomic.Value(i32) = .init(std.math.maxInt(i32)),
    output_enter_count: std.atomic.Value(u8) = .init(0),
    output_leave_count: std.atomic.Value(u8) = .init(0),
    fractional_scale_count: std.atomic.Value(u8) = .init(0),
    fractional_scale: std.atomic.Value(u32) = .init(0),

    const expected_globals = [_]struct { name: []const u8, version: u32 }{
        .{ .name = "wl_compositor", .version = 6 },
        .{ .name = "wl_shm", .version = 1 },
        .{ .name = "wl_subcompositor", .version = 1 },
        .{ .name = "wl_seat", .version = 11 },
        .{ .name = "wl_output", .version = 4 },
        .{ .name = "xdg_wm_base", .version = 7 },
        .{ .name = "wp_viewporter", .version = 1 },
        .{ .name = "wp_fractional_scale_manager_v1", .version = 1 },
        .{ .name = "wp_cursor_shape_manager_v1", .version = 2 },
    };

    fn run(self: *WayringHeadlessClient) void {
        self.runFallible() catch |err| {
            self.failure = err;
            self.stage.store(@intFromEnum(Stage.failed), .release);
            return;
        };
        self.stage.store(@intFromEnum(Stage.disconnected), .release);
    }

    fn runFallible(self: *WayringHeadlessClient) !void {
        const path = try std.fmt.allocPrintSentinel(
            std.heap.page_allocator,
            "{s}/{s}",
            .{ self.runtime_directory, self.display_name },
            0,
        );
        defer std.heap.page_allocator.free(path);
        const fd = try connectWayringTestSocket(path);
        var fd_owned = true;
        defer if (fd_owned) {
            _ = std.os.linux.close(fd);
        };
        const raw_wake_fd = std.os.linux.dup(fd);
        if (std.os.linux.errno(raw_wake_fd) != .SUCCESS) return error.WakeFdFailed;
        const wake_fd: i32 = @intCast(raw_wake_fd);
        if (self.wake_fd.cmpxchgStrong(-1, wake_fd, .acq_rel, .acquire)) |state| {
            _ = std.os.linux.close(wake_fd);
            std.debug.assert(state == -2);
            return error.ClientShutdown;
        }
        defer self.closeWake(false);

        const display = try wayland.client.wl.Display.connectToFd(fd);
        fd_owned = false;
        defer display.disconnect();
        const registry = try display.getRegistry();
        defer registry.destroy();
        registry.setListener(*WayringHeadlessClient, registryEvent, self);
        try expectClientRoundtrip(display);
        if (!self.globals_exact or self.global_count != expected_globals.len or
            self.text_input_global_seen or self.input_method_global_seen)
            return error.UnexpectedRegistrySnapshot;
        const compositor = self.compositor orelse return error.CompositorMissing;
        const shm = self.shm orelse return error.ShmMissing;
        const output = self.output orelse return error.OutputMissing;
        const viewporter = self.viewporter orelse return error.ViewporterMissing;
        const fractional_scale_manager = self.fractional_scale_manager orelse return error.FractionalScaleMissing;
        const cursor_shape_manager = self.cursor_shape_manager orelse return error.CursorShapeMissing;
        defer cursor_shape_manager.destroy();
        defer fractional_scale_manager.destroy();
        defer viewporter.destroy();
        defer output.release();
        try expectClientRoundtrip(display);
        if (self.output_globals != 1 or self.output_version != 4 or
            !self.output_name_valid or self.output_mode_width != 4 or
            self.output_mode_height != 2 or self.output_scale != 1 or
            self.output_done_count != 1)
            return error.UnexpectedOutputState;
        const surface = try compositor.createSurface();
        defer surface.destroy();
        const fractional_scale = try fractional_scale_manager.getFractionalScale(surface);
        defer fractional_scale.destroy();
        fractional_scale.setListener(*WayringHeadlessClient, fractionalScaleEvent, self);
        const viewport = try viewporter.getViewport(surface);
        var viewport_live = true;
        defer if (viewport_live) viewport.destroy();
        surface.setListener(*WayringHeadlessClient, surfaceEvent, self);
        try expectClientRoundtrip(display);
        if (self.preferred_buffer_scale_count.load(.acquire) != 1 or
            self.preferred_buffer_scale.load(.acquire) != 1)
            return error.UnexpectedPreferredBufferScale;
        if (self.preferred_buffer_transform_count.load(.acquire) != 1 or
            self.preferred_buffer_transform.load(.acquire) != @intFromEnum(wayland.client.wl.Output.Transform.normal))
            return error.UnexpectedPreferredBufferTransform;
        if (self.fractional_scale_count.load(.acquire) != 1 or
            self.fractional_scale.load(.acquire) != 120)
            return error.UnexpectedFractionalScale;
        const region = try compositor.createRegion();
        region.add(0, 0, 2, 1);
        region.subtract(1, 0, 1, 1);
        surface.setOpaqueRegion(region);
        surface.setInputRegion(region);
        region.destroy();

        const shm_fd = try std.posix.memfd_create("keywork-wayring-headless", std.os.linux.MFD.CLOEXEC);
        defer _ = std.os.linux.close(shm_fd);
        const byte_count = 2 * @sizeOf(u32);
        if (std.os.linux.errno(std.os.linux.ftruncate(shm_fd, byte_count)) != .SUCCESS)
            return error.ShmResizeFailed;
        const pool = try shm.createPool(shm_fd, byte_count);
        defer pool.destroy();
        const buffer = try pool.createBuffer(0, 2, 1, byte_count, .xrgb8888);
        defer buffer.destroy();
        buffer.setListener(*WayringHeadlessClient, bufferEvent, self);
        const fractional_shm_fd = try std.posix.memfd_create("keywork-wayring-fractional", std.os.linux.MFD.CLOEXEC);
        defer _ = std.os.linux.close(fractional_shm_fd);
        if (std.os.linux.errno(std.os.linux.ftruncate(fractional_shm_fd, @sizeOf(@TypeOf(wayring_fractional_pixels)))) != .SUCCESS)
            return error.ShmResizeFailed;
        const fractional_pool = try shm.createPool(fractional_shm_fd, @sizeOf(@TypeOf(wayring_fractional_pixels)));
        defer fractional_pool.destroy();
        const fractional_buffer = try fractional_pool.createBuffer(
            0,
            6,
            3,
            6 * @sizeOf(u32),
            .xrgb8888,
        );
        defer fractional_buffer.destroy();
        fractional_buffer.setListener(*WayringHeadlessClient, bufferEvent, self);

        try self.requestFrame(surface);
        try self.commitBuffer(display, surface, buffer, shm_fd, .{ 0x0011_2233, 0x0044_5566 }, 1);
        if (self.frame_done_count.load(.acquire) != 0) return error.UnexpectedFrameDone;
        self.stage.store(@intFromEnum(Stage.initial_released), .release);
        try waitForWayringCommand(self.command_fd);
        try expectClientRoundtrip(display);
        if (self.frame_done_count.load(.acquire) != 1) return error.MissingFrameDone;
        if (self.output_enter_count.load(.acquire) != 1 or
            self.output_leave_count.load(.acquire) != 0)
            return error.UnexpectedOutputMembership;
        self.stage.store(@intFromEnum(Stage.initial_done), .release);
        try waitForWayringCommand(self.command_fd);

        try writeWayringFractionalPixels(fractional_shm_fd, wayring_fractional_pixels);
        surface.setBufferScale(1);
        viewport.setDestination(4, 2);
        surface.attach(fractional_buffer, 0, 0);
        surface.damage(0, 0, 4, 2);
        surface.commit();
        try expectClientRoundtrip(display);
        if (self.release_count.load(.acquire) != 2) return error.UnexpectedBufferRelease;
        try writeWayringFractionalPixels(fractional_shm_fd, @splat(0x00de_ad00));
        if (self.fractional_scale_count.load(.acquire) != 2 or
            self.fractional_scale.load(.acquire) != 180)
            return error.UnexpectedFractionalScale;
        self.stage.store(@intFromEnum(Stage.replacement_released), .release);
        try waitForWayringCommand(self.command_fd);

        try self.requestFrame(surface);
        try writeWayringTestPixels(shm_fd, .{ 0x0066_7788, 0x0099_aabb });
        viewport.setDestination(-1, -1);
        surface.attach(buffer, 0, 0);
        surface.damage(0, 0, 2, 1);
        surface.setBufferTransform(.@"90");
        surface.commit();
        try expectClientRoundtrip(display);
        if (self.release_count.load(.acquire) != 3) return error.UnexpectedBufferRelease;
        try writeWayringTestPixels(shm_fd, .{ 0x00de_ad00, 0x00be_ef00 });
        if (self.frame_done_count.load(.acquire) != 1) return error.UnexpectedFrameDone;
        if (self.fractional_scale_count.load(.acquire) != 3 or
            self.fractional_scale.load(.acquire) != 120)
            return error.UnexpectedFractionalScale;
        self.stage.store(@intFromEnum(Stage.transformed_committed), .release);
        try waitForWayringCommand(self.command_fd);
        try expectClientRoundtrip(display);
        if (self.frame_done_count.load(.acquire) != 2) return error.MissingFrameDone;
        self.stage.store(@intFromEnum(Stage.transformed_done), .release);
        try waitForWayringCommand(self.command_fd);

        const scale_shm_fd = try std.posix.memfd_create("keywork-wayring-scale", std.os.linux.MFD.CLOEXEC);
        defer _ = std.os.linux.close(scale_shm_fd);
        const scale_byte_count = 8 * @sizeOf(u32);
        if (std.os.linux.errno(std.os.linux.ftruncate(scale_shm_fd, scale_byte_count)) != .SUCCESS)
            return error.ShmResizeFailed;
        const scale_pool = try shm.createPool(scale_shm_fd, scale_byte_count);
        defer scale_pool.destroy();
        const scale_buffer = try scale_pool.createBuffer(0, 4, 2, 4 * @sizeOf(u32), .xrgb8888);
        defer scale_buffer.destroy();
        scale_buffer.setListener(*WayringHeadlessClient, bufferEvent, self);
        try self.commitScaleBuffer(display, surface, scale_buffer, scale_shm_fd, 4);
        self.stage.store(@intFromEnum(Stage.scale_buffer_released), .release);
        try waitForWayringCommand(self.command_fd);

        viewport.setSource(
            wayland.client.wl.Fixed.fromInt(1),
            wayland.client.wl.Fixed.fromInt(0),
            wayland.client.wl.Fixed.fromInt(2),
            wayland.client.wl.Fixed.fromInt(2),
        );
        viewport.setDestination(4, 2);
        surface.commit();
        try expectClientRoundtrip(display);
        self.stage.store(@intFromEnum(Stage.viewport_committed), .release);
        try waitForWayringCommand(self.command_fd);

        viewport.destroy();
        viewport_live = false;
        surface.commit();
        try expectClientRoundtrip(display);
        self.stage.store(@intFromEnum(Stage.viewport_destroyed), .release);
        try waitForWayringCommand(self.command_fd);

        try self.requestFrame(surface);
        surface.setBufferScale(2);
        surface.commit();
        try expectClientRoundtrip(display);
        if (self.release_count.load(.acquire) != 4) return error.UnexpectedBufferRelease;
        if (self.frame_done_count.load(.acquire) != 2) return error.UnexpectedFrameDone;
        self.stage.store(@intFromEnum(Stage.scaled_committed), .release);
        try waitForWayringCommand(self.command_fd);
        try expectClientRoundtrip(display);
        if (self.frame_done_count.load(.acquire) != 3) return error.MissingFrameDone;
        self.stage.store(@intFromEnum(Stage.scaled_done), .release);
        try waitForWayringCommand(self.command_fd);

        try self.requestFrame(surface);
        surface.damageBuffer(0, 0, 4, 2);
        surface.commit();
        try expectClientRoundtrip(display);
        if (self.frame_done_count.load(.acquire) != 3) return error.UnexpectedFrameDone;
        self.stage.store(@intFromEnum(Stage.damage_buffer_committed), .release);
        try waitForWayringCommand(self.command_fd);
        try expectClientRoundtrip(display);
        if (self.frame_done_count.load(.acquire) != 4) return error.MissingFrameDone;
        self.stage.store(@intFromEnum(Stage.damage_buffer_done), .release);
        try waitForWayringCommand(self.command_fd);

        try self.requestFrame(surface);
        try writeWayringScalePixels(scale_shm_fd, .{
            0x0011_0000, 0x0022_0000, 0x0033_0000, 0x0044_0000,
            0x0055_0000, 0x0066_0000, 0x0077_0000, 0x0088_0000,
        });
        surface.offset(-3, 2);
        surface.attach(scale_buffer, 0, 0);
        surface.commit();
        try expectClientRoundtrip(display);
        if (self.release_count.load(.acquire) != 5) return error.UnexpectedBufferRelease;
        if (self.frame_done_count.load(.acquire) != 4) return error.UnexpectedFrameDone;
        self.stage.store(@intFromEnum(Stage.offset_attachment_released), .release);
        try waitForWayringCommand(self.command_fd);
        try expectClientRoundtrip(display);
        if (self.frame_done_count.load(.acquire) != 5) return error.MissingFrameDone;
        self.stage.store(@intFromEnum(Stage.offset_attachment_done), .release);
        try waitForWayringCommand(self.command_fd);

        try self.requestFrame(surface);
        surface.offset(7, -5);
        surface.commit();
        try expectClientRoundtrip(display);
        if (self.release_count.load(.acquire) != 5) return error.UnexpectedBufferRelease;
        if (self.frame_done_count.load(.acquire) != 5) return error.UnexpectedFrameDone;
        self.stage.store(@intFromEnum(Stage.offset_only_committed), .release);
        try waitForWayringCommand(self.command_fd);
        try expectClientRoundtrip(display);
        if (self.frame_done_count.load(.acquire) != 6) return error.MissingFrameDone;
        self.stage.store(@intFromEnum(Stage.offset_only_done), .release);
        try waitForWayringCommand(self.command_fd);

        try self.requestFrame(surface);
        surface.setBufferScale(1);
        surface.attach(null, 0, 0);
        surface.commit();
        try expectClientRoundtrip(display);
        if (self.release_count.load(.acquire) != 5) return error.UnexpectedBufferRelease;
        if (self.frame_done_count.load(.acquire) != 6) return error.UnexpectedFrameDone;
        self.stage.store(@intFromEnum(Stage.unmapped), .release);
        try waitForWayringCommand(self.command_fd);
        try expectClientRoundtrip(display);
        if (self.frame_done_count.load(.acquire) != 6) return error.UnexpectedFrameDone;
        if (self.output_enter_count.load(.acquire) != 1 or
            self.output_leave_count.load(.acquire) != 1)
            return error.UnexpectedOutputMembership;
        self.stage.store(@intFromEnum(Stage.unmapped_no_done), .release);
        try waitForWayringCommand(self.command_fd);

        try self.commitBuffer(display, surface, buffer, shm_fd, .{ 0x00cc_ddee, 0x0001_0203 }, 6);
        self.stage.store(@intFromEnum(Stage.remapped_released), .release);
        try waitForWayringCommand(self.command_fd);
        try expectClientRoundtrip(display);
        if (self.frame_done_count.load(.acquire) != 7) return error.MissingFrameDone;
        if (self.output_enter_count.load(.acquire) != 2 or
            self.output_leave_count.load(.acquire) != 1)
            return error.UnexpectedOutputMembership;
        self.stage.store(@intFromEnum(Stage.remapped_done), .release);
        try waitForWayringCommand(self.command_fd);

        const replacement_surface = try compositor.createSurface();
        defer replacement_surface.destroy();
        const replacement_fractional_scale = try fractional_scale_manager.getFractionalScale(replacement_surface);
        defer replacement_fractional_scale.destroy();
        replacement_fractional_scale.setListener(*WayringHeadlessClient, fractionalScaleEvent, self);
        try expectClientRoundtrip(display);
        if (self.fractional_scale_count.load(.acquire) != 4 or
            self.fractional_scale.load(.acquire) != 240)
            return error.UnexpectedFractionalScale;
        self.stage.store(@intFromEnum(Stage.default_replaced), .release);
        try waitForWayringCommand(self.command_fd);

        try self.requestFrame(surface);
        surface.commit();
        try expectClientRoundtrip(display);
        if (self.frame_done_count.load(.acquire) != 7) return error.UnexpectedFrameDone;
        self.stage.store(@intFromEnum(Stage.outstanding_callback), .release);
        try waitForWayringCommand(self.command_fd);
    }

    fn requestFrame(
        self: *WayringHeadlessClient,
        surface: *wayland.client.wl.Surface,
    ) !void {
        const callback = try surface.frame();
        callback.setListener(*WayringHeadlessClient, frameEvent, self);
    }

    fn commitBuffer(
        self: *WayringHeadlessClient,
        display: *wayland.client.wl.Display,
        surface: *wayland.client.wl.Surface,
        buffer: *wayland.client.wl.Buffer,
        shm_fd: std.posix.fd_t,
        pixels: [2]u32,
        expected_releases: u8,
    ) !void {
        try writeWayringTestPixels(shm_fd, pixels);
        surface.attach(buffer, 0, 0);
        surface.damage(0, 0, 2, 1);
        surface.commit();
        try expectClientRoundtrip(display);
        if (self.release_count.load(.acquire) != expected_releases)
            return error.UnexpectedBufferRelease;
        // The release permits immediate source reuse. Poisoning the memfd
        // before notifying the test proves subsequent rendering is borrowed
        // from the published copy rather than client storage.
        try writeWayringTestPixels(shm_fd, .{ 0x00de_ad00, 0x00be_ef00 });
    }

    fn commitScaleBuffer(
        self: *WayringHeadlessClient,
        display: *wayland.client.wl.Display,
        surface: *wayland.client.wl.Surface,
        buffer: *wayland.client.wl.Buffer,
        shm_fd: std.posix.fd_t,
        expected_releases: u8,
    ) !void {
        try writeWayringScalePixels(shm_fd, .{
            0x0011_0000, 0x0022_0000, 0x0033_0000, 0x0044_0000,
            0x0055_0000, 0x0066_0000, 0x0077_0000, 0x0088_0000,
        });
        surface.attach(buffer, 0, 0);
        surface.damage(0, 0, 4, 2);
        surface.setBufferTransform(.normal);
        surface.commit();
        try expectClientRoundtrip(display);
        if (self.release_count.load(.acquire) != expected_releases)
            return error.UnexpectedBufferRelease;
        try writeWayringScalePixels(shm_fd, @splat(0x00de_ad00));
    }

    fn registryEvent(
        registry: *wayland.client.wl.Registry,
        event: wayland.client.wl.Registry.Event,
        self: *WayringHeadlessClient,
    ) void {
        switch (event) {
            .global => |global| {
                const interface = std.mem.span(global.interface);
                if (std.mem.eql(u8, interface, "zwp_text_input_manager_v3")) {
                    self.text_input_global_seen = true;
                    self.globals_exact = false;
                }
                if (std.mem.eql(u8, interface, "zwp_input_method_manager_v2")) {
                    self.input_method_global_seen = true;
                    self.globals_exact = false;
                }
                const index = self.global_count;
                self.global_count += 1;
                if (index >= expected_globals.len or
                    !std.mem.eql(u8, interface, expected_globals[index].name) or
                    global.version != expected_globals[index].version)
                    self.globals_exact = false;
                if (std.mem.eql(u8, interface, "wl_compositor") and self.compositor == null) {
                    self.compositor_version.store(global.version, .release);
                    self.compositor = registry.bind(
                        global.name,
                        wayland.client.wl.Compositor,
                        global.version,
                    ) catch null;
                } else if (std.mem.eql(u8, interface, "wl_shm") and self.shm == null) {
                    self.shm = registry.bind(
                        global.name,
                        wayland.client.wl.Shm,
                        global.version,
                    ) catch null;
                } else if (std.mem.eql(u8, interface, "wl_output")) {
                    self.output_globals += 1;
                    self.output_version = global.version;
                    if (self.output == null and global.version >= 4) {
                        self.output = registry.bind(
                            global.name,
                            wayland.client.wl.Output,
                            4,
                        ) catch null;
                        if (self.output) |output| {
                            output.setListener(*WayringHeadlessClient, outputEvent, self);
                        }
                    }
                } else if (std.mem.eql(u8, interface, "wp_viewporter") and self.viewporter == null) {
                    self.viewporter = registry.bind(
                        global.name,
                        wayland.client.wp.Viewporter,
                        1,
                    ) catch null;
                } else if (std.mem.eql(u8, interface, "wp_fractional_scale_manager_v1") and self.fractional_scale_manager == null) {
                    self.fractional_scale_manager = registry.bind(
                        global.name,
                        wayland.client.wp.FractionalScaleManagerV1,
                        1,
                    ) catch null;
                } else if (std.mem.eql(u8, interface, "wp_cursor_shape_manager_v1") and self.cursor_shape_manager == null) {
                    self.cursor_shape_manager = registry.bind(
                        global.name,
                        wayland.client.wp.CursorShapeManagerV1,
                        global.version,
                    ) catch null;
                }
            },
            .global_remove => {},
        }
    }

    fn bufferEvent(
        _: *wayland.client.wl.Buffer,
        event: wayland.client.wl.Buffer.Event,
        self: *WayringHeadlessClient,
    ) void {
        switch (event) {
            .release => _ = self.release_count.fetchAdd(1, .acq_rel),
        }
    }

    fn surfaceEvent(
        _: *wayland.client.wl.Surface,
        event: wayland.client.wl.Surface.Event,
        self: *WayringHeadlessClient,
    ) void {
        switch (event) {
            .preferred_buffer_scale => |preferred| {
                self.preferred_buffer_scale.store(preferred.factor, .monotonic);
                _ = self.preferred_buffer_scale_count.fetchAdd(1, .release);
            },
            .preferred_buffer_transform => |preferred| {
                self.preferred_buffer_transform.store(@intFromEnum(preferred.transform), .monotonic);
                _ = self.preferred_buffer_transform_count.fetchAdd(1, .release);
            },
            .enter => _ = self.output_enter_count.fetchAdd(1, .acq_rel),
            .leave => _ = self.output_leave_count.fetchAdd(1, .acq_rel),
        }
    }

    fn outputEvent(
        _: *wayland.client.wl.Output,
        event: wayland.client.wl.Output.Event,
        self: *WayringHeadlessClient,
    ) void {
        switch (event) {
            .geometry, .description => {},
            .mode => |mode| if (mode.flags.current) {
                self.output_mode_width = mode.width;
                self.output_mode_height = mode.height;
            },
            .scale => |scale| self.output_scale = scale.factor,
            .name => |name| {
                self.output_name_valid = std.mem.eql(u8, std.mem.span(name.name), "HEADLESS-1");
            },
            .done => self.output_done_count += 1,
        }
    }

    fn fractionalScaleEvent(
        _: *wayland.client.wp.FractionalScaleV1,
        event: wayland.client.wp.FractionalScaleV1.Event,
        self: *WayringHeadlessClient,
    ) void {
        switch (event) {
            .preferred_scale => |preferred| {
                self.fractional_scale.store(preferred.scale, .monotonic);
                _ = self.fractional_scale_count.fetchAdd(1, .release);
            },
        }
    }

    fn frameEvent(
        callback: *wayland.client.wl.Callback,
        event: wayland.client.wl.Callback.Event,
        self: *WayringHeadlessClient,
    ) void {
        switch (event) {
            .done => |done| {
                self.last_frame_timestamp_ms.store(done.callback_data, .release);
                _ = self.frame_done_count.fetchAdd(1, .acq_rel);
                callback.destroy();
            },
        }
    }

    fn closeWake(self: *WayringHeadlessClient, shutdown_requested: bool) void {
        const fd = self.wake_fd.swap(if (shutdown_requested) -2 else -1, .acq_rel);
        if (fd < 0) return;
        if (shutdown_requested) _ = std.os.linux.shutdown(fd, std.os.linux.SHUT.RDWR);
        _ = std.os.linux.close(fd);
    }

    fn shutdown(self: *WayringHeadlessClient) void {
        signalWayringCommand(self.command_fd) catch {};
        self.closeWake(true);
    }
};

// Staged real libwayland-client peer for the subsurface E2E below. Listener-
// owned values are published by the stage release, and the server thread reads
// them only after the matching acquire.
const WayringSubsurfaceClient = struct {
    const Stage = enum(u8) {
        starting,
        queued,
        applied,
        first_done,
        child_desync_locked,
        ancestor_unlocked,
        second_done,
        occluded,
        occluded_no_done,
        restacked,
        restacked_done,
        hidden,
        hidden_no_done,
        remapped,
        remapped_done,
        off_output,
        off_output_no_done,
        on_output,
        on_output_done,
        frame_pending,
        frame_not_done,
        frame_done,
        multi_pending,
        multi_first_done,
        multi_second_unchanged,
        queued_detached,
        detached_no_done,
        recreated,
        parent_destroyed,
        disconnected,
        failed,
    };

    runtime_directory: []const u8,
    display_name: []const u8,
    command_fd: std.posix.fd_t,
    stage: std.atomic.Value(u8) = .init(@intFromEnum(Stage.starting)),
    wake_fd: std.atomic.Value(i32) = .init(-1),
    failure: ?anyerror = null,
    compositor: ?*wayland.client.wl.Compositor = null,
    shm: ?*wayland.client.wl.Shm = null,
    subcompositor: ?*wayland.client.wl.Subcompositor = null,
    compositor_globals: u8 = 0,
    subcompositor_globals: u8 = 0,
    output_globals: u8 = 0,
    compositor_version: u32 = 0,
    subcompositor_version: u32 = 0,
    output_version: u32 = 0,
    release_count: std.atomic.Value(u8) = .init(0),
    done_count: std.atomic.Value(u8) = .init(0),
    last_done_timestamp_ms: std.atomic.Value(u32) = .init(0),

    fn run(self: *WayringSubsurfaceClient) void {
        self.runFallible() catch |err| {
            self.failure = err;
            self.stage.store(@intFromEnum(Stage.failed), .release);
            return;
        };
        self.stage.store(@intFromEnum(Stage.disconnected), .release);
    }

    fn runFallible(self: *WayringSubsurfaceClient) !void {
        const path = try std.fmt.allocPrintSentinel(std.heap.page_allocator, "{s}/{s}", .{
            self.runtime_directory, self.display_name,
        }, 0);
        defer std.heap.page_allocator.free(path);
        const fd = try connectWayringTestSocket(path);
        var fd_owned = true;
        defer if (fd_owned) {
            _ = std.os.linux.close(fd);
        };
        const raw_wake_fd = std.os.linux.dup(fd);
        if (std.os.linux.errno(raw_wake_fd) != .SUCCESS) return error.WakeFdFailed;
        const wake_fd: i32 = @intCast(raw_wake_fd);
        if (self.wake_fd.cmpxchgStrong(-1, wake_fd, .acq_rel, .acquire)) |_| {
            _ = std.os.linux.close(wake_fd);
            return error.ClientShutdown;
        }
        defer self.closeWake(false);
        const display = try wayland.client.wl.Display.connectToFd(fd);
        fd_owned = false;
        defer display.disconnect();
        const registry = try display.getRegistry();
        defer registry.destroy();
        registry.setListener(*WayringSubsurfaceClient, registryEvent, self);
        try expectClientRoundtrip(display);
        if (self.compositor_globals != 1 or self.subcompositor_globals != 1 or
            self.compositor_version != 6 or self.subcompositor_version != 1)
            return error.UnexpectedGlobalCount;
        const compositor = self.compositor orelse return error.CompositorMissing;
        const shm = self.shm orelse return error.ShmMissing;
        const manager = self.subcompositor orelse return error.SubcompositorMissing;
        var manager_live = true;
        defer if (manager_live) manager.destroy();

        const root = try compositor.createSurface();
        var root_live = true;
        defer if (root_live) root.destroy();
        const parent = try compositor.createSurface();
        var parent_live = true;
        defer if (parent_live) parent.destroy();
        const child = try compositor.createSurface();
        var child_live = true;
        defer if (child_live) child.destroy();
        const sibling = try compositor.createSurface();
        var sibling_live = true;
        defer if (sibling_live) sibling.destroy();
        const parent_role = try manager.getSubsurface(parent, root);
        var parent_role_live = true;
        defer if (parent_role_live) parent_role.destroy();
        var child_role = try manager.getSubsurface(child, parent);
        var child_role_live = true;
        defer if (child_role_live) child_role.destroy();
        const sibling_role = try manager.getSubsurface(sibling, root);
        var sibling_role_live = true;
        defer if (sibling_role_live) sibling_role.destroy();
        parent_role.setPosition(1, 0);
        child_role.setPosition(1, 0);
        sibling_role.setPosition(1, 0);

        const shm_fd = try std.posix.memfd_create("keywork-wayring-subsurface", std.os.linux.MFD.CLOEXEC);
        defer _ = std.os.linux.close(shm_fd);
        const pixels = [_]u32{
            0x00ff_0000,
            0x00ff_0000,
            0x0000_ff00,
            0x0000_00ff,
            0x0000_ffff,
            0x00ff_ff00,
        };
        if (std.os.linux.errno(std.os.linux.ftruncate(shm_fd, @sizeOf(@TypeOf(pixels)))) != .SUCCESS)
            return error.ShmResizeFailed;
        if (std.c.pwrite(shm_fd, @ptrCast(&pixels), @sizeOf(@TypeOf(pixels)), 0) != @sizeOf(@TypeOf(pixels)))
            return error.ShmWriteFailed;
        const pool = try shm.createPool(shm_fd, @sizeOf(@TypeOf(pixels)));
        defer pool.destroy();
        const buffers = [_]*wayland.client.wl.Buffer{
            try pool.createBuffer(0, 2, 1, 2 * @sizeOf(u32), .xrgb8888),
            try pool.createBuffer(2 * @sizeOf(u32), 1, 1, @sizeOf(u32), .xrgb8888),
            try pool.createBuffer(3 * @sizeOf(u32), 1, 1, @sizeOf(u32), .xrgb8888),
            try pool.createBuffer(4 * @sizeOf(u32), 1, 1, @sizeOf(u32), .xrgb8888),
            try pool.createBuffer(5 * @sizeOf(u32), 1, 1, @sizeOf(u32), .xrgb8888),
        };
        for (buffers) |buffer| buffer.setListener(*WayringSubsurfaceClient, bufferEvent, self);
        defer for (buffers) |buffer| buffer.destroy();

        root.attach(buffers[0], 0, 0);
        child.attach(buffers[2], 0, 0);
        try self.requestFrame(child);
        child.commit();
        parent.attach(buffers[1], 0, 0);
        parent.commit(); // claims the first child cached state
        parent.commit(); // cannot claim the already-owned child tail twice
        child.attach(buffers[3], 0, 0);
        try self.requestFrame(child);
        child.commit();
        sibling.attach(buffers[4], 0, 0);
        sibling.commit();
        try expectClientRoundtrip(display);
        if (self.release_count.load(.acquire) != 4 or self.done_count.load(.acquire) != 0)
            return error.UnexpectedQueuedState;
        try self.pause(.queued);

        root.commit();
        try expectClientRoundtrip(display);
        if (self.release_count.load(.acquire) != 5 or self.done_count.load(.acquire) != 0)
            return error.UnexpectedAppliedState;
        try self.pause(.applied);
        try expectClientRoundtrip(display);
        try self.expectDone(1);
        try self.pause(.first_done);

        child_role.setDesync();
        try expectClientRoundtrip(display);
        try self.expectDone(1);
        try self.pause(.child_desync_locked);

        parent_role.setDesync();
        try expectClientRoundtrip(display);
        try self.expectDone(1);
        try self.pause(.ancestor_unlocked);
        try expectClientRoundtrip(display);
        try self.expectDone(2);
        try self.pause(.second_done);

        child_role.setPosition(0, 0);
        parent.commit();
        try self.requestFrame(child);
        child.commit();
        try expectClientRoundtrip(display);
        try self.expectDone(2);
        try self.pause(.occluded);
        try expectClientRoundtrip(display);
        try self.expectDone(2);
        try self.pause(.occluded_no_done);

        sibling_role.placeBelow(root);
        parent_role.placeAbove(sibling);
        parent_role.placeAbove(root);
        root.commit();
        try expectClientRoundtrip(display);
        try self.expectDone(2);
        try self.pause(.restacked);
        try expectClientRoundtrip(display);
        try self.expectDone(3);
        try self.pause(.restacked_done);

        try self.requestFrame(child);
        child.commit();
        parent.attach(null, 0, 0);
        parent.commit();
        try expectClientRoundtrip(display);
        try self.expectDone(3);
        try self.pause(.hidden);
        try expectClientRoundtrip(display);
        try self.expectDone(3);
        try self.pause(.hidden_no_done);

        parent.attach(buffers[1], 0, 0);
        parent.commit();
        try expectClientRoundtrip(display);
        if (self.release_count.load(.acquire) != 6) return error.UnexpectedBufferRelease;
        try self.expectDone(3);
        try self.pause(.remapped);
        try expectClientRoundtrip(display);
        try self.expectDone(4);
        try self.pause(.remapped_done);

        child_role.setPosition(20, 0);
        parent.commit();
        try self.requestFrame(child);
        child.commit();
        try expectClientRoundtrip(display);
        try self.expectDone(4);
        try self.pause(.off_output);
        try expectClientRoundtrip(display);
        try self.expectDone(4);
        try self.pause(.off_output_no_done);

        child_role.setPosition(-1, 0);
        parent.commit();
        try expectClientRoundtrip(display);
        try self.expectDone(4);
        try self.pause(.on_output);
        try expectClientRoundtrip(display);
        try self.expectDone(5);
        try self.pause(.on_output_done);

        try self.requestFrame(child);
        child.commit();
        try expectClientRoundtrip(display);
        try self.expectDone(5);
        try self.pause(.frame_pending);
        try expectClientRoundtrip(display);
        try self.expectDone(5);
        try self.pause(.frame_not_done);
        try expectClientRoundtrip(display);
        try self.expectDone(6);
        try self.pause(.frame_done);

        try self.requestFrame(child);
        child.commit();
        try expectClientRoundtrip(display);
        try self.expectDone(6);
        try self.pause(.multi_pending);
        try expectClientRoundtrip(display);
        try self.expectDone(7);
        try self.pause(.multi_first_done);
        try expectClientRoundtrip(display);
        try self.expectDone(7);
        try self.pause(.multi_second_unchanged);

        child_role.setSync();
        try self.requestFrame(child);
        child.commit();
        child_role.destroy();
        child_role_live = false;
        try expectClientRoundtrip(display);
        try self.expectDone(7);
        try self.pause(.queued_detached);
        try expectClientRoundtrip(display);
        try self.expectDone(7);
        try self.pause(.detached_no_done);

        child_role = try manager.getSubsurface(child, sibling);
        child_role_live = true;
        child_role.setPosition(-1, 0);
        sibling.commit();
        root.commit();
        try expectClientRoundtrip(display);
        try self.expectDone(7);
        try self.pause(.recreated);

        manager.destroy();
        manager_live = false;
        sibling_role.destroy();
        sibling_role_live = false;
        sibling.destroy();
        sibling_live = false;
        try expectClientRoundtrip(display);
        try self.pause(.parent_destroyed);

        // With its parent gone, the role is inert until destroyed. The direct
        // scanner fault matrix owns deterministic OOM and partial-construction
        // injection; this real fixture owns queued teardown and disconnect.
        child_role.setPosition(9, -3);
        child_role.destroy();
        child_role_live = false;
        child.destroy();
        child_live = false;
        parent_role.destroy();
        parent_role_live = false;
        parent.destroy();
        parent_live = false;
        root.destroy();
        root_live = false;
        try expectClientRoundtrip(display);
    }

    fn pause(self: *WayringSubsurfaceClient, stage: Stage) !void {
        self.stage.store(@intFromEnum(stage), .release);
        try waitForWayringCommand(self.command_fd);
    }

    fn expectDone(self: *WayringSubsurfaceClient, expected: u8) !void {
        if (self.done_count.load(.acquire) != expected) return error.UnexpectedFrameDone;
    }

    fn requestFrame(self: *WayringSubsurfaceClient, surface: *wayland.client.wl.Surface) !void {
        const callback = try surface.frame();
        callback.setListener(*WayringSubsurfaceClient, frameEvent, self);
    }

    fn registryEvent(registry: *wayland.client.wl.Registry, event: wayland.client.wl.Registry.Event, self: *WayringSubsurfaceClient) void {
        switch (event) {
            .global => |global| {
                const interface = std.mem.span(global.interface);
                if (std.mem.eql(u8, interface, "wl_compositor")) {
                    self.compositor_globals += 1;
                    self.compositor_version = global.version;
                    if (self.compositor == null and global.version >= 6)
                        self.compositor = registry.bind(global.name, wayland.client.wl.Compositor, 6) catch null;
                } else if (std.mem.eql(u8, interface, "wl_shm") and self.shm == null) {
                    self.shm = registry.bind(global.name, wayland.client.wl.Shm, 1) catch null;
                } else if (std.mem.eql(u8, interface, "wl_subcompositor")) {
                    self.subcompositor_globals += 1;
                    self.subcompositor_version = global.version;
                    if (self.subcompositor == null and global.version >= 1)
                        self.subcompositor = registry.bind(global.name, wayland.client.wl.Subcompositor, 1) catch null;
                } else if (std.mem.eql(u8, interface, "wl_output")) {
                    self.output_globals += 1;
                    self.output_version = global.version;
                }
            },
            .global_remove => {},
        }
    }

    fn bufferEvent(_: *wayland.client.wl.Buffer, event: wayland.client.wl.Buffer.Event, self: *WayringSubsurfaceClient) void {
        switch (event) {
            .release => _ = self.release_count.fetchAdd(1, .acq_rel),
        }
    }

    fn frameEvent(callback: *wayland.client.wl.Callback, event: wayland.client.wl.Callback.Event, self: *WayringSubsurfaceClient) void {
        switch (event) {
            .done => |done| {
                self.last_done_timestamp_ms.store(done.callback_data, .release);
                _ = self.done_count.fetchAdd(1, .acq_rel);
                callback.destroy();
            },
        }
    }

    fn closeWake(self: *WayringSubsurfaceClient, shutdown_requested: bool) void {
        const fd = self.wake_fd.swap(if (shutdown_requested) -2 else -1, .acq_rel);
        if (fd < 0) return;
        if (shutdown_requested) _ = std.os.linux.shutdown(fd, std.os.linux.SHUT.RDWR);
        _ = std.os.linux.close(fd);
    }

    fn shutdown(self: *WayringSubsurfaceClient) void {
        signalWayringCommand(self.command_fd) catch {};
        self.closeWake(true);
    }
};

// Compact production-path XDG peer: all objects are obtained from the real
// registry and all configure state is delivered by libwayland-client.
const WayringXdgClient = struct {
    const client_wl = wayland.client.wl;
    const client_ext = wayland.client.ext;
    const client_xdg = wayland.client.xdg;
    const client_zxdg = wayland.client.zxdg;
    const client_zwp = wayland.client.zwp;
    const client_zwlr = wayland.client.zwlr;
    const Stage = enum(u8) {
        starting,
        initial_commit_ready,
        configured,
        mapped,
        map_settled,
        token_ready,
        activated,
        source_left,
        invalids_checked,
        mode_changed,
        frame_done,
        registry_ready,
        manager_added,
        manager_removed,
        disconnected,
        failed,
    };
    const Offense = enum { duplicate_decoration, invalid_mode, activation_already_used };
    const ActivationRole = enum { source, target };
    const ActivationExchange = struct {
        token: [XdgActivation.token_character_count:0]u8 = @splat(0),
        unauthorized_token: [XdgActivation.token_character_count:0]u8 = @splat(0),
    };

    runtime_directory: []const u8,
    display_name: []const u8,
    command_fd: std.posix.fd_t,
    registry_only: bool = false,
    registry_watch_data_device: bool = false,
    registry_watch_primary_selection: bool = false,
    registry_watch_input_method: bool = false,
    registry_watch_virtual_keyboard: bool = false,
    expect_text_input: bool = false,
    expect_data_control: bool = false,
    expect_virtual_keyboard: bool = false,
    expect_layer_shell: bool = false,
    expect_idle_notify: bool = false,
    expect_session_lock: bool = false,
    expect_workspace: bool = false,
    guessed_data_control_name: ?u32 = null,
    guessed_virtual_keyboard_name: ?u32 = null,
    guessed_data_control_bind_issued: bool = false,
    guessed_input_method_name: ?u32 = null,
    guessed_input_method_bind_issued: bool = false,
    expect_input_method: bool = false,
    guessed_virtual_keyboard_bind_issued: bool = false,
    guessed_session_lock_name: ?u32 = null,
    guessed_session_lock_bind_issued: bool = false,
    guessed_workspace_name: ?u32 = null,
    guessed_workspace_bind_issued: bool = false,
    offense: ?Offense = null,
    activation_role: ?ActivationRole = null,
    activation_exchange: ?*ActivationExchange = null,
    stage: std.atomic.Value(u8) = .init(@intFromEnum(Stage.starting)),
    wake_fd: std.atomic.Value(i32) = .init(-1),
    failure: ?anyerror = null,
    compositor: ?*client_wl.Compositor = null,
    shm: ?*client_wl.Shm = null,
    output: ?*client_wl.Output = null,
    seat: ?*client_wl.Seat = null,
    wm_base: ?*client_xdg.WmBase = null,
    decoration_manager: ?*client_zxdg.DecorationManagerV1 = null,
    activation: ?*client_xdg.ActivationV1 = null,
    data_control_manager: ?*client_ext.DataControlManagerV1 = null,
    layer_shell: ?*client_zwlr.LayerShellV1 = null,
    global_count: usize = 0,
    globals_exact: bool = true,
    data_device_manager_count: usize = 0,
    data_device_manager_version: u32 = 0,
    data_device_manager_name: u32 = 0,
    data_device_manager_removed: bool = false,
    primary_selection_manager_count: usize = 0,
    primary_selection_manager_version: u32 = 0,
    primary_selection_manager_name: u32 = 0,
    primary_selection_manager_removed: bool = false,
    text_input_manager_count: usize = 0,
    text_input_manager_version: u32 = 0,
    data_control_manager_count: usize = 0,
    data_control_manager_version: u32 = 0,
    data_control_manager_name: u32 = 0,
    data_control_manager_removed: bool = false,
    generated_input_method_seen: bool = false,
    input_method_manager_count: usize = 0,
    input_method_manager_version: u32 = 0,
    input_method_manager_name: u32 = 0,
    input_method_manager_removed: bool = false,
    generated_virtual_keyboard_seen: bool = false,
    virtual_keyboard_manager_count: usize = 0,
    virtual_keyboard_manager_version: u32 = 0,
    virtual_keyboard_manager_name: u32 = 0,
    virtual_keyboard_manager_removed: bool = false,
    layer_shell_count: usize = 0,
    layer_shell_version: u32 = 0,
    layer_shell_name: u32 = 0,
    layer_shell_removed: bool = false,
    idle_notifier_count: usize = 0,
    idle_notifier_version: u32 = 0,
    idle_notifier_name: u32 = 0,
    idle_notifier_removed: bool = false,
    session_lock_manager_count: usize = 0,
    session_lock_manager_version: u32 = 0,
    session_lock_manager_name: u32 = 0,
    session_lock_manager_removed: bool = false,
    workspace_manager_count: usize = 0,
    workspace_manager_version: u32 = 0,
    workspace_manager_name: u32 = 0,
    configure_serial: u32 = 0,
    configure_count: u8 = 0,
    toplevel_configure_count: u8 = 0,
    capabilities_count: u8 = 0,
    decoration_configure_count: u8 = 0,
    decoration_mode: u32 = 0,
    event_sequence: u8 = 0,
    decoration_event_sequence: u8 = 0,
    toplevel_event_sequence: u8 = 0,
    surface_event_sequence: u8 = 0,
    initial_configure_serial: u32 = 0,
    later_configure_serial: u32 = 0,
    output_enter_count: std.atomic.Value(u8) = .init(0),
    frame_count: std.atomic.Value(u8) = .init(0),
    pointer_button_serial: u32 = 0,
    surface_object_id: u32 = 0,
    keyboard_enter_count: u8 = 0,
    keyboard_leave_count: u8 = 0,
    keyboard_enter_surface: u32 = 0,
    keyboard_leave_surface: u32 = 0,
    keyboard_enter_serial: u32 = 0,
    keyboard_leave_serial: u32 = 0,
    pending_activated: bool = false,
    activated_configure_serial: u32 = 0,
    activated_toplevel_sequence: u8 = 0,
    activated_surface_sequence: u8 = 0,
    activated_ack_sequence: u8 = 0,

    const ExpectedGlobal = WayringProfile.Entry;
    const expected_globals = WayringProfile.entries;

    fn expectedGlobalCount(self: *const @This()) usize {
        return expected_globals.len - @intFromBool(!self.expect_text_input) -
            @intFromBool(!self.expect_data_control) -
            @intFromBool(!self.expect_input_method) -
            @intFromBool(!self.expect_virtual_keyboard) -
            @intFromBool(!self.expect_layer_shell) -
            @intFromBool(!self.expect_idle_notify) -
            @intFromBool(!self.expect_session_lock) -
            @intFromBool(!self.expect_workspace);
    }

    fn expectedGlobal(self: *const @This(), visible_index: usize) ?ExpectedGlobal {
        var index: usize = 0;
        for (expected_globals) |global| {
            const present = if (std.mem.eql(u8, global.interface, "zwp_text_input_manager_v3"))
                self.expect_text_input
            else if (std.mem.eql(u8, global.interface, "ext_data_control_manager_v1"))
                self.expect_data_control
            else if (std.mem.eql(u8, global.interface, "zwp_input_method_manager_v2"))
                self.expect_input_method
            else if (std.mem.eql(u8, global.interface, "zwp_virtual_keyboard_manager_v1"))
                self.expect_virtual_keyboard
            else if (std.mem.eql(u8, global.interface, "zwlr_layer_shell_v1"))
                self.expect_layer_shell
            else if (std.mem.eql(u8, global.interface, "ext_idle_notifier_v1"))
                self.expect_idle_notify
            else if (std.mem.eql(u8, global.interface, "ext_session_lock_manager_v1"))
                self.expect_session_lock
            else if (std.mem.eql(u8, global.interface, "ext_workspace_manager_v1"))
                self.expect_workspace
            else
                true;
            if (!present) continue;
            if (index == visible_index) return global;
            index += 1;
        }
        return null;
    }

    fn run(self: *@This()) void {
        self.runFallible() catch |err| {
            self.failure = err;
            self.stage.store(@intFromEnum(Stage.failed), .release);
            return;
        };
        self.stage.store(@intFromEnum(Stage.disconnected), .release);
    }

    fn runFallible(self: *@This()) !void {
        const path = try std.fmt.allocPrintSentinel(std.heap.page_allocator, "{s}/{s}", .{ self.runtime_directory, self.display_name }, 0);
        defer std.heap.page_allocator.free(path);
        const fd = try connectWayringTestSocket(path);
        var fd_owned = true;
        defer if (fd_owned) {
            _ = std.os.linux.close(fd);
        };
        const raw_wake_fd = std.os.linux.dup(fd);
        if (std.os.linux.errno(raw_wake_fd) != .SUCCESS) return error.WakeFdFailed;
        const wake_fd: i32 = @intCast(raw_wake_fd);
        if (self.wake_fd.cmpxchgStrong(-1, wake_fd, .acq_rel, .acquire)) |_| {
            _ = std.os.linux.close(wake_fd);
            return error.ClientShutdown;
        }
        defer self.closeWake(false);

        const display = try client_wl.Display.connectToFd(fd);
        fd_owned = false;
        defer display.disconnect();
        const registry = try display.getRegistry();
        var registry_live = true;
        defer if (registry_live) registry.destroy();
        registry.setListener(*@This(), registryEvent, self);
        try expectClientRoundtrip(display);
        if (!self.globals_exact or self.global_count != self.expectedGlobalCount()) return error.UnexpectedRegistrySnapshot;
        // A bind emitted from the registry callback follows the first sync.
        // Materialize it before a test is allowed to unpublish the global.
        if (self.data_control_manager != null) try expectClientRoundtrip(display);
        const compositor = self.compositor orelse return error.CompositorMissing;
        const shm = self.shm orelse return error.ShmMissing;
        const output = self.output orelse return error.OutputMissing;
        var output_live = true;
        defer if (output_live) output.release();
        const seat = self.seat orelse return error.SeatMissing;
        var seat_live = true;
        defer if (seat_live) seat.release();
        const wm_base = self.wm_base orelse return error.XdgWmBaseMissing;
        var wm_base_live = true;
        defer if (wm_base_live) wm_base.destroy();
        wm_base.setListener(*@This(), wmBaseEvent, self);
        const decoration_manager = self.decoration_manager orelse return error.DecorationManagerMissing;
        var decoration_manager_live = true;
        defer if (decoration_manager_live) decoration_manager.destroy();
        const activation = self.activation orelse return error.ActivationMissing;
        var activation_live = true;
        defer if (activation_live) activation.destroy();
        defer if (self.data_control_manager) |manager| manager.destroy();
        defer if (self.layer_shell) |manager| manager.destroy();
        if (self.registry_only) {
            try self.pause(.registry_ready);
            if (self.registry_watch_virtual_keyboard) {
                try expectClientRoundtrip(display);
                if (!self.globals_exact or self.global_count != self.expectedGlobalCount() or
                    self.virtual_keyboard_manager_count != 1 or !self.generated_virtual_keyboard_seen)
                    return error.VirtualKeyboardGlobalMismatch;
                // The layer-shell bind is emitted by the registry callback
                // during the preceding sync. Materialize it before the test
                // is allowed to withdraw the dynamically published global.
                if (self.layer_shell != null) try expectClientRoundtrip(display);
                try self.pause(.manager_added);
            }
            if (self.guessed_data_control_name) |name| {
                // Materialize any publication that occurred while paused and
                // prove the restricted global remained absent before trying
                // to bypass registry visibility with its guessed name.
                try expectClientRoundtrip(display);
                if (!self.globals_exact or self.global_count != self.expectedGlobalCount() or
                    self.data_control_manager_count != 0 or self.data_control_manager != null)
                    return error.RestrictedGlobalAdvertised;
                try self.pause(.manager_added);
                // Deliberately bypass registry visibility. The server must
                // terminalize this connection rather than materialize a
                // restricted manager for a derived transport.
                self.data_control_manager = try registry.bind(name, client_ext.DataControlManagerV1, 1);
                self.guessed_data_control_bind_issued = true;
                expectClientRoundtrip(display) catch return;
                return error.RestrictedGlobalBindAccepted;
            }
            if (self.guessed_input_method_name) |name| {
                try expectClientRoundtrip(display);
                if (!self.globals_exact or self.global_count != self.expectedGlobalCount() or
                    self.input_method_manager_count != 0)
                    return error.RestrictedGlobalAdvertised;
                try self.pause(.manager_added);
                _ = try registry.bind(name, client_zwp.InputMethodManagerV2, 1);
                self.guessed_input_method_bind_issued = true;
                expectClientRoundtrip(display) catch return;
                return error.RestrictedGlobalBindAccepted;
            }
            if (self.guessed_virtual_keyboard_name) |name| {
                try expectClientRoundtrip(display);
                if (!self.globals_exact or self.global_count != self.expectedGlobalCount() or
                    self.virtual_keyboard_manager_count != 0)
                    return error.RestrictedGlobalAdvertised;
                try self.pause(.manager_added);
                _ = try registry.bind(name, client_zwp.VirtualKeyboardManagerV1, 1);
                self.guessed_virtual_keyboard_bind_issued = true;
                expectClientRoundtrip(display) catch return;
                return error.RestrictedGlobalBindAccepted;
            }
            if (self.guessed_session_lock_name) |name| {
                try expectClientRoundtrip(display);
                if (!self.globals_exact or self.global_count != self.expectedGlobalCount() or
                    self.session_lock_manager_count != 0)
                    return error.RestrictedGlobalAdvertised;
                try self.pause(.manager_added);
                _ = try registry.bind(name, client_ext.SessionLockManagerV1, 1);
                self.guessed_session_lock_bind_issued = true;
                expectClientRoundtrip(display) catch return;
                return error.RestrictedGlobalBindAccepted;
            }
            if (self.guessed_workspace_name) |name| {
                try expectClientRoundtrip(display);
                if (!self.globals_exact or self.global_count != self.expectedGlobalCount() or
                    self.workspace_manager_count != 0)
                    return error.RestrictedGlobalAdvertised;
                try self.pause(.manager_added);
                _ = try registry.bind(name, client_ext.WorkspaceManagerV1, 1);
                self.guessed_workspace_bind_issued = true;
                expectClientRoundtrip(display) catch return;
                return error.RestrictedGlobalBindAccepted;
            }
            if (self.registry_watch_data_device) {
                try expectClientRoundtrip(display);
                if (!self.data_device_manager_removed) return error.DataDeviceManagerRemovalMissing;
                if (self.data_control_manager) |manager| {
                    manager.destroy();
                    self.data_control_manager = null;
                }
                try self.pause(.manager_removed);
            } else if (self.registry_watch_primary_selection or self.registry_watch_input_method) {
                try expectClientRoundtrip(display);
                if (self.registry_watch_primary_selection and !self.primary_selection_manager_removed)
                    return error.PrimarySelectionManagerRemovalMissing;
                if (self.registry_watch_input_method and !self.input_method_manager_removed)
                    return error.InputMethodManagerRemovalMissing;
                try self.pause(.manager_removed);
            }
            activation.destroy();
            activation_live = false;
            decoration_manager.destroy();
            decoration_manager_live = false;
            wm_base.destroy();
            wm_base_live = false;
            seat.release();
            seat_live = false;
            output.release();
            output_live = false;
            registry.destroy();
            registry_live = false;
            // Do not require a final sync after globals have been withdrawn:
            // disconnect is the authoritative cleanup path, and a concurrent
            // denied peer may already have terminalized its own transport.
            return;
        }

        const pointer: ?*client_wl.Pointer = if (self.activation_role != null) try seat.getPointer() else null;
        defer if (pointer) |value| value.release();
        if (pointer) |value| value.setListener(*@This(), pointerEvent, self);
        const keyboard: ?*client_wl.Keyboard = if (self.activation_role != null) try seat.getKeyboard() else null;
        defer if (keyboard) |value| value.release();
        if (keyboard) |value| value.setListener(*@This(), keyboardEvent, self);

        const surface = try compositor.createSurface();
        self.surface_object_id = surface.getId();
        var surface_live = true;
        defer if (surface_live) surface.destroy();
        surface.setListener(*@This(), surfaceEvent, self);
        const xdg_surface = try wm_base.getXdgSurface(surface);
        var xdg_surface_live = true;
        defer if (xdg_surface_live) xdg_surface.destroy();
        xdg_surface.setListener(*@This(), xdgSurfaceEvent, self);
        const toplevel = try xdg_surface.getToplevel();
        var toplevel_live = true;
        defer if (toplevel_live) toplevel.destroy();
        toplevel.setListener(*@This(), toplevelEvent, self);
        const decoration = try decoration_manager.getToplevelDecoration(toplevel);
        var decoration_live = true;
        defer if (decoration_live) decoration.destroy();
        if (self.offense) |offense| {
            switch (offense) {
                .duplicate_decoration => _ = try decoration_manager.getToplevelDecoration(toplevel),
                .invalid_mode => decoration.setMode(@enumFromInt(99)),
                .activation_already_used => {
                    const token = try activation.getActivationToken();
                    token.commit();
                    try expectClientRoundtrip(display);
                    token.setAppId("org.keywork.activation-offender");
                },
            }
            expectClientRoundtrip(display) catch return;
            return error.ExpectedProtocolFailure;
        }
        decoration.setListener(*@This(), decorationEvent, self);
        decoration.setMode(.server_side);
        if (self.activation_role) |role| toplevel.setAppId(switch (role) {
            .source => "org.keywork.activation-source",
            .target => "org.keywork.activation-target",
        });
        if (self.activation_role == .target) try self.pause(.initial_commit_ready);
        surface.commit();
        try expectClientRoundtrip(display);
        const initial_configure_valid = if (self.activation_role == null)
            self.configure_count == 1 and self.toplevel_configure_count == 1 and
                self.decoration_configure_count == 1
        else
            self.configure_count >= 1 and self.toplevel_configure_count >= 1 and
                self.decoration_configure_count >= 1;
        if (!initial_configure_valid or self.capabilities_count != 1 or
            self.decoration_mode != @as(u32, @intCast(@intFromEnum(client_zxdg.ToplevelDecorationV1.Mode.server_side))) or
            self.configure_serial == 0 or
            !(self.decoration_event_sequence < self.toplevel_event_sequence and
                self.toplevel_event_sequence < self.surface_event_sequence))
            return error.UnexpectedInitialConfigure;
        try self.pause(.configured);

        const shm_fd = try std.posix.memfd_create("keywork-wayring-xdg", std.os.linux.MFD.CLOEXEC);
        defer _ = std.os.linux.close(shm_fd);
        const pixel: u32 = 0x007a_a2f7;
        if (std.os.linux.errno(std.os.linux.ftruncate(shm_fd, @sizeOf(u32))) != .SUCCESS) return error.ShmResizeFailed;
        if (std.c.pwrite(shm_fd, @ptrCast(&pixel), @sizeOf(u32), 0) != @sizeOf(u32)) return error.ShmWriteFailed;
        const pool = try shm.createPool(shm_fd, @sizeOf(u32));
        var pool_live = true;
        defer if (pool_live) pool.destroy();
        const buffer = try pool.createBuffer(0, 1, 1, @sizeOf(u32), .xrgb8888);
        var buffer_live = true;
        defer if (buffer_live) buffer.destroy();
        const callback = try surface.frame();
        callback.setListener(*@This(), frameEvent, self);
        surface.attach(buffer, 0, 0);
        surface.damageBuffer(0, 0, 1, 1);
        surface.commit();
        try expectClientRoundtrip(display);
        try self.pause(.mapped);

        if (self.activation_role) |role| {
            const exchange = self.activation_exchange orelse return error.ActivationExchangeMissing;
            switch (role) {
                .source => {
                    try expectClientRoundtrip(display);
                    try self.pause(.map_settled);
                    try expectClientRoundtrip(display);
                    if (self.pointer_button_serial == 0) return error.PointerButtonSerialMissing;
                    try self.requestActivationToken(
                        display,
                        activation,
                        seat,
                        surface,
                        self.pointer_button_serial,
                        "org.keywork.activation-target",
                        &exchange.token,
                    );
                    try self.requestActivationToken(
                        display,
                        activation,
                        seat,
                        surface,
                        self.pointer_button_serial ^ 0x8000_0000,
                        "org.keywork.activation-unauthorized",
                        &exchange.unauthorized_token,
                    );
                    try self.pause(.token_ready);
                    try expectClientRoundtrip(display);
                    if (self.keyboard_leave_count == 0 or
                        self.keyboard_leave_surface != self.surface_object_id or
                        self.keyboard_leave_serial == 0)
                        return error.SourceKeyboardLeaveMissing;
                    surface.commit();
                    try expectClientRoundtrip(display);
                    try self.pause(.source_left);
                },
                .target => {
                    self.event_sequence = 0;
                    self.activated_configure_serial = 0;
                    self.activated_toplevel_sequence = 0;
                    self.activated_surface_sequence = 0;
                    self.activated_ack_sequence = 0;
                    self.pending_activated = false;
                    activation.activate(&exchange.token, surface);
                    try expectClientRoundtrip(display);
                    if (self.activated_configure_serial == 0 or
                        self.activated_toplevel_sequence == 0 or
                        !(self.activated_toplevel_sequence < self.activated_surface_sequence and
                            self.activated_surface_sequence < self.activated_ack_sequence) or
                        self.keyboard_enter_count == 0 or
                        self.keyboard_enter_surface != self.surface_object_id or
                        self.keyboard_enter_serial == 0)
                        return error.TargetActivationEvidenceMissing;
                    surface.commit();
                    try expectClientRoundtrip(display);
                    try self.pause(.activated);
                    const configure_count = self.configure_count;
                    const keyboard_enter_count = self.keyboard_enter_count;
                    activation.activate(&exchange.token, surface);
                    activation.activate("unknown", surface);
                    activation.activate("not-a-32-character-hex-token", surface);
                    activation.activate(&exchange.unauthorized_token, surface);
                    try expectClientRoundtrip(display);
                    if (self.configure_count != configure_count or
                        self.keyboard_enter_count != keyboard_enter_count)
                        return error.InvalidActivationChangedState;
                    try self.pause(.invalids_checked);
                },
            }
        } else {
            self.event_sequence = 0;
            decoration.unsetMode();
            try expectClientRoundtrip(display);
            if (self.configure_count != 2 or self.toplevel_configure_count != 2 or
                self.decoration_configure_count != 2 or
                self.decoration_mode != @as(u32, @intCast(@intFromEnum(client_zxdg.ToplevelDecorationV1.Mode.server_side))) or
                self.configure_serial == self.initial_configure_serial or
                !(self.decoration_event_sequence < self.toplevel_event_sequence and
                    self.toplevel_event_sequence < self.surface_event_sequence))
                return error.UnexpectedLaterConfigure;
            self.later_configure_serial = self.configure_serial;
            try self.pause(.mode_changed);

            try expectClientRoundtrip(display);
            if (self.output_enter_count.load(.acquire) != 1) return error.OutputEnterMissing;
            if (self.frame_count.load(.acquire) != 1) return error.FrameDoneMissing;
            try self.pause(.frame_done);
        }

        buffer.destroy();
        buffer_live = false;
        pool.destroy();
        pool_live = false;
        decoration.destroy();
        decoration_live = false;
        toplevel.destroy();
        toplevel_live = false;
        xdg_surface.destroy();
        xdg_surface_live = false;
        surface.destroy();
        surface_live = false;
        decoration_manager.destroy();
        decoration_manager_live = false;
        activation.destroy();
        activation_live = false;
        wm_base.destroy();
        wm_base_live = false;
        seat.release();
        seat_live = false;
        output.release();
        output_live = false;
        registry.destroy();
        registry_live = false;
        try expectClientRoundtrip(display);
    }

    fn registryEvent(registry: *client_wl.Registry, event: client_wl.Registry.Event, self: *@This()) void {
        switch (event) {
            .global => |global| {
                const interface = std.mem.span(global.interface);
                if (std.mem.eql(u8, interface, "wl_data_device_manager")) {
                    self.data_device_manager_count += 1;
                    self.data_device_manager_version = global.version;
                    self.data_device_manager_name = global.name;
                } else if (std.mem.eql(u8, interface, "zwp_primary_selection_device_manager_v1")) {
                    self.primary_selection_manager_count += 1;
                    self.primary_selection_manager_version = global.version;
                    self.primary_selection_manager_name = global.name;
                }
                if (std.mem.eql(u8, interface, "zwp_text_input_manager_v3")) {
                    self.text_input_manager_count += 1;
                    self.text_input_manager_version = global.version;
                } else if (std.mem.eql(u8, interface, "ext_data_control_manager_v1")) {
                    self.data_control_manager_count += 1;
                    self.data_control_manager_version = global.version;
                    self.data_control_manager_name = global.name;
                    self.data_control_manager = registry.bind(global.name, client_ext.DataControlManagerV1, 1) catch null;
                } else if (std.mem.eql(u8, interface, "zwp_input_method_manager_v2")) {
                    self.input_method_manager_count += 1;
                    self.input_method_manager_version = global.version;
                    self.input_method_manager_name = global.name;
                } else if (std.mem.eql(u8, interface, "zwp_virtual_keyboard_manager_v1")) {
                    self.generated_virtual_keyboard_seen = true;
                    self.virtual_keyboard_manager_count += 1;
                    self.virtual_keyboard_manager_version = global.version;
                    self.virtual_keyboard_manager_name = global.name;
                } else if (std.mem.eql(u8, interface, "zwlr_layer_shell_v1")) {
                    self.layer_shell_count += 1;
                    self.layer_shell_version = global.version;
                    self.layer_shell_name = global.name;
                    self.layer_shell = registry.bind(global.name, client_zwlr.LayerShellV1, 5) catch null;
                } else if (std.mem.eql(u8, interface, "ext_idle_notifier_v1")) {
                    self.idle_notifier_count += 1;
                    self.idle_notifier_version = global.version;
                    self.idle_notifier_name = global.name;
                } else if (std.mem.eql(u8, interface, "ext_session_lock_manager_v1")) {
                    self.session_lock_manager_count += 1;
                    self.session_lock_manager_version = global.version;
                    self.session_lock_manager_name = global.name;
                } else if (std.mem.eql(u8, interface, "ext_workspace_manager_v1")) {
                    self.workspace_manager_count += 1;
                    self.workspace_manager_version = global.version;
                    self.workspace_manager_name = global.name;
                }
                const index = self.global_count;
                self.global_count += 1;
                const expected = self.expectedGlobal(index);
                if (expected == null or !std.mem.eql(u8, interface, expected.?.interface) or
                    global.version != expected.?.version) self.globals_exact = false;
                if (std.mem.eql(u8, interface, "wl_compositor")) self.compositor = registry.bind(global.name, client_wl.Compositor, 6) catch null else if (std.mem.eql(u8, interface, "wl_shm")) self.shm = registry.bind(global.name, client_wl.Shm, 1) catch null else if (std.mem.eql(u8, interface, "wl_output")) self.output = registry.bind(global.name, client_wl.Output, 4) catch null else if (std.mem.eql(u8, interface, "wl_seat")) self.seat = registry.bind(global.name, client_wl.Seat, 11) catch null else if (std.mem.eql(u8, interface, "xdg_wm_base")) self.wm_base = registry.bind(global.name, client_xdg.WmBase, 7) catch null else if (std.mem.eql(u8, interface, "zxdg_decoration_manager_v1")) self.decoration_manager = registry.bind(global.name, client_zxdg.DecorationManagerV1, 2) catch null else if (std.mem.eql(u8, interface, "xdg_activation_v1")) self.activation = registry.bind(global.name, client_xdg.ActivationV1, 1) catch null;
            },
            .global_remove => |removed| {
                if (removed.name == self.data_device_manager_name)
                    self.data_device_manager_removed = true;
                if (removed.name == self.primary_selection_manager_name)
                    self.primary_selection_manager_removed = true;
                if (removed.name == self.data_control_manager_name)
                    self.data_control_manager_removed = true;
                if (removed.name == self.input_method_manager_name)
                    self.input_method_manager_removed = true;
                if (removed.name == self.virtual_keyboard_manager_name)
                    self.virtual_keyboard_manager_removed = true;
                if (removed.name == self.layer_shell_name)
                    self.layer_shell_removed = true;
                if (removed.name == self.idle_notifier_name)
                    self.idle_notifier_removed = true;
                if (removed.name == self.session_lock_manager_name)
                    self.session_lock_manager_removed = true;
            },
        }
    }

    fn wmBaseEvent(wm_base: *client_xdg.WmBase, event: client_xdg.WmBase.Event, _: *@This()) void {
        switch (event) {
            .ping => |ping| wm_base.pong(ping.serial),
        }
    }
    fn xdgSurfaceEvent(xdg_surface: *client_xdg.Surface, event: client_xdg.Surface.Event, self: *@This()) void {
        switch (event) {
            .configure => |configure| {
                self.event_sequence += 1;
                self.surface_event_sequence = self.event_sequence;
                if (self.pending_activated) {
                    self.activated_configure_serial = configure.serial;
                    self.activated_surface_sequence = self.event_sequence;
                }
                self.configure_serial = configure.serial;
                self.configure_count += 1;
                if (self.configure_count == 1) self.initial_configure_serial = configure.serial;
                xdg_surface.ackConfigure(configure.serial);
                if (self.pending_activated) {
                    self.event_sequence += 1;
                    self.activated_ack_sequence = self.event_sequence;
                    self.pending_activated = false;
                }
            },
        }
    }
    fn toplevelEvent(_: *client_xdg.Toplevel, event: client_xdg.Toplevel.Event, self: *@This()) void {
        switch (event) {
            .configure => |configure| {
                self.event_sequence += 1;
                self.toplevel_event_sequence = self.event_sequence;
                self.toplevel_configure_count += 1;
                const activated_raw: u32 = @intCast(@intFromEnum(client_xdg.Toplevel.State.activated));
                for (configure.states.slice(u32)) |state| if (state == activated_raw) {
                    self.pending_activated = true;
                    self.activated_toplevel_sequence = self.event_sequence;
                    break;
                };
            },
            .wm_capabilities => self.capabilities_count += 1,
            .configure_bounds, .close => {},
        }
    }
    fn decorationEvent(_: *client_zxdg.ToplevelDecorationV1, event: client_zxdg.ToplevelDecorationV1.Event, self: *@This()) void {
        switch (event) {
            .configure => |configure| {
                self.event_sequence += 1;
                self.decoration_event_sequence = self.event_sequence;
                self.decoration_configure_count += 1;
                self.decoration_mode = @intCast(@intFromEnum(configure.mode));
            },
        }
    }
    fn surfaceEvent(_: *client_wl.Surface, event: client_wl.Surface.Event, self: *@This()) void {
        switch (event) {
            .enter => _ = self.output_enter_count.fetchAdd(1, .acq_rel),
            else => {},
        }
    }
    fn frameEvent(callback: *client_wl.Callback, event: client_wl.Callback.Event, self: *@This()) void {
        switch (event) {
            .done => {
                _ = self.frame_count.fetchAdd(1, .acq_rel);
                callback.destroy();
            },
        }
    }
    fn pointerEvent(_: *client_wl.Pointer, event: client_wl.Pointer.Event, self: *@This()) void {
        switch (event) {
            .button => |button| if (button.state == .pressed) {
                self.pointer_button_serial = button.serial;
            },
            else => {},
        }
    }
    fn keyboardEvent(_: *client_wl.Keyboard, event: client_wl.Keyboard.Event, self: *@This()) void {
        switch (event) {
            .keymap => |keymap| _ = std.os.linux.close(keymap.fd),
            .enter => |enter| {
                self.keyboard_enter_count += 1;
                self.keyboard_enter_surface = (enter.surface orelse return).getId();
                self.keyboard_enter_serial = enter.serial;
            },
            .leave => |leave| {
                self.keyboard_leave_count += 1;
                self.keyboard_leave_surface = (leave.surface orelse return).getId();
                self.keyboard_leave_serial = leave.serial;
            },
            else => {},
        }
    }
    const ActivationTokenCapture = struct {
        destination: *[XdgActivation.token_character_count:0]u8,
        done_count: u8 = 0,

        fn event(_: *client_xdg.ActivationTokenV1, value: client_xdg.ActivationTokenV1.Event, self: *@This()) void {
            switch (value) {
                .done => |done| {
                    const token = std.mem.span(done.token);
                    if (token.len != XdgActivation.token_character_count) return;
                    @memcpy(self.destination[0..XdgActivation.token_character_count], token);
                    self.destination[XdgActivation.token_character_count] = 0;
                    self.done_count += 1;
                },
            }
        }
    };
    fn requestActivationToken(
        self: *@This(),
        display: *client_wl.Display,
        activation: *client_xdg.ActivationV1,
        seat: *client_wl.Seat,
        surface: *client_wl.Surface,
        serial: u32,
        app_id: [*:0]const u8,
        destination: *[XdgActivation.token_character_count:0]u8,
    ) !void {
        _ = self;
        const token = try activation.getActivationToken();
        defer token.destroy();
        var capture: ActivationTokenCapture = .{ .destination = destination };
        token.setListener(*ActivationTokenCapture, ActivationTokenCapture.event, &capture);
        token.setSerial(serial, seat);
        token.setAppId(app_id);
        token.setSurface(surface);
        token.commit();
        try expectClientRoundtrip(display);
        if (capture.done_count != 1 or destination[0] == 0) return error.UnexpectedActivationDone;
    }
    fn pause(self: *@This(), value: Stage) !void {
        self.stage.store(@intFromEnum(value), .release);
        try waitForWayringCommand(self.command_fd);
    }
    fn closeWake(self: *@This(), shutdown_requested: bool) void {
        const fd = self.wake_fd.swap(-2, .acq_rel);
        if (fd < 0) return;
        if (shutdown_requested) _ = std.os.linux.shutdown(fd, std.os.linux.SHUT.RDWR);
        _ = std.os.linux.close(fd);
    }
    fn shutdown(self: *@This()) void {
        signalWayringCommand(self.command_fd) catch {};
        self.closeWake(true);
    }
};

/// Production-transport drag source used by mixed Wayring/compositor tests.
/// The pauses deliberately leave pointer focus, button injection, target
/// negotiation, and dropping to the server-side scenario that owns the peer.
const WayringDndClient = struct {
    const client_wl = wayland.client.wl;
    const client_xdg = wayland.client.xdg;
    const mime_type: [:0]const u8 = "text/plain;charset=utf-8";
    const drag_bytes = "keywork generated drag\n";
    const Role = enum { source, target };

    const Stage = enum(u8) {
        starting,
        mapped,
        pointer_button_ready,
        drag_started,
        events_drained,
        transfer_sent,
        disconnected,
        failed,
    };
    const SourceEvent = enum {
        target,
        action,
        send,
        drop_performed,
        dnd_finished,
        cancelled,
    };
    const TargetEvent = enum { data_offer, offer_mime, source_actions, action, enter, motion, drop, leave };

    runtime_directory: []const u8,
    display_name: []const u8,
    command_fd: std.posix.fd_t,
    role: Role = .source,
    bytes: []const u8 = drag_bytes,
    expected_bytes: []const u8 = MatureDataDeviceClient.drag_bytes,
    source_enabled: bool = true,
    icon_enabled: bool = true,
    expect_offer: bool = true,
    expect_target: bool = true,
    stage: std.atomic.Value(u8) = .init(@intFromEnum(Stage.starting)),
    wake_fd: std.atomic.Value(i32) = .init(-1),
    failure: ?anyerror = null,
    compositor: ?*client_wl.Compositor = null,
    shm: ?*client_wl.Shm = null,
    seat: ?*client_wl.Seat = null,
    wm_base: ?*client_xdg.WmBase = null,
    manager: ?*client_wl.DataDeviceManager = null,
    origin_object_id: u32 = 0,
    icon_object_id: u32 = 0,
    source_object_id: u32 = 0,
    pointer_button_serial: u32 = 0,
    configure_serial: u32 = 0,
    events: [24]SourceEvent = undefined,
    event_count: usize = 0,
    target_mime_valid: bool = true,
    send_mime_valid: bool = true,
    selected_action: ?client_wl.DataDeviceManager.DndAction = null,
    offer: ?*client_wl.DataOffer = null,
    target_events: [24]TargetEvent = undefined,
    target_event_count: usize = 0,
    received: [64]u8 = undefined,
    received_len: usize = 0,
    enter_x: f64 = 0,
    enter_y: f64 = 0,
    motion_x: f64 = 0,
    motion_y: f64 = 0,

    fn run(self: *@This()) void {
        self.runFallible() catch |err| {
            self.failure = err;
            self.stage.store(@intFromEnum(Stage.failed), .release);
            return;
        };
        self.stage.store(@intFromEnum(Stage.disconnected), .release);
    }

    fn runFallible(self: *@This()) !void {
        const path = try std.fmt.allocPrintSentinel(
            std.heap.page_allocator,
            "{s}/{s}",
            .{ self.runtime_directory, self.display_name },
            0,
        );
        defer std.heap.page_allocator.free(path);
        const fd = try connectWayringTestSocket(path);
        var fd_owned = true;
        defer if (fd_owned) {
            _ = std.os.linux.close(fd);
        };
        const raw_wake_fd = std.os.linux.dup(fd);
        if (std.os.linux.errno(raw_wake_fd) != .SUCCESS) return error.WakeFdFailed;
        const wake_fd: i32 = @intCast(raw_wake_fd);
        if (self.wake_fd.cmpxchgStrong(-1, wake_fd, .acq_rel, .acquire)) |_| {
            _ = std.os.linux.close(wake_fd);
            return error.ClientShutdown;
        }
        defer self.closeWake(false);

        const display = try client_wl.Display.connectToFd(fd);
        fd_owned = false;
        defer display.disconnect();
        const registry = try display.getRegistry();
        defer registry.destroy();
        registry.setListener(*@This(), registryEvent, self);
        try expectClientRoundtrip(display);
        const compositor = self.compositor orelse return error.CompositorMissing;
        defer compositor.destroy();
        const shm = self.shm orelse return error.ShmMissing;
        defer shm.release();
        const seat = self.seat orelse return error.SeatMissing;
        defer seat.release();
        const wm_base = self.wm_base orelse return error.XdgWmBaseMissing;
        defer wm_base.destroy();
        wm_base.setListener(*@This(), wmBaseEvent, self);
        const manager = self.manager orelse return error.DataDeviceManagerMissing;
        defer manager.release();
        if (manager.getVersion() != 4) return error.DataDeviceManagerVersionMismatch;

        const pointer = try seat.getPointer();
        defer pointer.release();
        pointer.setListener(*@This(), pointerEvent, self);
        const device = try manager.getDataDevice(seat);
        defer device.release();
        device.setListener(*@This(), deviceEvent, self);
        const source = if (self.role == .source and self.source_enabled) try manager.createDataSource() else null;
        defer if (source) |value| value.destroy();
        if (source) |value| {
            self.source_object_id = value.getId();
            value.setListener(*@This(), sourceEvent, self);
            value.offer(mime_type);
            value.setActions(.{ .copy = true });
        }

        const origin = try compositor.createSurface();
        defer origin.destroy();
        self.origin_object_id = origin.getId();
        const xdg_surface = try wm_base.getXdgSurface(origin);
        defer xdg_surface.destroy();
        xdg_surface.setListener(*@This(), xdgSurfaceEvent, self);
        const toplevel = try xdg_surface.getToplevel();
        defer toplevel.destroy();
        toplevel.setListener(*@This(), toplevelEvent, self);
        origin.commit();
        try expectClientRoundtrip(display);
        if (self.configure_serial == 0) return error.InitialConfigureMissing;
        const origin_buffer = try MatureDataDeviceClient.createMatureTestBuffer(shm, 0xff28_6498);
        defer origin_buffer.buffer.destroy();
        defer origin_buffer.pool.destroy();
        defer _ = std.os.linux.close(origin_buffer.fd);
        origin.attach(origin_buffer.buffer, 0, 0);
        origin.damageBuffer(0, 0, 1, 1);
        origin.commit();

        const icon = if (self.icon_enabled) try compositor.createSurface() else null;
        defer if (icon) |value| value.destroy();
        var icon_buffer: ?MatureDataDeviceClient.TestBuffer = null;
        defer if (icon_buffer) |value| {
            value.buffer.destroy();
            value.pool.destroy();
            _ = std.os.linux.close(value.fd);
        };
        if (icon) |value| {
            self.icon_object_id = value.getId();
            icon_buffer = try MatureDataDeviceClient.createMatureTestBuffer(shm, 0xff46_b36b);
        }
        try expectClientRoundtrip(display);
        try self.pause(display, .mapped);

        if (self.role == .target) {
            try expectClientRoundtrip(display);
            if (!self.expect_offer) {
                if (self.offer != null or self.targetEventIndex(.data_offer) != null)
                    return error.UnexpectedDragOffer;
                if (!self.expect_target and self.target_event_count != 0)
                    return error.UnexpectedDragTarget;
                try self.pause(display, .events_drained);
                try expectClientRoundtrip(display);
                if (self.expect_target) {
                    if (self.targetEventIndex(.drop) == null or self.targetEventIndex(.leave) == null)
                        return error.DropChronologyMissing;
                } else if (self.target_event_count != 0) return error.UnexpectedDragTarget;
                try self.pause(display, .transfer_sent);
                return;
            }
            const drag_offer = self.offer orelse return error.DragOfferMissing;
            defer drag_offer.destroy();
            drag_offer.setActions(.{ .copy = true }, .{ .copy = true });
            drag_offer.accept(self.pointer_button_serial, mime_type);
            var pipe_fds: [2]std.posix.fd_t = undefined;
            if (std.c.pipe(&pipe_fds) != 0) return error.PipeFailed;
            var read_open = true;
            defer {
                if (read_open) _ = std.os.linux.close(pipe_fds[0]);
            }
            drag_offer.receive(mime_type, pipe_fds[1]);
            try closeMatureTransferFd(pipe_fds[1]);
            try expectClientRoundtrip(display);
            try self.pause(display, .events_drained);
            try expectClientRoundtrip(display);
            if (self.targetEventIndex(.drop) == null or self.targetEventIndex(.leave) == null)
                return error.DropChronologyMissing;
            self.received_len = try readMatureTransfer(pipe_fds[0], &self.received);
            try closeMatureTransferFd(pipe_fds[0]);
            read_open = false;
            if (!std.mem.eql(u8, self.received[0..self.received_len], self.expected_bytes))
                return error.DragBytesMismatch;
            drag_offer.finish();
            try expectClientRoundtrip(display);
            try self.pause(display, .transfer_sent);
            return;
        }

        try expectClientRoundtrip(display);
        if (self.pointer_button_serial == 0) return error.PointerButtonSerialMissing;
        try self.pause(display, .pointer_button_ready);
        device.startDrag(source, origin, icon, self.pointer_button_serial);
        if (icon) |value| {
            value.attach(icon_buffer.?.buffer, 0, 0);
            value.damageBuffer(0, 0, 1, 1);
            value.offset(1, 1);
            value.commit();
        }
        try expectClientRoundtrip(display);
        try self.pause(display, .drag_started);

        try expectClientRoundtrip(display);
        if (source == null) {
            try self.pause(display, .events_drained);
            try self.pause(display, .transfer_sent);
            return;
        }
        if (!self.target_mime_valid or !self.send_mime_valid) return error.UnexpectedDragMimeType;
        try self.pause(display, .events_drained);
        while (self.eventIndex(.send) == null) try expectClientRoundtrip(display);
        try self.pause(display, .transfer_sent);
        try expectClientRoundtrip(display);
    }

    fn append(self: *@This(), value: SourceEvent) void {
        if (self.event_count == self.events.len) return;
        self.events[self.event_count] = value;
        self.event_count += 1;
    }

    fn eventIndex(self: *const @This(), wanted: SourceEvent) ?usize {
        for (self.events[0..self.event_count], 0..) |event, index| {
            if (event == wanted) return index;
        }
        return null;
    }

    fn appendTarget(self: *@This(), value: TargetEvent) void {
        if (self.target_event_count == self.target_events.len) return;
        self.target_events[self.target_event_count] = value;
        self.target_event_count += 1;
    }

    fn targetEventIndex(self: *const @This(), wanted: TargetEvent) ?usize {
        for (self.target_events[0..self.target_event_count], 0..) |event, index| {
            if (event == wanted) return index;
        }
        return null;
    }

    fn registryEvent(registry: *client_wl.Registry, event: client_wl.Registry.Event, self: *@This()) void {
        switch (event) {
            .global => |global| {
                const interface = std.mem.span(global.interface);
                if (std.mem.eql(u8, interface, "wl_compositor"))
                    self.compositor = registry.bind(global.name, client_wl.Compositor, @min(global.version, 6)) catch null
                else if (std.mem.eql(u8, interface, "wl_shm"))
                    self.shm = registry.bind(global.name, client_wl.Shm, 1) catch null
                else if (std.mem.eql(u8, interface, "wl_seat"))
                    self.seat = registry.bind(global.name, client_wl.Seat, @min(global.version, 11)) catch null
                else if (std.mem.eql(u8, interface, "xdg_wm_base"))
                    self.wm_base = registry.bind(global.name, client_xdg.WmBase, @min(global.version, 7)) catch null
                else if (std.mem.eql(u8, interface, "wl_data_device_manager") and global.version >= 4)
                    self.manager = registry.bind(global.name, client_wl.DataDeviceManager, 4) catch null;
            },
            .global_remove => {},
        }
    }

    fn wmBaseEvent(wm_base: *client_xdg.WmBase, event: client_xdg.WmBase.Event, _: *@This()) void {
        switch (event) {
            .ping => |ping| wm_base.pong(ping.serial),
        }
    }

    fn xdgSurfaceEvent(xdg_surface: *client_xdg.Surface, event: client_xdg.Surface.Event, self: *@This()) void {
        switch (event) {
            .configure => |configure| {
                self.configure_serial = configure.serial;
                xdg_surface.ackConfigure(configure.serial);
            },
        }
    }

    fn toplevelEvent(_: *client_xdg.Toplevel, _: client_xdg.Toplevel.Event, _: *@This()) void {}

    fn pointerEvent(_: *client_wl.Pointer, event: client_wl.Pointer.Event, self: *@This()) void {
        switch (event) {
            .button => |button| if (button.state == .pressed) {
                self.pointer_button_serial = button.serial;
            },
            else => {},
        }
    }

    fn deviceEvent(_: *client_wl.DataDevice, event: client_wl.DataDevice.Event, self: *@This()) void {
        switch (event) {
            .data_offer => |data| {
                self.offer = data.id;
                data.id.setListener(*@This(), offerEvent, self);
                self.appendTarget(.data_offer);
            },
            .enter => |enter| {
                self.pointer_button_serial = enter.serial;
                self.offer = enter.id;
                self.enter_x = enter.x.toDouble();
                self.enter_y = enter.y.toDouble();
                self.appendTarget(.enter);
            },
            .motion => |motion| {
                self.motion_x = motion.x.toDouble();
                self.motion_y = motion.y.toDouble();
                self.appendTarget(.motion);
            },
            .drop => self.appendTarget(.drop),
            .leave => self.appendTarget(.leave),
            .selection => {},
        }
    }

    fn offerEvent(_: *client_wl.DataOffer, event: client_wl.DataOffer.Event, self: *@This()) void {
        switch (event) {
            .offer => self.appendTarget(.offer_mime),
            .source_actions => self.appendTarget(.source_actions),
            .action => |action| {
                self.selected_action = action.dnd_action;
                self.appendTarget(.action);
            },
        }
    }

    fn sourceEvent(_: *client_wl.DataSource, event: client_wl.DataSource.Event, self: *@This()) void {
        switch (event) {
            .target => |target| {
                if (target.mime_type) |mime| self.target_mime_valid = self.target_mime_valid and
                    std.mem.eql(u8, std.mem.span(mime), mime_type);
                self.append(.target);
            },
            .action => |action| {
                self.selected_action = action.dnd_action;
                self.append(.action);
            },
            .send => |send| {
                self.send_mime_valid = self.send_mime_valid and
                    std.mem.eql(u8, std.mem.span(send.mime_type), mime_type);
                if (std.c.write(send.fd, self.bytes.ptr, self.bytes.len) != self.bytes.len) {
                    self.failure = error.DragSendFailed;
                }
                closeMatureTransferFd(send.fd) catch |err| {
                    self.failure = err;
                };
                self.append(.send);
            },
            .dnd_drop_performed => self.append(.drop_performed),
            .dnd_finished => self.append(.dnd_finished),
            .cancelled => self.append(.cancelled),
        }
    }

    fn pause(self: *@This(), display: *client_wl.Display, value: Stage) !void {
        self.stage.store(@intFromEnum(value), .release);
        try waitForWayringCommandDraining(display, self.command_fd);
    }

    fn closeWake(self: *@This(), shutdown_requested: bool) void {
        const fd = self.wake_fd.swap(-2, .acq_rel);
        if (fd < 0) return;
        if (shutdown_requested) _ = std.os.linux.shutdown(fd, std.os.linux.SHUT.RDWR);
        _ = std.os.linux.close(fd);
    }

    fn shutdown(self: *@This()) void {
        signalWayringCommand(self.command_fd) catch {};
        self.closeWake(true);
    }
};

test "Wayring DnD source events decode and send owned bytes" {
    var client: WayringDndClient = .{
        .runtime_directory = "",
        .display_name = "",
        .command_fd = -1,
    };
    WayringDndClient.sourceEvent(undefined, .{ .target = .{ .mime_type = WayringDndClient.mime_type } }, &client);
    WayringDndClient.sourceEvent(undefined, .{ .action = .{ .dnd_action = .{ .copy = true } } }, &client);

    var pipe_fds: [2]std.posix.fd_t = undefined;
    if (std.c.pipe(&pipe_fds) != 0) return error.PipeFailed;
    defer _ = std.os.linux.close(pipe_fds[0]);
    WayringDndClient.sourceEvent(undefined, .{
        .send = .{ .mime_type = WayringDndClient.mime_type, .fd = pipe_fds[1] },
    }, &client);
    var received: [WayringDndClient.drag_bytes.len]u8 = undefined;
    try std.testing.expectEqual(@as(isize, received.len), std.c.read(pipe_fds[0], &received, received.len));
    try std.testing.expectEqualSlices(u8, WayringDndClient.drag_bytes, &received);
    try std.testing.expectEqualSlices(WayringDndClient.SourceEvent, &.{ .target, .action, .send }, client.events[0..client.event_count]);
    try std.testing.expectEqual(wayland.client.wl.DataDeviceManager.DndAction{ .copy = true }, client.selected_action.?);
    try std.testing.expect(client.target_mime_valid and client.send_mime_valid);
    try std.testing.expect(std.c.fcntl(pipe_fds[1], std.posix.F.GETFD) < 0);
}

const WayringSeatClient = struct {
    const client_wl = wayland.client.wl;
    const client_wp = wayland.client.wp;
    const Stage = enum(u8) {
        starting,
        ready,
        shape_ready,
        stale_shape_ignored,
        cursor_ready,
        cursor_cleared,
        cursor_and_late_touch_ready,
        resources_released,
        registry_ready,
        disconnected,
        failed,
    };
    const PointerTag = enum { enter, leave, motion, button, frame };
    const KeyboardTag = enum { keymap, enter, leave, key, modifiers, repeat_info };
    const TouchTag = enum { down, up, motion, frame, cancel, shape, orientation };
    const TouchLog = struct {
        tags: [16]TouchTag = undefined,
        ids: [16]?i32 = @splat(null),
        x: [16]?f64 = @splat(null),
        y: [16]?f64 = @splat(null),
        count: usize = 0,

        fn append(self: *TouchLog, tag: TouchTag, id: ?i32, x: ?f64, y: ?f64) void {
            if (self.count == self.tags.len) return;
            self.tags[self.count] = tag;
            self.ids[self.count] = id;
            self.x[self.count] = x;
            self.y[self.count] = y;
            self.count += 1;
        }
    };

    runtime_directory: []const u8,
    display_name: []const u8,
    command_fd: std.posix.fd_t,
    registry_only: bool = false,
    stage: std.atomic.Value(u8) = .init(@intFromEnum(Stage.starting)),
    wake_fd: std.atomic.Value(i32) = .init(-1),
    failure: ?anyerror = null,
    compositor: ?*client_wl.Compositor = null,
    shm: ?*client_wl.Shm = null,
    output: ?*client_wl.Output = null,
    seat: ?*client_wl.Seat = null,
    cursor_shape_manager: ?*client_wp.CursorShapeManagerV1 = null,
    global_count: usize = 0,
    globals_exact: bool = true,
    seat_name_valid: bool = false,
    seat_capabilities_valid: bool = false,
    seat_event_count: usize = 0,
    pointer_tags: [16]PointerTag = undefined,
    pointer_count: usize = 0,
    pointer_enter_serial: u32 = 0,
    pointer_motion_x: f64 = 0,
    pointer_motion_y: f64 = 0,
    keyboard_tags: [16]KeyboardTag = undefined,
    keyboard_count: usize = 0,
    keymap_valid: bool = false,
    repeat_valid: bool = false,
    keyboard_enter_keys: [8]u32 = @splat(0),
    keyboard_enter_key_count: usize = 0,
    keyboard_enter_count: usize = 0,
    keyboard_key_states: [4]client_wl.Keyboard.KeyState = undefined,
    keyboard_key_count: usize = 0,
    explicit_modifiers_seen: bool = false,
    touch: TouchLog = .{},
    late_touch: TouchLog = .{},

    fn run(self: *WayringSeatClient) void {
        self.runFallible() catch |err| {
            self.failure = err;
            self.stage.store(@intFromEnum(Stage.failed), .release);
            return;
        };
        self.stage.store(@intFromEnum(Stage.disconnected), .release);
    }

    fn runFallible(self: *WayringSeatClient) !void {
        const path = try std.fmt.allocPrintSentinel(
            std.heap.page_allocator,
            "{s}/{s}",
            .{ self.runtime_directory, self.display_name },
            0,
        );
        defer std.heap.page_allocator.free(path);
        const fd = try connectWayringTestSocket(path);
        var fd_owned = true;
        defer if (fd_owned) {
            _ = std.os.linux.close(fd);
        };
        const raw_wake_fd = std.os.linux.dup(fd);
        if (std.os.linux.errno(raw_wake_fd) != .SUCCESS) return error.WakeFdFailed;
        const wake_fd: i32 = @intCast(raw_wake_fd);
        if (self.wake_fd.cmpxchgStrong(-1, wake_fd, .acq_rel, .acquire)) |_| {
            _ = std.os.linux.close(wake_fd);
            return error.ClientShutdown;
        }
        defer self.closeWake(false);

        const display = try client_wl.Display.connectToFd(fd);
        fd_owned = false;
        defer display.disconnect();
        const registry = try display.getRegistry();
        defer registry.destroy();
        registry.setListener(*WayringSeatClient, registryEvent, self);
        try expectClientRoundtrip(display);
        if (!self.globals_exact or self.global_count != expected_globals.len)
            return error.UnexpectedRegistrySnapshot;
        const compositor = self.compositor orelse return error.CompositorMissing;
        const shm = self.shm orelse return error.ShmMissing;
        const output = self.output orelse return error.OutputMissing;
        var output_live = true;
        defer if (output_live) output.release();
        const seat = self.seat orelse return error.SeatMissing;
        var seat_live = true;
        defer if (seat_live) seat.release();
        const cursor_shape_manager = self.cursor_shape_manager orelse return error.CursorShapeMissing;
        defer cursor_shape_manager.destroy();
        try expectClientRoundtrip(display);
        if (!self.seat_name_valid or !self.seat_capabilities_valid or
            self.seat_event_count != 2 or seat.getVersion() != client_wl.Seat.generated_version)
            return error.UnexpectedSeatSnapshot;

        if (self.registry_only) {
            output.release();
            output_live = false;
            seat.release();
            seat_live = false;
            try expectClientRoundtrip(display);
            try self.pause(.registry_ready);
            return;
        }

        const surface = try compositor.createSurface();
        defer surface.destroy();
        surface.setListener(*WayringSeatClient, surfaceEvent, self);
        const cursor_surface = try compositor.createSurface();
        defer cursor_surface.destroy();
        cursor_surface.setListener(*WayringSeatClient, surfaceEvent, self);
        const shm_fd = try std.posix.memfd_create("keywork-wayring-seat", std.os.linux.MFD.CLOEXEC);
        defer _ = std.os.linux.close(shm_fd);
        const pixels: [4]u32 = @splat(0x00aa_bbcc);
        if (std.os.linux.errno(std.os.linux.ftruncate(shm_fd, @sizeOf(@TypeOf(pixels)))) != .SUCCESS)
            return error.ShmResizeFailed;
        if (std.c.pwrite(shm_fd, @ptrCast(&pixels), @sizeOf(@TypeOf(pixels)), 0) != @sizeOf(@TypeOf(pixels)))
            return error.ShmWriteFailed;
        const pool = try shm.createPool(shm_fd, @sizeOf(@TypeOf(pixels)));
        defer pool.destroy();
        const buffer = try pool.createBuffer(0, 2, 2, 2 * @sizeOf(u32), .xrgb8888);
        defer buffer.destroy();
        buffer.setListener(*WayringSeatClient, bufferEvent, self);
        surface.attach(buffer, 0, 0);
        surface.damageBuffer(0, 0, 2, 2);
        surface.commit();

        const pointer = try seat.getPointer();
        var pointer_live = true;
        defer if (pointer_live) pointer.release();
        pointer.setListener(*WayringSeatClient, pointerEvent, self);
        const cursor_shape_device = try cursor_shape_manager.getPointer(pointer);
        defer cursor_shape_device.destroy();
        const keyboard = try seat.getKeyboard();
        var keyboard_live = true;
        defer if (keyboard_live) keyboard.release();
        keyboard.setListener(*WayringSeatClient, keyboardEvent, self);
        const touch = try seat.getTouch();
        var touch_live = true;
        defer if (touch_live) touch.release();
        touch.setListener(*TouchLog, touchEvent, &self.touch);
        try expectClientRoundtrip(display);
        if (!self.keymap_valid or !self.repeat_valid) return error.UnexpectedKeyboardInitial;
        try self.pause(.ready);

        try expectClientRoundtrip(display);
        if (self.pointer_enter_serial == 0) return error.PointerEnterMissing;
        cursor_shape_device.setShape(self.pointer_enter_serial, .crosshair);
        try expectClientRoundtrip(display);
        try self.pause(.shape_ready);
        cursor_shape_device.setShape(self.pointer_enter_serial - 1, .text);
        try expectClientRoundtrip(display);
        try self.pause(.stale_shape_ignored);
        pointer.setCursor(self.pointer_enter_serial, cursor_surface, 1, 1);
        try expectClientRoundtrip(display);
        try self.pause(.cursor_ready);
        pointer.setCursor(self.pointer_enter_serial, null, 0, 0);
        try expectClientRoundtrip(display);
        try self.pause(.cursor_cleared);
        const late_touch = try seat.getTouch();
        var late_touch_live = true;
        defer if (late_touch_live) late_touch.release();
        late_touch.setListener(*TouchLog, touchEvent, &self.late_touch);
        try expectClientRoundtrip(display);
        try self.pause(.cursor_and_late_touch_ready);

        try expectClientRoundtrip(display);
        try self.validateDelivery();
        late_touch.release();
        late_touch_live = false;
        touch.release();
        touch_live = false;
        keyboard.release();
        keyboard_live = false;
        pointer.release();
        pointer_live = false;
        seat.release();
        seat_live = false;
        output.release();
        output_live = false;
        try expectClientRoundtrip(display);
        try self.pause(.resources_released);
    }

    fn validateDelivery(self: *const WayringSeatClient) !void {
        try std.testing.expectEqualSlices(PointerTag, &.{
            .enter,
            .motion,
            .button,
            .frame,
            .button,
            .frame,
            .leave,
            .frame,
            .enter,
            .frame,
        }, self.pointer_tags[0..self.pointer_count]);
        try std.testing.expectApproxEqAbs(@as(f64, 0.75), self.pointer_motion_x, 0.01);
        try std.testing.expectApproxEqAbs(@as(f64, 0.75), self.pointer_motion_y, 0.01);
        try std.testing.expectEqualSlices(KeyboardTag, &.{
            .keymap,
            .repeat_info,
            .enter,
            .modifiers,
            .modifiers,
            .key,
            .key,
            .leave,
            .enter,
            .modifiers,
        }, self.keyboard_tags[0..self.keyboard_count]);
        try std.testing.expectEqualSlices(u32, &.{30}, self.keyboard_enter_keys[0..self.keyboard_enter_key_count]);
        try std.testing.expectEqual(@as(usize, 2), self.keyboard_key_count);
        try std.testing.expectEqual(client_wl.Keyboard.KeyState.repeated, self.keyboard_key_states[0]);
        try std.testing.expectEqual(client_wl.Keyboard.KeyState.released, self.keyboard_key_states[1]);
        try std.testing.expect(self.explicit_modifiers_seen);
        try std.testing.expectEqualSlices(TouchTag, &.{
            .down,
            .shape,
            .orientation,
            .motion,
            .frame,
            .up,
            .frame,
            .down,
            .cancel,
        }, self.touch.tags[0..self.touch.count]);
        try std.testing.expectEqualSlices(TouchTag, &.{ .down, .cancel }, self.late_touch.tags[0..self.late_touch.count]);
        try std.testing.expectEqual(@as(?i32, 7), self.touch.ids[0]);
        try std.testing.expectEqual(@as(?i32, 8), self.late_touch.ids[0]);
    }

    const expected_globals = [_]struct { name: []const u8, version: u32 }{
        .{ .name = "wl_compositor", .version = 6 },
        .{ .name = "wl_shm", .version = 1 },
        .{ .name = "wl_subcompositor", .version = 1 },
        .{ .name = "wl_seat", .version = 11 },
        .{ .name = "wl_output", .version = 4 },
        .{ .name = "wp_cursor_shape_manager_v1", .version = 2 },
    };

    fn registryEvent(registry: *client_wl.Registry, event: client_wl.Registry.Event, self: *WayringSeatClient) void {
        switch (event) {
            .global => |global| {
                const interface = std.mem.span(global.interface);
                const index = self.global_count;
                self.global_count += 1;
                if (index >= expected_globals.len or
                    !std.mem.eql(u8, interface, expected_globals[index].name) or
                    global.version != expected_globals[index].version)
                {
                    self.globals_exact = false;
                }
                if (std.mem.eql(u8, interface, "wl_compositor") and self.compositor == null)
                    self.compositor = registry.bind(global.name, client_wl.Compositor, 6) catch null
                else if (std.mem.eql(u8, interface, "wl_shm") and self.shm == null)
                    self.shm = registry.bind(global.name, client_wl.Shm, 1) catch null
                else if (std.mem.eql(u8, interface, "wl_output") and self.output == null) {
                    self.output = registry.bind(global.name, client_wl.Output, 4) catch null;
                    if (self.output) |output| output.setListener(*WayringSeatClient, outputEvent, self);
                } else if (std.mem.eql(u8, interface, "wl_seat") and self.seat == null) {
                    self.seat = registry.bind(global.name, client_wl.Seat, global.version) catch null;
                    if (self.seat) |seat| seat.setListener(*WayringSeatClient, seatEvent, self);
                } else if (std.mem.eql(u8, interface, "wp_cursor_shape_manager_v1") and self.cursor_shape_manager == null) {
                    self.cursor_shape_manager = registry.bind(
                        global.name,
                        client_wp.CursorShapeManagerV1,
                        global.version,
                    ) catch null;
                }
            },
            .global_remove => {},
        }
    }

    fn seatEvent(_: *client_wl.Seat, event: client_wl.Seat.Event, self: *WayringSeatClient) void {
        self.seat_event_count += 1;
        switch (event) {
            .name => |name| self.seat_name_valid = self.seat_event_count == 1 and
                std.mem.eql(u8, std.mem.span(name.name), "default"),
            .capabilities => |capabilities| self.seat_capabilities_valid = self.seat_event_count == 2 and
                capabilities.capabilities.pointer and capabilities.capabilities.keyboard and
                capabilities.capabilities.touch,
        }
    }

    fn pointerEvent(_: *client_wl.Pointer, event: client_wl.Pointer.Event, self: *WayringSeatClient) void {
        if (self.pointer_count == self.pointer_tags.len) return;
        const tag: ?PointerTag = switch (event) {
            .enter => |enter| value: {
                self.pointer_enter_serial = enter.serial;
                break :value .enter;
            },
            .leave => .leave,
            .motion => |motion| value: {
                self.pointer_motion_x = motion.surface_x.toDouble();
                self.pointer_motion_y = motion.surface_y.toDouble();
                break :value .motion;
            },
            .button => .button,
            .frame => .frame,
            else => null,
        };
        if (tag) |value| {
            self.pointer_tags[self.pointer_count] = value;
            self.pointer_count += 1;
        }
    }

    fn keyboardEvent(_: *client_wl.Keyboard, event: client_wl.Keyboard.Event, self: *WayringSeatClient) void {
        if (self.keyboard_count == self.keyboard_tags.len) return;
        const tag: KeyboardTag = switch (event) {
            .keymap => |keymap| value: {
                self.keymap_valid = keymap.format == .xkb_v1 and keymap.size == 8;
                _ = std.os.linux.close(keymap.fd);
                break :value .keymap;
            },
            .enter => |enter| value: {
                if (self.keyboard_enter_count == 0) {
                    const keys = enter.keys.slice(u32);
                    self.keyboard_enter_key_count = @min(keys.len, self.keyboard_enter_keys.len);
                    @memcpy(self.keyboard_enter_keys[0..self.keyboard_enter_key_count], keys[0..self.keyboard_enter_key_count]);
                }
                self.keyboard_enter_count += 1;
                break :value .enter;
            },
            .leave => .leave,
            .key => |key| value: {
                if (self.keyboard_key_count < self.keyboard_key_states.len) {
                    self.keyboard_key_states[self.keyboard_key_count] = key.state;
                    self.keyboard_key_count += 1;
                }
                break :value .key;
            },
            .modifiers => |modifiers| value: {
                if (modifiers.mods_depressed == 1 and modifiers.mods_latched == 2 and
                    modifiers.mods_locked == 4 and modifiers.group == 3)
                    self.explicit_modifiers_seen = true;
                break :value .modifiers;
            },
            .repeat_info => |repeat| value: {
                self.repeat_valid = repeat.rate == 0 and repeat.delay == 500;
                break :value .repeat_info;
            },
        };
        self.keyboard_tags[self.keyboard_count] = tag;
        self.keyboard_count += 1;
    }

    fn touchEvent(_: *client_wl.Touch, event: client_wl.Touch.Event, log_value: *TouchLog) void {
        switch (event) {
            .down => |down| log_value.append(.down, down.id, down.x.toDouble(), down.y.toDouble()),
            .up => |up| log_value.append(.up, up.id, null, null),
            .motion => |motion| log_value.append(.motion, motion.id, motion.x.toDouble(), motion.y.toDouble()),
            .frame => log_value.append(.frame, null, null, null),
            .cancel => log_value.append(.cancel, null, null, null),
            .shape => |shape| log_value.append(.shape, shape.id, shape.major.toDouble(), shape.minor.toDouble()),
            .orientation => |orientation| log_value.append(.orientation, orientation.id, orientation.orientation.toDouble(), null),
        }
    }

    fn surfaceEvent(_: *client_wl.Surface, _: client_wl.Surface.Event, _: *WayringSeatClient) void {}
    fn outputEvent(_: *client_wl.Output, _: client_wl.Output.Event, _: *WayringSeatClient) void {}
    fn bufferEvent(_: *client_wl.Buffer, _: client_wl.Buffer.Event, _: *WayringSeatClient) void {}

    fn pause(self: *WayringSeatClient, stage_value: Stage) !void {
        self.stage.store(@intFromEnum(stage_value), .release);
        try waitForWayringCommand(self.command_fd);
    }

    fn closeWake(self: *WayringSeatClient, shutdown_requested: bool) void {
        const fd = self.wake_fd.swap(-2, .acq_rel);
        if (fd < 0) return;
        if (shutdown_requested) _ = std.os.linux.shutdown(fd, std.os.linux.SHUT.RDWR);
        _ = std.os.linux.close(fd);
    }

    fn shutdown(self: *WayringSeatClient) void {
        signalWayringCommand(self.command_fd) catch {};
        self.closeWake(true);
    }
};

const MatureLayerClient = struct {
    const client_wl = wayland.client.wl;
    const client_zwlr = wayland.client.zwlr;
    const Stage = enum(u8) { starting, mapped, unmapped, remapped, disconnected, failed };

    runtime_directory: []const u8,
    display_name: []const u8,
    command_fd: std.posix.fd_t,
    stage: std.atomic.Value(u8) = .init(@intFromEnum(Stage.starting)),
    wake_fd: std.atomic.Value(i32) = .init(-1),
    failure: ?anyerror = null,
    compositor: ?*client_wl.Compositor = null,
    shm: ?*client_wl.Shm = null,
    output: ?*client_wl.Output = null,
    shell: ?*client_zwlr.LayerShellV1 = null,
    configure_serial: u32 = 0,
    acked_serial: u32 = 0,
    explicit_acked_serial: u32 = 0,

    fn run(self: *@This()) void {
        self.runFallible() catch |err| {
            self.failure = err;
            self.stage.store(@intFromEnum(Stage.failed), .release);
            return;
        };
        self.stage.store(@intFromEnum(Stage.disconnected), .release);
    }

    fn runFallible(self: *@This()) !void {
        const path = try std.fmt.allocPrintSentinel(std.heap.page_allocator, "{s}/{s}", .{ self.runtime_directory, self.display_name }, 0);
        defer std.heap.page_allocator.free(path);
        const fd = try connectWayringTestSocket(path);
        var fd_owned = true;
        defer {
            if (fd_owned) _ = std.os.linux.close(fd);
        }
        const raw_wake = std.os.linux.dup(fd);
        if (std.os.linux.errno(raw_wake) != .SUCCESS) return error.WakeFdFailed;
        const wake: i32 = @intCast(raw_wake);
        if (self.wake_fd.cmpxchgStrong(-1, wake, .acq_rel, .acquire)) |_| {
            _ = std.os.linux.close(wake);
            return error.ClientShutdown;
        }
        defer self.closeWake(false);
        const display = try client_wl.Display.connectToFd(fd);
        fd_owned = false;
        defer display.disconnect();
        const registry = try display.getRegistry();
        defer registry.destroy();
        registry.setListener(*@This(), registryEvent, self);
        try expectClientRoundtrip(display);
        const compositor = self.compositor orelse return error.CompositorMissing;
        defer compositor.destroy();
        const shm = self.shm orelse return error.ShmMissing;
        defer shm.release();
        const output = self.output orelse return error.OutputMissing;
        defer output.release();
        const shell = self.shell orelse return error.LayerShellMissing;
        defer shell.destroy();
        if (shell.getVersion() != 5) return error.LayerShellVersionMismatch;
        const explicit_surface = try compositor.createSurface();
        defer explicit_surface.destroy();
        const explicit_layer = try shell.getLayerSurface(explicit_surface, output, .top, "org.keywork.mature-layer-explicit");
        defer explicit_layer.destroy();
        explicit_layer.setListener(*@This(), layerEvent, self);
        explicit_layer.setSize(1, 1);
        explicit_surface.commit();
        try expectClientRoundtrip(display);
        if (self.configure_serial == 0) return error.ExplicitConfigureMissing;
        self.explicit_acked_serial = self.configure_serial;
        explicit_layer.ackConfigure(self.configure_serial);
        self.configure_serial = 0;
        const surface = try compositor.createSurface();
        defer surface.destroy();
        const layer = try shell.getLayerSurface(surface, null, .top, "org.keywork.mature-layer");
        defer layer.destroy();
        layer.setListener(*@This(), layerEvent, self);
        layer.setSize(100, 20);
        layer.setAnchor(.{ .top = true });
        layer.setExclusiveZone(20);
        layer.setKeyboardInteractivity(.exclusive);
        surface.commit();
        try expectClientRoundtrip(display);
        if (self.configure_serial == 0) return error.ConfigureMissing;
        self.acked_serial = self.configure_serial;
        layer.ackConfigure(self.configure_serial);
        const buffer = try createBuffer(shm);
        defer buffer.buffer.destroy();
        defer buffer.pool.destroy();
        defer _ = std.os.linux.close(buffer.fd);
        surface.attach(buffer.buffer, 0, 0);
        surface.damageBuffer(0, 0, 100, 20);
        surface.commit();
        try expectClientRoundtrip(display);
        try self.pause(.mapped);

        surface.attach(null, 0, 0);
        surface.commit();
        try expectClientRoundtrip(display);
        try self.pause(.unmapped);
        self.configure_serial = 0;
        layer.setSize(100, 20);
        layer.setAnchor(.{ .top = true });
        layer.setExclusiveZone(20);
        layer.setKeyboardInteractivity(.exclusive);
        surface.commit();
        try expectClientRoundtrip(display);
        if (self.configure_serial == 0) return error.RemapConfigureMissing;
        self.acked_serial = self.configure_serial;
        layer.ackConfigure(self.configure_serial);
        surface.attach(buffer.buffer, 0, 0);
        surface.damageBuffer(0, 0, 100, 20);
        surface.commit();
        try expectClientRoundtrip(display);
        try self.pause(.remapped);
    }

    const TestBuffer = struct { fd: std.posix.fd_t, pool: *client_wl.ShmPool, buffer: *client_wl.Buffer };
    fn createBuffer(shm: *client_wl.Shm) !TestBuffer {
        const size = 100 * 20 * @sizeOf(u32);
        const fd = try std.posix.memfd_create("keywork-mature-layer", std.os.linux.MFD.CLOEXEC);
        errdefer _ = std.os.linux.close(fd);
        if (std.os.linux.errno(std.os.linux.ftruncate(fd, size)) != .SUCCESS) return error.ShmResizeFailed;
        const pool = try shm.createPool(fd, size);
        errdefer pool.destroy();
        return .{ .fd = fd, .pool = pool, .buffer = try pool.createBuffer(0, 100, 20, 400, .argb8888) };
    }

    fn registryEvent(registry: *client_wl.Registry, event: client_wl.Registry.Event, self: *@This()) void {
        switch (event) {
            .global => |global| {
                const interface = std.mem.span(global.interface);
                if (std.mem.eql(u8, interface, "wl_compositor")) self.compositor = registry.bind(global.name, client_wl.Compositor, @min(global.version, 6)) catch null else if (std.mem.eql(u8, interface, "wl_shm")) self.shm = registry.bind(global.name, client_wl.Shm, 1) catch null else if (std.mem.eql(u8, interface, "wl_output")) self.output = registry.bind(global.name, client_wl.Output, @min(global.version, 4)) catch null else if (std.mem.eql(u8, interface, "zwlr_layer_shell_v1")) self.shell = registry.bind(global.name, client_zwlr.LayerShellV1, 5) catch null;
            },
            .global_remove => {},
        }
    }
    fn layerEvent(_: *client_zwlr.LayerSurfaceV1, event: client_zwlr.LayerSurfaceV1.Event, self: *@This()) void {
        switch (event) {
            .configure => |configure| self.configure_serial = configure.serial,
            .closed => {},
        }
    }
    fn pause(self: *@This(), value: Stage) !void {
        self.stage.store(@intFromEnum(value), .release);
        var count: u64 = 0;
        if (std.os.linux.read(self.command_fd, @ptrCast(&count), @sizeOf(u64)) != @sizeOf(u64)) return error.CommandReadFailed;
    }
    fn closeWake(self: *@This(), replace: bool) void {
        const value = self.wake_fd.swap(if (replace) -2 else -1, .acq_rel);
        if (value >= 0) {
            if (replace) _ = std.os.linux.shutdown(value, std.os.linux.SHUT.RDWR);
            _ = std.os.linux.close(value);
        }
    }
    fn shutdown(self: *@This()) void {
        self.closeWake(true);
        signalWayringCommand(self.command_fd) catch {};
    }
};

const MatureIdleNotifyClient = struct {
    const client_wl = wayland.client.wl;
    const client_ext = wayland.client.ext;
    const Stage = enum(u8) { starting, created, idled, resumed, reidled, destroyed, disconnected, failed };

    runtime_directory: []const u8,
    display_name: []const u8,
    command_fd: std.posix.fd_t,
    stage: std.atomic.Value(u8) = .init(@intFromEnum(Stage.starting)),
    wake_fd: std.atomic.Value(i32) = .init(-1),
    failure: ?anyerror = null,
    seat: ?*client_wl.Seat = null,
    notifier: ?*client_ext.IdleNotifierV1 = null,
    notifier_global_count: usize = 0,
    notifier_global_version: u32 = 0,
    idled_count: u8 = 0,
    resumed_count: u8 = 0,
    timeout_ms: u32 = 20,
    pause_after_create: bool = false,

    fn run(self: *@This()) void {
        self.runFallible() catch |err| {
            self.failure = err;
            self.stage.store(@intFromEnum(Stage.failed), .release);
            return;
        };
        self.stage.store(@intFromEnum(Stage.disconnected), .release);
    }

    fn runFallible(self: *@This()) !void {
        const path = try std.fmt.allocPrintSentinel(std.heap.page_allocator, "{s}/{s}", .{ self.runtime_directory, self.display_name }, 0);
        defer std.heap.page_allocator.free(path);
        const fd = try connectWayringTestSocket(path);
        var fd_owned = true;
        defer if (fd_owned) {
            _ = std.os.linux.close(fd);
        };
        const raw_wake = std.os.linux.dup(fd);
        if (std.os.linux.errno(raw_wake) != .SUCCESS) return error.WakeFdFailed;
        const wake: i32 = @intCast(raw_wake);
        if (self.wake_fd.cmpxchgStrong(-1, wake, .acq_rel, .acquire)) |_| {
            _ = std.os.linux.close(wake);
            return error.ClientShutdown;
        }
        defer self.closeWake(false);
        const display = try client_wl.Display.connectToFd(fd);
        fd_owned = false;
        defer display.disconnect();
        const registry = try display.getRegistry();
        defer registry.destroy();
        registry.setListener(*@This(), registryEvent, self);
        try expectClientRoundtrip(display);
        if (self.notifier_global_count != 1 or self.notifier_global_version != 2)
            return error.IdleNotifierVisibilityMismatch;
        const seat = self.seat orelse return error.SeatMissing;
        defer seat.release();
        const notifier = self.notifier orelse return error.IdleNotifierMissing;
        defer notifier.destroy();
        if (notifier.getVersion() != 2) return error.IdleNotifierVersionMismatch;
        const notification = try notifier.getIdleNotification(self.timeout_ms, seat);
        notification.setListener(*@This(), notificationEvent, self);
        if (self.pause_after_create) {
            try expectClientRoundtrip(display);
            try self.pause(.created);
        }
        while (self.idled_count == 0)
            if (display.dispatch() != .SUCCESS) return error.WaylandDispatchFailed;
        try self.pause(.idled);
        try expectClientRoundtrip(display);
        if (self.resumed_count != 1) return error.ResumedMissing;
        try self.pause(.resumed);
        while (self.idled_count != 2)
            if (display.dispatch() != .SUCCESS) return error.WaylandDispatchFailed;
        try self.pause(.reidled);
        notification.destroy();
        try expectClientRoundtrip(display);
        try self.pause(.destroyed);
    }

    fn registryEvent(registry: *client_wl.Registry, event: client_wl.Registry.Event, self: *@This()) void {
        switch (event) {
            .global => |global| {
                const interface = std.mem.span(global.interface);
                if (std.mem.eql(u8, interface, "wl_seat") and self.seat == null) {
                    self.seat = registry.bind(global.name, client_wl.Seat, @min(global.version, 9)) catch null;
                } else if (std.mem.eql(u8, interface, "ext_idle_notifier_v1")) {
                    self.notifier_global_count += 1;
                    self.notifier_global_version = global.version;
                    if (self.notifier == null)
                        self.notifier = registry.bind(global.name, client_ext.IdleNotifierV1, 2) catch null;
                }
            },
            .global_remove => {},
        }
    }

    fn notificationEvent(_: *client_ext.IdleNotificationV1, event: client_ext.IdleNotificationV1.Event, self: *@This()) void {
        switch (event) {
            .idled => self.idled_count += 1,
            .resumed => self.resumed_count += 1,
        }
    }

    fn pause(self: *@This(), value: Stage) !void {
        self.stage.store(@intFromEnum(value), .release);
        try waitForWayringCommand(self.command_fd);
    }

    fn closeWake(self: *@This(), replace: bool) void {
        const value = self.wake_fd.swap(if (replace) -2 else -1, .acq_rel);
        if (value >= 0) {
            if (replace) _ = std.os.linux.shutdown(value, std.os.linux.SHUT.RDWR);
            _ = std.os.linux.close(value);
        }
    }

    fn shutdown(self: *@This()) void {
        self.closeWake(true);
        signalWayringCommand(self.command_fd) catch {};
    }
};

/// Exercises the scanner-generated layer-shell client API against the
/// production Wayring adapter. Both output selection paths deliberately live
/// on one connection so object and canonical output identities are shared.
const GeneratedLayerClient = struct {
    const client_wl = wayland.client.wl;
    const client_zwlr = wayland.client.zwlr;
    const Stage = enum(u8) { starting, mapped, unmapped, remapped, disconnected, failed };

    runtime_directory: []const u8,
    display_name: []const u8,
    command_fd: std.posix.fd_t,
    stage: std.atomic.Value(u8) = .init(@intFromEnum(Stage.starting)),
    wake_fd: std.atomic.Value(i32) = .init(-1),
    failure: ?anyerror = null,
    compositor: ?*client_wl.Compositor = null,
    shm: ?*client_wl.Shm = null,
    output: ?*client_wl.Output = null,
    shell: ?*client_zwlr.LayerShellV1 = null,
    explicit_layer: ?*client_zwlr.LayerSurfaceV1 = null,
    default_layer: ?*client_zwlr.LayerSurfaceV1 = null,
    explicit_serial: u32 = 0,
    default_serial: u32 = 0,

    fn run(self: *@This()) void {
        self.runFallible() catch |err| {
            self.failure = err;
            self.stage.store(@intFromEnum(Stage.failed), .release);
            return;
        };
        self.stage.store(@intFromEnum(Stage.disconnected), .release);
    }

    fn runFallible(self: *@This()) !void {
        const path = try std.fmt.allocPrintSentinel(std.heap.page_allocator, "{s}/{s}", .{ self.runtime_directory, self.display_name }, 0);
        defer std.heap.page_allocator.free(path);
        const fd = try connectWayringTestSocket(path);
        var fd_owned = true;
        defer if (fd_owned) {
            _ = std.os.linux.close(fd);
        };
        const raw_wake = std.os.linux.dup(fd);
        if (std.os.linux.errno(raw_wake) != .SUCCESS) return error.WakeFdFailed;
        const wake: i32 = @intCast(raw_wake);
        if (self.wake_fd.cmpxchgStrong(-1, wake, .acq_rel, .acquire)) |_| {
            _ = std.os.linux.close(wake);
            return error.ClientShutdown;
        }
        defer self.closeWake(false);
        const display = try client_wl.Display.connectToFd(fd);
        fd_owned = false;
        defer display.disconnect();
        const registry = try display.getRegistry();
        defer registry.destroy();
        registry.setListener(*@This(), registryEvent, self);
        try expectClientRoundtrip(display);
        const compositor = self.compositor orelse return error.CompositorMissing;
        defer compositor.destroy();
        const shm = self.shm orelse return error.ShmMissing;
        defer shm.release();
        const output = self.output orelse return error.OutputMissing;
        defer output.release();
        const shell = self.shell orelse return error.LayerShellMissing;
        defer shell.destroy();
        if (shell.getVersion() != 5) return error.LayerShellVersionMismatch;

        const explicit_surface = try compositor.createSurface();
        defer explicit_surface.destroy();
        const explicit_layer = try shell.getLayerSurface(explicit_surface, output, .overlay, "org.keywork.generated-layer-explicit");
        self.explicit_layer = explicit_layer;
        defer explicit_layer.destroy();
        explicit_layer.setListener(*@This(), layerEvent, self);
        explicit_layer.setSize(1, 1);
        explicit_layer.setAnchor(.{ .bottom = true, .right = true });
        explicit_surface.commit();

        const surface = try compositor.createSurface();
        defer surface.destroy();
        const layer = try shell.getLayerSurface(surface, null, .bottom, "org.keywork.generated-layer-default");
        self.default_layer = layer;
        defer layer.destroy();
        layer.setListener(*@This(), layerEvent, self);
        // Cover every request added after v1 while making the final state easy
        // to distinguish in the canonical model and Scene.
        layer.setSize(1, 1);
        layer.setAnchor(.{ .top = true, .left = true });
        layer.setExclusiveZone(1);
        layer.setMargin(2, 0, 0, 3);
        layer.setKeyboardInteractivity(.on_demand);
        layer.setKeyboardInteractivity(.exclusive);
        layer.setLayer(.top);
        layer.setExclusiveEdge(.{ .top = true });
        surface.commit();
        try expectClientRoundtrip(display);
        if (self.explicit_serial == 0 or self.default_serial == 0) return error.ConfigureMissing;
        explicit_layer.ackConfigure(self.explicit_serial);
        layer.ackConfigure(self.default_serial);

        const explicit_buffer = try createBuffer(shm, 0xff21_4365);
        defer explicit_buffer.buffer.destroy();
        defer explicit_buffer.pool.destroy();
        defer _ = std.os.linux.close(explicit_buffer.fd);
        const buffer = try createBuffer(shm, 0xff65_4321);
        defer buffer.buffer.destroy();
        defer buffer.pool.destroy();
        defer _ = std.os.linux.close(buffer.fd);
        explicit_surface.attach(explicit_buffer.buffer, 0, 0);
        explicit_surface.damageBuffer(0, 0, 1, 1);
        explicit_surface.commit();
        surface.attach(buffer.buffer, 0, 0);
        surface.damageBuffer(0, 0, 1, 1);
        surface.commit();
        try expectClientRoundtrip(display);
        try self.pause(.mapped);

        surface.attach(null, 0, 0);
        surface.commit();
        try expectClientRoundtrip(display);
        try self.pause(.unmapped);
        self.default_serial = 0;
        layer.setSize(1, 1);
        layer.setAnchor(.{ .top = true, .left = true });
        layer.setExclusiveZone(1);
        layer.setMargin(2, 0, 0, 3);
        layer.setKeyboardInteractivity(.exclusive);
        layer.setLayer(.top);
        layer.setExclusiveEdge(.{ .top = true });
        surface.commit();
        try expectClientRoundtrip(display);
        if (self.default_serial == 0) return error.RemapConfigureMissing;
        layer.ackConfigure(self.default_serial);
        surface.attach(buffer.buffer, 0, 0);
        surface.damageBuffer(0, 0, 1, 1);
        surface.commit();
        try expectClientRoundtrip(display);
        try self.pause(.remapped);
    }

    const TestBuffer = struct { fd: std.posix.fd_t, pool: *client_wl.ShmPool, buffer: *client_wl.Buffer };
    fn createBuffer(shm: *client_wl.Shm, pixel: u32) !TestBuffer {
        const fd = try std.posix.memfd_create("keywork-generated-layer", std.os.linux.MFD.CLOEXEC);
        errdefer _ = std.os.linux.close(fd);
        if (std.os.linux.errno(std.os.linux.ftruncate(fd, 4)) != .SUCCESS) return error.ShmResizeFailed;
        if (std.c.pwrite(fd, @ptrCast(&pixel), 4, 0) != 4) return error.ShmWriteFailed;
        const pool = try shm.createPool(fd, 4);
        errdefer pool.destroy();
        return .{ .fd = fd, .pool = pool, .buffer = try pool.createBuffer(0, 1, 1, 4, .argb8888) };
    }

    fn registryEvent(registry: *client_wl.Registry, event: client_wl.Registry.Event, self: *@This()) void {
        switch (event) {
            .global => |global| {
                const interface = std.mem.span(global.interface);
                if (std.mem.eql(u8, interface, "wl_compositor")) self.compositor = registry.bind(global.name, client_wl.Compositor, @min(global.version, 6)) catch null else if (std.mem.eql(u8, interface, "wl_shm")) self.shm = registry.bind(global.name, client_wl.Shm, 1) catch null else if (std.mem.eql(u8, interface, "wl_output")) self.output = registry.bind(global.name, client_wl.Output, @min(global.version, 4)) catch null else if (std.mem.eql(u8, interface, "zwlr_layer_shell_v1")) self.shell = registry.bind(global.name, client_zwlr.LayerShellV1, 5) catch null;
            },
            .global_remove => {},
        }
    }
    fn layerEvent(resource: *client_zwlr.LayerSurfaceV1, event: client_zwlr.LayerSurfaceV1.Event, self: *@This()) void {
        switch (event) {
            .configure => |configure| if (resource == self.explicit_layer) {
                self.explicit_serial = configure.serial;
            } else if (resource == self.default_layer) {
                self.default_serial = configure.serial;
            },
            .closed => {},
        }
    }
    fn pause(self: *@This(), value: Stage) !void {
        self.stage.store(@intFromEnum(value), .release);
        try waitForWayringCommand(self.command_fd);
    }
    fn closeWake(self: *@This(), shutdown_requested: bool) void {
        const value = self.wake_fd.swap(if (shutdown_requested) -2 else -1, .acq_rel);
        if (value < 0) return;
        if (shutdown_requested) _ = std.os.linux.shutdown(value, std.os.linux.SHUT.RDWR);
        _ = std.os.linux.close(value);
    }
    fn shutdown(self: *@This()) void {
        signalWayringCommand(self.command_fd) catch {};
        self.closeWake(true);
    }
};

const MatureSessionLockClient = struct {
    const client_wl = wayland.client.wl;
    const client_ext = wayland.client.ext;
    const Stage = enum(u8) { starting, mapped, acquired, unlocked, disconnected, failed };

    runtime_directory: []const u8,
    display_name: []const u8,
    command_fd: std.posix.fd_t,
    stage: std.atomic.Value(u8) = .init(@intFromEnum(Stage.starting)),
    wake_fd: std.atomic.Value(i32) = .init(-1),
    locked_count: std.atomic.Value(usize) = .init(0),
    failure: ?anyerror = null,
    compositor: ?*client_wl.Compositor = null,
    shm: ?*client_wl.Shm = null,
    output: ?*client_wl.Output = null,
    manager: ?*client_ext.SessionLockManagerV1 = null,
    manager_global_count: usize = 0,
    manager_global_version: u32 = 0,
    configure_serial: u32 = 0,
    acked_serial: u32 = 0,
    configure_width: u32 = 0,
    configure_height: u32 = 0,
    pixel: u32 = 0,

    fn run(self: *@This()) void {
        self.runFallible() catch |err| {
            self.failure = err;
            self.stage.store(@intFromEnum(Stage.failed), .release);
            return;
        };
        self.stage.store(@intFromEnum(Stage.disconnected), .release);
    }

    fn runFallible(self: *@This()) !void {
        const path = try std.fmt.allocPrintSentinel(std.heap.page_allocator, "{s}/{s}", .{ self.runtime_directory, self.display_name }, 0);
        defer std.heap.page_allocator.free(path);
        const fd = try connectWayringTestSocket(path);
        var fd_owned = true;
        defer if (fd_owned) {
            _ = std.os.linux.close(fd);
        };
        const raw_wake = std.os.linux.dup(fd);
        if (std.os.linux.errno(raw_wake) != .SUCCESS) return error.WakeFdFailed;
        const wake: i32 = @intCast(raw_wake);
        if (self.wake_fd.cmpxchgStrong(-1, wake, .acq_rel, .acquire)) |_| {
            _ = std.os.linux.close(wake);
            return error.ClientShutdown;
        }
        defer self.closeWake(false);
        const display = try client_wl.Display.connectToFd(fd);
        fd_owned = false;
        defer display.disconnect();
        const registry = try display.getRegistry();
        defer registry.destroy();
        registry.setListener(*@This(), registryEvent, self);
        try expectClientRoundtrip(display);
        if (self.manager_global_count != 1 or self.manager_global_version != 1) return error.SessionLockRegistryMismatch;
        const compositor = self.compositor orelse return error.CompositorMissing;
        defer compositor.destroy();
        const shm = self.shm orelse return error.ShmMissing;
        defer shm.release();
        const output = self.output orelse return error.OutputMissing;
        defer output.release();
        const manager = self.manager orelse return error.SessionLockManagerMissing;
        defer manager.destroy();
        if (manager.getVersion() != 1) return error.SessionLockVersionMismatch;
        const lock = try manager.lock();
        lock.setListener(*@This(), lockEvent, self);
        const surface = try compositor.createSurface();
        const lock_surface = try lock.getLockSurface(surface, output);
        lock_surface.setListener(*@This(), lockSurfaceEvent, self);
        try expectClientRoundtrip(display);
        if (self.configure_serial == 0 or self.configure_width == 0 or self.configure_height == 0) return error.ConfigureMissing;
        self.acked_serial = self.configure_serial;
        lock_surface.ackConfigure(self.configure_serial);
        const buffer = try createBuffer(shm, self.configure_width, self.configure_height, self.pixel);
        defer buffer.buffer.destroy();
        defer buffer.pool.destroy();
        defer _ = std.os.linux.close(buffer.fd);
        surface.attach(buffer.buffer, 0, 0);
        surface.damageBuffer(0, 0, @intCast(self.configure_width), @intCast(self.configure_height));
        surface.commit();
        try expectClientRoundtrip(display);
        if (self.locked_count.load(.acquire) != 0) return error.LockedBeforeCoverage;
        try self.pause(.mapped);
        try expectClientRoundtrip(display);
        if (self.locked_count.load(.acquire) != 1) return error.LockedEventMismatch;
        try self.pause(.acquired);
        lock.unlockAndDestroy();
        try expectClientRoundtrip(display);
        try self.pause(.unlocked);
        // The parent lock is already gone; its child remains independently destructible.
        lock_surface.destroy();
        surface.destroy();
        try expectClientRoundtrip(display);
    }

    const TestBuffer = struct { fd: std.posix.fd_t, pool: *client_wl.ShmPool, buffer: *client_wl.Buffer };
    fn createBuffer(shm: *client_wl.Shm, width: u32, height: u32, pixel: u32) !TestBuffer {
        const stride = std.math.mul(u32, width, @sizeOf(u32)) catch return error.ShmSizeOverflow;
        const size = std.math.mul(u32, stride, height) catch return error.ShmSizeOverflow;
        const fd = try std.posix.memfd_create("keywork-mature-session-lock", std.os.linux.MFD.CLOEXEC);
        errdefer _ = std.os.linux.close(fd);
        if (std.os.linux.errno(std.os.linux.ftruncate(fd, size)) != .SUCCESS) return error.ShmResizeFailed;
        var row: [640]u32 = @splat(pixel);
        if (width > row.len) return error.TestBufferTooWide;
        for (0..height) |y|
            if (std.c.pwrite(fd, @ptrCast(row[0..width].ptr), stride, @intCast(y * @as(usize, stride))) != stride)
                return error.ShmWriteFailed;
        const pool = try shm.createPool(fd, @intCast(size));
        errdefer pool.destroy();
        return .{ .fd = fd, .pool = pool, .buffer = try pool.createBuffer(0, @intCast(width), @intCast(height), @intCast(stride), .argb8888) };
    }

    fn registryEvent(registry: *client_wl.Registry, event: client_wl.Registry.Event, self: *@This()) void {
        switch (event) {
            .global => |global| {
                const interface = std.mem.span(global.interface);
                if (std.mem.eql(u8, interface, "wl_compositor")) self.compositor = registry.bind(global.name, client_wl.Compositor, @min(global.version, 6)) catch null else if (std.mem.eql(u8, interface, "wl_shm")) self.shm = registry.bind(global.name, client_wl.Shm, 1) catch null else if (std.mem.eql(u8, interface, "wl_output")) self.output = registry.bind(global.name, client_wl.Output, @min(global.version, 4)) catch null else if (std.mem.eql(u8, interface, "ext_session_lock_manager_v1")) {
                    self.manager_global_count += 1;
                    self.manager_global_version = global.version;
                    self.manager = registry.bind(global.name, client_ext.SessionLockManagerV1, 1) catch null;
                }
            },
            .global_remove => {},
        }
    }
    fn lockEvent(_: *client_ext.SessionLockV1, event: client_ext.SessionLockV1.Event, self: *@This()) void {
        switch (event) {
            .locked => _ = self.locked_count.fetchAdd(1, .acq_rel),
            .finished => {},
        }
    }
    fn lockSurfaceEvent(_: *client_ext.SessionLockSurfaceV1, event: client_ext.SessionLockSurfaceV1.Event, self: *@This()) void {
        switch (event) {
            .configure => |configure| {
                self.configure_serial = configure.serial;
                self.configure_width = configure.width;
                self.configure_height = configure.height;
            },
        }
    }
    fn pause(self: *@This(), value: Stage) !void {
        self.stage.store(@intFromEnum(value), .release);
        try waitForWayringCommand(self.command_fd);
    }
    fn closeWake(self: *@This(), replace: bool) void {
        const value = self.wake_fd.swap(if (replace) -2 else -1, .acq_rel);
        if (value >= 0) {
            if (replace) _ = std.os.linux.shutdown(value, std.os.linux.SHUT.RDWR);
            _ = std.os.linux.close(value);
        }
    }
    fn shutdown(self: *@This()) void {
        self.closeWake(true);
        signalWayringCommand(self.command_fd) catch {};
    }
};

const MatureWorkspaceClient = struct {
    const client_wl = wayland.client.wl;
    const client_ext = wayland.client.ext;
    const client_xdg = wayland.client.xdg;
    const Stage = enum(u8) { starting, connected, registry, initial, mapped, second_workspace, activated, child_destroyed, readvertised, finished, disconnected, failed };
    runtime_directory: []const u8,
    display_name: []const u8,
    command_fd: std.posix.fd_t,
    stage: std.atomic.Value(u8) = .init(@intFromEnum(Stage.starting)),
    wake_fd: std.atomic.Value(i32) = .init(-1),
    failure: ?anyerror = null,
    compositor: ?*client_wl.Compositor = null,
    shm: ?*client_wl.Shm = null,
    wm_base: ?*client_xdg.WmBase = null,
    manager: ?*client_ext.WorkspaceManagerV1 = null,
    output: ?*client_wl.Output = null,
    configure_serial: u32 = 0,
    manager_global_count: usize = 0,
    manager_global_version: u32 = 0,
    group_count: usize = 0,
    output_enter_count: usize = 0,
    workspace_count: usize = 0,
    done_count: usize = 0,
    finished_count: usize = 0,
    workspace_only_disconnect: bool = false,
    groups: [2]?*client_ext.WorkspaceGroupHandleV1 = .{ null, null },
    workspaces: [4]?*client_ext.WorkspaceHandleV1 = .{ null, null, null, null },
    names: [4][8]u8 = @splat(@splat(0)),
    name_lens: [4]usize = @splat(0),
    coordinates: [4]u32 = @splat(std.math.maxInt(u32)),
    active: [4]bool = @splat(false),
    activate_capable: [4]bool = @splat(false),
    removed: [4]bool = @splat(false),

    fn run(self: *@This()) void {
        self.runFallible() catch |err| {
            self.failure = err;
            self.stage.store(@intFromEnum(Stage.failed), .release);
            return;
        };
        self.stage.store(@intFromEnum(Stage.disconnected), .release);
    }
    fn runFallible(self: *@This()) !void {
        const path = try std.fmt.allocPrintSentinel(std.heap.page_allocator, "{s}/{s}", .{ self.runtime_directory, self.display_name }, 0);
        defer std.heap.page_allocator.free(path);
        const fd = try connectWayringTestSocket(path);
        var fd_owned = true;
        defer if (fd_owned) {
            _ = std.os.linux.close(fd);
        };
        const raw_wake = std.os.linux.dup(fd);
        if (std.os.linux.errno(raw_wake) != .SUCCESS) return error.WakeFdFailed;
        const wake: i32 = @intCast(raw_wake);
        if (self.wake_fd.cmpxchgStrong(-1, wake, .acq_rel, .acquire)) |_| return error.ClientShutdown;
        defer self.closeWake(false);
        const display = try client_wl.Display.connectToFd(fd);
        fd_owned = false;
        defer display.disconnect();
        self.stage.store(@intFromEnum(Stage.connected), .release);
        const registry = try display.getRegistry();
        defer registry.destroy();
        registry.setListener(*@This(), registryEvent, self);
        self.stage.store(@intFromEnum(Stage.registry), .release);
        try expectClientRoundtrip(display);
        const manager = self.manager orelse return error.WorkspaceManagerMissing;
        // Registry callback binds are ordered before this second sync.
        try expectClientRoundtrip(display);
        if (self.output == null or self.done_count != 1 or self.workspace_count != 1) return error.InitialWorkspaceSnapshotMismatch;
        try self.pause(.initial);
        if (self.workspace_only_disconnect) {
            for (&self.groups) |*group| if (group.*) |value| {
                value.destroy();
                group.* = null;
            };
            try expectClientRoundtrip(display);
            manager.stop();
            while (self.finished_count == 0) try expectClientRoundtrip(display);
            self.stage.store(@intFromEnum(Stage.finished), .release);
            try waitForWayringCommand(self.command_fd);
            return;
        }

        const compositor = self.compositor orelse return error.CompositorMissing;
        defer compositor.destroy();
        const shm = self.shm orelse return error.ShmMissing;
        defer shm.release();
        const wm_base = self.wm_base orelse return error.XdgWmBaseMissing;
        defer wm_base.destroy();
        wm_base.setListener(*@This(), wmBaseEvent, self);
        const surface = try compositor.createSurface();
        defer surface.destroy();
        const xdg_surface = try wm_base.getXdgSurface(surface);
        defer xdg_surface.destroy();
        xdg_surface.setListener(*@This(), xdgSurfaceEvent, self);
        const toplevel = try xdg_surface.getToplevel();
        defer toplevel.destroy();
        toplevel.setListener(*@This(), toplevelEvent, self);
        toplevel.setAppId("org.keywork.workspace-test");
        surface.commit();
        while (self.configure_serial == 0) try expectClientRoundtrip(display);
        const buffer = try createClipboardBuffer(shm, 0xff4d_78cc);
        defer buffer.buffer.destroy();
        defer buffer.pool.destroy();
        defer _ = std.os.linux.close(buffer.fd);
        surface.attach(buffer.buffer, 0, 0);
        surface.damageBuffer(0, 0, 1, 1);
        surface.commit();
        try expectClientRoundtrip(display);
        try self.pause(.mapped);

        while (self.workspace_count < 2 or self.done_count < 2) try expectClientRoundtrip(display);
        self.stage.store(@intFromEnum(Stage.second_workspace), .release);
        try waitForWayringCommand(self.command_fd);
        const first = self.workspaces[0] orelse return error.FirstWorkspaceMissing;
        first.activate();
        manager.commit();
        while (!self.active[0] or self.done_count < 3) try expectClientRoundtrip(display);
        try self.pause(.activated);
        first.destroy();
        try expectClientRoundtrip(display);
        try self.pause(.child_destroyed);
        while (self.workspace_count < 3 or self.done_count < 4) try expectClientRoundtrip(display);
        try self.pause(.readvertised);
        manager.stop();
        while (self.finished_count == 0) try expectClientRoundtrip(display);
        self.stage.store(@intFromEnum(Stage.finished), .release);
        try waitForWayringCommand(self.command_fd);
        // Leave every remaining group/workspace child alive. Returning closes
        // the display abruptly after stop/finished so production disconnect
        // cleanup must tear down the managerless binding child-first.
    }
    fn registryEvent(registry: *client_wl.Registry, event: client_wl.Registry.Event, self: *@This()) void {
        switch (event) {
            .global => |global| {
                const interface = std.mem.span(global.interface);
                if (std.mem.eql(u8, interface, "wl_compositor")) self.compositor = registry.bind(global.name, client_wl.Compositor, @min(global.version, 6)) catch null else if (std.mem.eql(u8, interface, "wl_shm")) self.shm = registry.bind(global.name, client_wl.Shm, 1) catch null else if (std.mem.eql(u8, interface, "xdg_wm_base")) self.wm_base = registry.bind(global.name, client_xdg.WmBase, @min(global.version, 7)) catch null else if (std.mem.eql(u8, interface, "wl_output")) self.output = registry.bind(global.name, client_wl.Output, @min(global.version, 4)) catch null else if (std.mem.eql(u8, interface, "ext_workspace_manager_v1")) {
                    self.manager_global_count += 1;
                    self.manager_global_version = global.version;
                    self.manager = registry.bind(global.name, client_ext.WorkspaceManagerV1, 1) catch null;
                    if (self.manager) |manager| manager.setListener(*@This(), managerEvent, self);
                }
            },
            .global_remove => {},
        }
    }
    fn wmBaseEvent(wm_base: *client_xdg.WmBase, event: client_xdg.WmBase.Event, _: *@This()) void {
        switch (event) {
            .ping => |ping| wm_base.pong(ping.serial),
        }
    }
    fn xdgSurfaceEvent(xdg_surface: *client_xdg.Surface, event: client_xdg.Surface.Event, self: *@This()) void {
        switch (event) {
            .configure => |configure| {
                self.configure_serial = configure.serial;
                xdg_surface.ackConfigure(configure.serial);
            },
        }
    }
    fn toplevelEvent(_: *client_xdg.Toplevel, _: client_xdg.Toplevel.Event, _: *@This()) void {}
    fn managerEvent(_: *client_ext.WorkspaceManagerV1, event: client_ext.WorkspaceManagerV1.Event, self: *@This()) void {
        switch (event) {
            .workspace_group => |value| {
                const index = self.group_count;
                if (index < self.groups.len) self.groups[index] = value.workspace_group;
                self.group_count += 1;
                value.workspace_group.setListener(*@This(), groupEvent, self);
            },
            .workspace => |value| {
                const index = self.workspace_count;
                if (index < self.workspaces.len) self.workspaces[index] = value.workspace;
                self.workspace_count += 1;
                value.workspace.setListener(*@This(), workspaceEvent, self);
            },
            .done => self.done_count += 1,
            .finished => self.finished_count += 1,
        }
    }
    fn groupEvent(_: *client_ext.WorkspaceGroupHandleV1, event: client_ext.WorkspaceGroupHandleV1.Event, self: *@This()) void {
        switch (event) {
            .output_enter => self.output_enter_count += 1,
            else => {},
        }
    }
    fn workspaceIndex(self: *@This(), resource: *client_ext.WorkspaceHandleV1) ?usize {
        for (self.workspaces, 0..) |candidate, index| if (candidate == resource) return index;
        return null;
    }
    fn workspaceEvent(resource: *client_ext.WorkspaceHandleV1, event: client_ext.WorkspaceHandleV1.Event, self: *@This()) void {
        const index = self.workspaceIndex(resource) orelse return;
        switch (event) {
            .name => |value| {
                const name = std.mem.span(value.name);
                self.name_lens[index] = @min(name.len, self.names[index].len);
                @memcpy(self.names[index][0..self.name_lens[index]], name[0..self.name_lens[index]]);
            },
            .coordinates => |value| if (value.coordinates.size == @sizeOf(u32)) {
                self.coordinates[index] = @as(*align(1) const u32, @ptrCast(value.coordinates.data)).*;
            },
            .state => |value| self.active[index] = value.state.active,
            .capabilities => |value| self.activate_capable[index] = value.capabilities.activate,
            .removed => self.removed[index] = true,
            else => {},
        }
    }
    fn pause(self: *@This(), value: Stage) !void {
        self.stage.store(@intFromEnum(value), .release);
        try waitForWayringCommand(self.command_fd);
    }
    fn closeWake(self: *@This(), replace: bool) void {
        const value = self.wake_fd.swap(if (replace) -2 else -1, .acq_rel);
        if (value >= 0) {
            if (replace) _ = std.os.linux.shutdown(value, std.os.linux.SHUT.RDWR);
            _ = std.os.linux.close(value);
        }
    }
    fn shutdown(self: *@This()) void {
        self.closeWake(true);
        signalWayringCommand(self.command_fd) catch {};
    }
};

/// Scanner-generated session-lock client used through the production Wayring
/// transport. The mature implementation is protocol-identical client code;
/// this owner fixes the generated E2E's dimensions and distinctive contents.
const GeneratedSessionLockClient = struct {
    const Stage = MatureSessionLockClient.Stage;
    inner: MatureSessionLockClient,

    fn run(self: *@This()) void {
        self.inner.run();
    }
    fn shutdown(self: *@This()) void {
        self.inner.shutdown();
    }
};

const MatureDataDeviceClient = struct {
    const client_wl = wayland.client.wl;
    const client_ext = wayland.client.ext;
    const Role = enum { source, target, dnd_source, dnd_target, offender };
    const Stage = enum(u8) {
        starting,
        ready,
        selection_set,
        control_selection_ready,
        late_mime_offered,
        late_mime_received,
        selection_sent,
        selection_received,
        selection_replaced,
        stale_mime_offered,
        stale_mime_checked,
        stale_clear_checked,
        selection_cleared,
        drag_rejected,
        drag_started,
        icon_destroyed,
        drag_received,
        drop_finished,
        source_finished,
        offender_ready,
        disconnected,
        failed,
    };
    const EventTag = enum {
        data_offer,
        offer_mime,
        source_actions,
        action,
        selection,
        enter,
        motion,
        drop,
        leave,
        target,
        send,
        cancelled,
        drop_performed,
        finished,
    };
    const ControlEventTag = enum { data_offer, initial_mime, selection, late_mime };
    const mime_type: [:0]const u8 = "text/plain;charset=utf-8";
    const late_mime_type: [:0]const u8 = "text/html";
    const stale_mime_type: [:0]const u8 = "application/x-keywork-stale";
    const selection_bytes = "keywork mature clipboard\n";
    const drag_bytes = "keywork mature drag\n";

    runtime_directory: []const u8,
    display_name: []const u8,
    command_fd: std.posix.fd_t,
    role: Role,
    stage: std.atomic.Value(u8) = .init(@intFromEnum(Stage.starting)),
    wake_fd: std.atomic.Value(i32) = .init(-1),
    failure: ?anyerror = null,
    compositor: ?*client_wl.Compositor = null,
    shm: ?*client_wl.Shm = null,
    seat: ?*client_wl.Seat = null,
    manager: ?*client_wl.DataDeviceManager = null,
    control_manager: ?*client_ext.DataControlManagerV1 = null,
    control_device: ?*client_ext.DataControlDeviceV1 = null,
    control_pending_offer: ?*client_ext.DataControlOfferV1 = null,
    control_selection_offer: ?*client_ext.DataControlOfferV1 = null,
    surface_object_id: u32 = 0,
    icon_object_id: u32 = 0,
    source_object_id: u32 = 0,
    keyboard_serial: u32 = 0,
    pointer_serial: u32 = 0,
    pointer_enter_serial: u32 = 0,
    offer: ?*client_wl.DataOffer = null,
    selection_source: ?*client_wl.DataSource = null,
    drag_source: ?*client_wl.DataSource = null,
    events: [48]EventTag = undefined,
    event_count: usize = 0,
    cancelled_count: usize = 0,
    received: [64]u8 = undefined,
    received_len: usize = 0,
    enter_x: f64 = 0,
    enter_y: f64 = 0,
    motion_x: f64 = 0,
    motion_y: f64 = 0,
    control_events: [16]ControlEventTag = undefined,
    control_event_count: usize = 0,
    control_stale_mime_seen: bool = false,

    fn run(self: *@This()) void {
        self.runFallible() catch |err| {
            self.failure = err;
            self.stage.store(@intFromEnum(Stage.failed), .release);
            return;
        };
        self.stage.store(@intFromEnum(Stage.disconnected), .release);
    }

    fn runFallible(self: *@This()) !void {
        const path = try std.fmt.allocPrintSentinel(std.heap.page_allocator, "{s}/{s}", .{ self.runtime_directory, self.display_name }, 0);
        defer std.heap.page_allocator.free(path);
        const fd = try connectWayringTestSocket(path);
        var fd_owned = true;
        defer if (fd_owned) {
            _ = std.os.linux.close(fd);
        };
        const raw_wake_fd = std.os.linux.dup(fd);
        if (std.os.linux.errno(raw_wake_fd) != .SUCCESS) return error.WakeFdFailed;
        const wake_fd: i32 = @intCast(raw_wake_fd);
        if (self.wake_fd.cmpxchgStrong(-1, wake_fd, .acq_rel, .acquire)) |_| {
            _ = std.os.linux.close(wake_fd);
            return error.ClientShutdown;
        }
        defer self.closeWake(false);

        const display = try client_wl.Display.connectToFd(fd);
        fd_owned = false;
        defer display.disconnect();
        const registry = try display.getRegistry();
        defer registry.destroy();
        registry.setListener(*@This(), registryEvent, self);
        try expectClientRoundtrip(display);
        const manager = self.manager orelse return error.DataDeviceManagerMissing;
        defer manager.release();
        const control_manager = self.control_manager;
        defer if (control_manager) |value| value.destroy();
        if (self.role == .offender) {
            const source = try manager.createDataSource();
            defer source.destroy();
            self.source_object_id = source.getId();
            try expectClientRoundtrip(display);
            try self.pause(.offender_ready);
            source.setActions(@bitCast(@as(u32, 1 << 8)));
            expectClientRoundtrip(display) catch return;
            return error.ExpectedProtocolFailure;
        }
        const compositor = self.compositor orelse return error.CompositorMissing;
        defer compositor.destroy();
        const shm = self.shm orelse return error.ShmMissing;
        defer shm.release();
        const seat = self.seat orelse return error.SeatMissing;
        defer seat.release();
        defer if (self.control_device) |device| device.destroy();
        if (self.role == .target) {
            const control = control_manager orelse return error.DataControlManagerMissing;
            const device = try control.getDataDevice(seat);
            self.control_device = device;
            device.setListener(*@This(), controlDeviceEvent, self);
        }
        const pointer = try seat.getPointer();
        defer pointer.release();
        pointer.setListener(*@This(), pointerEvent, self);
        const keyboard = try seat.getKeyboard();
        defer keyboard.release();
        keyboard.setListener(*@This(), keyboardEvent, self);
        const device = try manager.getDataDevice(seat);
        var device_live = true;
        defer if (device_live) device.release();
        device.setListener(*@This(), deviceEvent, self);
        const surface = try compositor.createSurface();
        self.surface_object_id = surface.getId();
        defer surface.destroy();
        const surface_buffer = try createMatureTestBuffer(shm, if (self.role == .source or self.role == .dnd_source) 0xff22_4466 else 0xff66_4422);
        defer surface_buffer.buffer.destroy();
        defer surface_buffer.pool.destroy();
        defer _ = std.os.linux.close(surface_buffer.fd);
        surface.attach(surface_buffer.buffer, 0, 0);
        surface.damageBuffer(0, 0, 1, 1);
        surface.commit();
        try expectClientRoundtrip(display);
        try self.pause(.ready);

        switch (self.role) {
            .source => try self.runSource(display, manager, device, pointer, compositor, shm, surface),
            .target => try self.runTarget(display, manager, seat, device, &device_live),
            .dnd_source => try self.runDndSource(display, manager, device, compositor, shm, surface),
            .dnd_target => try self.runDndTarget(display, device),
            .offender => unreachable,
        }
    }

    fn runDndSource(
        self: *@This(),
        display: *client_wl.Display,
        manager: *client_wl.DataDeviceManager,
        device: *client_wl.DataDevice,
        compositor: *client_wl.Compositor,
        shm: *client_wl.Shm,
        surface: *client_wl.Surface,
    ) !void {
        try expectClientRoundtrip(display);
        if (self.pointer_serial == 0) return error.DragSerialMissing;
        const drag = try manager.createDataSource();
        self.drag_source = drag;
        defer drag.destroy();
        drag.setListener(*@This(), sourceEvent, self);
        drag.offer(mime_type);
        drag.setActions(.{ .copy = true });
        const icon = try compositor.createSurface();
        self.icon_object_id = icon.getId();
        defer icon.destroy();
        const icon_buffer = try createMatureTestBuffer(shm, 0xff33_aa55);
        defer icon_buffer.buffer.destroy();
        defer icon_buffer.pool.destroy();
        defer _ = std.os.linux.close(icon_buffer.fd);
        icon.attach(icon_buffer.buffer, 0, 0);
        icon.damageBuffer(0, 0, 1, 1);
        icon.commit();
        device.startDrag(drag, surface, icon, self.pointer_serial);
        try expectClientRoundtrip(display);
        try self.pause(.drag_started);

        while (self.eventIndex(.send) == null) try expectClientRoundtrip(display);
        try self.pause(.drag_received);
        try expectClientRoundtrip(display);
        if (self.eventIndex(.drop_performed) == null) return error.DropPerformedMissing;
        try self.pause(.drop_finished);
        try expectClientRoundtrip(display);
        if (self.eventIndex(.finished) == null) return error.FinishedMissing;
        try self.pause(.source_finished);
    }

    fn runDndTarget(
        self: *@This(),
        display: *client_wl.Display,
        device: *client_wl.DataDevice,
    ) !void {
        try expectClientRoundtrip(display);
        const drag_offer = self.offer orelse return error.DragOfferMissing;
        drag_offer.setActions(.{ .copy = true }, .{ .copy = true });
        drag_offer.accept(self.pointer_serial, mime_type);
        var drag_pipe: [2]std.posix.fd_t = undefined;
        if (std.c.pipe(&drag_pipe) != 0) return error.PipeFailed;
        var read_open = true;
        defer if (read_open) {
            _ = std.os.linux.close(drag_pipe[0]);
        };
        drag_offer.receive(mime_type, drag_pipe[1]);
        try closeMatureTransferFd(drag_pipe[1]);
        try expectClientRoundtrip(display);
        try self.pause(.drag_received);
        try expectClientRoundtrip(display);
        if (eventIndex(self, .drop) == null or eventIndex(self, .leave) == null)
            return error.DropChronologyMissing;
        self.received_len = try readMatureTransfer(drag_pipe[0], &self.received);
        try closeMatureTransferFd(drag_pipe[0]);
        read_open = false;
        if (!std.mem.eql(u8, self.received[0..self.received_len], WayringDndClient.drag_bytes))
            return error.DragBytesMismatch;
        drag_offer.finish();
        try expectClientRoundtrip(display);
        try self.pause(.drop_finished);
        _ = device;
    }

    fn runSource(
        self: *@This(),
        display: *client_wl.Display,
        manager: *client_wl.DataDeviceManager,
        device: *client_wl.DataDevice,
        pointer: *client_wl.Pointer,
        compositor: *client_wl.Compositor,
        shm: *client_wl.Shm,
        surface: *client_wl.Surface,
    ) !void {
        try expectClientRoundtrip(display);
        if (self.keyboard_serial == 0) return error.SelectionSerialMissing;
        const selection = try manager.createDataSource();
        self.selection_source = selection;
        defer selection.destroy();
        selection.setListener(*@This(), sourceEvent, self);
        selection.offer(mime_type);
        device.setSelection(selection, self.keyboard_serial);
        try expectClientRoundtrip(display);
        try self.pause(.selection_set);
        selection.offer(late_mime_type);
        try expectClientRoundtrip(display);
        try self.pause(.late_mime_offered);

        while (self.eventCount(.send) == 0) try expectClientRoundtrip(display);
        try self.pause(.selection_sent);

        try expectClientRoundtrip(display);
        if (self.cancelled_count != 1) return error.SelectionCancellationMissing;
        selection.offer(stale_mime_type);
        try expectClientRoundtrip(display);
        try self.pause(.stale_mime_offered);
        device.setSelection(null, self.keyboard_serial);
        try expectClientRoundtrip(display);
        try self.pause(.stale_clear_checked);

        try expectClientRoundtrip(display);
        try self.pause(.selection_cleared);

        try expectClientRoundtrip(display);
        if (self.pointer_serial == 0) return error.DragSerialMissing;
        const drag = try manager.createDataSource();
        self.drag_source = drag;
        defer drag.destroy();
        drag.setListener(*@This(), sourceEvent, self);
        drag.offer(mime_type);
        drag.setActions(.{ .copy = true });
        const conflicting_icon = try compositor.createSurface();
        defer conflicting_icon.destroy();
        pointer.setCursor(self.pointer_enter_serial, conflicting_icon, 0, 0);
        try expectClientRoundtrip(display);
        device.startDrag(drag, surface, conflicting_icon, self.pointer_serial +% 1);
        try expectClientRoundtrip(display);
        try self.pause(.drag_rejected);
        const icon = try compositor.createSurface();
        self.icon_object_id = icon.getId();
        var icon_live = true;
        defer if (icon_live) icon.destroy();
        const icon_buffer = try createMatureTestBuffer(shm, 0xff33_aa55);
        defer icon_buffer.buffer.destroy();
        defer icon_buffer.pool.destroy();
        defer _ = std.os.linux.close(icon_buffer.fd);
        icon.attach(icon_buffer.buffer, 0, 0);
        icon.damageBuffer(0, 0, 1, 1);
        icon.commit();
        device.startDrag(drag, surface, icon, self.pointer_serial);
        try expectClientRoundtrip(display);
        try self.pause(.drag_started);
        icon.destroy();
        icon_live = false;
        try expectClientRoundtrip(display);
        try self.pause(.icon_destroyed);

        while (self.eventCount(.send) < 2) try expectClientRoundtrip(display);
        try self.pause(.drag_received);
        try expectClientRoundtrip(display);
        if (eventIndex(self, .drop_performed) == null) return error.DropPerformedMissing;
        try self.pause(.drop_finished);
        try expectClientRoundtrip(display);
        if (eventIndex(self, .finished) == null) return error.FinishedMissing;
        try self.pause(.source_finished);
    }

    fn runTarget(
        self: *@This(),
        display: *client_wl.Display,
        manager: *client_wl.DataDeviceManager,
        seat: *client_wl.Seat,
        selection_device: *client_wl.DataDevice,
        selection_device_live: *bool,
    ) !void {
        try expectClientRoundtrip(display);
        if (self.controlEventIndex(.data_offer) == null or self.controlEventIndex(.initial_mime) == null or
            self.controlEventIndex(.selection) == null) return error.ControlSelectionChronologyMissing;
        try self.pause(.control_selection_ready);
        try expectClientRoundtrip(display);
        if (self.controlEventIndex(.late_mime) == null) return error.ControlLateMimeMissing;
        try self.pause(.late_mime_received);
        try expectClientRoundtrip(display);
        const selection_offer = self.offer orelse return error.SelectionOfferMissing;
        selection_device.release();
        selection_device_live.* = false;
        try expectClientRoundtrip(display);
        var pipe_fds: [2]std.posix.fd_t = undefined;
        if (std.c.pipe(&pipe_fds) != 0) return error.PipeFailed;
        var read_open = true;
        defer {
            if (read_open) _ = std.os.linux.close(pipe_fds[0]);
        }
        selection_offer.receive(mime_type, pipe_fds[1]);
        try closeMatureTransferFd(pipe_fds[1]);
        try expectClientRoundtrip(display);
        self.received_len = try readMatureTransfer(pipe_fds[0], &self.received);
        try closeMatureTransferFd(pipe_fds[0]);
        read_open = false;
        if (!std.mem.eql(u8, self.received[0..self.received_len], selection_bytes)) return error.SelectionBytesMismatch;
        try self.pause(.selection_received);

        const device = try manager.getDataDevice(seat);
        var device_live = true;
        defer if (device_live) device.release();
        device.setListener(*@This(), deviceEvent, self);
        try expectClientRoundtrip(display);
        if (self.keyboard_serial == 0) return error.ReplacementSerialMissing;
        const replacement = try manager.createDataSource();
        defer replacement.destroy();
        replacement.setListener(*@This(), sourceEvent, self);
        replacement.offer(mime_type);
        device.setSelection(replacement, self.keyboard_serial);
        try expectClientRoundtrip(display);
        try self.pause(.selection_replaced);
        try expectClientRoundtrip(display);
        if (self.control_stale_mime_seen) return error.ControlStaleMimeForwarded;
        try self.pause(.stale_mime_checked);
        device.setSelection(null, self.keyboard_serial);
        try expectClientRoundtrip(display);
        if (self.cancelled_count != 1) return error.ReplacementCancellationMissing;
        try self.pause(.selection_cleared);

        try expectClientRoundtrip(display);
        const drag_offer = self.offer orelse return error.DragOfferMissing;
        drag_offer.setActions(.{ .copy = true }, .{ .copy = true });
        drag_offer.accept(self.pointer_serial, mime_type);
        var drag_pipe: [2]std.posix.fd_t = undefined;
        if (std.c.pipe(&drag_pipe) != 0) return error.PipeFailed;
        var drag_read_open = true;
        defer {
            if (drag_read_open) _ = std.os.linux.close(drag_pipe[0]);
        }
        drag_offer.receive(mime_type, drag_pipe[1]);
        try closeMatureTransferFd(drag_pipe[1]);
        try expectClientRoundtrip(display);
        self.received_len = try readMatureTransfer(drag_pipe[0], &self.received);
        try closeMatureTransferFd(drag_pipe[0]);
        drag_read_open = false;
        if (!std.mem.eql(u8, self.received[0..self.received_len], drag_bytes)) return error.DragBytesMismatch;
        try self.pause(.drag_received);
        try expectClientRoundtrip(display);
        if (eventIndex(self, .drop) == null or eventIndex(self, .leave) == null) return error.DropChronologyMissing;
        device.release();
        device_live = false;
        try expectClientRoundtrip(display);
        drag_offer.finish();
        try expectClientRoundtrip(display);
        try self.pause(.drop_finished);
    }

    const TestBuffer = struct {
        fd: std.posix.fd_t,
        pool: *client_wl.ShmPool,
        buffer: *client_wl.Buffer,
    };

    fn createMatureTestBuffer(shm: *client_wl.Shm, pixel: u32) !TestBuffer {
        const fd = try std.posix.memfd_create("keywork-mature-data-device", std.os.linux.MFD.CLOEXEC);
        errdefer _ = std.os.linux.close(fd);
        if (std.os.linux.errno(std.os.linux.ftruncate(fd, @sizeOf(u32))) != .SUCCESS) return error.ShmResizeFailed;
        if (std.c.pwrite(fd, @ptrCast(&pixel), @sizeOf(u32), 0) != @sizeOf(u32)) return error.ShmWriteFailed;
        const pool = try shm.createPool(fd, @sizeOf(u32));
        errdefer pool.destroy();
        return .{ .fd = fd, .pool = pool, .buffer = try pool.createBuffer(0, 1, 1, @sizeOf(u32), .argb8888) };
    }

    fn append(self: *@This(), tag: EventTag) void {
        if (self.event_count == self.events.len) return;
        self.events[self.event_count] = tag;
        self.event_count += 1;
    }
    fn eventIndex(self: *const @This(), tag: EventTag) ?usize {
        for (self.events[0..self.event_count], 0..) |event, index| if (event == tag) return index;
        return null;
    }
    fn eventIndexAfter(self: *const @This(), tag: EventTag, start: usize) ?usize {
        for (self.events[start..self.event_count], start..) |event, index| if (event == tag) return index;
        return null;
    }
    fn eventCount(self: *const @This(), tag: EventTag) usize {
        var count: usize = 0;
        for (self.events[0..self.event_count]) |event| if (event == tag) {
            count += 1;
        };
        return count;
    }
    fn appendControl(self: *@This(), tag: ControlEventTag) void {
        if (self.control_event_count == self.control_events.len) return;
        self.control_events[self.control_event_count] = tag;
        self.control_event_count += 1;
    }
    fn controlEventIndex(self: *const @This(), tag: ControlEventTag) ?usize {
        for (self.control_events[0..self.control_event_count], 0..) |event, index| if (event == tag) return index;
        return null;
    }
    fn registryEvent(registry: *client_wl.Registry, event: client_wl.Registry.Event, self: *@This()) void {
        switch (event) {
            .global => |global| {
                const interface = std.mem.span(global.interface);
                if (std.mem.eql(u8, interface, "wl_compositor")) self.compositor = registry.bind(global.name, client_wl.Compositor, @min(global.version, 6)) catch null else if (std.mem.eql(u8, interface, "wl_shm")) self.shm = registry.bind(global.name, client_wl.Shm, 1) catch null else if (std.mem.eql(u8, interface, "wl_seat")) self.seat = registry.bind(global.name, client_wl.Seat, @min(global.version, 10)) catch null else if (std.mem.eql(u8, interface, "wl_data_device_manager")) self.manager = registry.bind(global.name, client_wl.DataDeviceManager, 3) catch null else if (std.mem.eql(u8, interface, "ext_data_control_manager_v1")) self.control_manager = registry.bind(global.name, client_ext.DataControlManagerV1, 1) catch null;
            },
            .global_remove => {},
        }
    }
    fn keyboardEvent(_: *client_wl.Keyboard, event: client_wl.Keyboard.Event, self: *@This()) void {
        switch (event) {
            .keymap => |keymap| _ = std.os.linux.close(keymap.fd),
            .enter => |enter| self.keyboard_serial = enter.serial,
            else => {},
        }
    }
    fn pointerEvent(_: *client_wl.Pointer, event: client_wl.Pointer.Event, self: *@This()) void {
        switch (event) {
            .enter => |enter| {
                self.pointer_serial = enter.serial;
                self.pointer_enter_serial = enter.serial;
            },
            .button => |button| if (button.state == .pressed) {
                self.pointer_serial = button.serial;
            },
            else => {},
        }
    }
    fn deviceEvent(_: *client_wl.DataDevice, event: client_wl.DataDevice.Event, self: *@This()) void {
        switch (event) {
            .data_offer => |data| {
                self.append(.data_offer);
                self.offer = data.id;
                data.id.setListener(*@This(), offerEvent, self);
            },
            .selection => self.append(.selection),
            .enter => |enter| {
                self.pointer_serial = enter.serial;
                self.offer = enter.id;
                self.enter_x = enter.x.toDouble();
                self.enter_y = enter.y.toDouble();
                self.append(.enter);
            },
            .motion => |motion| {
                self.motion_x = motion.x.toDouble();
                self.motion_y = motion.y.toDouble();
                self.append(.motion);
            },
            .drop => self.append(.drop),
            .leave => self.append(.leave),
        }
    }
    fn offerEvent(_: *client_wl.DataOffer, event: client_wl.DataOffer.Event, self: *@This()) void {
        switch (event) {
            .offer => self.append(.offer_mime),
            .source_actions => self.append(.source_actions),
            .action => self.append(.action),
        }
    }
    fn sourceEvent(_: *client_wl.DataSource, event: client_wl.DataSource.Event, self: *@This()) void {
        switch (event) {
            .target => self.append(.target),
            .send => |send| {
                self.append(.send);
                const bytes = if (self.drag_source != null) drag_bytes else selection_bytes;
                std.debug.assert(std.c.write(send.fd, bytes.ptr, bytes.len) == bytes.len);
                closeMatureTransferFd(send.fd) catch unreachable;
            },
            .cancelled => {
                self.cancelled_count += 1;
                self.append(.cancelled);
            },
            .dnd_drop_performed => self.append(.drop_performed),
            .dnd_finished => self.append(.finished),
            .action => self.append(.action),
        }
    }
    fn controlDeviceEvent(_: *client_ext.DataControlDeviceV1, event: client_ext.DataControlDeviceV1.Event, self: *@This()) void {
        switch (event) {
            .data_offer => |data| {
                self.control_pending_offer = data.id;
                data.id.setListener(*@This(), controlOfferEvent, self);
                self.appendControl(.data_offer);
            },
            .selection => |selection| {
                self.control_selection_offer = selection.id;
                self.control_pending_offer = null;
                if (selection.id != null) self.appendControl(.selection);
            },
            .primary_selection, .finished => {},
        }
    }
    fn controlOfferEvent(_: *client_ext.DataControlOfferV1, event: client_ext.DataControlOfferV1.Event, self: *@This()) void {
        switch (event) {
            .offer => |offer| {
                const mime = std.mem.span(offer.mime_type);
                if (std.mem.eql(u8, mime, mime_type)) self.appendControl(.initial_mime);
                if (std.mem.eql(u8, mime, late_mime_type)) self.appendControl(.late_mime);
                if (std.mem.eql(u8, mime, stale_mime_type)) self.control_stale_mime_seen = true;
            },
        }
    }
    fn pause(self: *@This(), stage_value: Stage) !void {
        self.stage.store(@intFromEnum(stage_value), .release);
        try waitForWayringCommand(self.command_fd);
    }
    fn closeWake(self: *@This(), shutdown_requested: bool) void {
        const fd = self.wake_fd.swap(-2, .acq_rel);
        if (fd < 0) return;
        if (shutdown_requested) _ = std.os.linux.shutdown(fd, std.os.linux.SHUT.RDWR);
        _ = std.os.linux.close(fd);
    }
    fn shutdown(self: *@This()) void {
        signalWayringCommand(self.command_fd) catch {};
        self.closeWake(true);
    }
};

fn PrimarySelectionTestClient(comptime app_id: [:0]const u8, comptime pixel: u32) type {
    const application_id = app_id;
    const surface_pixel = pixel;
    return struct {
        const client_wl = wayland.client.wl;
        const client_xdg = wayland.client.xdg;
        const client_zwp = wayland.client.zwp;

        const Stage = enum(u8) { starting, ready, focused, selected, stale_ignored, late_offered, receive_requested, sent, received, replaced, cleared, released, disconnected, failed };
        const ClientCommand = enum(u8) { wait, focus, select, stale_clear, offer_late, serve, receive, replace, clear, release };
        const mime_type: [:0]const u8 = "text/plain;charset=utf-8";
        const late_mime_type: [:0]const u8 = "text/html";
        const generated_bytes = "generated primary selection\n";
        const mature_bytes = "mature primary selection\n";

        runtime_directory: []const u8,
        display_name: []const u8,
        command_fd: std.posix.fd_t,
        payload: []const u8,
        stage: std.atomic.Value(u8) = .init(@intFromEnum(Stage.starting)),
        command: std.atomic.Value(u8) = .init(@intFromEnum(ClientCommand.wait)),
        wake_fd: std.atomic.Value(i32) = .init(-1),
        failure: ?anyerror = null,
        compositor: ?*client_wl.Compositor = null,
        shm: ?*client_wl.Shm = null,
        seat: ?*client_wl.Seat = null,
        wm_base: ?*client_xdg.WmBase = null,
        manager: ?*client_zwp.PrimarySelectionDeviceManagerV1 = null,
        device: ?*client_zwp.PrimarySelectionDeviceV1 = null,
        source: ?*client_zwp.PrimarySelectionSourceV1 = null,
        offer: ?*client_zwp.PrimarySelectionOfferV1 = null,
        keyboard_serial: u32 = 0,
        configure_serial: u32 = 0,
        surface_object_id: u32 = 0,
        mime_count: usize = 0,
        late_mime_count: usize = 0,
        selection_count: usize = 0,
        null_selection_count: usize = 0,
        send_count: usize = 0,
        cancelled_count: usize = 0,
        received: [128]u8 = undefined,
        received_len: usize = 0,

        fn run(self: *@This()) void {
            self.runFallible() catch |err| {
                self.failure = err;
                self.stage.store(@intFromEnum(Stage.failed), .release);
                return;
            };
            self.stage.store(@intFromEnum(Stage.disconnected), .release);
        }

        fn runFallible(self: *@This()) !void {
            const path = try std.fmt.allocPrintSentinel(std.heap.page_allocator, "{s}/{s}", .{ self.runtime_directory, self.display_name }, 0);
            defer std.heap.page_allocator.free(path);
            const fd = try connectWayringTestSocket(path);
            var fd_owned = true;
            defer if (fd_owned) {
                _ = std.os.linux.close(fd);
            };
            const raw_wake_fd = std.os.linux.dup(fd);
            if (std.os.linux.errno(raw_wake_fd) != .SUCCESS) return error.WakeFdFailed;
            const wake_fd: i32 = @intCast(raw_wake_fd);
            if (self.wake_fd.cmpxchgStrong(-1, wake_fd, .acq_rel, .acquire)) |_| {
                _ = std.os.linux.close(wake_fd);
                return error.ClientShutdown;
            }
            defer self.closeWake(false);

            const display = try client_wl.Display.connectToFd(fd);
            fd_owned = false;
            defer display.disconnect();
            const registry = try display.getRegistry();
            defer registry.destroy();
            registry.setListener(*@This(), registryEvent, self);
            try expectClientRoundtrip(display);
            const compositor = self.compositor orelse return error.CompositorMissing;
            defer compositor.destroy();
            const shm = self.shm orelse return error.ShmMissing;
            defer shm.release();
            const seat = self.seat orelse return error.SeatMissing;
            defer seat.release();
            const wm_base = self.wm_base orelse return error.XdgWmBaseMissing;
            defer wm_base.destroy();
            wm_base.setListener(*@This(), wmBaseEvent, self);
            const manager = self.manager orelse return error.PrimarySelectionManagerMissing;
            defer manager.destroy();
            const keyboard = try seat.getKeyboard();
            defer keyboard.release();
            keyboard.setListener(*@This(), keyboardEvent, self);
            const device = try manager.getDevice(seat);
            self.device = device;
            defer device.destroy();
            device.setListener(*@This(), deviceEvent, self);
            const surface = try compositor.createSurface();
            self.surface_object_id = surface.getId();
            defer surface.destroy();
            const xdg_surface = try wm_base.getXdgSurface(surface);
            defer xdg_surface.destroy();
            xdg_surface.setListener(*@This(), xdgSurfaceEvent, self);
            const toplevel = try xdg_surface.getToplevel();
            defer toplevel.destroy();
            toplevel.setListener(*@This(), toplevelEvent, self);
            toplevel.setAppId(application_id);
            surface.commit();
            while (self.configure_serial == 0) try expectClientRoundtrip(display);
            const buffer = try createClipboardBuffer(shm, surface_pixel);
            defer buffer.buffer.destroy();
            defer buffer.pool.destroy();
            defer _ = std.os.linux.close(buffer.fd);
            surface.attach(buffer.buffer, 0, 0);
            surface.damageBuffer(0, 0, 1, 1);
            surface.commit();
            try expectClientRoundtrip(display);
            try self.pause(.ready);

            while (true) {
                const command: ClientCommand = @enumFromInt(self.command.swap(@intFromEnum(ClientCommand.wait), .acq_rel));
                switch (command) {
                    .wait => return,
                    .focus => {
                        try expectClientRoundtrip(display);
                        if (self.keyboard_serial == 0) return error.PrimaryFocusSerialMissing;
                        try self.pause(.focused);
                    },
                    .select => {
                        if (self.keyboard_serial == 0) return error.PrimaryFocusSerialMissing;
                        if (self.source) |old| old.destroy();
                        const source = try manager.createSource();
                        self.source = source;
                        source.setListener(*@This(), sourceEvent, self);
                        source.offer(mime_type);
                        device.setSelection(source, self.keyboard_serial);
                        try expectClientRoundtrip(display);
                        try self.pause(.selected);
                    },
                    .stale_clear => {
                        if (self.keyboard_serial < 2) return error.PrimaryFocusSerialMissing;
                        device.setSelection(null, self.keyboard_serial - 1);
                        try expectClientRoundtrip(display);
                        try self.pause(.stale_ignored);
                    },
                    .offer_late => {
                        (self.source orelse return error.PrimarySourceMissing).offer(late_mime_type);
                        try expectClientRoundtrip(display);
                        try self.pause(.late_offered);
                    },
                    .serve => {
                        try expectClientRoundtrip(display);
                        if (self.send_count == 0) return error.PrimarySendMissing;
                        try self.pause(.sent);
                    },
                    .receive => {
                        try expectClientRoundtrip(display);
                        const selected_offer = self.offer orelse return error.PrimaryOfferMissing;
                        var pipe: [2]std.posix.fd_t = undefined;
                        if (std.c.pipe(&pipe) != 0) return error.PipeFailed;
                        var read_open = true;
                        defer if (read_open) {
                            _ = std.os.linux.close(pipe[0]);
                        };
                        selected_offer.receive(mime_type, pipe[1]);
                        try closeMatureTransferFd(pipe[1]);
                        try expectClientRoundtrip(display);
                        try self.pause(.receive_requested);
                        self.received_len = try readMatureTransfer(pipe[0], &self.received);
                        try closeMatureTransferFd(pipe[0]);
                        read_open = false;
                        try self.pause(.received);
                    },
                    .replace => {
                        const replacement = try manager.createSource();
                        replacement.setListener(*@This(), sourceEvent, self);
                        replacement.offer(mime_type);
                        device.setSelection(replacement, self.keyboard_serial);
                        try expectClientRoundtrip(display);
                        if (self.source) |old| old.destroy();
                        self.source = replacement;
                        try self.pause(.replaced);
                    },
                    .clear => {
                        device.setSelection(null, self.keyboard_serial);
                        try expectClientRoundtrip(display);
                        try self.pause(.cleared);
                    },
                    .release => {
                        if (self.offer) |offer| {
                            offer.destroy();
                            self.offer = null;
                        }
                        if (self.source) |source| {
                            source.destroy();
                            self.source = null;
                        }
                        self.device = null;
                        self.manager = null;
                        try self.pause(.released);
                        return;
                    },
                }
            }
        }

        fn registryEvent(registry: *client_wl.Registry, event: client_wl.Registry.Event, self: *@This()) void {
            switch (event) {
                .global => |global| {
                    const interface = std.mem.span(global.interface);
                    if (std.mem.eql(u8, interface, "wl_compositor")) self.compositor = registry.bind(global.name, client_wl.Compositor, @min(global.version, 6)) catch null else if (std.mem.eql(u8, interface, "wl_shm")) self.shm = registry.bind(global.name, client_wl.Shm, 1) catch null else if (std.mem.eql(u8, interface, "wl_seat")) self.seat = registry.bind(global.name, client_wl.Seat, @min(global.version, 10)) catch null else if (std.mem.eql(u8, interface, "xdg_wm_base")) self.wm_base = registry.bind(global.name, client_xdg.WmBase, @min(global.version, 7)) catch null else if (std.mem.eql(u8, interface, "zwp_primary_selection_device_manager_v1")) self.manager = registry.bind(global.name, client_zwp.PrimarySelectionDeviceManagerV1, 1) catch null;
                },
                .global_remove => {},
            }
        }
        fn wmBaseEvent(wm_base: *client_xdg.WmBase, event: client_xdg.WmBase.Event, _: *@This()) void {
            switch (event) {
                .ping => |ping| wm_base.pong(ping.serial),
            }
        }
        fn xdgSurfaceEvent(xdg_surface: *client_xdg.Surface, event: client_xdg.Surface.Event, self: *@This()) void {
            switch (event) {
                .configure => |configure| {
                    self.configure_serial = configure.serial;
                    xdg_surface.ackConfigure(configure.serial);
                },
            }
        }
        fn toplevelEvent(_: *client_xdg.Toplevel, _: client_xdg.Toplevel.Event, _: *@This()) void {}
        fn keyboardEvent(_: *client_wl.Keyboard, event: client_wl.Keyboard.Event, self: *@This()) void {
            switch (event) {
                .keymap => |keymap| _ = std.os.linux.close(keymap.fd),
                .enter => |enter| self.keyboard_serial = enter.serial,
                else => {},
            }
        }
        fn deviceEvent(_: *client_zwp.PrimarySelectionDeviceV1, event: client_zwp.PrimarySelectionDeviceV1.Event, self: *@This()) void {
            switch (event) {
                .data_offer => |data| data.offer.setListener(*@This(), offerEvent, self),
                .selection => |selection| {
                    self.selection_count += 1;
                    if (selection.id == null) self.null_selection_count += 1;
                    self.offer = selection.id;
                },
            }
        }
        fn offerEvent(_: *client_zwp.PrimarySelectionOfferV1, event: client_zwp.PrimarySelectionOfferV1.Event, self: *@This()) void {
            switch (event) {
                .offer => |offer| if (std.mem.eql(u8, std.mem.span(offer.mime_type), late_mime_type)) {
                    self.late_mime_count += 1;
                } else {
                    self.mime_count += 1;
                },
            }
        }
        fn sourceEvent(_: *client_zwp.PrimarySelectionSourceV1, event: client_zwp.PrimarySelectionSourceV1.Event, self: *@This()) void {
            switch (event) {
                .send => |send| {
                    if (std.c.write(send.fd, self.payload.ptr, self.payload.len) != self.payload.len) self.failure = error.PrimarySendFailed;
                    closeMatureTransferFd(send.fd) catch |err| {
                        self.failure = err;
                        return;
                    };
                    self.send_count += 1;
                },
                .cancelled => self.cancelled_count += 1,
            }
        }
        fn pause(self: *@This(), value: Stage) !void {
            self.stage.store(@intFromEnum(value), .release);
            try waitForWayringCommand(self.command_fd);
        }
        fn closeWake(self: *@This(), shutdown_requested: bool) void {
            const fd = self.wake_fd.swap(-2, .acq_rel);
            if (fd < 0) return;
            if (shutdown_requested) _ = std.os.linux.shutdown(fd, std.os.linux.SHUT.RDWR);
            _ = std.os.linux.close(fd);
        }
        fn shutdown(self: *@This()) void {
            signalWayringCommand(self.command_fd) catch {};
            self.closeWake(true);
        }
    };
}

const GeneratedPrimaryClient = PrimarySelectionTestClient("org.keywork.primary-generated", 0xff31_79d4);
const MaturePrimaryClient = PrimarySelectionTestClient("org.keywork.primary-mature", 0xffd4_7931);

comptime {
    _ = GeneratedPrimaryClient.run;
    _ = MaturePrimaryClient.run;
}

/// Socket client used by mixed-front-end clipboard tests.  This deliberately
/// owns its connection and protocol objects instead of borrowing the much
/// broader `MatureDataDeviceClient` (which also exercises data-control and
/// drag-and-drop).
const GeneratedClipboardClient = struct {
    const client_wl = wayland.client.wl;
    const client_xdg = wayland.client.xdg;
    const Stage = enum(u8) {
        starting,
        ready,
        generated_selected,
        generated_late,
        generated_sent,
        mature_received,
        generated_cancelled,
        mature_selected,
        mature_late,
        mature_sent,
        generated_received,
        mature_replaced,
        cleared,
        disconnected,
        failed,
    };
    const Event = enum { data_offer, initial_mime, selection, late_mime, send, cancelled };

    runtime_directory: []const u8,
    display_name: []const u8,
    command_fd: std.posix.fd_t,
    stage: std.atomic.Value(u8) = .init(@intFromEnum(Stage.starting)),
    wake_fd: std.atomic.Value(i32) = .init(-1),
    failure: ?anyerror = null,
    compositor: ?*client_wl.Compositor = null,
    shm: ?*client_wl.Shm = null,
    seat: ?*client_wl.Seat = null,
    wm_base: ?*client_xdg.WmBase = null,
    manager: ?*client_wl.DataDeviceManager = null,
    surface_object_id: u32 = 0,
    keyboard_serial: u32 = 0,
    configure_serial: u32 = 0,
    offer: ?*client_wl.DataOffer = null,
    source: ?*client_wl.DataSource = null,
    events: [16]Event = undefined,
    event_count: usize = 0,
    received: [64]u8 = undefined,
    received_len: usize = 0,

    fn run(self: *@This()) void {
        self.runFallible() catch |err| {
            self.failure = err;
            self.stage.store(@intFromEnum(Stage.failed), .release);
            return;
        };
        self.stage.store(@intFromEnum(Stage.disconnected), .release);
    }

    fn runFallible(self: *@This()) !void {
        const path = try std.fmt.allocPrintSentinel(
            std.heap.page_allocator,
            "{s}/{s}",
            .{ self.runtime_directory, self.display_name },
            0,
        );
        defer std.heap.page_allocator.free(path);
        const fd = try connectWayringTestSocket(path);
        var fd_owned = true;
        defer if (fd_owned) {
            _ = std.os.linux.close(fd);
        };
        const raw_wake_fd = std.os.linux.dup(fd);
        if (std.os.linux.errno(raw_wake_fd) != .SUCCESS) return error.WakeFdFailed;
        const wake_fd: i32 = @intCast(raw_wake_fd);
        if (self.wake_fd.cmpxchgStrong(-1, wake_fd, .acq_rel, .acquire)) |_| {
            _ = std.os.linux.close(wake_fd);
            return error.ClientShutdown;
        }
        defer self.closeWake(false);

        const display = try client_wl.Display.connectToFd(fd);
        fd_owned = false;
        defer display.disconnect();
        const registry = try display.getRegistry();
        defer registry.destroy();
        registry.setListener(*@This(), registryEvent, self);
        try expectClientRoundtrip(display);
        const compositor = self.compositor orelse return error.CompositorMissing;
        defer compositor.destroy();
        const shm = self.shm orelse return error.ShmMissing;
        defer shm.release();
        const seat = self.seat orelse return error.SeatMissing;
        defer seat.release();
        const wm_base = self.wm_base orelse return error.XdgWmBaseMissing;
        defer wm_base.destroy();
        wm_base.setListener(*@This(), wmBaseEvent, self);
        const manager = self.manager orelse return error.DataDeviceManagerMissing;
        defer manager.release();
        const keyboard = try seat.getKeyboard();
        defer keyboard.release();
        keyboard.setListener(*@This(), keyboardEvent, self);
        const device = try manager.getDataDevice(seat);
        var device_live = true;
        defer if (device_live) device.release();
        device.setListener(*@This(), deviceEvent, self);
        const surface = try compositor.createSurface();
        self.surface_object_id = surface.getId();
        defer surface.destroy();
        const xdg_surface = try wm_base.getXdgSurface(surface);
        defer xdg_surface.destroy();
        xdg_surface.setListener(*@This(), xdgSurfaceEvent, self);
        const toplevel = try xdg_surface.getToplevel();
        defer toplevel.destroy();
        toplevel.setListener(*@This(), toplevelEvent, self);
        toplevel.setAppId("org.keywork.clipboard-generated");
        surface.commit();
        while (self.configure_serial == 0) try expectClientRoundtrip(display);
        const buffer = try createClipboardBuffer(shm, 0xff19_75d2);
        defer buffer.buffer.destroy();
        defer buffer.pool.destroy();
        defer _ = std.os.linux.close(buffer.fd);
        surface.attach(buffer.buffer, 0, 0);
        surface.damageBuffer(0, 0, 1, 1);
        surface.commit();
        try expectClientRoundtrip(display);
        try self.pause(.ready);

        try expectClientRoundtrip(display);
        if (self.keyboard_serial == 0) return error.GeneratedFocusSerialMissing;
        const stale = try manager.createDataSource();
        defer stale.destroy();
        stale.offer(MatureClipboardClient.mime_type);
        device.setSelection(stale, self.keyboard_serial ^ 0x8000_0000);
        const source = try manager.createDataSource();
        self.source = source;
        defer source.destroy();
        source.setListener(*@This(), sourceEvent, self);
        source.offer(MatureClipboardClient.mime_type);
        device.setSelection(source, self.keyboard_serial);
        try expectClientRoundtrip(display);
        try self.pause(.generated_selected);
        source.offer(MatureClipboardClient.late_mime_type);
        try expectClientRoundtrip(display);
        try self.pause(.generated_late);
        while (self.eventIndex(.send) == null) try expectClientRoundtrip(display);
        try self.pause(.generated_sent);

        try expectClientRoundtrip(display);
        if (self.eventIndex(.cancelled) == null) return error.GeneratedCancellationMissing;
        try self.pause(.generated_cancelled);
        self.event_count = 0;
        while (self.eventIndex(.selection) == null) try expectClientRoundtrip(display);
        const data_offer = self.eventIndex(.data_offer).?;
        const initial_mime = self.eventIndex(.initial_mime).?;
        const selection = self.eventIndex(.selection).?;
        if (!(data_offer < initial_mime and initial_mime < selection))
            return error.GeneratedOfferOrderInvalid;
        try self.pause(.mature_selected);
        while (self.eventIndex(.late_mime) == null) try expectClientRoundtrip(display);
        const late_mime = self.eventIndex(.late_mime).?;
        if (!(selection < late_mime))
            return error.GeneratedOfferOrderInvalid;
        try self.pause(.mature_late);

        const retained = self.offer orelse return error.GeneratedOfferMissing;
        device.release();
        device_live = false;
        var pipe: [2]std.posix.fd_t = undefined;
        if (std.c.pipe(&pipe) != 0) return error.PipeFailed;
        var read_open = true;
        defer if (read_open) {
            _ = std.os.linux.close(pipe[0]);
        };
        retained.receive(MatureClipboardClient.mime_type, pipe[1]);
        try closeMatureTransferFd(pipe[1]);
        try expectClientRoundtrip(display);
        self.received_len = try readMatureTransfer(pipe[0], &self.received);
        try closeMatureTransferFd(pipe[0]);
        read_open = false;
        if (!std.mem.eql(u8, self.received[0..self.received_len], MatureClipboardClient.mature_bytes))
            return error.GeneratedClipboardBytesMismatch;
        try self.pause(.generated_received);
        retained.destroy();
        self.offer = null;
        try expectClientRoundtrip(display);
        try self.pause(.cleared);
    }

    fn append(self: *@This(), event: Event) void {
        if (self.event_count == self.events.len) return;
        self.events[self.event_count] = event;
        self.event_count += 1;
    }
    fn eventIndex(self: *const @This(), wanted: Event) ?usize {
        for (self.events[0..self.event_count], 0..) |event, index| if (event == wanted) return index;
        return null;
    }
    fn registryEvent(registry: *client_wl.Registry, event: client_wl.Registry.Event, self: *@This()) void {
        switch (event) {
            .global => |global| {
                const interface = std.mem.span(global.interface);
                if (std.mem.eql(u8, interface, "wl_compositor")) self.compositor = registry.bind(global.name, client_wl.Compositor, @min(global.version, 6)) catch null else if (std.mem.eql(u8, interface, "wl_shm")) self.shm = registry.bind(global.name, client_wl.Shm, 1) catch null else if (std.mem.eql(u8, interface, "wl_seat")) self.seat = registry.bind(global.name, client_wl.Seat, @min(global.version, 10)) catch null else if (std.mem.eql(u8, interface, "xdg_wm_base")) self.wm_base = registry.bind(global.name, client_xdg.WmBase, @min(global.version, 7)) catch null else if (std.mem.eql(u8, interface, "wl_data_device_manager")) self.manager = registry.bind(global.name, client_wl.DataDeviceManager, 3) catch null;
            },
            .global_remove => {},
        }
    }
    fn wmBaseEvent(wm_base: *client_xdg.WmBase, event: client_xdg.WmBase.Event, _: *@This()) void {
        switch (event) {
            .ping => |ping| wm_base.pong(ping.serial),
        }
    }
    fn xdgSurfaceEvent(xdg_surface: *client_xdg.Surface, event: client_xdg.Surface.Event, self: *@This()) void {
        switch (event) {
            .configure => |configure| {
                self.configure_serial = configure.serial;
                xdg_surface.ackConfigure(configure.serial);
            },
        }
    }
    fn toplevelEvent(_: *client_xdg.Toplevel, _: client_xdg.Toplevel.Event, _: *@This()) void {}
    fn keyboardEvent(_: *client_wl.Keyboard, event: client_wl.Keyboard.Event, self: *@This()) void {
        switch (event) {
            .keymap => |keymap| _ = std.os.linux.close(keymap.fd),
            .enter => |enter| self.keyboard_serial = enter.serial,
            else => {},
        }
    }
    fn deviceEvent(_: *client_wl.DataDevice, event: client_wl.DataDevice.Event, self: *@This()) void {
        switch (event) {
            .data_offer => |data| {
                self.offer = data.id;
                data.id.setListener(*@This(), offerEvent, self);
                self.append(.data_offer);
            },
            .selection => self.append(.selection),
            else => {},
        }
    }
    fn offerEvent(_: *client_wl.DataOffer, event: client_wl.DataOffer.Event, self: *@This()) void {
        switch (event) {
            .offer => |offer| {
                const mime = std.mem.span(offer.mime_type);
                self.append(if (std.mem.eql(u8, mime, MatureClipboardClient.late_mime_type)) .late_mime else .initial_mime);
            },
            else => {},
        }
    }
    fn sourceEvent(_: *client_wl.DataSource, event: client_wl.DataSource.Event, self: *@This()) void {
        switch (event) {
            .send => |send| {
                if (std.c.fcntl(send.fd, std.posix.F.GETFD) < 0) {
                    self.failure = error.GeneratedSendFdClosed;
                    return;
                }
                const bytes = MatureClipboardClient.generated_bytes;
                if (std.c.write(send.fd, bytes.ptr, bytes.len) != bytes.len) {
                    self.failure = error.GeneratedSendFailed;
                    return;
                }
                closeMatureTransferFd(send.fd) catch |err| {
                    self.failure = err;
                    return;
                };
                self.append(.send);
            },
            .cancelled => self.append(.cancelled),
            else => {},
        }
    }
    fn pause(self: *@This(), value: Stage) !void {
        self.stage.store(@intFromEnum(value), .release);
        try waitForWayringCommand(self.command_fd);
    }
    fn closeWake(self: *@This(), shutdown_requested: bool) void {
        const fd = self.wake_fd.swap(-2, .acq_rel);
        if (fd < 0) return;
        if (shutdown_requested) _ = std.os.linux.shutdown(fd, std.os.linux.SHUT.RDWR);
        _ = std.os.linux.close(fd);
    }
    fn shutdown(self: *@This()) void {
        signalWayringCommand(self.command_fd) catch {};
        self.closeWake(true);
    }
};

/// Direct libwayland-client coverage for the privileged EXT data-control
/// bridge. This client deliberately owns both sides of each transfer so the
/// test can verify descriptor ownership and per-device offer fanout without
/// involving focus, surfaces, or serials.
const GeneratedDataControlClient = struct {
    const client_wl = wayland.client.wl;
    const client_ext = wayland.client.ext;
    const Stage = enum(u8) { starting, ready, selected, transferred, replaced, cleared, released, disconnected, failed };
    const Channel = enum { regular, primary };
    const regular_mime: [:0]const u8 = "text/plain";
    const primary_mime: [:0]const u8 = "text/x-keywork-primary";
    const regular_bytes = "generated data-control regular\n";
    const primary_bytes = "generated data-control primary\n";

    runtime_directory: []const u8,
    display_name: []const u8,
    command_fd: std.posix.fd_t,
    stage: std.atomic.Value(u8) = .init(@intFromEnum(Stage.starting)),
    wake_fd: std.atomic.Value(i32) = .init(-1),
    failure: ?anyerror = null,
    seat: ?*client_wl.Seat = null,
    manager: ?*client_ext.DataControlManagerV1 = null,
    manager_count: usize = 0,
    manager_version: u32 = 0,
    devices: [2]?*client_ext.DataControlDeviceV1 = .{ null, null },
    pending: [2]?*client_ext.DataControlOfferV1 = .{ null, null },
    offers: [2][2]?*client_ext.DataControlOfferV1 = @splat(@splat(null)),
    data_offer_count: usize = 0,
    mime_count: usize = 0,
    selection_count: usize = 0,
    primary_selection_count: usize = 0,
    null_selection_count: usize = 0,
    null_primary_count: usize = 0,
    regular_send_count: usize = 0,
    primary_send_count: usize = 0,
    regular_cancelled_count: usize = 0,
    primary_cancelled_count: usize = 0,
    initial_offer_count: usize = 0,
    received_regular: [64]u8 = undefined,
    received_regular_len: usize = 0,
    received_primary: [64]u8 = undefined,
    received_primary_len: usize = 0,
    regular_source: ?*client_ext.DataControlSourceV1 = null,
    primary_source: ?*client_ext.DataControlSourceV1 = null,

    fn run(self: *@This()) void {
        self.runFallible() catch |err| {
            self.failure = err;
            self.stage.store(@intFromEnum(Stage.failed), .release);
            return;
        };
        self.stage.store(@intFromEnum(Stage.disconnected), .release);
    }

    fn runFallible(self: *@This()) !void {
        const path = try std.fmt.allocPrintSentinel(std.heap.page_allocator, "{s}/{s}", .{ self.runtime_directory, self.display_name }, 0);
        defer std.heap.page_allocator.free(path);
        const fd = try connectWayringTestSocket(path);
        var fd_owned = true;
        defer if (fd_owned) {
            _ = std.os.linux.close(fd);
        };
        const raw_wake_fd = std.os.linux.dup(fd);
        if (std.os.linux.errno(raw_wake_fd) != .SUCCESS) return error.WakeFdFailed;
        const wake_fd: i32 = @intCast(raw_wake_fd);
        if (self.wake_fd.cmpxchgStrong(-1, wake_fd, .acq_rel, .acquire)) |_| {
            _ = std.os.linux.close(wake_fd);
            return error.ClientShutdown;
        }
        defer self.closeWake(false);
        const display = try client_wl.Display.connectToFd(fd);
        fd_owned = false;
        defer display.disconnect();
        const registry = try display.getRegistry();
        defer registry.destroy();
        registry.setListener(*@This(), registryEvent, self);
        try expectClientRoundtrip(display);
        if (self.manager_count != 1 or self.manager_version != 1) return error.DataControlGlobalMismatch;
        const seat = self.seat orelse return error.SeatMissing;
        defer seat.release();
        const manager = self.manager orelse return error.DataControlManagerMissing;
        defer manager.destroy();
        for (0..2) |index| {
            const device = try manager.getDataDevice(seat);
            self.devices[index] = device;
            device.setListener(*@This(), deviceEvent, self);
        }
        try expectClientRoundtrip(display);
        if (self.null_selection_count != 2 or self.null_primary_count != 2) return error.InitialDataControlStateMissing;
        self.null_selection_count = 0;
        self.null_primary_count = 0;
        try self.pause(.ready);

        const regular = try manager.createDataSource();
        self.regular_source = regular;
        regular.setListener(*@This(), sourceEvent, self);
        regular.offer(regular_mime);
        const primary = try manager.createDataSource();
        self.primary_source = primary;
        primary.setListener(*@This(), sourceEvent, self);
        primary.offer(primary_mime);
        self.devices[0].?.setSelection(regular);
        self.devices[0].?.setPrimarySelection(primary);
        try expectClientRoundtrip(display);
        if (self.data_offer_count != 4 or self.mime_count != 4 or self.selection_count != 2 or self.primary_selection_count != 2)
            return error.DataControlFanoutMissing;
        for (self.offers) |pair| if (pair[0] == null or pair[1] == null or pair[0] == pair[1])
            return error.DataControlOfferIdentityMissing;
        self.initial_offer_count = self.data_offer_count;
        try self.pause(.selected);

        // EXT explicitly keeps offers alive independently of their device.
        self.devices[0].?.destroy();
        self.devices[0] = null;
        var regular_pipe: [2]std.posix.fd_t = undefined;
        var primary_pipe: [2]std.posix.fd_t = undefined;
        if (std.c.pipe(&regular_pipe) != 0 or std.c.pipe(&primary_pipe) != 0) return error.PipeFailed;
        var regular_read_open = true;
        var primary_read_open = true;
        defer if (regular_read_open) {
            _ = std.os.linux.close(regular_pipe[0]);
        };
        defer if (primary_read_open) {
            _ = std.os.linux.close(primary_pipe[0]);
        };
        self.offers[0][0].?.receive(regular_mime, regular_pipe[1]);
        try closeMatureTransferFd(regular_pipe[1]);
        self.offers[1][1].?.receive(primary_mime, primary_pipe[1]);
        try closeMatureTransferFd(primary_pipe[1]);
        try expectClientRoundtrip(display);
        if (self.failure) |err| return err;
        self.received_regular_len = try readMatureTransfer(regular_pipe[0], &self.received_regular);
        try closeMatureTransferFd(regular_pipe[0]);
        regular_read_open = false;
        self.received_primary_len = try readMatureTransfer(primary_pipe[0], &self.received_primary);
        try closeMatureTransferFd(primary_pipe[0]);
        primary_read_open = false;
        if (!std.mem.eql(u8, self.received_regular[0..self.received_regular_len], regular_bytes) or
            !std.mem.eql(u8, self.received_primary[0..self.received_primary_len], primary_bytes))
            return error.DataControlPayloadMismatch;
        try self.pause(.transferred);

        const replacement_regular = try manager.createDataSource();
        replacement_regular.setListener(*@This(), sourceEvent, self);
        replacement_regular.offer(regular_mime);
        const replacement_primary = try manager.createDataSource();
        replacement_primary.setListener(*@This(), sourceEvent, self);
        replacement_primary.offer(primary_mime);
        self.devices[1].?.setSelection(replacement_regular);
        self.devices[1].?.setPrimarySelection(replacement_primary);
        try expectClientRoundtrip(display);
        if (self.regular_cancelled_count != 1 or self.primary_cancelled_count != 1) return error.DataControlCancellationMissing;
        try self.pause(.replaced);
        self.devices[1].?.setSelection(null);
        self.devices[1].?.setPrimarySelection(null);
        try expectClientRoundtrip(display);
        if (self.null_selection_count != 1 or self.null_primary_count != 1) return error.DataControlClearMissing;
        try self.pause(.cleared);

        for (&self.offers) |*pair| for (pair) |*offer| if (offer.*) |value| {
            value.destroy();
            offer.* = null;
        };
        self.devices[1].?.destroy();
        self.devices[1] = null;
        regular.destroy();
        primary.destroy();
        replacement_regular.destroy();
        replacement_primary.destroy();
        self.regular_source = null;
        self.primary_source = null;
        try expectClientRoundtrip(display);
        try self.pause(.released);
    }

    fn registryEvent(registry: *client_wl.Registry, event: client_wl.Registry.Event, self: *@This()) void {
        switch (event) {
            .global => |global| {
                const interface = std.mem.span(global.interface);
                if (std.mem.eql(u8, interface, "wl_seat")) self.seat = registry.bind(global.name, client_wl.Seat, @min(global.version, 10)) catch null else if (std.mem.eql(u8, interface, "ext_data_control_manager_v1")) {
                    self.manager_count += 1;
                    self.manager_version = global.version;
                    self.manager = registry.bind(global.name, client_ext.DataControlManagerV1, 1) catch null;
                }
            },
            .global_remove => {},
        }
    }
    fn deviceIndex(self: *@This(), device: *client_ext.DataControlDeviceV1) ?usize {
        for (self.devices, 0..) |candidate, index| if (candidate == device) return index;
        return null;
    }
    fn deviceEvent(device: *client_ext.DataControlDeviceV1, event: client_ext.DataControlDeviceV1.Event, self: *@This()) void {
        const index = self.deviceIndex(device) orelse return;
        switch (event) {
            .data_offer => |data| {
                self.pending[index] = data.id;
                data.id.setListener(*@This(), offerEvent, self);
                self.data_offer_count += 1;
            },
            .selection => |selection| {
                if (selection.id) |offer| {
                    if (self.offers[index][0]) |old| if (old != offer) old.destroy();
                    self.offers[index][0] = offer;
                    self.selection_count += 1;
                } else self.null_selection_count += 1;
                self.pending[index] = null;
            },
            .primary_selection => |selection| {
                if (selection.id) |offer| {
                    if (self.offers[index][1]) |old| if (old != offer) old.destroy();
                    self.offers[index][1] = offer;
                    self.primary_selection_count += 1;
                } else self.null_primary_count += 1;
                self.pending[index] = null;
            },
            .finished => {},
        }
    }
    fn offerEvent(_: *client_ext.DataControlOfferV1, event: client_ext.DataControlOfferV1.Event, self: *@This()) void {
        switch (event) {
            .offer => self.mime_count += 1,
        }
    }
    fn sourceEvent(source: *client_ext.DataControlSourceV1, event: client_ext.DataControlSourceV1.Event, self: *@This()) void {
        const channel: Channel = if (source == self.regular_source) .regular else .primary;
        switch (event) {
            .send => |send| {
                if (std.c.fcntl(send.fd, std.posix.F.GETFD) < 0) {
                    self.failure = error.DataControlSendFdClosed;
                    return;
                }
                const bytes = if (channel == .regular) regular_bytes else primary_bytes;
                if (std.c.write(send.fd, bytes.ptr, bytes.len) != bytes.len) {
                    self.failure = error.DataControlSendFailed;
                }
                closeMatureTransferFd(send.fd) catch |err| {
                    if (self.failure == null) self.failure = err;
                    return;
                };
                if (self.failure != null) return;
                if (channel == .regular) self.regular_send_count += 1 else self.primary_send_count += 1;
            },
            .cancelled => {
                if (channel == .regular) {
                    self.regular_cancelled_count += 1;
                } else self.primary_cancelled_count += 1;
            },
        }
    }
    fn pause(self: *@This(), value: Stage) !void {
        self.stage.store(@intFromEnum(value), .release);
        try waitForWayringCommand(self.command_fd);
    }
    fn closeWake(self: *@This(), shutdown_requested: bool) void {
        const fd = self.wake_fd.swap(-2, .acq_rel);
        if (fd < 0) return;
        if (shutdown_requested) _ = std.os.linux.shutdown(fd, std.os.linux.SHUT.RDWR);
        _ = std.os.linux.close(fd);
    }
    fn shutdown(self: *@This()) void {
        signalWayringCommand(self.command_fd) catch {};
        self.closeWake(true);
    }
};

/// Independent generated client that proves a terminal data-device fault is
/// isolated by the production host from valid clipboard peers.
const GeneratedDragOffender = struct {
    const client_wl = wayland.client.wl;
    const Stage = enum(u8) { starting, ready, disconnected, failed };

    runtime_directory: []const u8,
    display_name: []const u8,
    command_fd: std.posix.fd_t,
    stage: std.atomic.Value(u8) = .init(@intFromEnum(Stage.starting)),
    wake_fd: std.atomic.Value(i32) = .init(-1),
    failure: ?anyerror = null,
    compositor: ?*client_wl.Compositor = null,
    seat: ?*client_wl.Seat = null,
    manager: ?*client_wl.DataDeviceManager = null,
    surface_object_id: u32 = 0,
    device_object_id: u32 = 0,

    fn run(self: *@This()) void {
        self.runFallible() catch |err| {
            self.failure = err;
            self.stage.store(@intFromEnum(Stage.failed), .release);
            return;
        };
        self.stage.store(@intFromEnum(Stage.disconnected), .release);
    }

    fn runFallible(self: *@This()) !void {
        const path = try std.fmt.allocPrintSentinel(
            std.heap.page_allocator,
            "{s}/{s}",
            .{ self.runtime_directory, self.display_name },
            0,
        );
        defer std.heap.page_allocator.free(path);
        const fd = try connectWayringTestSocket(path);
        var fd_owned = true;
        defer if (fd_owned) {
            _ = std.os.linux.close(fd);
        };
        const raw_wake_fd = std.os.linux.dup(fd);
        if (std.os.linux.errno(raw_wake_fd) != .SUCCESS) return error.WakeFdFailed;
        const wake_fd: i32 = @intCast(raw_wake_fd);
        if (self.wake_fd.cmpxchgStrong(-1, wake_fd, .acq_rel, .acquire)) |_| {
            _ = std.os.linux.close(wake_fd);
            return error.ClientShutdown;
        }
        defer self.closeWake(false);

        const display = try client_wl.Display.connectToFd(fd);
        fd_owned = false;
        defer display.disconnect();
        const registry = try display.getRegistry();
        defer registry.destroy();
        registry.setListener(*@This(), registryEvent, self);
        try expectClientRoundtrip(display);
        const compositor = self.compositor orelse return error.CompositorMissing;
        defer compositor.destroy();
        const seat = self.seat orelse return error.SeatMissing;
        defer seat.release();
        const manager = self.manager orelse return error.DataDeviceManagerMissing;
        defer manager.release();
        const device = try manager.getDataDevice(seat);
        self.device_object_id = device.getId();
        defer device.release();
        const surface = try compositor.createSurface();
        self.surface_object_id = surface.getId();
        defer surface.destroy();
        try expectClientRoundtrip(display);
        try self.pause(.ready);

        device.startDrag(null, surface, null, 1);
        try expectClientRoundtrip(display);
    }

    fn registryEvent(registry: *client_wl.Registry, event: client_wl.Registry.Event, self: *@This()) void {
        switch (event) {
            .global => |global| {
                const interface = std.mem.span(global.interface);
                if (std.mem.eql(u8, interface, "wl_compositor")) self.compositor = registry.bind(global.name, client_wl.Compositor, @min(global.version, 6)) catch null else if (std.mem.eql(u8, interface, "wl_seat")) self.seat = registry.bind(global.name, client_wl.Seat, @min(global.version, 10)) catch null else if (std.mem.eql(u8, interface, "wl_data_device_manager")) self.manager = registry.bind(global.name, client_wl.DataDeviceManager, 3) catch null;
            },
            .global_remove => {},
        }
    }

    fn pause(self: *@This(), value: Stage) !void {
        self.stage.store(@intFromEnum(value), .release);
        try waitForWayringCommand(self.command_fd);
    }
    fn closeWake(self: *@This(), shutdown_requested: bool) void {
        const fd = self.wake_fd.swap(-2, .acq_rel);
        if (fd < 0) return;
        if (shutdown_requested) _ = std.os.linux.shutdown(fd, std.os.linux.SHUT.RDWR);
        _ = std.os.linux.close(fd);
    }
    fn shutdown(self: *@This()) void {
        signalWayringCommand(self.command_fd) catch {};
        self.closeWake(true);
    }
};

/// The libwayland-side peer for mixed-front-end clipboard tests.  Its state is
/// intentionally separate from both `GeneratedClipboardClient` and
/// `MatureDataDeviceClient`, so either side can be torn down independently.
const MatureClipboardClient = struct {
    const client_wl = wayland.client.wl;
    const Stage = GeneratedClipboardClient.Stage;
    const Event = GeneratedClipboardClient.Event;
    const mime_type: [:0]const u8 = "text/plain;charset=utf-8";
    const late_mime_type: [:0]const u8 = "text/html";
    const stale_mime_type: [:0]const u8 = "application/x-keywork-stale";
    const generated_bytes = "generated-to-mature clipboard\n";
    const mature_bytes = "mature-to-generated clipboard\n";

    runtime_directory: []const u8,
    display_name: []const u8,
    command_fd: std.posix.fd_t,
    stage: std.atomic.Value(u8) = .init(@intFromEnum(Stage.starting)),
    wake_fd: std.atomic.Value(i32) = .init(-1),
    failure: ?anyerror = null,
    compositor: ?*client_wl.Compositor = null,
    shm: ?*client_wl.Shm = null,
    seat: ?*client_wl.Seat = null,
    manager: ?*client_wl.DataDeviceManager = null,
    surface_object_id: u32 = 0,
    keyboard_serial: u32 = 0,
    offer: ?*client_wl.DataOffer = null,
    source: ?*client_wl.DataSource = null,
    events: [16]Event = undefined,
    event_count: usize = 0,
    received: [64]u8 = undefined,
    received_len: usize = 0,

    fn run(self: *@This()) void {
        self.runFallible() catch |err| {
            self.failure = err;
            self.stage.store(@intFromEnum(Stage.failed), .release);
            return;
        };
        self.stage.store(@intFromEnum(Stage.disconnected), .release);
    }

    fn runFallible(self: *@This()) !void {
        const path = try std.fmt.allocPrintSentinel(std.heap.page_allocator, "{s}/{s}", .{ self.runtime_directory, self.display_name }, 0);
        defer std.heap.page_allocator.free(path);
        const fd = try connectWayringTestSocket(path);
        var fd_owned = true;
        defer if (fd_owned) {
            _ = std.os.linux.close(fd);
        };
        const raw_wake_fd = std.os.linux.dup(fd);
        if (std.os.linux.errno(raw_wake_fd) != .SUCCESS) return error.WakeFdFailed;
        const wake_fd: i32 = @intCast(raw_wake_fd);
        if (self.wake_fd.cmpxchgStrong(-1, wake_fd, .acq_rel, .acquire)) |_| {
            _ = std.os.linux.close(wake_fd);
            return error.ClientShutdown;
        }
        defer self.closeWake(false);
        const display = try client_wl.Display.connectToFd(fd);
        fd_owned = false;
        defer display.disconnect();
        const registry = try display.getRegistry();
        defer registry.destroy();
        registry.setListener(*@This(), registryEvent, self);
        try expectClientRoundtrip(display);
        const compositor = self.compositor orelse return error.CompositorMissing;
        defer compositor.destroy();
        const shm = self.shm orelse return error.ShmMissing;
        defer shm.release();
        const seat = self.seat orelse return error.SeatMissing;
        defer seat.release();
        const manager = self.manager orelse return error.DataDeviceManagerMissing;
        defer manager.release();
        const keyboard = try seat.getKeyboard();
        defer keyboard.release();
        keyboard.setListener(*@This(), keyboardEvent, self);
        const device = try manager.getDataDevice(seat);
        var device_live = true;
        defer if (device_live) device.release();
        device.setListener(*@This(), deviceEvent, self);
        const surface = try compositor.createSurface();
        self.surface_object_id = surface.getId();
        defer surface.destroy();
        const buffer = try createClipboardBuffer(shm, 0xffd2_7519);
        defer buffer.buffer.destroy();
        defer buffer.pool.destroy();
        defer _ = std.os.linux.close(buffer.fd);
        surface.attach(buffer.buffer, 0, 0);
        surface.damageBuffer(0, 0, 1, 1);
        surface.commit();
        try expectClientRoundtrip(display);
        try self.pause(.ready);

        while (self.eventIndex(.selection) == null) try expectClientRoundtrip(display);
        const data_offer = self.eventIndex(.data_offer).?;
        const initial_mime = self.eventIndex(.initial_mime).?;
        const selection = self.eventIndex(.selection).?;
        if (!(data_offer < initial_mime and initial_mime < selection))
            return error.MatureOfferOrderInvalid;
        try self.pause(.generated_selected);
        while (self.eventIndex(.late_mime) == null) try expectClientRoundtrip(display);
        const late_mime = self.eventIndex(.late_mime).?;
        if (!(selection < late_mime))
            return error.MatureOfferOrderInvalid;
        try self.pause(.generated_late);
        const retained = self.offer orelse return error.MatureOfferMissing;
        device.release();
        device_live = false;
        var pipe: [2]std.posix.fd_t = undefined;
        if (std.c.pipe(&pipe) != 0) return error.PipeFailed;
        var read_open = true;
        defer if (read_open) {
            _ = std.os.linux.close(pipe[0]);
        };
        retained.receive(mime_type, pipe[1]);
        try closeMatureTransferFd(pipe[1]);
        try expectClientRoundtrip(display);
        self.received_len = try readMatureTransfer(pipe[0], &self.received);
        try closeMatureTransferFd(pipe[0]);
        read_open = false;
        if (!std.mem.eql(u8, self.received[0..self.received_len], generated_bytes))
            return error.MatureClipboardBytesMismatch;
        try self.pause(.mature_received);
        retained.destroy();
        self.offer = null;
        self.event_count = 0;

        const replacement_device = try manager.getDataDevice(seat);
        defer replacement_device.release();
        replacement_device.setListener(*@This(), deviceEvent, self);
        try expectClientRoundtrip(display);
        if (self.keyboard_serial == 0) return error.MatureFocusSerialMissing;
        const stale = try manager.createDataSource();
        defer stale.destroy();
        stale.offer(mime_type);
        replacement_device.setSelection(stale, self.keyboard_serial ^ 0x8000_0000);
        const source = try manager.createDataSource();
        self.source = source;
        defer source.destroy();
        source.setListener(*@This(), sourceEvent, self);
        source.offer(mime_type);
        replacement_device.setSelection(source, self.keyboard_serial);
        try expectClientRoundtrip(display);
        try self.pause(.mature_selected);
        source.offer(late_mime_type);
        try expectClientRoundtrip(display);
        try self.pause(.mature_late);
        while (self.eventIndex(.send) == null) try expectClientRoundtrip(display);
        try self.pause(.mature_sent);

        const replacement = try manager.createDataSource();
        defer replacement.destroy();
        replacement.setListener(*@This(), sourceEvent, self);
        replacement.offer(mime_type);
        replacement_device.setSelection(replacement, self.keyboard_serial);
        try expectClientRoundtrip(display);
        if (self.eventIndex(.cancelled) == null) return error.MatureCancellationMissing;
        try self.pause(.mature_replaced);
        replacement_device.setSelection(null, self.keyboard_serial);
        try expectClientRoundtrip(display);
        try self.pause(.cleared);
    }

    fn append(self: *@This(), event: Event) void {
        if (self.event_count == self.events.len) return;
        self.events[self.event_count] = event;
        self.event_count += 1;
    }
    fn eventIndex(self: *const @This(), wanted: Event) ?usize {
        for (self.events[0..self.event_count], 0..) |event, index| if (event == wanted) return index;
        return null;
    }
    fn registryEvent(registry: *client_wl.Registry, event: client_wl.Registry.Event, self: *@This()) void {
        switch (event) {
            .global => |global| {
                const interface = std.mem.span(global.interface);
                if (std.mem.eql(u8, interface, "wl_compositor")) self.compositor = registry.bind(global.name, client_wl.Compositor, @min(global.version, 6)) catch null else if (std.mem.eql(u8, interface, "wl_shm")) self.shm = registry.bind(global.name, client_wl.Shm, 1) catch null else if (std.mem.eql(u8, interface, "wl_seat")) self.seat = registry.bind(global.name, client_wl.Seat, @min(global.version, 10)) catch null else if (std.mem.eql(u8, interface, "wl_data_device_manager")) self.manager = registry.bind(global.name, client_wl.DataDeviceManager, 3) catch null;
            },
            .global_remove => {},
        }
    }
    fn keyboardEvent(_: *client_wl.Keyboard, event: client_wl.Keyboard.Event, self: *@This()) void {
        switch (event) {
            .keymap => |keymap| _ = std.os.linux.close(keymap.fd),
            .enter => |enter| self.keyboard_serial = enter.serial,
            else => {},
        }
    }
    fn deviceEvent(_: *client_wl.DataDevice, event: client_wl.DataDevice.Event, self: *@This()) void {
        switch (event) {
            .data_offer => |data| {
                self.offer = data.id;
                data.id.setListener(*@This(), offerEvent, self);
                self.append(.data_offer);
            },
            .selection => self.append(.selection),
            else => {},
        }
    }
    fn offerEvent(_: *client_wl.DataOffer, event: client_wl.DataOffer.Event, self: *@This()) void {
        switch (event) {
            .offer => |offer| self.append(if (std.mem.eql(u8, std.mem.span(offer.mime_type), late_mime_type)) .late_mime else .initial_mime),
            else => {},
        }
    }
    fn sourceEvent(_: *client_wl.DataSource, event: client_wl.DataSource.Event, self: *@This()) void {
        switch (event) {
            .send => |send| {
                if (std.c.fcntl(send.fd, std.posix.F.GETFD) < 0) {
                    self.failure = error.MatureSendFdClosed;
                    return;
                }
                const bytes = mature_bytes;
                if (std.c.write(send.fd, bytes.ptr, bytes.len) != bytes.len) {
                    self.failure = error.MatureSendFailed;
                    return;
                }
                closeMatureTransferFd(send.fd) catch |err| {
                    self.failure = err;
                    return;
                };
                self.append(.send);
            },
            .cancelled => self.append(.cancelled),
            else => {},
        }
    }
    fn pause(self: *@This(), value: Stage) !void {
        self.stage.store(@intFromEnum(value), .release);
        try waitForWayringCommand(self.command_fd);
    }
    fn closeWake(self: *@This(), shutdown_requested: bool) void {
        const fd = self.wake_fd.swap(-2, .acq_rel);
        if (fd < 0) return;
        if (shutdown_requested) _ = std.os.linux.shutdown(fd, std.os.linux.SHUT.RDWR);
        _ = std.os.linux.close(fd);
    }
    fn shutdown(self: *@This()) void {
        signalWayringCommand(self.command_fd) catch {};
        self.closeWake(true);
    }
};

const ClipboardBuffer = struct {
    fd: std.posix.fd_t,
    pool: *wayland.client.wl.ShmPool,
    buffer: *wayland.client.wl.Buffer,
};

fn createClipboardBuffer(shm: *wayland.client.wl.Shm, pixel: u32) !ClipboardBuffer {
    const fd = try std.posix.memfd_create("keywork-mixed-clipboard", std.os.linux.MFD.CLOEXEC);
    errdefer _ = std.os.linux.close(fd);
    if (std.os.linux.errno(std.os.linux.ftruncate(fd, @sizeOf(u32))) != .SUCCESS)
        return error.ShmResizeFailed;
    if (std.c.pwrite(fd, @ptrCast(&pixel), @sizeOf(u32), 0) != @sizeOf(u32))
        return error.ShmWriteFailed;
    const pool = try shm.createPool(fd, @sizeOf(u32));
    errdefer pool.destroy();
    return .{
        .fd = fd,
        .pool = pool,
        .buffer = try pool.createBuffer(0, 1, 1, @sizeOf(u32), .argb8888),
    };
}

fn readMatureTransfer(fd: std.posix.fd_t, buffer: []u8) !usize {
    var offset: usize = 0;
    while (offset < buffer.len) {
        const result = std.c.read(fd, buffer.ptr + offset, buffer.len - offset);
        if (result > 0) {
            offset += @intCast(result);
            continue;
        }
        if (result == 0) return offset;
        if (std.posix.errno(result) == .INTR) continue;
        return error.TransferReadFailed;
    }
    return error.TransferTooLarge;
}

fn closeMatureTransferFd(fd: std.posix.fd_t) !void {
    if (std.os.linux.errno(std.os.linux.close(fd)) != .SUCCESS) return error.TransferCloseFailed;
    const result = std.c.fcntl(fd, std.posix.F.GETFD);
    if (result != -1 or std.posix.errno(result) != .BADF)
        return error.TransferFdStillOpen;
}

fn countMatureDataDeviceFds() !usize {
    var directory = try std.Io.Dir.openDirAbsolute(std.testing.io, "/proc/self/fd", .{ .iterate = true });
    defer directory.close(std.testing.io);
    var iterator = directory.iterate();
    var count: usize = 0;
    while (try iterator.next(std.testing.io)) |_| count += 1;
    return count;
}

const MatureKeyboardClient = struct {
    const client_wl = wayland.client.wl;
    const Stage = enum(u8) {
        starting,
        resources_bound,
        focused,
        late_bound,
        reentered,
        resource_rebound,
        disconnected,
        failed,
    };
    const KeyboardTag = enum { keymap, repeat_info, enter, modifiers, leave };
    const KeyboardLog = struct {
        tags: [12]KeyboardTag = undefined,
        count: usize = 0,
        enter_serials: [3]u32 = @splat(0),
        enter_keys: [3][8]u32 = @splat(@splat(0)),
        enter_key_counts: [3]usize = @splat(0),
        enter_count: usize = 0,
        modifier_serials: [3]u32 = @splat(0),
        modifiers: [3]SeatDelivery.Modifiers = @splat(.{}),
        modifier_count: usize = 0,

        fn handleEvent(_: *client_wl.Keyboard, event: client_wl.Keyboard.Event, self: *KeyboardLog) void {
            if (self.count == self.tags.len) return;
            const tag: KeyboardTag = switch (event) {
                .keymap => |keymap| value: {
                    _ = std.os.linux.close(keymap.fd);
                    break :value .keymap;
                },
                .repeat_info => .repeat_info,
                .enter => |enter| value: {
                    if (self.enter_count < self.enter_serials.len) {
                        const index = self.enter_count;
                        const keys = enter.keys.slice(u32);
                        self.enter_serials[index] = enter.serial;
                        self.enter_key_counts[index] = @min(keys.len, self.enter_keys[index].len);
                        @memcpy(
                            self.enter_keys[index][0..self.enter_key_counts[index]],
                            keys[0..self.enter_key_counts[index]],
                        );
                    }
                    self.enter_count += 1;
                    break :value .enter;
                },
                .modifiers => |modifiers| value: {
                    if (self.modifier_count < self.modifier_serials.len) {
                        const index = self.modifier_count;
                        self.modifier_serials[index] = modifiers.serial;
                        self.modifiers[index] = .{
                            .depressed = modifiers.mods_depressed,
                            .latched = modifiers.mods_latched,
                            .locked = modifiers.mods_locked,
                            .group = modifiers.group,
                        };
                    }
                    self.modifier_count += 1;
                    break :value .modifiers;
                },
                .leave => .leave,
                .key => return,
            };
            self.tags[self.count] = tag;
            self.count += 1;
        }

        fn expectInitial(self: *const KeyboardLog, serial: u32) !void {
            try std.testing.expectEqualSlices(
                KeyboardTag,
                &.{ .keymap, .repeat_info, .enter, .modifiers },
                self.tags[0..self.count],
            );
            try std.testing.expectEqual(@as(usize, 1), self.enter_count);
            try std.testing.expectEqual(serial, self.enter_serials[0]);
            try std.testing.expectEqualSlices(
                u32,
                &.{30},
                self.enter_keys[0][0..self.enter_key_counts[0]],
            );
            try std.testing.expectEqual(@as(usize, 1), self.modifier_count);
            try std.testing.expectEqual(serial, self.modifier_serials[0]);
            try std.testing.expectEqual(
                SeatDelivery.Modifiers{ .depressed = 1, .latched = 2, .locked = 4, .group = 3 },
                self.modifiers[0],
            );
        }

        fn expectReentered(self: *const KeyboardLog, first_serial: u32) !void {
            try std.testing.expectEqualSlices(
                KeyboardTag,
                &.{ .keymap, .repeat_info, .enter, .modifiers, .leave, .enter, .modifiers },
                self.tags[0..self.count],
            );
            try std.testing.expectEqual(@as(usize, 2), self.enter_count);
            try std.testing.expectEqual(first_serial, self.enter_serials[0]);
            try std.testing.expect(self.enter_serials[1] != first_serial);
            try std.testing.expectEqualSlices(
                u32,
                &.{30},
                self.enter_keys[1][0..self.enter_key_counts[1]],
            );
            try std.testing.expectEqual(self.enter_serials[1], self.modifier_serials[1]);
            try std.testing.expectEqual(self.modifiers[0], self.modifiers[1]);
        }

        fn expectGrabbed(self: *const KeyboardLog, first_serial: u32, grab_serial: u32) !void {
            try std.testing.expectEqualSlices(
                KeyboardTag,
                &.{
                    .keymap,
                    .repeat_info,
                    .enter,
                    .modifiers,
                    .leave,
                    .enter,
                    .modifiers,
                    .leave,
                    .enter,
                    .modifiers,
                },
                self.tags[0..self.count],
            );
            try std.testing.expectEqual(@as(usize, 3), self.enter_count);
            try std.testing.expectEqual(first_serial, self.enter_serials[0]);
            try std.testing.expectEqual(grab_serial, self.enter_serials[2]);
            try std.testing.expectEqualSlices(
                u32,
                &.{30},
                self.enter_keys[2][0..self.enter_key_counts[2]],
            );
            try std.testing.expectEqual(grab_serial, self.modifier_serials[2]);
            try std.testing.expectEqual(self.modifiers[0], self.modifiers[2]);
        }
    };

    fd: std.posix.fd_t,
    command_fd: std.posix.fd_t,
    stage: std.atomic.Value(u8) = .init(@intFromEnum(Stage.starting)),
    wake_fd: std.atomic.Value(i32) = .init(-1),
    failure: ?anyerror = null,
    compositor: ?*client_wl.Compositor = null,
    seat: ?*client_wl.Seat = null,
    first: KeyboardLog = .{},
    second: KeyboardLog = .{},
    third: KeyboardLog = .{},

    fn run(self: *MatureKeyboardClient) void {
        self.runFallible() catch |err| {
            self.failure = err;
            self.stage.store(@intFromEnum(Stage.failed), .release);
            return;
        };
        self.stage.store(@intFromEnum(Stage.disconnected), .release);
    }

    fn runFallible(self: *MatureKeyboardClient) !void {
        const raw_wake_fd = std.os.linux.dup(self.fd);
        if (std.os.linux.errno(raw_wake_fd) != .SUCCESS) return error.WakeFdFailed;
        const wake_fd: i32 = @intCast(raw_wake_fd);
        if (self.wake_fd.cmpxchgStrong(-1, wake_fd, .acq_rel, .acquire)) |_| {
            _ = std.os.linux.close(wake_fd);
            return error.ClientShutdown;
        }
        defer self.closeWake(false);

        const display = try client_wl.Display.connectToFd(self.fd);
        defer display.disconnect();
        const registry = try display.getRegistry();
        defer registry.destroy();
        registry.setListener(*MatureKeyboardClient, registryEvent, self);
        try expectClientRoundtrip(display);
        const compositor = self.compositor orelse return error.CompositorMissing;
        defer compositor.destroy();
        const seat = self.seat orelse return error.SeatMissing;
        var seat_live = true;
        defer if (seat_live) seat.release();
        const surface = try compositor.createSurface();
        defer surface.destroy();
        const first = try seat.getKeyboard();
        var first_live = true;
        defer if (first_live) first.release();
        first.setListener(*KeyboardLog, KeyboardLog.handleEvent, &self.first);
        try expectClientRoundtrip(display);
        try self.pause(.resources_bound);

        try expectClientRoundtrip(display);
        const first_serial = self.first.enter_serials[0];
        if (first_serial == 0) return error.KeyboardEnterMissing;
        try self.first.expectInitial(first_serial);
        try self.pause(.focused);

        const second = try seat.getKeyboard();
        var second_live = true;
        defer if (second_live) second.release();
        second.setListener(*KeyboardLog, KeyboardLog.handleEvent, &self.second);
        try expectClientRoundtrip(display);
        try self.first.expectInitial(first_serial);
        try self.second.expectInitial(first_serial);
        try self.pause(.late_bound);

        try expectClientRoundtrip(display);
        try self.first.expectReentered(first_serial);
        try self.second.expectReentered(first_serial);
        if (self.first.enter_serials[1] != self.second.enter_serials[1])
            return error.KeyboardReenterSerialMismatch;
        try self.pause(.reentered);

        second.release();
        second_live = false;
        try expectClientRoundtrip(display);
        const third = try seat.getKeyboard();
        var third_live = true;
        defer if (third_live) third.release();
        third.setListener(*KeyboardLog, KeyboardLog.handleEvent, &self.third);
        try expectClientRoundtrip(display);
        const grab_serial = self.first.enter_serials[2];
        try self.first.expectGrabbed(first_serial, grab_serial);
        try self.third.expectInitial(grab_serial);
        try self.pause(.resource_rebound);

        third.release();
        third_live = false;
        first.release();
        first_live = false;
        seat.release();
        seat_live = false;
        try expectClientRoundtrip(display);
    }

    fn registryEvent(registry: *client_wl.Registry, event: client_wl.Registry.Event, self: *MatureKeyboardClient) void {
        switch (event) {
            .global => |global| {
                const interface = std.mem.span(global.interface);
                if (std.mem.eql(u8, interface, "wl_compositor") and self.compositor == null)
                    self.compositor = registry.bind(global.name, client_wl.Compositor, @min(global.version, 6)) catch null
                else if (std.mem.eql(u8, interface, "wl_seat") and self.seat == null) {
                    self.seat = registry.bind(global.name, client_wl.Seat, @min(global.version, 10)) catch null;
                    if (self.seat) |seat| seat.setListener(*MatureKeyboardClient, seatEvent, self);
                }
            },
            .global_remove => {},
        }
    }

    fn seatEvent(_: *client_wl.Seat, _: client_wl.Seat.Event, _: *MatureKeyboardClient) void {}

    fn pause(self: *MatureKeyboardClient, stage_value: Stage) !void {
        self.stage.store(@intFromEnum(stage_value), .release);
        try waitForWayringCommand(self.command_fd);
    }

    fn closeWake(self: *MatureKeyboardClient, shutdown_requested: bool) void {
        const fd = self.wake_fd.swap(-2, .acq_rel);
        if (fd < 0) return;
        if (shutdown_requested) _ = std.os.linux.shutdown(fd, std.os.linux.SHUT.RDWR);
        _ = std.os.linux.close(fd);
    }

    fn shutdown(self: *MatureKeyboardClient) void {
        signalWayringCommand(self.command_fd) catch {};
        self.closeWake(true);
    }
};

const MatureTextClient = struct {
    const client_wl = wayland.client.wl;
    const client_zwp = wayland.client.zwp;
    const Role = enum { application, input_method };
    const Stage = enum(u8) { starting, ready, state_received, edit_received, popup_clicked, popup_recommitted, popup_unmapped, disconnected, failed };
    const EditTag = enum { preedit, delete, commit, done };
    fd: std.posix.fd_t,
    role: Role,
    stage: std.atomic.Value(u8) = .init(@intFromEnum(Stage.starting)),
    proceed: std.atomic.Value(bool) = .init(false),
    shutdown_requested: std.atomic.Value(bool) = .init(false),
    failure: ?anyerror = null,
    compositor: ?*client_wl.Compositor = null,
    shm: ?*client_wl.Shm = null,
    seat: ?*client_wl.Seat = null,
    text_manager: ?*client_zwp.TextInputManagerV3 = null,
    method_manager: ?*client_zwp.InputMethodManagerV2 = null,
    text_manager_version: u32 = 0,
    edits: [4]EditTag = undefined,
    edit_count: usize = 0,
    done_serial: u32 = 0,
    method_done_count: u32 = 0,
    method_events: [5]u8 = undefined,
    method_event_count: usize = 0,
    method_surrounding: [16]u8 = undefined,
    method_surrounding_len: usize = 0,
    method_cursor: u32 = 0,
    method_anchor: u32 = 0,
    method_cause: i32 = 0,
    method_content_hint: u32 = 0,
    method_content_purpose: i32 = 0,
    popup_surface_object_id: u32 = 0,
    popup_rectangle: NeutralTextInput.Rectangle = .{ .x = 0, .y = 0, .width = 0, .height = 0 },
    popup_rectangle_count: usize = 0,
    popup_rectangle_after_done: bool = false,
    popup_pointer_surface: u32 = 0,
    listen_pointer: bool = false,
    grab_delivery: bool = false,
    grab_events: [6]u8 = undefined,
    grab_event_count: usize = 0,
    grab_keymap_size: u32 = 0,
    grab_keymap_bytes: [16]u8 = undefined,
    grab_keymap_len: usize = 0,
    grab_keymap_fd_closed: bool = false,
    grab_repeat_rate: i32 = 0,
    grab_repeat_delay: i32 = 0,
    grab_key_serial: u32 = 0,
    grab_key_time: u32 = 0,
    grab_key: u32 = 0,
    grab_key_state: i32 = 0,
    grab_modifier_serial: u32 = 0,
    grab_modifiers: [4]u32 = @splat(0),

    fn run(self: *@This()) void {
        self.runFallible() catch |err| {
            self.failure = err;
            self.stage.store(@intFromEnum(Stage.failed), .release);
            return;
        };
        self.stage.store(@intFromEnum(Stage.disconnected), .release);
    }
    fn runFallible(self: *@This()) !void {
        const display = try client_wl.Display.connectToFd(self.fd);
        defer display.disconnect();
        const registry = try display.getRegistry();
        defer registry.destroy();
        registry.setListener(*@This(), registryEvent, self);
        try expectClientRoundtrip(display);
        const seat = self.seat orelse return error.SeatMissing;
        defer seat.release();
        switch (self.role) {
            .application => {
                const compositor = self.compositor orelse return error.CompositorMissing;
                defer compositor.destroy();
                const manager = self.text_manager orelse return error.TextInputManagerMissing;
                defer manager.destroy();
                const surface = try compositor.createSurface();
                defer surface.destroy();
                const input = try manager.getTextInput(seat);
                defer input.destroy();
                input.setListener(*@This(), textEvent, self);
                try expectClientRoundtrip(display);
                self.stage.store(@intFromEnum(Stage.ready), .release);
                while (!self.proceed.load(.acquire)) {
                    if (self.shutdown_requested.load(.acquire)) return;
                    std.atomic.spinLoopHint();
                }
                try expectClientRoundtrip(display);
                input.enable();
                input.setSurroundingText("héllo", 3, 1);
                input.setTextChangeCause(.other);
                input.setContentType(.{
                    .completion = true,
                    .on_screen_input_provided = true,
                    .no_emoji = true,
                    .preedit_shown = true,
                }, .email);
                input.setCursorRectangle(2, 3, 4, 5);
                input.commit();
                while (self.edit_count < 4) try expectClientRoundtrip(display);
                self.stage.store(@intFromEnum(Stage.edit_received), .release);
                while (self.proceed.load(.acquire)) {
                    if (self.shutdown_requested.load(.acquire)) return;
                    std.atomic.spinLoopHint();
                }
            },
            .input_method => {
                const compositor = self.compositor orelse return error.CompositorMissing;
                defer compositor.destroy();
                const shm = self.shm orelse return error.ShmMissing;
                defer shm.release();
                const manager = self.method_manager orelse return error.InputMethodManagerMissing;
                defer manager.destroy();
                const method = try manager.getInputMethod(seat);
                defer method.destroy();
                method.setListener(*@This(), methodEvent, self);
                const grab = try method.grabKeyboard();
                defer grab.release();
                grab.setListener(*@This(), grabEvent, self);
                const pointer = if (self.listen_pointer) try seat.getPointer() else null;
                defer if (pointer) |value| value.release();
                if (pointer) |value| value.setListener(*@This(), pointerEvent, self);
                const popup_surface = try compositor.createSurface();
                defer popup_surface.destroy();
                self.popup_surface_object_id = popup_surface.getId();
                const popup = try method.getInputPopupSurface(popup_surface);
                defer popup.destroy();
                popup.setListener(*@This(), popupEvent, self);
                const shm_fd = try std.posix.memfd_create("keywork-generated-input-popup", std.os.linux.MFD.CLOEXEC);
                defer _ = std.os.linux.close(shm_fd);
                const popup_pixels = [2]u32{ 0xffe1_37a5, 0xff46_c972 };
                if (std.os.linux.errno(std.os.linux.ftruncate(shm_fd, @sizeOf(@TypeOf(popup_pixels)))) != .SUCCESS)
                    return error.ShmResizeFailed;
                if (std.c.pwrite(shm_fd, @ptrCast(&popup_pixels), @sizeOf(@TypeOf(popup_pixels)), 0) != @sizeOf(@TypeOf(popup_pixels)))
                    return error.ShmWriteFailed;
                const pool = try shm.createPool(shm_fd, @sizeOf(@TypeOf(popup_pixels)));
                defer pool.destroy();
                const buffer = try pool.createBuffer(0, 1, 1, @sizeOf(u32), .argb8888);
                defer buffer.destroy();
                const replacement_buffer = try pool.createBuffer(@sizeOf(u32), 1, 1, @sizeOf(u32), .argb8888);
                defer replacement_buffer.destroy();
                self.stage.store(@intFromEnum(Stage.ready), .release);
                while (self.method_event_count < 5) try expectClientRoundtrip(display);
                popup_surface.attach(buffer, 0, 0);
                popup_surface.damageBuffer(0, 0, 1, 1);
                popup_surface.commit();
                try expectClientRoundtrip(display);
                self.stage.store(@intFromEnum(Stage.state_received), .release);
                if (self.listen_pointer) {
                    while (@as(Stage, @enumFromInt(self.stage.load(.acquire))) != .popup_clicked) {
                        if (self.shutdown_requested.load(.acquire)) return;
                        try expectClientRoundtrip(display);
                    }
                    popup_surface.attach(replacement_buffer, 0, 0);
                    popup_surface.damageBuffer(0, 0, 1, 1);
                    popup_surface.commit();
                    try expectClientRoundtrip(display);
                    self.stage.store(@intFromEnum(Stage.popup_recommitted), .release);
                }
                while (!self.proceed.load(.acquire)) {
                    if (self.shutdown_requested.load(.acquire)) return;
                    std.atomic.spinLoopHint();
                }
                method.setPreeditString("候補", 0, 6);
                method.deleteSurroundingText(2, 1);
                method.commitString("確定");
                method.commit(self.method_done_count);
                popup_surface.attach(null, 0, 0);
                popup_surface.commit();
                try expectClientRoundtrip(display);
                self.stage.store(@intFromEnum(Stage.popup_unmapped), .release);
                while (self.proceed.load(.acquire)) {
                    if (self.shutdown_requested.load(.acquire)) return;
                    std.atomic.spinLoopHint();
                }
            },
        }
    }
    fn registryEvent(registry: *client_wl.Registry, event: client_wl.Registry.Event, self: *@This()) void {
        switch (event) {
            .global => |g| {
                const name = std.mem.span(g.interface);
                if (std.mem.eql(u8, name, "wl_compositor")) self.compositor = registry.bind(g.name, client_wl.Compositor, @min(g.version, 6)) catch null else if (std.mem.eql(u8, name, "wl_shm")) self.shm = registry.bind(g.name, client_wl.Shm, 1) catch null else if (std.mem.eql(u8, name, "wl_seat")) self.seat = registry.bind(g.name, client_wl.Seat, @min(g.version, 10)) catch null else if (std.mem.eql(u8, name, "zwp_text_input_manager_v3")) {
                    self.text_manager_version = @min(g.version, 2);
                    self.text_manager = registry.bind(g.name, client_zwp.TextInputManagerV3, self.text_manager_version) catch null;
                } else if (std.mem.eql(u8, name, "zwp_input_method_manager_v2")) self.method_manager = registry.bind(g.name, client_zwp.InputMethodManagerV2, 1) catch null;
            },
            .global_remove => {},
        }
    }
    fn popupEvent(_: *client_zwp.InputPopupSurfaceV2, event: client_zwp.InputPopupSurfaceV2.Event, self: *@This()) void {
        switch (event) {
            .text_input_rectangle => |value| {
                self.popup_rectangle = .{ .x = value.x, .y = value.y, .width = value.width, .height = value.height };
                self.popup_rectangle_count += 1;
                self.popup_rectangle_after_done = self.method_done_count > 0;
            },
        }
    }
    fn pointerEvent(_: *client_wl.Pointer, event: client_wl.Pointer.Event, self: *@This()) void {
        switch (event) {
            .enter => |enter| self.popup_pointer_surface = (enter.surface orelse return).getId(),
            .button => |button| if (button.state == .pressed)
                self.stage.store(@intFromEnum(Stage.popup_clicked), .release),
            else => {},
        }
    }
    fn textEvent(_: *client_zwp.TextInputV3, event: client_zwp.TextInputV3.Event, self: *@This()) void {
        const tag: ?EditTag = switch (event) {
            .preedit_string => .preedit,
            .delete_surrounding_text => .delete,
            .commit_string => .commit,
            .done => |done| value: {
                self.done_serial = done.serial;
                break :value .done;
            },
            else => null,
        };
        if (tag) |value| {
            self.edits[self.edit_count] = value;
            self.edit_count += 1;
        }
    }
    fn methodEvent(_: *client_zwp.InputMethodV2, event: client_zwp.InputMethodV2.Event, self: *@This()) void {
        const tag: u8 = switch (event) {
            .activate => 1,
            .surrounding_text => |value| value: {
                const text = std.mem.span(value.text);
                self.method_surrounding_len = @min(text.len, self.method_surrounding.len);
                @memcpy(self.method_surrounding[0..self.method_surrounding_len], text[0..self.method_surrounding_len]);
                self.method_cursor = value.cursor;
                self.method_anchor = value.anchor;
                break :value 2;
            },
            .text_change_cause => |value| value: {
                self.method_cause = @intFromEnum(value.cause);
                break :value 3;
            },
            .content_type => |value| value: {
                self.method_content_hint = @bitCast(value.hint);
                self.method_content_purpose = @intFromEnum(value.purpose);
                break :value 4;
            },
            .done => value: {
                self.method_done_count += 1;
                break :value 5;
            },
            else => 0,
        };
        if (tag != 0 and self.method_event_count < self.method_events.len) {
            self.method_events[self.method_event_count] = tag;
            self.method_event_count += 1;
        }
    }
    fn grabEvent(_: *client_zwp.InputMethodKeyboardGrabV2, event: client_zwp.InputMethodKeyboardGrabV2.Event, self: *@This()) void {
        switch (event) {
            .keymap => |value| {
                self.grab_keymap_size = value.size;
                const wanted = @min(@as(usize, value.size), self.grab_keymap_bytes.len);
                const read_count = std.c.pread(value.fd, &self.grab_keymap_bytes, wanted, 0);
                if (read_count > 0) self.grab_keymap_len = @intCast(read_count);
                _ = std.os.linux.close(value.fd);
                self.grab_keymap_fd_closed = std.os.linux.errno(std.os.linux.fcntl(value.fd, std.os.linux.F.GETFD, 0)) == .BADF;
                self.grab_delivery = true;
                self.grab_events[self.grab_event_count] = 1;
                self.grab_event_count += 1;
            },
            .repeat_info => |value| {
                self.grab_repeat_rate = value.rate;
                self.grab_repeat_delay = value.delay;
                self.grab_delivery = true;
                self.grab_events[self.grab_event_count] = 2;
                self.grab_event_count += 1;
            },
            .key => |value| {
                self.grab_key_serial = value.serial;
                self.grab_key_time = value.time;
                self.grab_key = value.key;
                self.grab_key_state = @intFromEnum(value.state);
                self.grab_events[self.grab_event_count] = 3;
                self.grab_event_count += 1;
            },
            .modifiers => |value| {
                self.grab_modifier_serial = value.serial;
                self.grab_modifiers = .{ value.mods_depressed, value.mods_latched, value.mods_locked, value.group };
                self.grab_events[self.grab_event_count] = 4;
                self.grab_event_count += 1;
            },
        }
    }
    fn shutdown(self: *@This()) void {
        self.shutdown_requested.store(true, .release);
        _ = std.os.linux.shutdown(self.fd, std.os.linux.SHUT.RDWR);
    }
};

const GeneratedTextInputClient = struct {
    const client_wl = wayland.client.wl;
    const client_xdg = wayland.client.xdg;
    const client_zwp = wayland.client.zwp;
    const Stage = enum(u8) { starting, mapped, state_sent, edit_received, left, disconnected, failed };
    const EditTag = enum { preedit, delete, commit, done };

    runtime_directory: []const u8,
    display_name: []const u8,
    command_fd: std.posix.fd_t,
    stage: std.atomic.Value(u8) = .init(@intFromEnum(Stage.starting)),
    wake_fd: std.atomic.Value(i32) = .init(-1),
    failure: ?anyerror = null,
    compositor: ?*client_wl.Compositor = null,
    shm: ?*client_wl.Shm = null,
    seat: ?*client_wl.Seat = null,
    wm_base: ?*client_xdg.WmBase = null,
    text_manager: ?*client_zwp.TextInputManagerV3 = null,
    surface_object_id: u32 = 0,
    configure_serial: u32 = 0,
    entered: bool = false,
    left_value: bool = false,
    edits: [4]EditTag = undefined,
    edit_count: usize = 0,
    preedit: [16]u8 = undefined,
    preedit_len: usize = 0,
    preedit_begin: i32 = 0,
    preedit_end: i32 = 0,
    delete_before: u32 = 0,
    delete_after: u32 = 0,
    committed: [16]u8 = undefined,
    committed_len: usize = 0,
    done_serial: u32 = 0,
    keyboard_enter_serial: u32 = 0,
    keyboard_serials: [2]u32 = @splat(0),
    keyboard_times: [2]u32 = @splat(0),
    keyboard_states: [2]client_wl.Keyboard.KeyState = undefined,
    keyboard_event_count: usize = 0,
    keyboard_modifiers_seen: bool = false,

    fn run(self: *@This()) void {
        self.runFallible() catch |err| {
            self.failure = err;
            self.stage.store(@intFromEnum(Stage.failed), .release);
            return;
        };
        self.stage.store(@intFromEnum(Stage.disconnected), .release);
    }

    fn runFallible(self: *@This()) !void {
        const path = try std.fmt.allocPrintSentinel(
            std.heap.page_allocator,
            "{s}/{s}",
            .{ self.runtime_directory, self.display_name },
            0,
        );
        defer std.heap.page_allocator.free(path);
        const fd = try connectWayringTestSocket(path);
        var fd_owned = true;
        defer if (fd_owned) {
            _ = std.os.linux.close(fd);
        };
        const raw_wake_fd = std.os.linux.dup(fd);
        if (std.os.linux.errno(raw_wake_fd) != .SUCCESS) return error.WakeFdFailed;
        const wake_fd: i32 = @intCast(raw_wake_fd);
        if (self.wake_fd.cmpxchgStrong(-1, wake_fd, .acq_rel, .acquire)) |_| {
            _ = std.os.linux.close(wake_fd);
            return error.ClientShutdown;
        }
        defer self.closeWake(false);

        const display = try client_wl.Display.connectToFd(fd);
        fd_owned = false;
        defer display.disconnect();
        const registry = try display.getRegistry();
        defer registry.destroy();
        registry.setListener(*@This(), registryEvent, self);
        try expectClientRoundtrip(display);
        const compositor = self.compositor orelse return error.CompositorMissing;
        defer compositor.destroy();
        const shm = self.shm orelse return error.ShmMissing;
        defer shm.release();
        const seat = self.seat orelse return error.SeatMissing;
        defer seat.release();
        const wm_base = self.wm_base orelse return error.XdgWmBaseMissing;
        defer wm_base.destroy();
        wm_base.setListener(*@This(), wmBaseEvent, self);
        const manager = self.text_manager orelse return error.TextInputManagerMissing;
        defer manager.destroy();
        const keyboard = try seat.getKeyboard();
        defer keyboard.release();
        keyboard.setListener(*@This(), keyboardEvent, self);

        const surface = try compositor.createSurface();
        defer surface.destroy();
        self.surface_object_id = surface.getId();
        const xdg_surface = try wm_base.getXdgSurface(surface);
        defer xdg_surface.destroy();
        xdg_surface.setListener(*@This(), xdgSurfaceEvent, self);
        const toplevel = try xdg_surface.getToplevel();
        defer toplevel.destroy();
        surface.commit();
        while (self.configure_serial == 0) try expectClientRoundtrip(display);

        const shm_fd = try std.posix.memfd_create("keywork-generated-text", std.os.linux.MFD.CLOEXEC);
        defer _ = std.os.linux.close(shm_fd);
        const pixel: u32 = 0xff33_6699;
        if (std.os.linux.errno(std.os.linux.ftruncate(shm_fd, @sizeOf(u32))) != .SUCCESS)
            return error.ShmResizeFailed;
        if (std.c.pwrite(shm_fd, @ptrCast(&pixel), @sizeOf(u32), 0) != @sizeOf(u32))
            return error.ShmWriteFailed;
        const pool = try shm.createPool(shm_fd, @sizeOf(u32));
        defer pool.destroy();
        const buffer = try pool.createBuffer(0, 1, 1, @sizeOf(u32), .argb8888);
        defer buffer.destroy();
        surface.attach(buffer, 0, 0);
        surface.damageBuffer(0, 0, 1, 1);
        surface.commit();
        try expectClientRoundtrip(display);

        const input = try manager.getTextInput(seat);
        defer input.destroy();
        input.setListener(*@This(), textEvent, self);
        try expectClientRoundtrip(display);
        try self.pause(display, .mapped);
        while (!self.entered) try expectClientRoundtrip(display);
        input.enable();
        input.setSurroundingText("héllo", 3, 1);
        input.setTextChangeCause(.other);
        input.setContentType(.{
            .completion = true,
            .on_screen_input_provided = true,
            .no_emoji = true,
            .preedit_shown = true,
        }, .email);
        input.setCursorRectangle(2, 3, 4, 5);
        input.commit();
        // Version 2 cursor rectangles settle with the associated surface
        // transaction rather than the text-input commit alone.
        surface.commit();
        try expectClientRoundtrip(display);
        try self.pause(display, .state_sent);
        while (self.edit_count < self.edits.len) try expectClientRoundtrip(display);
        try self.pause(display, .edit_received);
        while (!self.left_value) try expectClientRoundtrip(display);
        try self.pause(display, .left);
    }

    fn registryEvent(registry: *client_wl.Registry, event: client_wl.Registry.Event, self: *@This()) void {
        switch (event) {
            .global => |global| {
                const interface = std.mem.span(global.interface);
                if (std.mem.eql(u8, interface, "wl_compositor"))
                    self.compositor = registry.bind(global.name, client_wl.Compositor, @min(global.version, 6)) catch null
                else if (std.mem.eql(u8, interface, "wl_shm"))
                    self.shm = registry.bind(global.name, client_wl.Shm, 1) catch null
                else if (std.mem.eql(u8, interface, "wl_seat"))
                    self.seat = registry.bind(global.name, client_wl.Seat, @min(global.version, 10)) catch null
                else if (std.mem.eql(u8, interface, "xdg_wm_base"))
                    self.wm_base = registry.bind(global.name, client_xdg.WmBase, @min(global.version, 7)) catch null
                else if (std.mem.eql(u8, interface, "zwp_text_input_manager_v3"))
                    self.text_manager = registry.bind(global.name, client_zwp.TextInputManagerV3, @min(global.version, 2)) catch null;
            },
            .global_remove => {},
        }
    }

    fn wmBaseEvent(wm_base: *client_xdg.WmBase, event: client_xdg.WmBase.Event, _: *@This()) void {
        switch (event) {
            .ping => |ping| wm_base.pong(ping.serial),
        }
    }

    fn xdgSurfaceEvent(xdg_surface: *client_xdg.Surface, event: client_xdg.Surface.Event, self: *@This()) void {
        switch (event) {
            .configure => |configure| {
                self.configure_serial = configure.serial;
                xdg_surface.ackConfigure(configure.serial);
            },
        }
    }

    fn textEvent(_: *client_zwp.TextInputV3, event: client_zwp.TextInputV3.Event, self: *@This()) void {
        const tag: ?EditTag = switch (event) {
            .enter => value: {
                self.entered = true;
                break :value null;
            },
            .leave => value: {
                self.left_value = true;
                break :value null;
            },
            .preedit_string => |preedit| value: {
                const text = if (preedit.text) |text| std.mem.span(text) else "";
                self.preedit_len = @min(text.len, self.preedit.len);
                @memcpy(self.preedit[0..self.preedit_len], text[0..self.preedit_len]);
                self.preedit_begin = preedit.cursor_begin;
                self.preedit_end = preedit.cursor_end;
                break :value .preedit;
            },
            .delete_surrounding_text => |delete| value: {
                self.delete_before = delete.before_length;
                self.delete_after = delete.after_length;
                break :value .delete;
            },
            .commit_string => |commit| value: {
                const text = if (commit.text) |text| std.mem.span(text) else "";
                self.committed_len = @min(text.len, self.committed.len);
                @memcpy(self.committed[0..self.committed_len], text[0..self.committed_len]);
                break :value .commit;
            },
            .done => |done| value: {
                self.done_serial = done.serial;
                break :value .done;
            },
            else => null,
        };
        if (tag) |value| if (self.edit_count < self.edits.len) {
            self.edits[self.edit_count] = value;
            self.edit_count += 1;
        };
    }

    fn keyboardEvent(_: *client_wl.Keyboard, event: client_wl.Keyboard.Event, self: *@This()) void {
        switch (event) {
            .keymap => |keymap| _ = std.os.linux.close(keymap.fd),
            .enter => |enter| self.keyboard_enter_serial = enter.serial,
            .key => |key| if (self.keyboard_event_count < self.keyboard_serials.len) {
                const index = self.keyboard_event_count;
                self.keyboard_serials[index] = key.serial;
                self.keyboard_times[index] = key.time;
                self.keyboard_states[index] = key.state;
                self.keyboard_event_count += 1;
            },
            .modifiers => |modifiers| {
                if (modifiers.mods_depressed == 8 and modifiers.mods_latched == 16 and
                    modifiers.mods_locked == 32 and modifiers.group == 4)
                    self.keyboard_modifiers_seen = true;
            },
            else => {},
        }
    }

    fn pause(self: *@This(), display: *client_wl.Display, stage_value: Stage) !void {
        self.stage.store(@intFromEnum(stage_value), .release);
        try waitForWayringCommandDraining(display, self.command_fd);
    }

    fn closeWake(self: *@This(), shutdown_requested: bool) void {
        const fd = self.wake_fd.swap(-2, .acq_rel);
        if (fd < 0) return;
        if (shutdown_requested) _ = std.os.linux.shutdown(fd, std.os.linux.SHUT.RDWR);
        _ = std.os.linux.close(fd);
    }

    fn shutdown(self: *@This()) void {
        signalWayringCommand(self.command_fd) catch {};
        self.closeWake(true);
    }
};

const GeneratedVirtualKeyboardClient = struct {
    const client_wl = wayland.client.wl;
    const client_zwp = wayland.client.zwp;
    const Stage = enum(u8) { starting, ready, sent, disconnected, failed };

    runtime_directory: []const u8,
    display_name: []const u8,
    command_fd: std.posix.fd_t,
    stage: std.atomic.Value(u8) = .init(@intFromEnum(Stage.starting)),
    wake_fd: std.atomic.Value(i32) = .init(-1),
    failure: ?anyerror = null,
    seat: ?*client_wl.Seat = null,
    manager: ?*client_zwp.VirtualKeyboardManagerV1 = null,
    keymap_fd_open_after_send: bool = false,

    fn run(self: *@This()) void {
        self.runFallible() catch |err| {
            self.failure = err;
            self.stage.store(@intFromEnum(Stage.failed), .release);
            return;
        };
        self.stage.store(@intFromEnum(Stage.disconnected), .release);
    }

    fn runFallible(self: *@This()) !void {
        const path = try std.fmt.allocPrintSentinel(
            std.heap.page_allocator,
            "{s}/{s}",
            .{ self.runtime_directory, self.display_name },
            0,
        );
        defer std.heap.page_allocator.free(path);
        const fd = try connectWayringTestSocket(path);
        var fd_owned = true;
        defer if (fd_owned) {
            _ = std.os.linux.close(fd);
        };
        const raw_wake_fd = std.os.linux.dup(fd);
        if (std.os.linux.errno(raw_wake_fd) != .SUCCESS) return error.WakeFdFailed;
        const wake_fd: i32 = @intCast(raw_wake_fd);
        if (self.wake_fd.cmpxchgStrong(-1, wake_fd, .acq_rel, .acquire)) |_| {
            _ = std.os.linux.close(wake_fd);
            return error.ClientShutdown;
        }
        defer self.closeWake(false);

        const display = try client_wl.Display.connectToFd(fd);
        fd_owned = false;
        defer display.disconnect();
        const registry = try display.getRegistry();
        defer registry.destroy();
        registry.setListener(*@This(), registryEvent, self);
        try expectClientRoundtrip(display);
        const seat = self.seat orelse return error.SeatMissing;
        defer seat.release();
        const manager = self.manager orelse return error.VirtualKeyboardManagerMissing;
        defer manager.destroy();
        const keyboard = try manager.createVirtualKeyboard(seat);
        defer keyboard.destroy();
        try expectClientRoundtrip(display);
        try self.pause(display, .ready);

        const keymap = "keymap\x00\x00";
        const keymap_fd = try std.posix.memfd_create("keywork-generated-virtual-keyboard", std.os.linux.MFD.CLOEXEC);
        defer _ = std.os.linux.close(keymap_fd);
        if (std.os.linux.errno(std.os.linux.ftruncate(keymap_fd, keymap.len)) != .SUCCESS)
            return error.KeymapResizeFailed;
        if (std.c.pwrite(keymap_fd, keymap.ptr, keymap.len, 0) != keymap.len)
            return error.KeymapWriteFailed;
        keyboard.keymap(.xkb_v1, keymap_fd, keymap.len);
        keyboard.key(41, 31, @intFromEnum(client_wl.Keyboard.KeyState.pressed));
        keyboard.modifiers(8, 16, 32, 4);
        keyboard.key(42, 31, @intFromEnum(client_wl.Keyboard.KeyState.released));
        try expectClientRoundtrip(display);
        self.keymap_fd_open_after_send = std.c.fcntl(keymap_fd, std.posix.F.GETFD) >= 0;
        try self.pause(display, .sent);
    }

    fn registryEvent(registry: *client_wl.Registry, event: client_wl.Registry.Event, self: *@This()) void {
        switch (event) {
            .global => |global| {
                const interface = std.mem.span(global.interface);
                if (std.mem.eql(u8, interface, "wl_seat"))
                    self.seat = registry.bind(global.name, client_wl.Seat, @min(global.version, 10)) catch null
                else if (std.mem.eql(u8, interface, "zwp_virtual_keyboard_manager_v1"))
                    self.manager = registry.bind(global.name, client_zwp.VirtualKeyboardManagerV1, 1) catch null;
            },
            .global_remove => {},
        }
    }

    fn pause(self: *@This(), display: *client_wl.Display, stage_value: Stage) !void {
        self.stage.store(@intFromEnum(stage_value), .release);
        try waitForWayringCommandDraining(display, self.command_fd);
    }

    fn closeWake(self: *@This(), shutdown_requested: bool) void {
        const fd = self.wake_fd.swap(-2, .acq_rel);
        if (fd < 0) return;
        if (shutdown_requested) _ = std.os.linux.shutdown(fd, std.os.linux.SHUT.RDWR);
        _ = std.os.linux.close(fd);
    }

    fn shutdown(self: *@This()) void {
        signalWayringCommand(self.command_fd) catch {};
        self.closeWake(true);
    }
};

fn connectWayringTestSocket(path: [:0]const u8) !std.posix.fd_t {
    const linux = std.os.linux;
    var address: linux.sockaddr.un = .{ .family = linux.AF.UNIX, .path = @splat(0) };
    if (path.len >= address.path.len) return error.InvalidSocketPath;
    @memcpy(address.path[0..path.len], path);
    const raw_fd = linux.socket(linux.AF.UNIX, linux.SOCK.STREAM | linux.SOCK.CLOEXEC, 0);
    if (linux.errno(raw_fd) != .SUCCESS) return error.SocketFailed;
    const fd: linux.fd_t = @intCast(raw_fd);
    errdefer _ = linux.close(fd);
    const length: linux.socklen_t = @intCast(@offsetOf(linux.sockaddr.un, "path") + path.len + 1);
    if (linux.errno(linux.connect(fd, @ptrCast(&address), length)) != .SUCCESS)
        return error.ConnectFailed;
    return fd;
}

fn expectClientRoundtrip(display: *wayland.client.wl.Display) !void {
    if (display.roundtrip() != .SUCCESS) return error.RoundtripFailed;
