fn wayringSurfaceWithPixel(server: *Self, pixel: u32) ?SurfaceRegistry.Id {
    var iterator = server.headless_surface_forest.nodeIterator();
    while (iterator.next()) |node| {
        const state = server.surface_registry.renderState(node.id) orelse continue;
        if (state.buffer.pixels.len == 1 and state.buffer.pixels[0] == (pixel | 0xff00_0000))
            return node.id;
    }
    return null;
}

fn waitForWayringDisconnect(server: *Self, host: anytype, compositor: *WayringCompositor) !void {
    for (0..1_000) |_| {
        if (host.connectionCount() == 0 and compositor.surfaceCount() == 0 and
            server.headless_surface_forest.len() == 0) return;
        try server.eventLoop().dispatch(1);
        if (host.failure()) |err| return err;
    }
    return error.WayringDisconnectTimedOut;
}

fn expectWayringSnapshot(
    server: *Self,
    expected_pixels: [2]u32,
    expected_version: u64,
    expected_logical_size: render.Size,
    expected_transform: render.BufferTransform,
) !void {
    try std.testing.expectEqual(@as(usize, 1), server.headless_surface_forest.len());
    const state = server.surface_registry.renderState(server.headless_surface_forest.rootAt(0).?.id).?;
    try std.testing.expectEqual(expected_logical_size, state.logical_size);
    try std.testing.expectEqual(expected_transform, state.transform);
    try std.testing.expectEqual(expected_version, state.buffer.source_cache.?.version);
    const normalized = [2]u32{
        expected_pixels[0] | 0xff00_0000,
        expected_pixels[1] | 0xff00_0000,
    };
    try std.testing.expectEqualSlices(u32, &normalized, state.buffer.pixels[0..2]);
}

fn expectWayringScaleSnapshot(
    server: *Self,
    expected_pixels: [8]u32,
    expected_version: u64,
    expected_logical_size: render.Size,
) !void {
    try std.testing.expectEqual(@as(usize, 1), server.headless_surface_forest.len());
    const state = server.surface_registry.renderState(server.headless_surface_forest.rootAt(0).?.id).?;
    try std.testing.expectEqual(render.Size{ .width = 4, .height = 2 }, state.buffer.size);
    try std.testing.expectEqual(expected_logical_size, state.logical_size);
    try std.testing.expectEqual(render.BufferTransform.normal, state.transform);
    try std.testing.expectEqual(expected_version, state.buffer.source_cache.?.version);
    var normalized = expected_pixels;
    for (&normalized) |*pixel| pixel.* |= 0xff00_0000;
    try std.testing.expectEqualSlices(u32, &normalized, state.buffer.pixels);
}

fn expectWayringFractionalSnapshot(server: *Self, expected_version: u64) !void {
    try std.testing.expectEqual(@as(usize, 1), server.headless_surface_forest.len());
    const state = server.surface_registry.renderState(server.headless_surface_forest.rootAt(0).?.id).?;
    try std.testing.expectEqual(render.Size{ .width = 6, .height = 3 }, state.buffer.size);
    try std.testing.expectEqual(render.Size{ .width = 4, .height = 2 }, state.logical_size);
    try std.testing.expectEqual(render.BufferTransform.normal, state.transform);
    try std.testing.expectEqual(expected_version, state.buffer.source_cache.?.version);
    var normalized = wayring_fractional_pixels;
    for (&normalized) |*pixel| pixel.* |= 0xff00_0000;
    try std.testing.expectEqualSlices(u32, &normalized, state.buffer.pixels);
}

fn expectWayringHeadlessPixels(server: *Self, expected_surface: ?[2]u32) !void {
    const target = switch (server.primaryRenderOutput().backend.acquire().?) {
        .pixels => |pixels| pixels,
        else => return error.ExpectedCpuHeadlessTarget,
    };
    var expected: [8]u32 = @splat(renderColor(server.palette.desktop_background).argb8888());
    if (expected_surface) |pixels| {
        expected[0] = pixels[0] | 0xff00_0000;
        expected[1] = pixels[1] | 0xff00_0000;
    }
    try std.testing.expectEqualSlices(u32, &expected, target.pixels);
}

