fn renderPendingWayringFrame(server: *Self, host: anytype, previous_frames: u64) !void {
    const output = server.primaryRenderOutput();
    try renderPendingWayringOutput(server, host, output, previous_frames);
}

fn renderPendingWayringOutput(
    server: *Self,
    host: anytype,
    output: *RenderOutput,
    previous_frames: u64,
) !void {
    try std.testing.expect(output.repaint_needed);
    try std.testing.expect(output.render_scheduled);
    try output.timer.?.timerUpdate(1);
    for (0..100) |_| {
        try server.eventLoop().dispatch(50);
        if (host.failure()) |err| return err;
        if (output.frame_statistics.frames_presented > previous_frames) return;
    }
    return error.WayringFrameTimedOut;
}

fn rejectWayringFrames(server: *Self, output: *RenderOutput, child_id: SurfaceRegistry.Id) !void {
    try server.renderer.beginFrame(.{ .offscreen = .{
        .id = 1,
        .size = .{ .width = 1, .height = 1 },
    } }, .{}, .{}, null, .{});
    try server.renderer.append(&.{.{ .image = imageFromRenderState(
        server.surface_registry.renderState(child_id).?,
        .{ .position = .{}, .rounded_clip = null, .clip = null },
        surfaceSampleTag(child_id),
    ) }});
    try std.testing.expectError(error.InvalidTarget, server.renderer.finishFrame());
    try std.testing.expect(server.headless_surface_forest.state(child_id).?.frame_demand);

    var target_pixels: [12]u32 = undefined;
    try server.renderer.beginFrame(.{ .pixels = .{
        .size = .{ .width = 6, .height = 2 },
        .stride_pixels = 6,
        .pixels = &target_pixels,
    } }, .{}, .{}, null, .{});
    var capture_id: u32 = 1;
    const frame: OutputFrame = .{
        .render_output = output,
        .output = server.outputs.get(output.protocol_id).?,
        .visible_rect = .{ .x = 0, .y = 0, .width = 6, .height = 2 },
        .track_visibility = false,
        .next_backdrop_capture_id = &capture_id,
    };
    try server.renderCommands(&frame, &.{.{ .clear = render.Color.rgba(0, 0, 0, 0) }});
    _ = try server.renderDesktopContents(&frame, false, false);
    server.renderer.cancelFrame();
    try std.testing.expect(!server.renderer.wasSampled(surfaceSampleTag(child_id)));
    try std.testing.expect(server.headless_surface_forest.state(child_id).?.frame_demand);
}

test "production Wayring fractional scale and viewporter render real SHM pixels end to end" {
    const WayringHost = @import("wayland/WayringHost.zig");
    const wayring = @import("wayring");
    const linux = std.os.linux;
    var marker: u8 = 0;
    const runtime_directory = try std.fmt.allocPrintSentinel(
        std.testing.allocator,
        "/tmp/keywork-wayring-headless-{d}-{x}",
        .{ linux.getpid(), @intFromPtr(&marker) },
        0,
    );
    defer std.testing.allocator.free(runtime_directory);
    if (linux.errno(linux.mkdir(runtime_directory.ptr, 0o700)) != .SUCCESS)
        return error.TestDirectoryCreationFailed;
    defer _ = linux.rmdir(runtime_directory.ptr);

    const server = try Self.createWithVirtualOutput(
        std.testing.allocator,
        std.testing.io,
        .cpu,
        .headless,
        null,
        .{
            .size = .{ .width = 4, .height = 2 },
            // Keep presentation behind the client release handshake. The
            // test advances this real refresh timer explicitly afterward.
            .refresh_millihertz = 1,
        },
    );
    var server_live = true;
    defer if (server_live) server.destroy();
    const registry_baseline = server.surface_registry.len();
    try std.testing.expectEqual(@as(usize, 0), registry_baseline);
    const initial_output = server.primary_render_output;
    const output = server.primaryRenderOutput();
    try std.testing.expect(server.wayringPresentationListener() != null);

    var protocol_server: wayring.server.Server = .init(std.testing.allocator);
    var protocol_server_live = true;
    defer if (protocol_server_live) protocol_server.deinit();
    var clients: WayringClients = undefined;
    clients.init(std.testing.allocator, server.clientRegistry());
    var clients_live = true;
    defer if (clients_live) clients.deinit();
    var compositor: WayringCompositor = undefined;
    try compositor.init(
        std.testing.allocator,
        &protocol_server,
        server.surfaceRegistry(),
        server.wayringPresentationListener(),
    );
    var compositor_live = true;
    defer if (compositor_live) compositor.deinit();
    var seat: WayringSeatAdapter = .init(
        std.testing.allocator,
        &protocol_server,
        &clients,
        &compositor,
        server.generatedSeatRequestSink(),
        server.generatedSeatName(),
    );
    var seat_live = true;
    defer if (seat_live) {
        seat.unpublish();
        seat.deinit();
    };
    try seat.publish();
    var wayring_outputs: WayringOutput = undefined;
    try wayring_outputs.init(
        std.testing.allocator,
        &protocol_server,
        server.wayringOutputLayout().?,
        &compositor,
    );
    var wayring_outputs_live = true;
    defer if (wayring_outputs_live) wayring_outputs.deinit();
    var xdg: WayringXdgShell = undefined;
    xdg.init(
        std.testing.allocator,
        &protocol_server,
        server.neutralXdgShell(),
        &clients,
        &compositor,
        &wayring_outputs,
    );
    var xdg_live = true;
    defer if (xdg_live) {
        xdg.unpublish();
        xdg.deinit();
    };
    xdg.setSeatAdapter(&seat);
    try xdg.publish();
    var viewporter: WayringViewporter = undefined;
    viewporter.init(std.testing.allocator, &protocol_server, &compositor);
    var viewporter_live = true;
    defer if (viewporter_live) {
        viewporter.unpublish();
        viewporter.deinit();
    };
    try viewporter.publish();
    var fractional_scale: WayringFractionalScale = undefined;
    try fractional_scale.init(
        std.testing.allocator,
        &protocol_server,
        &compositor,
        &wayring_outputs,
        server.wayringOutputLayout().?,
        server.wayringDefaultOutputId().?,
    );
    var fractional_scale_live = true;
    var default_output_listener_live = false;
    defer if (fractional_scale_live) {
        if (default_output_listener_live) server.clearWayringDefaultOutputListener(&fractional_scale);
        fractional_scale.unpublish();
        fractional_scale.deinit();
    };
    server.setWayringDefaultOutputListener(.{
        .context = &fractional_scale,
        .changed = WayringFractionalScale.defaultOutputChanged,
    });
    default_output_listener_live = true;
    try fractional_scale.publish();
    var cursor_shape: WayringCursorShape = undefined;
    cursor_shape.init(
        std.testing.allocator,
        &protocol_server,
        &seat,
        server.generatedCursorShape(),
        server.generatedSeatRequestSink(),
    );
    var cursor_shape_live = true;
    defer if (cursor_shape_live) {
        cursor_shape.unpublish();
        cursor_shape.deinit();
    };
    try cursor_shape.publish();
    const Lifecycle = struct {
        clients: *WayringClients,
        outputs: *WayringOutput,
        xdg: *WayringXdgShell,
        viewporter: *WayringViewporter,
        fractional_scale: *WayringFractionalScale,
        cursor_shape: *WayringCursorShape,
        compositor: *WayringCompositor,
        seat: *WayringSeatAdapter,

        fn accepted(context: *anyopaque, client: *wayring.server.Client) !void {
            const self: *@This() = @ptrCast(@alignCast(context));
            _ = try self.clients.register(client);
            errdefer self.clients.unregister(client);
            try self.seat.trackClient(client);
        }

        fn destroy(erased: *anyopaque, client: *wayring.server.Client) void {
            const self: *@This() = @ptrCast(@alignCast(erased));
            self.cursor_shape.destroyClientResources(client);
            self.seat.destroyClientResources(client);
            self.fractional_scale.destroyClientResources(client);
            self.viewporter.destroyClientResources(client);
            self.xdg.destroyClientResources(client);
            self.outputs.destroyClientResources(client);
            self.compositor.destroyClientResources(client);
            if (self.clients.id(client) != null) self.clients.unregister(client);
        }
    };
    var lifecycle: Lifecycle = .{
        .clients = &clients,
        .outputs = &wayring_outputs,
        .xdg = &xdg,
        .viewporter = &viewporter,
        .fractional_scale = &fractional_scale,
        .cursor_shape = &cursor_shape,
        .compositor = &compositor,
        .seat = &seat,
    };
    const host = try WayringHost.create(
        std.testing.allocator,
        server.eventLoop(),
        &protocol_server,
        runtime_directory,
        .{
            .context = &lifecycle,
            .accepted = Lifecycle.accepted,
            .destroy_resources = Lifecycle.destroy,
        },
    );
    var host_live = true;
    defer if (host_live) host.destroy() catch {};

    const raw_command_fd = linux.eventfd(0, linux.EFD.CLOEXEC);
    if (linux.errno(raw_command_fd) != .SUCCESS) return error.EventFdFailed;
    const command_fd: std.posix.fd_t = @intCast(raw_command_fd);
    defer _ = linux.close(command_fd);
    var client: WayringHeadlessClient = .{
        .runtime_directory = runtime_directory,
        .display_name = host.displayName(),
        .command_fd = command_fd,
    };
    const thread = try std.Thread.spawn(.{}, WayringHeadlessClient.run, .{&client});
    var joined = false;
    defer if (!joined) {
        client.shutdown();
        thread.join();
    };

    var previous_frames = output.frame_statistics.frames_presented;
    try waitForWayringClientStage(server, host, &client, .initial_released);
    try std.testing.expectEqual(previous_frames, output.frame_statistics.frames_presented);
    try std.testing.expectEqual(@as(u32, 6), client.compositor_version.load(.acquire));
    try std.testing.expectEqual(@as(u8, 1), client.preferred_buffer_scale_count.load(.acquire));
    try std.testing.expectEqual(@as(i32, 1), client.preferred_buffer_scale.load(.acquire));
    try std.testing.expectEqual(@as(u8, 1), client.preferred_buffer_transform_count.load(.acquire));
    try std.testing.expectEqual(
        @as(i32, @intFromEnum(wayland.client.wl.Output.Transform.normal)),
        client.preferred_buffer_transform.load(.acquire),
    );
    try std.testing.expectEqual(@as(u8, 1), client.release_count.load(.acquire));
    try std.testing.expectEqual(registry_baseline + 1, server.surface_registry.len());
    try std.testing.expectEqual(@as(usize, 1), compositor.surfaceCount());
    try std.testing.expectEqual(@as(usize, 0), compositor.regionCount());
    const initial_state = server.surface_registry.renderState(server.headless_surface_forest.rootAt(0).?.id).?;
    try std.testing.expect(initial_state.opaque_region.?.contains(0, 0));
    try std.testing.expect(!initial_state.opaque_region.?.contains(1, 0));
    try expectWayringSnapshot(
        server,
        .{ 0x0011_2233, 0x0044_5566 },
        1,
        .{ .width = 2, .height = 1 },
        .normal,
    );
    try renderPendingWayringFrame(server, host, previous_frames);
    try expectWayringHeadlessPixels(server, .{ 0x0011_2233, 0x0044_5566 });
    try std.testing.expectEqual(@as(u8, 0), client.frame_done_count.load(.acquire));

    try signalWayringCommand(command_fd);
    try waitForWayringClientStage(server, host, &client, .initial_done);
    try std.testing.expectEqual(@as(u8, 1), client.frame_done_count.load(.acquire));

    const output_snapshot = server.outputs.get(output.protocol_id).?.snapshot();
    _ = server.outputs.get(output.protocol_id).?.configure(
        output_snapshot.position,
        output_snapshot.size,
        output_snapshot.mode_size,
        output_snapshot.refresh_millihertz,
        output_snapshot.mode_preferred,
        @intCast(output_snapshot.scale),
        .{ .numerator = 180 },
    );
    previous_frames = output.frame_statistics.frames_presented;
    try signalWayringCommand(command_fd);
    try waitForWayringClientStage(server, host, &client, .replacement_released);
    try std.testing.expectEqual(previous_frames, output.frame_statistics.frames_presented);
    try expectWayringFractionalSnapshot(server, 2);
    try renderPendingWayringFrame(server, host, previous_frames);
    try expectWayringHeadlessExactPixels(server, .{
        0x001c_0000, 0x0034_0000, 0x004c_0000, 0x0064_0000,
        0x004c_0000, 0x0064_0000, 0x007c_0000, 0x0094_0000,
    });

    const changed_output_snapshot = server.outputs.get(output.protocol_id).?.snapshot();
    _ = server.outputs.get(output.protocol_id).?.configure(
        changed_output_snapshot.position,
        changed_output_snapshot.size,
        changed_output_snapshot.mode_size,
        changed_output_snapshot.refresh_millihertz,
        changed_output_snapshot.mode_preferred,
        @intCast(changed_output_snapshot.scale),
        .{ .numerator = 120 },
    );
    previous_frames = output.frame_statistics.frames_presented;
    try signalWayringCommand(command_fd);
    try waitForWayringClientStage(server, host, &client, .transformed_committed);
    try std.testing.expectEqual(previous_frames, output.frame_statistics.frames_presented);
    try std.testing.expectEqual(@as(u8, 1), client.frame_done_count.load(.acquire));
    try expectWayringSnapshot(
        server,
        .{ 0x0066_7788, 0x0099_aabb },
        3,
        .{ .width = 1, .height = 2 },
        .rotate_90,
    );
    try std.testing.expect(output.damage.coversRectangle(0, 0, 2, 1));
    try std.testing.expect(output.damage.coversRectangle(0, 0, 1, 2));
    try std.testing.expect(server.headless_surface_forest.rootAt(0).?.frame_demand);
    try renderPendingWayringFrame(server, host, previous_frames);
    try expectWayringRotatedHeadlessPixels(server, .{ 0x0066_7788, 0x0099_aabb });

    try signalWayringCommand(command_fd);
    try waitForWayringClientStage(server, host, &client, .transformed_done);
    try std.testing.expectEqual(@as(u8, 2), client.frame_done_count.load(.acquire));

    // Every source pixel is distinct so the CPU target distinguishes an
    // uncropped buffer from the cropped and linearly scaled result below.
    const scale_pixels = [8]u32{
        0x0011_0000, 0x0022_0000, 0x0033_0000, 0x0044_0000,
        0x0055_0000, 0x0066_0000, 0x0077_0000, 0x0088_0000,
    };
    previous_frames = output.frame_statistics.frames_presented;
    try signalWayringCommand(command_fd);
    try waitForWayringClientStage(server, host, &client, .scale_buffer_released);
    try std.testing.expectEqual(previous_frames, output.frame_statistics.frames_presented);
    try std.testing.expectEqual(@as(u8, 4), client.release_count.load(.acquire));
    try expectWayringScaleSnapshot(server, scale_pixels, 4, .{ .width = 4, .height = 2 });
    try std.testing.expect(output.damage.coversRectangle(0, 0, 1, 2));
    try std.testing.expect(output.damage.coversRectangle(0, 0, 4, 2));
    try renderPendingWayringFrame(server, host, previous_frames);
    try expectWayringHeadlessExactPixels(server, scale_pixels);

    const viewport_pixels = [8]u32{
        0x001d_0000, 0x0026_0000, 0x002e_0000, 0x0037_0000,
        0x0061_0000, 0x006a_0000, 0x0072_0000, 0x007b_0000,
    };
    previous_frames = output.frame_statistics.frames_presented;
    try signalWayringCommand(command_fd);
    try waitForWayringClientStage(server, host, &client, .viewport_committed);
    try std.testing.expectEqual(previous_frames, output.frame_statistics.frames_presented);
    try std.testing.expectEqual(@as(usize, 1), viewporter.viewports.items.len);
    try renderPendingWayringFrame(server, host, previous_frames);
    try expectWayringHeadlessExactPixels(server, viewport_pixels);

    previous_frames = output.frame_statistics.frames_presented;
    try signalWayringCommand(command_fd);
    try waitForWayringClientStage(server, host, &client, .viewport_destroyed);
    try std.testing.expectEqual(previous_frames, output.frame_statistics.frames_presented);
    try std.testing.expectEqual(@as(usize, 0), viewporter.viewports.items.len);
    try renderPendingWayringFrame(server, host, previous_frames);
    try expectWayringHeadlessExactPixels(server, scale_pixels);

    previous_frames = output.frame_statistics.frames_presented;
    try signalWayringCommand(command_fd);
    try waitForWayringClientStage(server, host, &client, .scaled_committed);
    try std.testing.expectEqual(previous_frames, output.frame_statistics.frames_presented);
    try std.testing.expectEqual(@as(u8, 2), client.frame_done_count.load(.acquire));
    try std.testing.expectEqual(@as(u8, 4), client.release_count.load(.acquire));
    try expectWayringScaleSnapshot(server, scale_pixels, 4, .{ .width = 2, .height = 1 });
    try std.testing.expect(output.damage.coversRectangle(0, 0, 4, 2));
    try std.testing.expect(output.damage.coversRectangle(0, 0, 2, 1));
    try std.testing.expect(output.repaint_needed);
    try std.testing.expect(output.render_scheduled);
    try std.testing.expect(server.headless_surface_forest.rootAt(0).?.frame_demand);
    try renderPendingWayringFrame(server, host, previous_frames);
    try expectWayringHeadlessPixels(server, .{ 0x003b_0000, 0x005d_0000 });

    try signalWayringCommand(command_fd);
    try waitForWayringClientStage(server, host, &client, .scaled_done);
    try std.testing.expectEqual(@as(u8, 3), client.frame_done_count.load(.acquire));

    previous_frames = output.frame_statistics.frames_presented;
    try signalWayringCommand(command_fd);
    try waitForWayringClientStage(server, host, &client, .damage_buffer_committed);
    try std.testing.expectEqual(previous_frames, output.frame_statistics.frames_presented);
    try std.testing.expectEqual(@as(u8, 3), client.frame_done_count.load(.acquire));
    try expectWayringScaleSnapshot(server, scale_pixels, 4, .{ .width = 2, .height = 1 });
    try std.testing.expect(output.damage.coversRectangle(0, 0, 2, 1));
    try std.testing.expect(output.repaint_needed);
    try std.testing.expect(output.render_scheduled);
    try std.testing.expect(server.headless_surface_forest.rootAt(0).?.frame_demand);
    try renderPendingWayringFrame(server, host, previous_frames);
    try expectWayringHeadlessPixels(server, .{ 0x003b_0000, 0x005d_0000 });

    try signalWayringCommand(command_fd);
    try waitForWayringClientStage(server, host, &client, .damage_buffer_done);
    try std.testing.expectEqual(@as(u8, 4), client.frame_done_count.load(.acquire));

    previous_frames = output.frame_statistics.frames_presented;
    try signalWayringCommand(command_fd);
    try waitForWayringClientStage(server, host, &client, .offset_attachment_released);
    try std.testing.expectEqual(previous_frames, output.frame_statistics.frames_presented);
    try std.testing.expectEqual(@as(u8, 5), client.release_count.load(.acquire));
    try std.testing.expectEqual(@as(u8, 4), client.frame_done_count.load(.acquire));
    try expectWayringScaleSnapshot(server, scale_pixels, 5, .{ .width = 2, .height = 1 });
    try std.testing.expect(output.damage.coversRectangle(0, 0, 2, 1));
    try std.testing.expect(output.repaint_needed);
    try std.testing.expect(output.render_scheduled);
    try std.testing.expect(server.headless_surface_forest.rootAt(0).?.frame_demand);
    try renderPendingWayringFrame(server, host, previous_frames);
    try expectWayringHeadlessPixels(server, .{ 0x003b_0000, 0x005d_0000 });
    const attached_offset_state = server.surface_registry.renderState(server.headless_surface_forest.rootAt(0).?.id).?;
    const attached_offset_pointer = attached_offset_state.buffer.pixels.ptr;
    const attached_offset_cache = attached_offset_state.buffer.source_cache.?;

    try signalWayringCommand(command_fd);
    try waitForWayringClientStage(server, host, &client, .offset_attachment_done);
    try std.testing.expectEqual(@as(u8, 5), client.frame_done_count.load(.acquire));

    previous_frames = output.frame_statistics.frames_presented;
    try signalWayringCommand(command_fd);
    try waitForWayringClientStage(server, host, &client, .offset_only_committed);
    try std.testing.expectEqual(previous_frames, output.frame_statistics.frames_presented);
    try std.testing.expectEqual(@as(u8, 5), client.release_count.load(.acquire));
    try std.testing.expectEqual(@as(u8, 5), client.frame_done_count.load(.acquire));
    const offset_only_state = server.surface_registry.renderState(server.headless_surface_forest.rootAt(0).?.id).?;
    try std.testing.expectEqual(attached_offset_pointer, offset_only_state.buffer.pixels.ptr);
    try std.testing.expectEqual(attached_offset_cache, offset_only_state.buffer.source_cache.?);
    try std.testing.expectEqual(render.Size{ .width = 2, .height = 1 }, offset_only_state.logical_size);
    try std.testing.expect(output.damage.coversRectangle(0, 0, 2, 1));
    try std.testing.expect(output.repaint_needed);
    try std.testing.expect(output.render_scheduled);
    try std.testing.expect(server.headless_surface_forest.rootAt(0).?.frame_demand);
    try renderPendingWayringFrame(server, host, previous_frames);
    try expectWayringHeadlessPixels(server, .{ 0x003b_0000, 0x005d_0000 });

    try signalWayringCommand(command_fd);
    try waitForWayringClientStage(server, host, &client, .offset_only_done);
    try std.testing.expectEqual(@as(u8, 6), client.frame_done_count.load(.acquire));

    previous_frames = output.frame_statistics.frames_presented;
    try signalWayringCommand(command_fd);
    try waitForWayringClientStage(server, host, &client, .unmapped);
    try std.testing.expectEqual(previous_frames, output.frame_statistics.frames_presented);
    try std.testing.expectEqual(@as(u8, 6), client.frame_done_count.load(.acquire));
    try std.testing.expect(server.surface_registry.renderState(server.headless_surface_forest.rootAt(0).?.id) == null);
    try std.testing.expect(server.headless_surface_forest.rootAt(0).?.frame_demand);
    try renderPendingWayringFrame(server, host, previous_frames);
    try expectWayringHeadlessPixels(server, null);

    try signalWayringCommand(command_fd);
    try waitForWayringClientStage(server, host, &client, .unmapped_no_done);
    try std.testing.expectEqual(@as(u8, 6), client.frame_done_count.load(.acquire));
    try std.testing.expect(server.headless_surface_forest.rootAt(0).?.frame_demand);

    previous_frames = output.frame_statistics.frames_presented;
    try signalWayringCommand(command_fd);
    try waitForWayringClientStage(server, host, &client, .remapped_released);
    try std.testing.expectEqual(previous_frames, output.frame_statistics.frames_presented);
    try expectWayringSnapshot(
        server,
        .{ 0x00cc_ddee, 0x0001_0203 },
        6,
        .{ .width = 2, .height = 1 },
        .normal,
    );
    try renderPendingWayringFrame(server, host, previous_frames);
    try expectWayringHeadlessPixels(server, .{ 0x00cc_ddee, 0x0001_0203 });

    try signalWayringCommand(command_fd);
    try waitForWayringClientStage(server, host, &client, .remapped_done);
    try std.testing.expectEqual(@as(u8, 7), client.frame_done_count.load(.acquire));

    const replacement_output = try server.addRenderOutput(std.testing.io, .{
        .kind = .headless,
        .size = .{ .width = 4, .height = 2 },
        .scale = .{ .numerator = 240 },
        .position = .{ .x = 4 },
        .name = "HEADLESS-2",
        .description = "Keywork fractional default replacement output",
        .model = "headless",
    });
    server.replacePrimaryRenderOutput(initial_output);
    try signalWayringCommand(command_fd);
    try waitForWayringClientStage(server, host, &client, .default_replaced);
    try std.testing.expectEqual(@as(u8, 4), client.fractional_scale_count.load(.acquire));
    try std.testing.expectEqual(@as(u32, 240), client.fractional_scale.load(.acquire));
    server.replacePrimaryRenderOutput(replacement_output);
    try std.testing.expect(server.removeRenderOutput(replacement_output));

    previous_frames = output.frame_statistics.frames_presented;
    try signalWayringCommand(command_fd);
    try waitForWayringClientStage(server, host, &client, .outstanding_callback);
    try std.testing.expectEqual(previous_frames, output.frame_statistics.frames_presented);
    try std.testing.expectEqual(@as(u8, 7), client.frame_done_count.load(.acquire));
    try std.testing.expect(server.headless_surface_forest.rootAt(0).?.frame_demand);

    try signalWayringCommand(command_fd);
    try waitForWayringClientStage(server, host, &client, .disconnected);
    thread.join();
    joined = true;
    try waitForWayringDisconnect(server, host, &compositor);
    try std.testing.expectEqual(previous_frames, output.frame_statistics.frames_presented);
    try std.testing.expectEqual(@as(u8, 7), client.frame_done_count.load(.acquire));
    try std.testing.expectEqual(@as(u8, 1), client.preferred_buffer_scale_count.load(.acquire));
    try std.testing.expectEqual(@as(u8, 1), client.preferred_buffer_transform_count.load(.acquire));
    try std.testing.expectEqual(@as(u8, 4), client.fractional_scale_count.load(.acquire));
    try std.testing.expectEqual(@as(u32, 240), client.fractional_scale.load(.acquire));
    try std.testing.expectEqual(registry_baseline, server.surface_registry.len());
    try std.testing.expectEqual(@as(usize, 0), fractional_scale.fractional_scales.items.len);
    try std.testing.expectEqual(@as(usize, 0), fractional_scale.managers.items.len);
    try std.testing.expectEqual(@as(usize, 0), cursor_shape.deviceCount());
    try std.testing.expectEqual(@as(usize, 0), cursor_shape.managerCount());
    try std.testing.expectEqual(@as(usize, 0), viewporter.viewports.items.len);
    try std.testing.expectEqual(@as(usize, 0), viewporter.managers.items.len);
    try std.testing.expectEqual(@as(usize, 0), server.client_registry.len());
    try renderPendingWayringFrame(server, host, previous_frames);
    try expectWayringHeadlessPixels(server, null);

    host.beginShutdown();
    for (0..100) |_| {
        if (host.route_count == 0 and host.connectionCount() == 0) break;
        try server.eventLoop().dispatch(50);
        if (host.failure()) |err| return err;
    } else return error.WayringTransportDrainTimedOut;
    try host.destroy();
    host_live = false;
    cursor_shape.unpublish();
    cursor_shape.deinit();
    cursor_shape_live = false;
    server.clearWayringDefaultOutputListener(&fractional_scale);
    default_output_listener_live = false;
    fractional_scale.unpublish();
    fractional_scale.deinit();
    fractional_scale_live = false;
    viewporter.unpublish();
    viewporter.deinit();
    viewporter_live = false;
    xdg.unpublish();
    xdg.deinit();
    xdg_live = false;
    wayring_outputs.deinit();
    wayring_outputs_live = false;
    seat.unpublish();
    seat.deinit();
    seat_live = false;
    compositor.deinit();
    compositor_live = false;
    clients.deinit();
    clients_live = false;
    protocol_server.deinit();
    protocol_server_live = false;
    try std.testing.expectEqual(@as(usize, 0), server.headless_surface_forest.len());
    try std.testing.expectEqual(registry_baseline, server.surface_registry.len());
    server.destroy();
    server_live = false;
}

test "Wayring wl_subcompositor v1 nested synchronized state is accepted end to end" {
    const WayringHost = @import("wayland/WayringHost.zig");
    const wayring = @import("wayring");
    const linux = std.os.linux;
    var marker: u8 = 0;
    const runtime_directory = try std.fmt.allocPrintSentinel(
        std.testing.allocator,
        "/tmp/keywork-wayring-subsurface-{d}-{x}",
        .{ linux.getpid(), @intFromPtr(&marker) },
        0,
    );
    defer std.testing.allocator.free(runtime_directory);
    if (linux.errno(linux.mkdir(runtime_directory.ptr, 0o700)) != .SUCCESS)
        return error.TestDirectoryCreationFailed;
    defer _ = linux.rmdir(runtime_directory.ptr);

    const server = try Self.createWithVirtualOutput(
        std.testing.allocator,
        std.testing.io,
        .cpu,
        .headless,
        null,
        .{
            .size = .{ .width = 6, .height = 2 },
            .refresh_millihertz = 1,
        },
    );
    defer server.destroy();
    const second_output_id = try server.addRenderOutput(std.testing.io, .{
        .kind = .headless,
        .size = .{ .width = 6, .height = 2 },
        .name = "HEADLESS-WAYRING-SECOND",
        .description = "Keywork Wayring completion test output",
        .model = "headless",
        .refresh_millihertz = 1,
    });
    defer std.debug.assert(server.removeRenderOutput(second_output_id));
    const output = server.primaryRenderOutput();
    const second_output = server.render_outputs.get(second_output_id).?.*;
    const registry_baseline = server.surface_registry.len();
    try std.testing.expectEqual(@as(usize, 0), registry_baseline);
    var protocol_server: wayring.server.Server = .init(std.testing.allocator);
    defer protocol_server.deinit();
    var compositor: WayringCompositor = undefined;
    try compositor.init(
        std.testing.allocator,
        &protocol_server,
        server.surfaceRegistry(),
        server.wayringPresentationListener(),
    );
    defer compositor.deinit();
    var wayring_outputs: WayringOutput = undefined;
    try wayring_outputs.init(
        std.testing.allocator,
        &protocol_server,
        server.wayringOutputLayout().?,
        &compositor,
    );
    defer wayring_outputs.deinit();
    const Lifecycle = struct {
        outputs: *WayringOutput,
        compositor: *WayringCompositor,

        fn accepted(_: *anyopaque, _: *wayring.server.Client) !void {}

        fn destroy(context: *anyopaque, peer: *wayring.server.Client) void {
            const self: *@This() = @ptrCast(@alignCast(context));
            self.outputs.destroyClientResources(peer);
            self.compositor.destroyClientResources(peer);
        }
    };
    var lifecycle: Lifecycle = .{ .outputs = &wayring_outputs, .compositor = &compositor };
    const host = try WayringHost.create(
        std.testing.allocator,
        server.eventLoop(),
        &protocol_server,
        runtime_directory,
        .{
            .context = &lifecycle,
            .accepted = Lifecycle.accepted,
            .destroy_resources = Lifecycle.destroy,
        },
    );
    defer host.destroy() catch {};
    const raw_command_fd = linux.eventfd(0, linux.EFD.CLOEXEC);
    if (linux.errno(raw_command_fd) != .SUCCESS) return error.EventFdFailed;
    const command_fd: std.posix.fd_t = @intCast(raw_command_fd);
    defer _ = linux.close(command_fd);
    var client: WayringSubsurfaceClient = .{
        .runtime_directory = runtime_directory,
        .display_name = host.displayName(),
        .command_fd = command_fd,
    };
    const thread = try std.Thread.spawn(.{}, WayringSubsurfaceClient.run, .{&client});
    var joined = false;
    defer if (!joined) {
        client.shutdown();
        thread.join();
    };

    try waitForWayringSubsurfaceStage(server, host, &client, .queued);
    try std.testing.expectEqual(@as(u8, 1), client.compositor_globals);
    try std.testing.expectEqual(@as(u32, 6), client.compositor_version);
    try std.testing.expectEqual(@as(u8, 1), client.subcompositor_globals);
    try std.testing.expectEqual(@as(u32, 1), client.subcompositor_version);
    try std.testing.expectEqual(@as(u8, 2), client.output_globals);
    try std.testing.expectEqual(@as(u32, 4), client.output_version);
    try std.testing.expectEqual(@as(u8, 4), client.release_count.load(.acquire));
    try std.testing.expectEqual(@as(u8, 0), client.done_count.load(.acquire));
    try std.testing.expectEqual(@as(usize, 4), compositor.surfaceCount());
    try std.testing.expectEqual(@as(usize, 4), server.headless_surface_forest.len());
    try std.testing.expectEqual(@as(usize, 1), server.headless_surface_forest.rootLen());
    var nodes = server.headless_surface_forest.nodeIterator();
    while (nodes.next()) |node|
        try std.testing.expect(server.surface_registry.renderState(node.id) == null);

    try signalWayringCommand(command_fd);
    try waitForWayringSubsurfaceStage(server, host, &client, .applied);
    try std.testing.expectEqual(@as(u8, 5), client.release_count.load(.acquire));
    try std.testing.expectEqual(@as(u8, 0), client.done_count.load(.acquire));
    const root_id = server.headless_surface_forest.rootAt(0).?.id;
    const parent_id = wayringSurfaceWithPixel(server, 0x0000_ff00).?;
    const child_id = wayringSurfaceWithPixel(server, 0x0000_00ff).?;
    const sibling_id = wayringSurfaceWithPixel(server, 0x00ff_ff00).?;
    try std.testing.expectEqualSlices(
        u32,
        &.{ 0xffff_0000, 0xffff_0000 },
        server.surface_registry.renderState(root_id).?.buffer.pixels,
    );
    try std.testing.expectEqual(@as(usize, 1), server.headless_surface_forest.rootLen());
    try std.testing.expectEqual(HeadlessSurfaceForest.Placement.root, server.headless_surface_forest.state(root_id).?.placement);
    try std.testing.expectEqual(HeadlessSurfaceForest.Placement{ .child = .{
        .parent = root_id,
        .position = .{ .x = 1 },
    } }, server.headless_surface_forest.state(parent_id).?.placement);
    try std.testing.expectEqual(HeadlessSurfaceForest.Placement{ .child = .{
        .parent = parent_id,
        .position = .{ .x = 1 },
    } }, server.headless_surface_forest.state(child_id).?.placement);
    try std.testing.expectEqual(HeadlessSurfaceForest.Placement{ .child = .{
        .parent = root_id,
        .position = .{ .x = 1 },
    } }, server.headless_surface_forest.state(sibling_id).?.placement);
    try std.testing.expectEqual(@as(u64, 1), server.surface_registry.renderState(child_id).?.buffer.source_cache.?.version);
    try std.testing.expectEqual(
        @as(u32, 0xff00_00ff),
        server.surface_registry.renderState(child_id).?.buffer.pixels[0],
    );
    try std.testing.expect(server.headless_surface_forest.state(child_id).?.frame_demand);
    var previous_frames = output.frame_statistics.frames_presented;
    try renderPendingWayringFrame(server, host, previous_frames);
    try std.testing.expect(server.renderer.wasSampled(surfaceSampleTag(child_id)));
    var expected: [12]u32 = @splat(renderColor(server.palette.desktop_background).argb8888());
    expected[0] = 0xffff_0000;
    expected[1] = 0xffff_ff00;
    expected[2] = 0xff00_00ff;
    try expectWayringOutputPixels(server, &expected);
    try std.testing.expectEqual(@as(u8, 0), client.done_count.load(.acquire));

    try signalWayringCommand(command_fd);
    try waitForWayringSubsurfaceStage(server, host, &client, .first_done);
    try std.testing.expectEqual(@as(u8, 1), client.done_count.load(.acquire));
    try std.testing.expect(!server.headless_surface_forest.state(child_id).?.frame_demand);

    try signalWayringCommand(command_fd);
    try waitForWayringSubsurfaceStage(server, host, &client, .child_desync_locked);
    try std.testing.expectEqual(@as(u64, 1), server.surface_registry.renderState(child_id).?.buffer.source_cache.?.version);
    try std.testing.expectEqual(@as(u8, 1), client.done_count.load(.acquire));
    try std.testing.expect(!server.headless_surface_forest.state(child_id).?.frame_demand);

    try signalWayringCommand(command_fd);
    try waitForWayringSubsurfaceStage(server, host, &client, .ancestor_unlocked);
    try std.testing.expectEqual(@as(u64, 2), server.surface_registry.renderState(child_id).?.buffer.source_cache.?.version);
    try std.testing.expectEqual(
        @as(u32, 0xff00_ffff),
        server.surface_registry.renderState(child_id).?.buffer.pixels[0],
    );
    try std.testing.expect(server.headless_surface_forest.state(child_id).?.frame_demand);
    previous_frames = output.frame_statistics.frames_presented;
    try renderPendingWayringFrame(server, host, previous_frames);
    try std.testing.expect(server.renderer.wasSampled(surfaceSampleTag(child_id)));
    expected[2] = 0xff00_ffff;
    try expectWayringOutputPixels(server, &expected);

    try signalWayringCommand(command_fd);
    try waitForWayringSubsurfaceStage(server, host, &client, .second_done);
    try std.testing.expectEqual(@as(u8, 2), client.done_count.load(.acquire));

    try signalWayringCommand(command_fd);
    try waitForWayringSubsurfaceStage(server, host, &client, .occluded);
    try std.testing.expectEqual(HeadlessSurfaceForest.Placement{ .child = .{
        .parent = parent_id,
        .position = .{},
    } }, server.headless_surface_forest.state(child_id).?.placement);
    previous_frames = output.frame_statistics.frames_presented;
    try renderPendingWayringFrame(server, host, previous_frames);
    try std.testing.expect(!server.renderer.wasSampled(surfaceSampleTag(child_id)));
    try std.testing.expect(server.renderer.wasSampled(surfaceSampleTag(sibling_id)));
    try std.testing.expect(server.headless_surface_forest.state(child_id).?.frame_demand);
    expected[1] = 0xffff_ff00;
    expected[2] = renderColor(server.palette.desktop_background).argb8888();
    try expectWayringOutputPixels(server, &expected);
    try signalWayringCommand(command_fd);
    try waitForWayringSubsurfaceStage(server, host, &client, .occluded_no_done);
    try std.testing.expectEqual(@as(u8, 2), client.done_count.load(.acquire));

    try signalWayringCommand(command_fd);
    try waitForWayringSubsurfaceStage(server, host, &client, .restacked);
    previous_frames = output.frame_statistics.frames_presented;
    try renderPendingWayringFrame(server, host, previous_frames);
    try std.testing.expect(server.renderer.wasSampled(surfaceSampleTag(child_id)));
    try std.testing.expect(!server.renderer.wasSampled(surfaceSampleTag(sibling_id)));
    expected[1] = 0xff00_ffff;
    try expectWayringOutputPixels(server, &expected);
    try signalWayringCommand(command_fd);
    try waitForWayringSubsurfaceStage(server, host, &client, .restacked_done);
    try std.testing.expectEqual(@as(u8, 3), client.done_count.load(.acquire));

    try signalWayringCommand(command_fd);
    try waitForWayringSubsurfaceStage(server, host, &client, .hidden);
    try std.testing.expect(server.surface_registry.renderState(parent_id) == null);
    try std.testing.expect(server.headless_surface_forest.state(child_id).?.frame_demand);
    previous_frames = output.frame_statistics.frames_presented;
    try renderPendingWayringFrame(server, host, previous_frames);
    try std.testing.expect(!server.renderer.wasSampled(surfaceSampleTag(child_id)));
    expected[1] = 0xffff_0000;
    try expectWayringOutputPixels(server, &expected);
    try signalWayringCommand(command_fd);
    try waitForWayringSubsurfaceStage(server, host, &client, .hidden_no_done);
    try std.testing.expectEqual(@as(u8, 3), client.done_count.load(.acquire));

    try signalWayringCommand(command_fd);
    try waitForWayringSubsurfaceStage(server, host, &client, .remapped);
    try std.testing.expectEqual(@as(u8, 6), client.release_count.load(.acquire));
    try std.testing.expect(server.surface_registry.renderState(parent_id) != null);
    previous_frames = output.frame_statistics.frames_presented;
    try renderPendingWayringFrame(server, host, previous_frames);
    try std.testing.expect(server.renderer.wasSampled(surfaceSampleTag(child_id)));
    expected[1] = 0xff00_ffff;
    try expectWayringOutputPixels(server, &expected);
    try signalWayringCommand(command_fd);
    try waitForWayringSubsurfaceStage(server, host, &client, .remapped_done);
    try std.testing.expectEqual(@as(u8, 4), client.done_count.load(.acquire));

    try signalWayringCommand(command_fd);
    try waitForWayringSubsurfaceStage(server, host, &client, .off_output);
    try std.testing.expectEqual(HeadlessSurfaceForest.Placement{ .child = .{
        .parent = parent_id,
        .position = .{ .x = 20 },
    } }, server.headless_surface_forest.state(child_id).?.placement);
    previous_frames = output.frame_statistics.frames_presented;
    try renderPendingWayringFrame(server, host, previous_frames);
    try std.testing.expect(!server.renderer.wasSampled(surfaceSampleTag(child_id)));
    expected[1] = 0xff00_ff00;
    try expectWayringOutputPixels(server, &expected);
    try signalWayringCommand(command_fd);
    try waitForWayringSubsurfaceStage(server, host, &client, .off_output_no_done);
    try std.testing.expectEqual(@as(u8, 4), client.done_count.load(.acquire));

    try signalWayringCommand(command_fd);
    try waitForWayringSubsurfaceStage(server, host, &client, .on_output);
    try std.testing.expectEqual(HeadlessSurfaceForest.Placement{ .child = .{
        .parent = parent_id,
        .position = .{ .x = -1 },
    } }, server.headless_surface_forest.state(child_id).?.placement);
    previous_frames = output.frame_statistics.frames_presented;
    try renderPendingWayringFrame(server, host, previous_frames);
    try std.testing.expect(server.renderer.wasSampled(surfaceSampleTag(child_id)));
    expected[0] = 0xff00_ffff;
    expected[1] = 0xff00_ff00;
    try expectWayringOutputPixels(server, &expected);
    try signalWayringCommand(command_fd);
    try waitForWayringSubsurfaceStage(server, host, &client, .on_output_done);
    try std.testing.expectEqual(@as(u8, 5), client.done_count.load(.acquire));

    try signalWayringCommand(command_fd);
    try waitForWayringSubsurfaceStage(server, host, &client, .frame_pending);
    try std.testing.expect(server.headless_surface_forest.state(child_id).?.frame_demand);
    try rejectWayringFrames(server, output, child_id);
    try signalWayringCommand(command_fd);
    try waitForWayringSubsurfaceStage(server, host, &client, .frame_not_done);
    try std.testing.expectEqual(@as(u8, 5), client.done_count.load(.acquire));
    try std.testing.expect(server.headless_surface_forest.state(child_id).?.frame_demand);
    previous_frames = output.frame_statistics.frames_presented;
    try renderPendingWayringFrame(server, host, previous_frames);
    try signalWayringCommand(command_fd);
    try waitForWayringSubsurfaceStage(server, host, &client, .frame_done);
    try std.testing.expectEqual(@as(u8, 6), client.done_count.load(.acquire));

    try signalWayringCommand(command_fd);
    try waitForWayringSubsurfaceStage(server, host, &client, .multi_pending);
    try std.testing.expect(server.headless_surface_forest.state(child_id).?.frame_demand);
    const previous_second_frames = second_output.frame_statistics.frames_presented;
    try renderPendingWayringOutput(server, host, second_output, previous_second_frames);
    try std.testing.expect(!server.headless_surface_forest.state(child_id).?.frame_demand);
    try signalWayringCommand(command_fd);
    try waitForWayringSubsurfaceStage(server, host, &client, .multi_first_done);
    try std.testing.expectEqual(@as(u8, 7), client.done_count.load(.acquire));
    const first_output_timestamp = client.last_done_timestamp_ms.load(.acquire);
    previous_frames = output.frame_statistics.frames_presented;
    try renderPendingWayringFrame(server, host, previous_frames);
    try signalWayringCommand(command_fd);
    try waitForWayringSubsurfaceStage(server, host, &client, .multi_second_unchanged);
    try std.testing.expectEqual(@as(u8, 7), client.done_count.load(.acquire));
    try std.testing.expectEqual(first_output_timestamp, client.last_done_timestamp_ms.load(.acquire));

    try signalWayringCommand(command_fd);
    try waitForWayringSubsurfaceStage(server, host, &client, .queued_detached);
    try std.testing.expectEqual(HeadlessSurfaceForest.Placement.detached, server.headless_surface_forest.state(child_id).?.placement);
    try std.testing.expect(!server.headless_surface_forest.state(child_id).?.frame_demand);
    previous_frames = output.frame_statistics.frames_presented;
    try renderPendingWayringFrame(server, host, previous_frames);
    try std.testing.expect(!server.renderer.wasSampled(surfaceSampleTag(child_id)));
    try signalWayringCommand(command_fd);
    try waitForWayringSubsurfaceStage(server, host, &client, .detached_no_done);
    try std.testing.expectEqual(@as(u8, 7), client.done_count.load(.acquire));

    try signalWayringCommand(command_fd);
    try waitForWayringSubsurfaceStage(server, host, &client, .recreated);
    try std.testing.expectEqual(HeadlessSurfaceForest.Placement{ .child = .{
        .parent = sibling_id,
        .position = .{ .x = -1 },
    } }, server.headless_surface_forest.state(child_id).?.placement);
    try std.testing.expect(!std.meta.eql(
        server.headless_surface_forest.state(child_id).?.placement,
        HeadlessSurfaceForest.Placement{ .child = .{ .parent = parent_id, .position = .{ .x = -1 } } },
    ));
    try std.testing.expectEqual(@as(?SurfaceRegistry.Id, null), server.scene.focusedSurface());
    try std.testing.expect(!server.scene.surfaceTracked(child_id));
    try std.testing.expectEqual(@as(?Seat.PointerFocus, null), server.pointerFocus(0, 0));
    // Topology changes alone cannot create membership on the primary output.
    // The second output retains its last completed-frame truth until its next
    // completed frame, independent of the newly recreated placement.
    try std.testing.expect(!server.outputs.get(output.protocol_id).?.containsSurface(child_id));
    try std.testing.expect(server.outputs.get(second_output.protocol_id).?.containsSurface(child_id));

    try signalWayringCommand(command_fd);
    try waitForWayringSubsurfaceStage(server, host, &client, .parent_destroyed);
    try std.testing.expect(!server.surface_registry.contains(sibling_id));
    try std.testing.expect(server.surface_registry.contains(child_id));
    try std.testing.expectEqual(HeadlessSurfaceForest.Placement.detached, server.headless_surface_forest.state(child_id).?.placement);
    try std.testing.expectEqual(@as(usize, 3), compositor.surfaceCount());

    try signalWayringCommand(command_fd);
    try waitForWayringSubsurfaceStage(server, host, &client, .disconnected);
    thread.join();
    joined = true;
    try waitForWayringDisconnect(server, host, &compositor);
    try std.testing.expectEqual(registry_baseline, server.surface_registry.len());
    try std.testing.expectEqual(@as(usize, 0), server.headless_surface_forest.len());
    try std.testing.expectEqual(@as(usize, 0), compositor.surfaceCount());
    try std.testing.expect(wayringPresentationEnabled(.headless));
    try std.testing.expect(!wayringPresentationEnabled(.drm));
    try std.testing.expect(!wayringPresentationEnabled(.nested));
}

test "server creates and destroys protocol globals" {
    const server = try Self.create(std.testing.allocator, std.testing.io, .cpu, .headless, null);
    defer server.destroy();
    try std.testing.expect(!server.native_input_initialized);
    try std.testing.expect(server.input_manager_initialized);
    try std.testing.expect(server.builtin_keybindings_initialized);
    try std.testing.expect(server.window_manager_initialized);
}

test "general configuration maps window shadows" {
    const defaults: Config.GeneralSettings = .{};
    const dark = configuredWindowEffects(defaults, theme.dark);
    try std.testing.expectEqual(Scene.Position{ .y = 4 }, dark.tiled.key_shadow.?.offset);
    try std.testing.expectEqual(@as(u32, 8), dark.tiled.key_shadow.?.blur_radius);
    try std.testing.expectEqual(Scene.Position{ .y = 8 }, dark.tiled_focused.key_shadow.?.offset);
    try std.testing.expectEqual(@as(u32, 16), dark.tiled_focused.key_shadow.?.blur_radius);
    try std.testing.expectEqual(Scene.Position{ .y = 14 }, dark.floating.key_shadow.?.offset);
    try std.testing.expectEqual(@as(u32, 28), dark.floating.key_shadow.?.blur_radius);
    try std.testing.expectEqual(Scene.Position{ .y = 32 }, dark.floating_focused.key_shadow.?.offset);
    try std.testing.expectEqual(@as(u32, 64), dark.floating_focused.key_shadow.?.blur_radius);
    try std.testing.expectEqual(renderColor(theme.dark.shadow_ambient), dark.tiled.ambient_shadow.?.color);
    try std.testing.expectEqual(renderColor(theme.dark.shadow_key), dark.tiled.key_shadow.?.color);

    const light = configuredWindowEffects(defaults, theme.light);
    try std.testing.expectEqual(renderColor(theme.light.shadow_ambient), light.tiled.ambient_shadow.?.color);
    try std.testing.expectEqual(renderColor(theme.light.shadow_key), light.tiled.key_shadow.?.color);

    var configured = defaults;
    configured.shadow_blur_radius = 20;
    configured.shadow_color = .{
        .red = 0x10,
        .green = 0x20,
        .blue = 0x30,
        .alpha = 0x70,
    };
    configured.focused_shadow_color = .{
        .red = 0x7a,
        .green = 0xa2,
        .blue = 0xf7,
        .alpha = 0x80,
    };
    const overridden = configuredWindowEffects(configured, theme.light);
    try std.testing.expectEqual(
        render.Color.rgba(0x7a, 0xa2, 0xf7, 0x80),
        overridden.tiled_focused.key_shadow.?.color,
    );
    try std.testing.expectEqual(
        render.Color.rgba(0x7a, 0xa2, 0xf7, 0x6e),
        overridden.tiled_focused.ambient_shadow.?.color,
    );
    try std.testing.expectEqual(@as(u32, 20), overridden.tiled.key_shadow.?.blur_radius);
    try std.testing.expectEqual(render.Color.rgba(0x10, 0x20, 0x30, 0x70), overridden.floating.key_shadow.?.color);

    var disabled = defaults;
    disabled.shadow_enabled = false;
    const effects = configuredWindowEffects(disabled, theme.dark);
    try std.testing.expect(effects.tiled.ambient_shadow == null);
    try std.testing.expect(effects.tiled.key_shadow == null);
    try std.testing.expectEqual(@as(u32, 12), effects.tiled.corner_radius);
}

test "general configuration maps window borders" {
    const defaults: Config.GeneralSettings = .{};
    const default_unfocused = windowBorder(
        defaults.unfocused_border_width,
        defaults.unfocused_border_color orelse theme.default_palette.unfocused_border,
    ).?;
    try std.testing.expectEqual(@as(u32, 1), default_unfocused.width);
    try std.testing.expectEqual(
        renderColor(theme.default_palette.unfocused_border),
        default_unfocused.color,
    );
    const default_focused = windowBorder(
        defaults.focused_border_width,
        defaults.focused_border_color orelse theme.default_palette.focused_border,
    ).?;
    try std.testing.expectEqual(@as(u32, 2), default_focused.width);
    try std.testing.expectEqual(
        renderColor(theme.default_palette.focused_border),
        default_focused.color,
    );

    try std.testing.expect(windowBorder(
        0,
        defaults.focused_border_color orelse theme.default_palette.focused_border,
    ) == null);

    const configured_color: Config.Color = .{
        .red = 0x7a,
        .green = 0xa2,
        .blue = 0xf7,
        .alpha = 0x80,
    };
    const border = windowBorder(3, configured_color).?;
    try std.testing.expectEqual(@as(u32, 3), border.width);
    try std.testing.expectEqual(
        render.Color.rgba(0x7a, 0xa2, 0xf7, 0x80),
        border.color,
    );
    try std.testing.expect(border.edges.top);
    try std.testing.expect(border.edges.bottom);
    try std.testing.expect(border.edges.left);
    try std.testing.expect(border.edges.right);
}

test "server adds and removes independent render outputs" {
    const server = try Self.create(std.testing.allocator, std.testing.io, .cpu, .headless, null);
    defer server.destroy();

    const second_id = try server.addRenderOutput(std.testing.io, .{
        .kind = .headless,
        .size = .{ .width = 640, .height = 480 },
        .position = .{ .x = 1280 },
        .name = "HEADLESS-2",
        .description = "Keywork test output",
        .model = "headless",
    });
    defer std.debug.assert(server.removeRenderOutput(second_id));

    try std.testing.expectEqual(@as(usize, 2), server.render_outputs.len());
    const second = server.render_outputs.get(second_id).?.*;
    try std.testing.expectEqual(
        Output.Position{ .x = 1280 },
        server.outputs.get(second.protocol_id).?.logicalPosition(),
    );
}

test "pointer motion crosses adjacent outputs and avoids layout gaps" {
    const server = try Self.create(std.testing.allocator, std.testing.io, .cpu, .headless, null);
    defer server.destroy();

    const second_id = try server.addRenderOutput(std.testing.io, .{
        .kind = .headless,
        .size = .{ .width = 640, .height = 480 },
        .position = .{ .x = 1280, .y = 240 },
        .name = "HEADLESS-2",
        .description = "Keywork test output",
        .model = "headless",
    });
    defer std.debug.assert(server.removeRenderOutput(second_id));

    try std.testing.expectEqual(
        RenderOutput.Point{ .x = 1280.25, .y = 300 },
        server.constrainPointerToOutputs(.{ .x = 1280.25, .y = 300 }).?,
    );
    try std.testing.expectEqual(
        RenderOutput.Point{ .x = 1279, .y = 100 },
        server.constrainPointerToOutputs(.{ .x = 1280.25, .y = 100 }).?,
    );
}

test "virtual pointer coordinates respect mapped bounds" {
    try std.testing.expectEqual(
        @as(f64, -100),
        clampVirtualPointerCoordinate(-200, -100, 640),
    );
    try std.testing.expectEqual(
        @as(f64, 539),
        clampVirtualPointerCoordinate(700, -100, 640),
    );
    try std.testing.expectEqual(
        @as(f64, -100),
        normalizedVirtualPointerCoordinate(0, 1000, -100, 640),
    );
    try std.testing.expectEqual(
        @as(f64, 219.5),
        normalizedVirtualPointerCoordinate(500, 1000, -100, 640),
    );
    try std.testing.expectEqual(
        @as(f64, 539),
        normalizedVirtualPointerCoordinate(1200, 1000, -100, 640),
    );
}

test "fullscreen selection is isolated to each output" {
    const server = try Self.create(std.testing.allocator, std.testing.io, .cpu, .headless, null);
    defer server.destroy();

    const first = try server.scene.addWindow(.{ .index = 100, .generation = 1 });
    defer server.scene.removeWindow(first);
    server.scene.setMapped(first, true);
    server.scene.setFullscreen(first, true);
    server.scene.setClipBox(first, .{ .x = 0, .y = 0, .width = 1280, .height = 720 });

    const second = try server.scene.addWindow(.{ .index = 101, .generation = 1 });
    defer server.scene.removeWindow(second);
    server.scene.setPosition(second, .{ .x = 1280 });
    server.scene.setMapped(second, true);
    server.scene.setFullscreen(second, true);
    server.scene.setClipBox(second, .{ .x = 0, .y = 0, .width = 640, .height = 480 });

    try std.testing.expectEqual(first, server.topFullscreenForOutput(.{
        .x = 0,
        .y = 0,
        .width = 1280,
        .height = 720,
    }).?.id);
    try std.testing.expectEqual(second, server.topFullscreenForOutput(.{
        .x = 1280,
        .y = 0,
        .width = 640,
        .height = 480,
    }).?.id);
}

test "production Wayring XDG publication accepts a real registry client and survives rebind" {
    const WayringHost = @import("wayland/WayringHost.zig");
    const wayring = @import("wayring");
    const linux = std.os.linux;
    var marker: u8 = 0;
    const runtime_directory = try std.fmt.allocPrintSentinel(std.testing.allocator, "/tmp/keywork-wayring-xdg-{d}-{x}", .{ linux.getpid(), @intFromPtr(&marker) }, 0);
    defer std.testing.allocator.free(runtime_directory);
    if (linux.errno(linux.mkdir(runtime_directory.ptr, 0o700)) != .SUCCESS) return error.TestDirectoryCreationFailed;
    defer _ = linux.rmdir(runtime_directory.ptr);

    const server = try Self.createWithVirtualOutput(std.testing.allocator, std.testing.io, .cpu, .headless, null, .{
        .size = .{ .width = 640, .height = 480 },
        .refresh_millihertz = 1,
    });
    defer server.destroy();
    const output = server.primaryRenderOutput();
    const registry_baseline = server.surface_registry.len();

    const keymap_fd = try std.posix.memfd_create("keywork-wayring-xdg-keymap", linux.MFD.CLOEXEC);
    const keymap = "keymap\x00\x00";
    if (linux.errno(linux.ftruncate(keymap_fd, keymap.len)) != .SUCCESS)
        return error.KeymapResizeFailed;
    if (std.c.pwrite(keymap_fd, keymap.ptr, keymap.len, 0) != keymap.len)
        return error.KeymapWriteFailed;
    server.seat.setKeymap(.xkb_v1, keymap_fd, keymap.len);
    server.seat.setRepeatInfo(0, 500);
    server.seat.setKeyboardAvailable(true);
    server.seat.setPointerAvailable(true);
    var protocol_server: wayring.server.Server = .init(std.testing.allocator);
    defer protocol_server.deinit();
    var clients: WayringClients = undefined;
    clients.init(std.testing.allocator, server.clientRegistry());
    defer clients.deinit();
    var compositor: WayringCompositor = undefined;
    try compositor.init(std.testing.allocator, &protocol_server, server.surfaceRegistry(), server.wayringPresentationListener());
    defer compositor.deinit();
    var seat: WayringSeatAdapter = .init(std.testing.allocator, &protocol_server, &clients, &compositor, server.generatedSeatRequestSink(), server.generatedSeatName());
    defer seat.deinit();
    server.setGeneratedSeatDeliverySink(seat.sink());
    defer server.clearGeneratedSeatDeliverySink(&seat);
    try seat.publish();
    defer seat.unpublish();
    var outputs: WayringOutput = undefined;
    try outputs.init(std.testing.allocator, &protocol_server, server.wayringOutputLayout().?, &compositor);
    defer outputs.deinit();
    var xdg: WayringXdgShell = undefined;
    xdg.init(std.testing.allocator, &protocol_server, server.neutralXdgShell(), &clients, &compositor, &outputs);
    defer xdg.deinit();
    xdg.setSeatAdapter(&seat);
    try xdg.publish();
    defer xdg.unpublish();
    var viewporter: WayringViewporter = undefined;
    viewporter.init(std.testing.allocator, &protocol_server, &compositor);
    defer viewporter.deinit();
    try viewporter.publish();
    defer viewporter.unpublish();
    var fractional_scale: WayringFractionalScale = undefined;
    try fractional_scale.init(
        std.testing.allocator,
        &protocol_server,
        &compositor,
        &outputs,
        server.wayringOutputLayout().?,
        server.wayringDefaultOutputId().?,
    );
    defer fractional_scale.deinit();
    try fractional_scale.publish();
    defer fractional_scale.unpublish();
    var cursor_shape: WayringCursorShape = undefined;
    cursor_shape.init(std.testing.allocator, &protocol_server, &seat, server.generatedCursorShape(), server.generatedSeatRequestSink());
    defer cursor_shape.deinit();
    try cursor_shape.publish();
    defer cursor_shape.unpublish();
    var decoration: WayringXdgDecoration = undefined;
    decoration.init(std.testing.allocator, &protocol_server, &xdg, server.neutralXdgShell());
    defer decoration.deinit();
    try decoration.publish();
    defer decoration.unpublish();
    var activation: WayringXdgActivation = undefined;
    activation.init(std.testing.allocator, &protocol_server, &seat, &xdg, server.xdgActivationOwner());
    defer activation.deinit();
    try activation.publish();
    defer activation.unpublish();
    var data_device: WayringDataDevice = undefined;
    data_device.init(std.testing.allocator, &protocol_server, &clients, &seat, server.neutralDataDevice(), &compositor);
    defer data_device.deinit();
    server.setDataDeviceObserver(.{
        .context = &data_device,
        .transaction_finalize = WayringDataDevice.transactionFinalize,
        .transaction_commit = WayringDataDevice.transactionCommit,
        .transaction_abort = WayringDataDevice.transactionAbort,
        .offer_rolled_back = WayringDataDevice.offerRolledBack,
        .offer_mime_offered = WayringDataDevice.offerMimeOffered,
        .offer_source_actions_preflight = WayringDataDevice.offerSourceActionsPreflight,
        .offer_source_actions_changed = WayringDataDevice.offerSourceActionsChanged,
        .offer_action_preflight = WayringDataDevice.offerActionPreflight,
        .offer_action_changed = WayringDataDevice.offerActionChanged,
    });
    defer server.setDataDeviceObserver(null);
    try data_device.publish();
    defer data_device.unpublish();
    var primary_selection: WayringPrimarySelection = undefined;
    primary_selection.init(std.testing.allocator, &protocol_server, &clients, &seat, server.neutralDataDevice());
    defer primary_selection.deinit();
    server.setPrimarySelectionObserver(.{
        .context = &primary_selection,
        .transaction_finalize = WayringPrimarySelection.transactionFinalize,
        .transaction_commit = WayringPrimarySelection.transactionCommit,
        .transaction_abort = WayringPrimarySelection.transactionAbort,
        .selection_changed = WayringPrimarySelection.selectionChanged,
        .mime_offered = WayringPrimarySelection.mimeOffered,
        .offer_rolled_back = WayringPrimarySelection.offerRolledBack,
        .offer_mime_offered = WayringPrimarySelection.offerMimeOffered,
    });
    defer server.setPrimarySelectionObserver(null);
    try primary_selection.publish();
    defer primary_selection.unpublish();

    const Lifecycle = struct {
        clients: *WayringClients,
        compositor: *WayringCompositor,
        outputs: *WayringOutput,
        seat: *WayringSeatAdapter,
        xdg: *WayringXdgShell,
        viewporter: *WayringViewporter,
        fractional_scale: *WayringFractionalScale,
        cursor_shape: *WayringCursorShape,
        decoration: *WayringXdgDecoration,
        activation: *WayringXdgActivation,
        data_device: *WayringDataDevice,
        primary_selection: *WayringPrimarySelection,
        accepted_count: usize = 0,

        fn accepted(context: *anyopaque, client: *wayring.server.Client) !void {
            const self: *@This() = @ptrCast(@alignCast(context));
            _ = try self.clients.register(client);
            errdefer self.clients.unregister(client);
            try self.seat.trackClient(client);
            self.accepted_count += 1;
        }
        fn destroy(context: *anyopaque, client: *wayring.server.Client) void {
            const self: *@This() = @ptrCast(@alignCast(context));
            self.data_device.destroyClientResources(client);
            self.primary_selection.destroyClientResources(client);
            self.activation.destroyClientResources(client);
            self.decoration.destroyClientResources(client);
            self.cursor_shape.destroyClientResources(client);
            self.fractional_scale.destroyClientResources(client);
            self.viewporter.destroyClientResources(client);
            self.xdg.destroyClientResources(client);
            self.seat.destroyClientResources(client);
            self.outputs.destroyClientResources(client);
            self.compositor.destroyClientResources(client);
            if (self.clients.id(client) != null) self.clients.unregister(client);
        }
    };
    var lifecycle: Lifecycle = .{ .clients = &clients, .compositor = &compositor, .outputs = &outputs, .seat = &seat, .xdg = &xdg, .viewporter = &viewporter, .fractional_scale = &fractional_scale, .cursor_shape = &cursor_shape, .decoration = &decoration, .activation = &activation, .data_device = &data_device, .primary_selection = &primary_selection };
    const host = try WayringHost.create(std.testing.allocator, server.eventLoop(), &protocol_server, runtime_directory, .{
        .context = &lifecycle,
        .accepted = Lifecycle.accepted,
        .destroy_resources = Lifecycle.destroy,
    });
    var host_live = true;
    defer if (host_live) host.destroy() catch {};

    const raw_command_fd = linux.eventfd(0, linux.EFD.CLOEXEC);
    if (linux.errno(raw_command_fd) != .SUCCESS) return error.EventFdFailed;
    const command_fd: std.posix.fd_t = @intCast(raw_command_fd);
    defer _ = linux.close(command_fd);
    var client: WayringXdgClient = .{ .runtime_directory = runtime_directory, .display_name = host.displayName(), .command_fd = command_fd };
    const thread = try std.Thread.spawn(.{}, WayringXdgClient.run, .{&client});
    var joined = false;
    defer if (!joined) {
        client.shutdown();
        thread.join();
    };
    try waitForWayringXdgStage(server, host, &client, .configured);
    try std.testing.expectEqual(@as(usize, 1), lifecycle.accepted_count);
    try std.testing.expectEqual(@as(usize, 1), server.client_registry.len());
    try std.testing.expectEqual(@as(usize, 1), compositor.surfaceCount());
    try std.testing.expectEqual(@as(usize, 1), server.headless_surface_forest.len());
    var neutral_windows = server.neutralXdgShell().windowIterator();
    const neutral_window = neutral_windows.next().?;
    try std.testing.expectEqual(NeutralXdgShell.DecorationPreference.prefers_ssd, server.neutralXdgShell().windowInfo(neutral_window).?.decoration_preference);
    try std.testing.expectEqual(NeutralXdgShell.DecorationMode.server_side, server.neutralXdgShell().windowInfo(neutral_window).?.configuration.decoration_mode);
    try std.testing.expect(server.surface_registry.renderState(server.headless_surface_forest.rootAt(0).?.id) == null);

    inline for (.{ WayringXdgClient.Offense.duplicate_decoration, WayringXdgClient.Offense.invalid_mode }) |offense| {
        var offender: WayringXdgClient = .{
            .runtime_directory = runtime_directory,
            .display_name = host.displayName(),
            .command_fd = command_fd,
            .offense = offense,
        };
        const offender_thread = try std.Thread.spawn(.{}, WayringXdgClient.run, .{&offender});
        var offender_joined = false;
        defer if (!offender_joined) {
            offender.shutdown();
            offender_thread.join();
        };
        try waitForWayringXdgStage(server, host, &offender, .disconnected);
        offender_thread.join();
        offender_joined = true;
        for (0..1_000) |_| {
            if (host.connectionCount() == 1 and compositor.surfaceCount() == 1 and
                server.client_registry.len() == 1) break;
            try server.eventLoop().dispatch(1);
            if (host.failure()) |err| return err;
        } else return error.WayringOffenderCleanupTimedOut;
        try std.testing.expectEqual(WayringXdgClient.Stage.configured, @as(WayringXdgClient.Stage, @enumFromInt(client.stage.load(.acquire))));
        try std.testing.expectEqual(NeutralXdgShell.DecorationPreference.prefers_ssd, server.neutralXdgShell().windowInfo(neutral_window).?.decoration_preference);
    }

    try signalWayringCommand(command_fd);
    try waitForWayringXdgStage(server, host, &client, .mapped);
    const surface_id = server.headless_surface_forest.rootAt(0).?.id;
    try std.testing.expect(server.scene.topWindowSurface() != null);
    try std.testing.expect(server.surface_registry.renderState(surface_id) != null);
    const previous_frames = server.primaryRenderOutput().frame_statistics.frames_presented;
    try renderPendingWayringFrame(server, host, previous_frames);
    try std.testing.expect(server.renderer.wasSampled(surfaceSampleTag(surface_id)));
    const capture_bounds = server.toplevelCaptureBounds(neutral_window).?;
    try std.testing.expectEqual(render.Rect{ .x = 0, .y = 0, .width = 1, .height = 1 }, capture_bounds);
    var captured_pixel: [1]u32 = undefined;
    const capture_fd = try server.captureToplevel(neutral_window, .{
        .size = .{ .width = 1, .height = 1 },
        .stride_pixels = 1,
        .pixels = &captured_pixel,
    });
    if (capture_fd) |value| _ = std.c.close(value);
    try std.testing.expectEqual(@as(u32, 0xff7a_a2f7), captured_pixel[0]);
    try signalWayringCommand(command_fd);
    try waitForWayringXdgStage(server, host, &client, .mode_changed);
    try std.testing.expect(client.later_configure_serial != 0);
    try std.testing.expect(client.later_configure_serial != client.initial_configure_serial);
    try std.testing.expectEqual(NeutralXdgShell.DecorationPreference.no_preference, server.neutralXdgShell().windowInfo(neutral_window).?.decoration_preference);
    try std.testing.expectEqual(NeutralXdgShell.DecorationMode.server_side, server.neutralXdgShell().windowInfo(neutral_window).?.configuration.decoration_mode);
    try std.testing.expectEqual(capture_bounds, server.toplevelCaptureBounds(neutral_window).?);
    captured_pixel[0] = 0;
    const later_capture_fd = try server.captureToplevel(neutral_window, .{
        .size = .{ .width = 1, .height = 1 },
        .stride_pixels = 1,
        .pixels = &captured_pixel,
    });
    if (later_capture_fd) |value| _ = std.c.close(value);
    try std.testing.expectEqual(@as(u32, 0xff7a_a2f7), captured_pixel[0]);
    try signalWayringCommand(command_fd);
    try waitForWayringXdgStage(server, host, &client, .frame_done);
    try signalWayringCommand(command_fd);
    try waitForWayringXdgStage(server, host, &client, .disconnected);
    thread.join();
    joined = true;
    try waitForWayringDisconnect(server, host, &compositor);
    try std.testing.expectEqual(registry_baseline, server.surface_registry.len());
    try std.testing.expect(server.scene.topWindowSurface() == null);
    try std.testing.expectEqual(@as(usize, 0), server.client_registry.len());

    var exchange: WayringXdgClient.ActivationExchange = .{};
    const raw_source_fd = linux.eventfd(0, linux.EFD.CLOEXEC);
    if (linux.errno(raw_source_fd) != .SUCCESS) return error.EventFdFailed;
    const source_fd: std.posix.fd_t = @intCast(raw_source_fd);
    defer _ = linux.close(source_fd);
    var source: WayringXdgClient = .{
        .runtime_directory = runtime_directory,
        .display_name = host.displayName(),
        .command_fd = source_fd,
        .activation_role = .source,
        .activation_exchange = &exchange,
    };
    const source_thread = try std.Thread.spawn(.{}, WayringXdgClient.run, .{&source});
    var source_joined = false;
    defer if (!source_joined) {
        source.shutdown();
        source_thread.join();
    };
    try waitForWayringXdgStage(server, host, &source, .configured);
    try signalWayringCommand(source_fd);
    try waitForWayringXdgStage(server, host, &source, .mapped);
    try signalWayringCommand(source_fd);
    try waitForWayringXdgStage(server, host, &source, .map_settled);
    // The client remains intentionally paused. Settle its first-map barrier
    // before asking WindowManager to begin the target's relayout transaction.
    server.window_manager.settleConfigureTransactionForTest();

    const raw_target_fd = linux.eventfd(0, linux.EFD.CLOEXEC);
    if (linux.errno(raw_target_fd) != .SUCCESS) return error.EventFdFailed;
    const target_fd: std.posix.fd_t = @intCast(raw_target_fd);
    defer _ = linux.close(target_fd);
    var target: WayringXdgClient = .{
        .runtime_directory = runtime_directory,
        .display_name = host.displayName(),
        .command_fd = target_fd,
        .activation_role = .target,
        .activation_exchange = &exchange,
    };
    const target_thread = try std.Thread.spawn(.{}, WayringXdgClient.run, .{&target});
    var target_joined = false;
    defer if (!target_joined) {
        target.shutdown();
        target_thread.join();
    };
    try waitForWayringXdgStage(server, host, &target, .initial_commit_ready);
    try signalWayringCommand(target_fd);
    for (0..1_000) |_| {
        if (server.headless_surface_forest.len() == 2) break;
        try server.eventLoop().dispatch(1);
        if (host.failure()) |err| return err;
    } else return error.WayringXdgClientTimedOut;
    // The target's first commit coalesces behind the paused source's current
    // configure. Publishing that barrier emits the target's initial batch.
    server.window_manager.settleConfigureTransactionForTest();
    try waitForWayringXdgStage(server, host, &target, .configured);
    try signalWayringCommand(target_fd);
    try waitForWayringXdgStage(server, host, &target, .mapped);
    server.window_manager.settleConfigureTransactionForTest();
    try std.testing.expectEqual(@as(usize, 2), host.connectionCount());
    try std.testing.expectEqual(@as(usize, 2), compositor.surfaceCount());
    try std.testing.expectEqual(@as(usize, 2), server.client_registry.len());
    try std.testing.expectEqual(@as(usize, 2), server.headless_surface_forest.len());

    const snapshots = try server.window_manager.windowSnapshots(std.testing.allocator);
    defer std.testing.allocator.free(snapshots);
    try std.testing.expectEqual(@as(usize, 2), snapshots.len);
    var source_root: ?SurfaceRegistry.Id = null;
    var target_root: ?SurfaceRegistry.Id = null;
    var source_rect: ?WindowManager.WindowRect = null;
    var neutral_iterator = server.neutralXdgShell().windowIterator();
    while (neutral_iterator.next()) |window_id| {
        const info = server.neutralXdgShell().windowInfo(window_id).?;
        const app_id = info.app_id orelse continue;
        if (std.mem.eql(u8, app_id, "org.keywork.activation-source"))
            source_root = server.scene.windowSurface(info.scene_id)
        else if (std.mem.eql(u8, app_id, "org.keywork.activation-target"))
            target_root = server.scene.windowSurface(info.scene_id);
    }
    for (snapshots) |snapshot| {
        const app_id = snapshot.app_id orelse continue;
        if (std.mem.eql(u8, app_id, "org.keywork.activation-source"))
            source_rect = snapshot.rect;
    }
    const exact_source = source_root orelse return error.ActivationSourceMissing;
    const exact_target = target_root orelse return error.ActivationTargetMissing;
    const rect = source_rect orelse return error.ActivationSourceGeometryMissing;
    try std.testing.expect(rect.width > 0 and rect.height > 0);
    const source_position = server.scene.surfacePosition(exact_source) orelse
        return error.ActivationSourceGeometryMissing;
    pointerMotion(
        output,
        20,
        @as(f64, @floatFromInt(source_position.x)) + 0.5,
        @as(f64, @floatFromInt(source_position.y)) + 0.5,
    );
    pointerButton(output, 21, linux_button_left, .pressed);
    pointerFrame(output);
    try std.testing.expectEqual(exact_source, server.window_manager.focusedSurface().?);
    try std.testing.expectEqual(exact_source, server.seat.generatedKeyboardFocus().?.surface);

    try signalWayringCommand(source_fd);
    try waitForWayringXdgStage(server, host, &source, .token_ready);
    try std.testing.expect(source.pointer_button_serial != 0);
    inline for (.{ &exchange.token, &exchange.unauthorized_token }) |token| {
        try std.testing.expectEqual(@as(u8, 0), token[XdgActivation.token_character_count]);
        for (token[0..XdgActivation.token_character_count]) |character|
            try std.testing.expect(std.ascii.isDigit(character) or (character >= 'a' and character <= 'f'));
    }
    try std.testing.expect(!std.mem.eql(u8, &exchange.token, &exchange.unauthorized_token));

    server.window_manager.settleConfigureTransactionForTest();
    try signalWayringCommand(target_fd);
    try waitForWayringXdgStage(server, host, &target, .activated);
    try std.testing.expectEqual(exact_target, server.window_manager.focusedSurface().?);
    try std.testing.expectEqual(exact_target, server.seat.generatedKeyboardFocus().?.surface);
    try std.testing.expect(target.activated_configure_serial != target.initial_configure_serial);
    try std.testing.expect(target.activated_configure_serial != 0);
    try std.testing.expect(server.surface_registry.renderState(exact_source) != null);
    try std.testing.expect(server.surface_registry.renderState(exact_target) != null);

    try signalWayringCommand(source_fd);
    try waitForWayringXdgStage(server, host, &source, .source_left);
    server.window_manager.settleConfigureTransactionForTest();
    try std.testing.expectEqual(exact_target, server.scene.focusedSurface().?);
    try std.testing.expectEqual(source.surface_object_id, source.keyboard_leave_surface);
    try std.testing.expectEqual(target.surface_object_id, target.keyboard_enter_surface);

    try signalWayringCommand(target_fd);
    try waitForWayringXdgStage(server, host, &target, .invalids_checked);
    try std.testing.expectEqual(exact_target, server.window_manager.focusedSurface().?);
    try std.testing.expectEqual(exact_target, server.seat.generatedKeyboardFocus().?.surface);

    const raw_activation_offender_fd = linux.eventfd(0, linux.EFD.CLOEXEC);
    if (linux.errno(raw_activation_offender_fd) != .SUCCESS) return error.EventFdFailed;
    const activation_offender_fd: std.posix.fd_t = @intCast(raw_activation_offender_fd);
    defer _ = linux.close(activation_offender_fd);
    var activation_offender: WayringXdgClient = .{
        .runtime_directory = runtime_directory,
        .display_name = host.displayName(),
        .command_fd = activation_offender_fd,
        .offense = .activation_already_used,
    };
    const activation_offender_thread = try std.Thread.spawn(.{}, WayringXdgClient.run, .{&activation_offender});
    try waitForWayringXdgStage(server, host, &activation_offender, .disconnected);
    activation_offender_thread.join();
    for (0..1_000) |_| {
        if (host.connectionCount() == 2 and compositor.surfaceCount() == 2 and
            server.client_registry.len() == 2) break;
        try server.eventLoop().dispatch(1);
        if (host.failure()) |err| return err;
    } else return error.WayringActivationOffenderCleanupTimedOut;
    try std.testing.expectEqual(exact_target, server.window_manager.focusedSurface().?);
    try std.testing.expectEqual(WayringXdgClient.Stage.source_left, @as(WayringXdgClient.Stage, @enumFromInt(source.stage.load(.acquire))));
    try std.testing.expectEqual(WayringXdgClient.Stage.invalids_checked, @as(WayringXdgClient.Stage, @enumFromInt(target.stage.load(.acquire))));

    pointerButton(output, 22, linux_button_left, .released);
    pointerFrame(output);
    try signalWayringCommand(source_fd);
    try signalWayringCommand(target_fd);
    try waitForWayringXdgStage(server, host, &source, .disconnected);
    try waitForWayringXdgStage(server, host, &target, .disconnected);
    source_thread.join();
    source_joined = true;
    target_thread.join();
    target_joined = true;
    try waitForWayringDisconnect(server, host, &compositor);
    try std.testing.expectEqual(registry_baseline, server.surface_registry.len());
    try std.testing.expectEqual(@as(usize, 0), server.client_registry.len());
    try std.testing.expect(server.scene.topWindowSurface() == null);
    try std.testing.expect(server.seat.generatedKeyboardFocus() == null);

    const raw_rebind_fd = linux.eventfd(0, linux.EFD.CLOEXEC);
    if (linux.errno(raw_rebind_fd) != .SUCCESS) return error.EventFdFailed;
    const rebind_fd: std.posix.fd_t = @intCast(raw_rebind_fd);
    defer _ = linux.close(rebind_fd);
    var rebind: WayringXdgClient = .{ .runtime_directory = runtime_directory, .display_name = host.displayName(), .command_fd = rebind_fd, .registry_only = true };
    const rebind_thread = try std.Thread.spawn(.{}, WayringXdgClient.run, .{&rebind});
    var rebind_joined = false;
    defer if (!rebind_joined) {
        rebind.shutdown();
        rebind_thread.join();
    };
    try waitForWayringXdgStage(server, host, &rebind, .registry_ready);
    try std.testing.expectEqual(@as(usize, 7), lifecycle.accepted_count);
    try signalWayringCommand(rebind_fd);
    try waitForWayringXdgStage(server, host, &rebind, .disconnected);
    rebind_thread.join();
    rebind_joined = true;
    try waitForWayringDisconnect(server, host, &compositor);
    try std.testing.expect(host.failure() == null);
    try host.destroy();
    host_live = false;
}

test "production generated data device completes the exact profile and supports unpublish" {
    const WayringHost = @import("wayland/WayringHost.zig");
    const WayringIdleNotification = @import("wayland/WayringIdleNotification.zig");
    const WayringDataControl = @import("wayland/WayringDataControl.zig");
    const WayringTextInput = @import("wayland/WayringTextInput.zig");
    const WayringVirtualKeyboard = @import("wayland/WayringVirtualKeyboard.zig");
    const wayring = @import("wayring");
    const linux = std.os.linux;
    var marker: u8 = 0;
    const runtime_directory = try std.fmt.allocPrintSentinel(
        std.testing.allocator,
        "/tmp/keywork-wayring-data-profile-{d}-{x}",
        .{ linux.getpid(), @intFromPtr(&marker) },
        0,
    );
    defer std.testing.allocator.free(runtime_directory);
    if (linux.errno(linux.mkdir(runtime_directory.ptr, 0o700)) != .SUCCESS)
        return error.TestDirectoryCreationFailed;
    defer _ = linux.rmdir(runtime_directory.ptr);
    const previous_runtime = if (libc.getenv("XDG_RUNTIME_DIR")) |value|
        try std.testing.allocator.dupeZ(u8, std.mem.span(value))
    else
        null;
    defer {
        if (previous_runtime) |value| {
            _ = libc.setenv("XDG_RUNTIME_DIR", value, 1);
            std.testing.allocator.free(value);
        } else {
            _ = libc.unsetenv("XDG_RUNTIME_DIR");
        }
    }
    if (libc.setenv("XDG_RUNTIME_DIR", runtime_directory, 1) != 0)
        return error.RuntimeEnvironmentFailed;

    const server = try Self.createWithVirtualOutput(
        std.testing.allocator,
        std.testing.io,
        .cpu,
        .headless,
        null,
        .{ .size = .{ .width = 640, .height = 480 }, .refresh_millihertz = 1 },
    );
    defer server.destroy();
    const output = server.primaryRenderOutput();
    const mature_socket_name = try server.listen();
    const keymap_fd = try std.posix.memfd_create("keywork-mixed-clipboard-keymap", linux.MFD.CLOEXEC);
    const keymap = "keymap\x00\x00";
    if (linux.errno(linux.ftruncate(keymap_fd, keymap.len)) != .SUCCESS)
        return error.KeymapResizeFailed;
    if (std.c.pwrite(keymap_fd, keymap.ptr, keymap.len, 0) != keymap.len)
        return error.KeymapWriteFailed;
    server.seat.setKeymap(.xkb_v1, keymap_fd, keymap.len);
    server.seat.setRepeatInfo(0, 500);
    server.seat.setKeyboardAvailable(true);
    server.seat.setPointerAvailable(true);
    const client_baseline = server.client_registry.len();
    const surface_baseline = server.surface_registry.len();
    const mature_surface_baseline = server.compositor.surfaceStore().len();
    const forest_baseline = server.headless_surface_forest.len();
    const resource_baseline = server.dataDeviceResourceSnapshot();

    var protocol_server: wayring.server.Server = .init(std.testing.allocator);
    defer protocol_server.deinit();
    var clients: WayringClients = undefined;
    clients.init(std.testing.allocator, server.clientRegistry());
    defer clients.deinit();
    var compositor: WayringCompositor = undefined;
    try compositor.init(
        std.testing.allocator,
        &protocol_server,
        server.surfaceRegistry(),
        server.wayringPresentationListener(),
    );
    defer compositor.deinit();
    var seat: WayringSeatAdapter = .init(
        std.testing.allocator,
        &protocol_server,
        &clients,
        &compositor,
        server.generatedSeatRequestSink(),
        server.generatedSeatName(),
    );
    defer seat.deinit();
    server.setGeneratedSeatDeliverySink(seat.sink());
    defer server.clearGeneratedSeatDeliverySink(&seat);
    try seat.publish();
    defer seat.unpublish();
    var outputs: WayringOutput = undefined;
    try outputs.init(
        std.testing.allocator,
