        server.generatedCursorShape(),
        server.generatedSeatRequestSink(),
    );
    defer cursor_shape.deinit();
    try cursor_shape.publish();
    defer cursor_shape.unpublish();
    var decoration: WayringXdgDecoration = undefined;
    decoration.init(std.testing.allocator, &protocol_server, &xdg, server.neutralXdgShell());
    defer decoration.deinit();
    try decoration.publish();
    defer decoration.unpublish();
    var activation: WayringXdgActivation = undefined;
    activation.init(std.testing.allocator, &protocol_server, &seat, &xdg, server.xdgActivationOwner());
    defer activation.deinit();
    try activation.publish();
    defer activation.unpublish();

    var data_device: WayringDataDevice = undefined;
    data_device.init(
        std.testing.allocator,
        &protocol_server,
        &clients,
        &seat,
        server.neutralDataDevice(),
        &compositor,
    );
    defer {
        if (data_device.global != null) data_device.unpublish();
        data_device.deinit();
    }
    server.setDataDeviceObserver(.{
        .context = &data_device,
        .transaction_finalize = WayringDataDevice.transactionFinalize,
        .transaction_commit = WayringDataDevice.transactionCommit,
        .transaction_abort = WayringDataDevice.transactionAbort,
        .offer_rolled_back = WayringDataDevice.offerRolledBack,
        .offer_mime_offered = WayringDataDevice.offerMimeOffered,
        .offer_source_actions_preflight = WayringDataDevice.offerSourceActionsPreflight,
        .offer_source_actions_changed = WayringDataDevice.offerSourceActionsChanged,
        .offer_action_preflight = WayringDataDevice.offerActionPreflight,
        .offer_action_changed = WayringDataDevice.offerActionChanged,
    });
    defer server.setDataDeviceObserver(null);

    // Production publishes stateful data-device after its dependencies.
    try data_device.publish();
    var primary_selection: WayringPrimarySelection = undefined;
    primary_selection.init(
        std.testing.allocator,
        &protocol_server,
        &clients,
        &seat,
        server.neutralDataDevice(),
    );
    defer {
        if (primary_selection.global != null) primary_selection.unpublish();
        primary_selection.deinit();
    }
    server.setPrimarySelectionObserver(.{
        .context = &primary_selection,
        .transaction_finalize = WayringPrimarySelection.transactionFinalize,
        .transaction_commit = WayringPrimarySelection.transactionCommit,
        .transaction_abort = WayringPrimarySelection.transactionAbort,
        .selection_changed = WayringPrimarySelection.selectionChanged,
        .mime_offered = WayringPrimarySelection.mimeOffered,
        .offer_rolled_back = WayringPrimarySelection.offerRolledBack,
        .offer_mime_offered = WayringPrimarySelection.offerMimeOffered,
    });
    defer server.setPrimarySelectionObserver(null);
    try primary_selection.publish();
    var text_input: WayringTextInput = undefined;
    text_input.init(
        std.testing.allocator,
        &protocol_server,
        &clients,
        &seat,
        &compositor,
        server.neutralTextInput(),
    );
    defer {
        if (text_input.global != null) text_input.unpublish();
        text_input.deinit();
    }
    try text_input.publish();
    var data_control: WayringDataControl = undefined;
    data_control.init(
        std.testing.allocator,
        &protocol_server,
        &clients,
        &seat,
        server.neutralDataDevice(),
        linux.getuid(),
    );
    defer {
        if (data_control.global != null) data_control.unpublish();
        data_control.deinit();
    }
    protocol_server.setGlobalFilter(WayringDataControl, &data_control, WayringDataControl.globalFilter);
    defer protocol_server.clearGlobalFilter();
    server.setDataControlObserver(.{
        .context = &data_control,
        .transaction_finalize = WayringDataControl.transactionFinalize,
        .transaction_commit = WayringDataControl.transactionCommit,
        .transaction_abort = WayringDataControl.transactionAbort,
        .offer_rolled_back = WayringDataControl.offerRolledBack,
        .offer_mime_offered = WayringDataControl.offerMimeOffered,
    });
    defer server.setDataControlObserver(null);
    // Restricted globals follow the public profile in deterministic owner
    // order: data control, then input method.
    try data_control.publish();
    var input_method: WayringInputMethod = undefined;
    input_method.init(
        std.testing.allocator,
        &protocol_server,
        &clients,
        &seat,
        server.canonicalSeat(),
        server.neutralTextInput(),
        &compositor,
        linux.getuid(),
        server.generatedInputMethodLayout(),
    );
    defer {
        server.setGeneratedInputMethodObserver(null);
        if (input_method.global != null) input_method.unpublish();
        input_method.deinit();
    }
    server.setGeneratedInputMethodObserver(.{
        .context = &input_method,
        .set_inhibited = WayringInputMethod.observerSetInhibited,
        .send_popup_rectangle = WayringInputMethod.observerSendPopupRectangle,
        .refresh_popups = WayringInputMethod.observerRefreshPopups,
    });
    try input_method.publish();
    var virtual_keyboard: WayringVirtualKeyboard = undefined;
    virtual_keyboard.init(
        std.testing.allocator,
        &protocol_server,
        &seat,
        server.canonicalSeat(),
        linux.getuid(),
    );
    defer {
        if (virtual_keyboard.global != null) virtual_keyboard.unpublish();
        virtual_keyboard.deinit();
    }
    var layer_shell: WayringLayerShell = undefined;
    layer_shell.init(
        std.testing.allocator,
        &protocol_server,
        &clients,
        &compositor,
        &outputs,
        &xdg,
        server.sharedLayerPolicy(),
        server.neutralLayerShell(),
    );
    defer {
        if (layer_shell.global != null) layer_shell.unpublish();
        layer_shell.deinit();
    }
    var session_lock: WayringSessionLock = undefined;
    session_lock.init(std.testing.allocator, &protocol_server, &clients, &compositor, &outputs, server.neutralSessionLock(), linux.getuid());
    defer {
        if (session_lock.global != null) session_lock.unpublish();
        session_lock.deinit();
    }
    var idle_notify: WayringIdleNotification = undefined;
    idle_notify.init(
        std.testing.allocator,
        &protocol_server,
        &clients,
        &seat,
        NeutralIdleNotification.SeatRef.fromPointer(server.canonicalSeat()),
        server.neutralIdleNotification(),
        .{ .context = server, .failed = Self.idleNotificationFrontendFailed },
    );
    defer {
        if (idle_notify.global != null) idle_notify.unpublish();
        idle_notify.deinit();
    }
    var generated_workspace: WayringWorkspace = undefined;
    generated_workspace.init(
        std.testing.allocator,
        &protocol_server,
        &clients,
        &outputs,
        server.neutralWorkspace(),
        linux.getuid(),
    );
    defer {
        if (generated_workspace.global != null) generated_workspace.unpublish();
        generated_workspace.deinit();
    }

    const Lifecycle = struct {
        const FatalEvidence = struct {
            kind: wayring.server.Fatal.Kind,
            transport_provenance: wayring.server.Client.TransportProvenance,
            object_id: u32,
            opcode: ?u16,
            protocol_code: ?u32,
            interface: ?*const wayring.wire.Interface,
            message: ?*const wayring.wire.MessageDescriptor,
            detail_buffer: [wayring.server.Fatal.max_detail_len]u8 = undefined,
            detail_len: usize = 0,

            fn detail(self: *const @This()) []const u8 {
                return self.detail_buffer[0..self.detail_len];
            }
        };

        clients: *WayringClients,
        compositor: *WayringCompositor,
        outputs: *WayringOutput,
        seat: *WayringSeatAdapter,
        xdg: *WayringXdgShell,
        viewporter: *WayringViewporter,
        fractional_scale: *WayringFractionalScale,
        cursor_shape: *WayringCursorShape,
        decoration: *WayringXdgDecoration,
        activation: *WayringXdgActivation,
        data_device: *WayringDataDevice,
        primary_selection: *WayringPrimarySelection,
        text_input: *WayringTextInput,
        data_control: *WayringDataControl,
        input_method: *WayringInputMethod,
        virtual_keyboard: *WayringVirtualKeyboard,
        layer_shell: *WayringLayerShell,
        idle_notify: *WayringIdleNotification,
        session_lock: *WayringSessionLock,
        workspace: *WayringWorkspace,
        generated_client: ?ClientRegistry.Id = null,
        generated_raw: ?*wayring.server.Client = null,
        offender_fatal: ?FatalEvidence = null,
        denied_fatal: ?FatalEvidence = null,
        fatal_count: usize = 0,

        fn accepted(context: *anyopaque, client: *wayring.server.Client) !void {
            const self: *@This() = @ptrCast(@alignCast(context));
            const id = try self.clients.register(client);
            errdefer self.clients.unregister(client);
            // Derived transports participate in shared protocol cleanup but
            // must not replace the direct-client handle used by later phases.
            if (client.transportProvenance() == .direct) {
                self.generated_raw = client;
                self.generated_client = id;
            }
            try self.seat.trackClient(client);
        }
        fn destroy(context: *anyopaque, client: *wayring.server.Client) void {
            const self: *@This() = @ptrCast(@alignCast(context));
            self.workspace.destroyClientResources(client);
            self.idle_notify.destroyClientResources(client);
            self.session_lock.destroyClientResources(client);
            self.layer_shell.destroyClientResources(client);
            if (client.fatal()) |fatal| {
                const provenance = client.transportProvenance();
                const destination: ?*?FatalEvidence = if (provenance == .security_context)
                    &self.denied_fatal
                else if (fatal.kind == .implementation)
                    &self.offender_fatal
                else
                    null;
                if (fatal.kind == .implementation) self.fatal_count += 1;
                if (destination) |evidence_slot| if (evidence_slot.* == null) {
                    var evidence: FatalEvidence = .{
                        .kind = fatal.kind,
                        .transport_provenance = provenance,
                        .object_id = fatal.object_id,
                        .opcode = fatal.opcode,
                        .protocol_code = fatal.protocol_code,
                        .interface = fatal.interface,
                        .message = fatal.message,
                    };
                    const detail = fatal.detail();
                    @memcpy(evidence.detail_buffer[0..detail.len], detail);
                    evidence.detail_len = detail.len;
                    evidence_slot.* = evidence;
                };
            }
            self.virtual_keyboard.destroyClientResources(client);
            self.input_method.destroyClientResources(client);
            self.data_control.destroyClientResources(client);
            self.text_input.destroyClientResources(client);
            self.data_device.destroyClientResources(client);
            self.primary_selection.destroyClientResources(client);
            self.activation.destroyClientResources(client);
            self.decoration.destroyClientResources(client);
            self.cursor_shape.destroyClientResources(client);
            self.fractional_scale.destroyClientResources(client);
            self.viewporter.destroyClientResources(client);
            self.xdg.destroyClientResources(client);
            self.seat.destroyClientResources(client);
            self.outputs.destroyClientResources(client);
            self.compositor.destroyClientResources(client);
            if (self.generated_raw == client) self.generated_raw = null;
            if (self.clients.id(client) != null) self.clients.unregister(client);
        }
    };
    var lifecycle: Lifecycle = .{
        .clients = &clients,
        .compositor = &compositor,
        .outputs = &outputs,
        .seat = &seat,
        .xdg = &xdg,
        .viewporter = &viewporter,
        .fractional_scale = &fractional_scale,
        .cursor_shape = &cursor_shape,
        .decoration = &decoration,
        .activation = &activation,
        .data_device = &data_device,
        .primary_selection = &primary_selection,
        .text_input = &text_input,
        .data_control = &data_control,
        .input_method = &input_method,
        .virtual_keyboard = &virtual_keyboard,
        .layer_shell = &layer_shell,
        .idle_notify = &idle_notify,
        .session_lock = &session_lock,
        .workspace = &generated_workspace,
    };
    const GlobalFilter = struct {
        data_control: *WayringDataControl,
        workspace: *WayringWorkspace,
        fn visible(self: *@This(), client: *const wayring.server.Client, global: *const wayring.server.Server.Global) bool {
            return self.data_control.globalFilter(client, global) and self.workspace.globalFilter(client, global);
        }
    };
    var global_filter: GlobalFilter = .{ .data_control = &data_control, .workspace = &generated_workspace };
    protocol_server.setGlobalFilter(GlobalFilter, &global_filter, GlobalFilter.visible);
    defer protocol_server.clearGlobalFilter();
    const host = try WayringHost.create(
        std.testing.allocator,
        server.eventLoop(),
        &protocol_server,
        runtime_directory,
        .{
            .context = &lifecycle,
            .accepted = Lifecycle.accepted,
            .destroy_resources = Lifecycle.destroy,
        },
    );
    var host_live = true;
    defer if (host_live) host.destroy() catch {};
    try server.attachIdleAlarmHost(host);
    var idle_alarm_attached = true;
    defer if (idle_alarm_attached) server.detachIdleAlarmHost(host) catch {};

    const raw_command_fd = linux.eventfd(0, linux.EFD.CLOEXEC);
    if (linux.errno(raw_command_fd) != .SUCCESS) return error.EventFdFailed;
    const command_fd: std.posix.fd_t = @intCast(raw_command_fd);
    defer _ = linux.close(command_fd);
    var peer: WayringXdgClient = .{
        .runtime_directory = runtime_directory,
        .display_name = host.displayName(),
        .command_fd = command_fd,
        .registry_only = true,
        .registry_watch_data_device = true,
        .registry_watch_virtual_keyboard = true,
        .expect_text_input = true,
        .expect_data_control = true,
        .expect_input_method = true,
    };
    const thread = try std.Thread.spawn(.{}, WayringXdgClient.run, .{&peer});
    var joined = false;
    defer if (!joined) {
        peer.shutdown();
        thread.join();
    };
    try waitForWayringXdgStage(server, host, &peer, .registry_ready);
    try std.testing.expect(peer.globals_exact);
    try std.testing.expectEqual(peer.expectedGlobalCount(), peer.global_count);
    try std.testing.expectEqual(@as(usize, 1), peer.data_device_manager_count);
    try std.testing.expectEqual(@as(u32, 4), peer.data_device_manager_version);
    try std.testing.expectEqual(@as(usize, 1), peer.primary_selection_manager_count);
    try std.testing.expectEqual(@as(u32, 1), peer.primary_selection_manager_version);
    try std.testing.expectEqual(@as(usize, 1), peer.text_input_manager_count);
    try std.testing.expectEqual(@as(u32, 2), peer.text_input_manager_version);
    try std.testing.expectEqual(@as(usize, 1), peer.data_control_manager_count);
    try std.testing.expectEqual(@as(u32, 1), peer.data_control_manager_version);
    try std.testing.expectEqual(@as(usize, 1), peer.input_method_manager_count);
    try std.testing.expect(!peer.generated_virtual_keyboard_seen);
    try std.testing.expectEqual(client_baseline + 1, server.client_registry.len());

    peer.expect_virtual_keyboard = true;
    peer.expect_layer_shell = true;
    peer.expect_idle_notify = true;
    peer.expect_session_lock = true;
    peer.expect_workspace = true;
    try virtual_keyboard.publish();
    try layer_shell.publish();
    try session_lock.publish();
    try idle_notify.publish();
    try generated_workspace.publish();
    try signalWayringCommand(command_fd);
    try waitForWayringXdgStage(server, host, &peer, .manager_added);
    try std.testing.expect(peer.globals_exact);
    try std.testing.expect(peer.generated_virtual_keyboard_seen);
    try std.testing.expectEqual(@as(usize, 1), peer.virtual_keyboard_manager_count);
    try std.testing.expectEqual(@as(u32, 1), peer.virtual_keyboard_manager_version);
    try std.testing.expectEqual(WayringProfile.expectedCount(.presenting_headless, .direct), peer.global_count);
    try std.testing.expectEqual(@as(usize, 1), peer.layer_shell_count);
    try std.testing.expectEqual(@as(u32, 5), peer.layer_shell_version);
    try std.testing.expectEqual(@as(usize, 1), peer.idle_notifier_count);
    try std.testing.expectEqual(@as(u32, 2), peer.idle_notifier_version);
    try std.testing.expectEqual(@as(usize, 1), peer.session_lock_manager_count);
    try std.testing.expectEqual(@as(u32, 1), peer.session_lock_manager_version);
    try std.testing.expectEqual(@as(usize, 1), peer.workspace_manager_count);
    try std.testing.expectEqual(@as(u32, 1), peer.workspace_manager_version);
    try std.testing.expect(WayringProfile.validate(&protocol_server, .presenting_headless) == null);

    // Drive the scanner-generated manager with the same real libwayland
    // client fixture used for the mature frontend. Keep the registry peer
    // alive to verify an unrelated direct client survives the full lifecycle.
    const raw_workspace_command = linux.eventfd(0, linux.EFD.CLOEXEC);
    if (linux.errno(raw_workspace_command) != .SUCCESS) return error.EventFdFailed;
    const workspace_command: std.posix.fd_t = @intCast(raw_workspace_command);
    defer _ = linux.close(workspace_command);
    const registry_peer_raw = lifecycle.generated_raw;
    const registry_peer_id = lifecycle.generated_client;
    const workspace_binding_baseline = generated_workspace.bindings.items.len;
    const workspace_fd_baseline = try countMatureDataDeviceFds();
    var workspace_client: MatureWorkspaceClient = .{
        .runtime_directory = runtime_directory,
        .display_name = host.displayName(),
        .command_fd = workspace_command,
    };
    const workspace_thread = try std.Thread.spawn(.{}, MatureWorkspaceClient.run, .{&workspace_client});
    var workspace_joined = false;
    defer if (!workspace_joined) {
        workspace_client.shutdown();
        workspace_thread.join();
    };
