        output,
        302,
        @as(f64, @floatFromInt(generated_peer_position.x)) + 0.5,
        @as(f64, @floatFromInt(generated_peer_position.y)) + 0.5,
    );
    pointerFrame(output);
    try signalWayringCommand(generated_peer_command);
    try waitForWayringDndStage(server, host, &generated_peer, .events_drained);
    try signalWayringCommand(generated_source_command);
    try waitForWayringDndStage(server, host, &generated_source, .events_drained);
    try std.testing.expectEqualSlices(
        WayringDndClient.TargetEvent,
        &.{ .data_offer, .offer_mime, .source_actions, .action, .enter, .motion, .action },
        generated_peer.target_events[0..generated_peer.target_event_count],
    );
    try std.testing.expectEqualSlices(
        WayringDndClient.SourceEvent,
        &.{ .target, .action, .action, .target, .send },
        generated_source.events[0..generated_source.event_count],
    );
    try signalWayringCommand(generated_source_command);
    try waitForWayringDndStage(server, host, &generated_source, .transfer_sent);
    try std.testing.expectEqualSlices(
        WayringDndClient.SourceEvent,
        &.{ .target, .action, .action, .target, .send },
        generated_source.events[0..generated_source.event_count],
    );
    pointerButton(output, 303, linux_button_left, .released);
    pointerFrame(output);
    try signalWayringCommand(generated_peer_command);
    try waitForWayringDndStage(server, host, &generated_peer, .transfer_sent);
    try std.testing.expectEqualSlices(
        WayringDndClient.TargetEvent,
        &.{ .data_offer, .offer_mime, .source_actions, .action, .enter, .motion, .action, .drop, .leave },
        generated_peer.target_events[0..generated_peer.target_event_count],
    );
    try std.testing.expectEqualStrings(
        WayringDndClient.drag_bytes,
        generated_peer.received[0..generated_peer.received_len],
    );
    try signalWayringCommand(generated_source_command);
    try waitForWayringDndStage(server, host, &generated_source, .disconnected);
    generated_source_thread.join();
    generated_source_joined = true;
    try std.testing.expectEqualSlices(
        WayringDndClient.SourceEvent,
        &.{ .target, .action, .action, .target, .send, .drop_performed, .dnd_finished },
        generated_source.events[0..generated_source.event_count],
    );
    try signalWayringCommand(generated_peer_command);
    try waitForWayringDndStage(server, host, &generated_peer, .disconnected);
    generated_peer_thread.?.join();
    generated_peer_joined = true;
    for (0..2_000) |_| {
        const snapshot = server.dataDeviceResourceSnapshot();
        if (host.connectionCount() == 0 and server.client_registry.len() == client_baseline and
            server.surface_registry.len() == surface_baseline and
            server.headless_surface_forest.len() == forest_baseline and
            std.meta.eql(snapshot.neutral, resource_baseline.neutral) and
            !snapshot.dragging) break;
        try server.eventLoop().dispatch(1);
        server.display.flushClients();
        if (host.failure()) |err| return err;
    } else return error.GeneratedDndCleanupTimedOut;
    _ = linux.close(generated_source_command);
    _ = linux.close(generated_peer_command);
    generated_commands_open = false;
    try std.testing.expectEqual(fd_baseline, try countMatureDataDeviceFds());

    // The same generated roles also cover the two nullable start_drag
    // arguments. A source-less drag remains owner-confined; disabling only
    // the icon preserves the normal cross-client offer and transfer chronology.
    for ([_]struct { source_enabled: bool, icon_enabled: bool, expect_offer: bool, expect_target: bool }{
        // Canonical policy permits a null source but confines that drag to
        // its owner; the other generated client must receive no target state.
        .{ .source_enabled = false, .icon_enabled = false, .expect_offer = false, .expect_target = false },
        .{ .source_enabled = true, .icon_enabled = false, .expect_offer = true, .expect_target = true },
    }, 0..) |settings, phase| {
        const raw_source_fd = linux.eventfd(0, linux.EFD.CLOEXEC);
        const raw_target_fd = linux.eventfd(0, linux.EFD.CLOEXEC);
        if (linux.errno(raw_source_fd) != .SUCCESS or linux.errno(raw_target_fd) != .SUCCESS)
            return error.EventFdFailed;
        const source_fd: std.posix.fd_t = @intCast(raw_source_fd);
        const target_fd: std.posix.fd_t = @intCast(raw_target_fd);
        defer _ = linux.close(source_fd);
        defer _ = linux.close(target_fd);
        var source_client: WayringDndClient = .{
            .runtime_directory = runtime_directory,
            .display_name = host.displayName(),
            .command_fd = source_fd,
            .source_enabled = settings.source_enabled,
            .icon_enabled = settings.icon_enabled,
        };
        var target_client: WayringDndClient = .{
            .runtime_directory = runtime_directory,
            .display_name = host.displayName(),
            .command_fd = target_fd,
            .role = .target,
            .expect_offer = settings.expect_offer,
            .expect_target = settings.expect_target,
            .expected_bytes = WayringDndClient.drag_bytes,
        };
        const source_thread = try std.Thread.spawn(.{}, WayringDndClient.run, .{&source_client});
        var source_joined = false;
        var target_joined = false;
        var target_thread: ?std.Thread = null;
        defer if (!source_joined) {
            source_client.shutdown();
            source_thread.join();
        };
        defer if (!target_joined) if (target_thread) |peer_thread| {
            target_client.shutdown();
            peer_thread.join();
        };
        try waitForWayringDndStage(server, host, &source_client, .mapped);
        const source_surface = wayringSurfaceWithPixel(server, 0xff28_6498) orelse
            return error.GeneratedDndOriginMissing;
        try std.testing.expect(server.focusGeneratedSurface(source_surface));
        const source_position = server.scene.surfacePosition(source_surface) orelse
            return error.GeneratedDndOriginPositionMissing;
        const time: u32 = @intCast(400 + phase * 10);
        pointerMotion(
            output,
            time,
            @as(f64, @floatFromInt(source_position.x)) + 0.5,
            @as(f64, @floatFromInt(source_position.y)) + 0.5,
        );
        pointerButton(output, time + 1, linux_button_left, .pressed);
        pointerFrame(output);
        try signalWayringCommand(source_fd);
        try waitForWayringDndStage(server, host, &source_client, .pointer_button_ready);
        try signalWayringCommand(source_fd);
        try waitForWayringDndStage(server, host, &source_client, .drag_started);
        try std.testing.expect(server.neutralDataDevice().dragIcon() == null);
        server.window_manager.settleConfigureTransactionForTest();
        target_thread = try std.Thread.spawn(.{}, WayringDndClient.run, .{&target_client});
        try waitForWayringDndStage(server, host, &target_client, .mapped);
        server.window_manager.settleConfigureTransactionForTest();
        const target_raw_client = clients.rawClient(lifecycle.generated_client.?) orelse
            return error.GeneratedDndClientMissing;
        const target_surface = compositor.surfaceId(target_raw_client, target_client.origin_object_id) orelse
            return error.GeneratedDndTargetMissing;
        const target_position = server.scene.surfacePosition(target_surface) orelse
            return error.GeneratedDndTargetPositionMissing;
        pointerMotion(
            output,
            time + 2,
            @as(f64, @floatFromInt(target_position.x)) + 0.5,
            @as(f64, @floatFromInt(target_position.y)) + 0.5,
        );
        pointerFrame(output);
        try signalWayringCommand(source_fd);
        try signalWayringCommand(target_fd);
        try waitForWayringDndStage(server, host, &source_client, .events_drained);
        try waitForWayringDndStage(server, host, &target_client, .events_drained);
        if (settings.expect_offer) {
            try std.testing.expect(target_client.targetEventIndex(.data_offer) != null);
            try signalWayringCommand(source_fd);
            try waitForWayringDndStage(server, host, &source_client, .transfer_sent);
        } else {
            try std.testing.expect(target_client.offer == null);
            try std.testing.expect(target_client.targetEventIndex(.data_offer) == null);
            if (settings.expect_target)
                try std.testing.expectEqualSlices(
                    WayringDndClient.TargetEvent,
                    &.{ .enter, .motion },
                    target_client.target_events[0..target_client.target_event_count],
                )
            else
                try std.testing.expectEqual(@as(usize, 0), target_client.target_event_count);
            try signalWayringCommand(source_fd);
            try waitForWayringDndStage(server, host, &source_client, .transfer_sent);
        }
        pointerButton(output, time + 3, linux_button_left, .released);
        pointerFrame(output);
        try signalWayringCommand(target_fd);
        try waitForWayringDndStage(server, host, &target_client, .transfer_sent);
        if (settings.expect_offer) {
            try std.testing.expectEqualStrings(
                WayringDndClient.drag_bytes,
                target_client.received[0..target_client.received_len],
            );
        }
        try signalWayringCommand(source_fd);
        try waitForWayringDndStage(server, host, &source_client, .disconnected);
        source_thread.join();
        source_joined = true;
        try signalWayringCommand(target_fd);
        try waitForWayringDndStage(server, host, &target_client, .disconnected);
        target_thread.?.join();
        target_joined = true;
        for (0..2_000) |_| {
            const snapshot = server.dataDeviceResourceSnapshot();
            if (host.connectionCount() == 0 and server.client_registry.len() == client_baseline and
                server.surface_registry.len() == surface_baseline and
                server.headless_surface_forest.len() == forest_baseline and
                std.meta.eql(snapshot.neutral, resource_baseline.neutral) and
                !snapshot.dragging) break;
            try server.eventLoop().dispatch(1);
            server.display.flushClients();
            if (host.failure()) |err| return err;
        } else return error.NullableGeneratedDndCleanupTimedOut;
    }

    // Both frontends share one neutral Seat timeline and the host-owned
    // io_uring alarm. Their wire ordering is intentionally observed only per
    // resource: canonical physical pointer activity resumes each
    // independently. Run this timing phase after other production clients
    // disconnect so no paused test client accumulates unrelated Seat events.
    {
        const notification_baseline = server.idle_notification.len();
        const raw_generated_idle_command = linux.eventfd(0, linux.EFD.CLOEXEC);
        const raw_mature_idle_command = linux.eventfd(0, linux.EFD.CLOEXEC);
        if (linux.errno(raw_generated_idle_command) != .SUCCESS or
            linux.errno(raw_mature_idle_command) != .SUCCESS)
            return error.EventFdFailed;
        const generated_idle_command: std.posix.fd_t = @intCast(raw_generated_idle_command);
        const mature_idle_command: std.posix.fd_t = @intCast(raw_mature_idle_command);
        defer _ = linux.close(generated_idle_command);
        defer _ = linux.close(mature_idle_command);
        var generated_idle: MatureIdleNotifyClient = .{
            .runtime_directory = runtime_directory,
            .display_name = host.displayName(),
            .command_fd = generated_idle_command,
            .timeout_ms = 0,
        };
        var mature_idle: MatureIdleNotifyClient = .{
            .runtime_directory = runtime_directory,
            .display_name = mature_socket_name,
            .command_fd = mature_idle_command,
        };
        const generated_idle_thread = try std.Thread.spawn(.{}, MatureIdleNotifyClient.run, .{&generated_idle});
        const mature_idle_thread = try std.Thread.spawn(.{}, MatureIdleNotifyClient.run, .{&mature_idle});
        var generated_idle_joined = false;
        var mature_idle_joined = false;
        defer if (!generated_idle_joined) {
            generated_idle.shutdown();
            generated_idle_thread.join();
        };
        defer if (!mature_idle_joined) {
            mature_idle.shutdown();
            mature_idle_thread.join();
        };
        try waitForMatureIdleNotifyStage(server, &generated_idle, .idled);
        try waitForMatureIdleNotifyStage(server, &mature_idle, .idled);
        try std.testing.expectEqual(notification_baseline + 2, server.idle_notification.len());
        try std.testing.expectEqual(@as(u8, 1), generated_idle.idled_count);
        try std.testing.expectEqual(@as(u8, 1), mature_idle.idled_count);

        pointerMotion(output, 401, 0.5, 0.5);
        pointerFrame(output);
        try signalWayringCommand(generated_idle_command);
        try signalWayringCommand(mature_idle_command);
        try waitForMatureIdleNotifyStage(server, &generated_idle, .resumed);
        try waitForMatureIdleNotifyStage(server, &mature_idle, .resumed);
        try std.testing.expectEqual(@as(u8, 1), generated_idle.resumed_count);
        try std.testing.expectEqual(@as(u8, 1), mature_idle.resumed_count);

        try signalWayringCommand(generated_idle_command);
        try signalWayringCommand(mature_idle_command);
        try waitForMatureIdleNotifyStage(server, &generated_idle, .reidled);
        try waitForMatureIdleNotifyStage(server, &mature_idle, .reidled);
        try std.testing.expectEqual(@as(u8, 2), generated_idle.idled_count);
        try std.testing.expectEqual(@as(u8, 2), mature_idle.idled_count);

        try signalWayringCommand(generated_idle_command);
        try signalWayringCommand(mature_idle_command);
        try waitForMatureIdleNotifyStage(server, &generated_idle, .destroyed);
        try waitForMatureIdleNotifyStage(server, &mature_idle, .destroyed);
        try std.testing.expectEqual(notification_baseline, server.idle_notification.len());
        try signalWayringCommand(generated_idle_command);
        try signalWayringCommand(mature_idle_command);
        try waitForMatureIdleNotifyStage(server, &generated_idle, .disconnected);
        try waitForMatureIdleNotifyStage(server, &mature_idle, .disconnected);
        generated_idle_thread.join();
        generated_idle_joined = true;
        mature_idle_thread.join();
        mature_idle_joined = true;
        try waitForWayringDisconnect(server, host, &compositor);
        try std.testing.expectEqual(notification_baseline, server.idle_notification.len());
        try std.testing.expectEqual(@as(usize, 0), host.connectionCount());
    }
    for (0..1_000) |_| {
        if (try countMatureDataDeviceFds() == fd_baseline) break;
        try server.eventLoop().dispatch(1);
        server.display.flushClients();
        if (host.failure()) |err| return err;
    } else return error.IdleNotificationCleanupTimedOut;

    const final = server.dataDeviceResourceSnapshot();
    try std.testing.expect(final.selection_generation >= resource_baseline.selection_generation);
    try std.testing.expect(server.scene.topWindowSurface() == null);
    try std.testing.expect(server.seat.generatedKeyboardFocus() == null);
    try std.testing.expect(server.seat.matureKeyboardFocus() == null);
    try std.testing.expectEqual(fd_baseline, try countMatureDataDeviceFds());
    data_device.unpublish();

    // A host transport failure is compositor-fatal even when the alarm it
    // cancels belongs only to a mature client. Otherwise the shared neutral
    // scheduler would remain attached to a permanently shutting-down host.
    const raw_fault_command = linux.eventfd(0, linux.EFD.CLOEXEC);
    if (linux.errno(raw_fault_command) != .SUCCESS) return error.EventFdFailed;
    const fault_command: std.posix.fd_t = @intCast(raw_fault_command);
    defer _ = linux.close(fault_command);
    const notification_baseline = server.idle_notification.len();
    var fault_client: MatureIdleNotifyClient = .{
        .runtime_directory = runtime_directory,
        .display_name = mature_socket_name,
        .command_fd = fault_command,
        .timeout_ms = std.math.maxInt(u32),
        .pause_after_create = true,
    };
    const fault_thread = try std.Thread.spawn(.{}, MatureIdleNotifyClient.run, .{&fault_client});
    var fault_joined = false;
    defer if (!fault_joined) {
        fault_client.shutdown();
        fault_thread.join();
    };
    try waitForMatureIdleNotifyStage(server, &fault_client, .created);
    try std.testing.expectEqual(notification_baseline + 1, server.idle_notification.len());
    try std.testing.expectEqual(@as(usize, 0), server.termination_requests);
    host.failForTesting(error.InjectedIdleAlarmTransportFailure);
    host.failForTesting(error.RepeatedIdleAlarmTransportFailure);
    try std.testing.expectEqual(@as(usize, 1), server.termination_requests);
    try std.testing.expectEqual(error.InjectedIdleAlarmTransportFailure, host.failure().?);
    fault_client.shutdown();
    fault_thread.join();
    fault_joined = true;
    for (0..2_000) |_| {
        if (server.idle_notification.len() == notification_baseline) break;
        try server.eventLoop().dispatch(1);
        server.display.flushClients();
    } else return error.MatureIdleNotifyFaultCleanupTimedOut;

    server.shutdownIdleAlarmHost(host);
    idle_alarm_attached = false;
    try std.testing.expectError(error.InjectedIdleAlarmTransportFailure, host.destroy());
    host_live = false;
    // Client/session teardown can still update canonical inhibition after the
    // native transport is gone; it must use the mature fallback, never host.
    server.setIdleInhibited(true);
    server.setIdleInhibited(false);
    try std.testing.expectEqual(@as(usize, 1), server.termination_requests);
}

test "production Wayring seat global accepts canonical input through the real host" {
    const WayringHost = @import("wayland/WayringHost.zig");
    const wayring = @import("wayring");
    const linux = std.os.linux;
    var marker: u8 = 0;
    const runtime_directory = try std.fmt.allocPrintSentinel(
        std.testing.allocator,
        "/tmp/keywork-wayring-seat-{d}-{x}",
        .{ linux.getpid(), @intFromPtr(&marker) },
        0,
    );
    defer std.testing.allocator.free(runtime_directory);
    if (linux.errno(linux.mkdir(runtime_directory.ptr, 0o700)) != .SUCCESS)
        return error.TestDirectoryCreationFailed;
    defer _ = linux.rmdir(runtime_directory.ptr);

    const server = try Self.createWithVirtualOutput(
        std.testing.allocator,
        std.testing.io,
        .cpu,
        .headless,
        null,
        .{
            .size = .{ .width = 4, .height = 4 },
            .refresh_millihertz = 1,
        },
    );
    var server_live = true;
    defer if (server_live) server.destroy();
    const output = server.primaryRenderOutput();
    const registry_baseline = server.surface_registry.len();
    try std.testing.expectEqual(@as(usize, 0), registry_baseline);

    const keymap_fd = try std.posix.memfd_create("keywork-wayring-keymap", linux.MFD.CLOEXEC);
    const keymap = "keymap\x00\x00";
    if (linux.errno(linux.ftruncate(keymap_fd, keymap.len)) != .SUCCESS)
        return error.KeymapResizeFailed;
    if (std.c.pwrite(keymap_fd, keymap.ptr, keymap.len, 0) != keymap.len)
        return error.KeymapWriteFailed;
    server.seat.setKeymap(.xkb_v1, keymap_fd, keymap.len);
    server.seat.setRepeatInfo(0, 500);
    server.seat.setKeyboardAvailable(true);
    server.seat.setPointerAvailable(true);
    server.seat.setTouchAvailable(true);

    var protocol_server: wayring.server.Server = .init(std.testing.allocator);
    var protocol_server_live = true;
    defer if (protocol_server_live) protocol_server.deinit();
    var clients: WayringClients = undefined;
    clients.init(std.testing.allocator, server.clientRegistry());
    var clients_live = true;
    defer if (clients_live) clients.deinit();
    var compositor: WayringCompositor = undefined;
    try compositor.init(
        std.testing.allocator,
        &protocol_server,
        server.surfaceRegistry(),
        server.wayringPresentationListener(),
    );
    var compositor_live = true;
    defer if (compositor_live) compositor.deinit();
    var seat_adapter: WayringSeatAdapter = .init(
        std.testing.allocator,
        &protocol_server,
        &clients,
        &compositor,
        server.generatedSeatRequestSink(),
        server.generatedSeatName(),
    );
    var seat_adapter_live = true;
    var seat_published = false;
    var seat_sink_installed = false;
    var cursor_listener_installed = false;
    defer if (seat_adapter_live) {
        if (seat_published) seat_adapter.unpublish();
        if (seat_sink_installed) server.clearGeneratedSeatDeliverySink(&seat_adapter);
        if (cursor_listener_installed) seat_adapter.clearCursorListener();
        seat_adapter.deinit();
    };
    seat_adapter.installCursorListener();
    cursor_listener_installed = true;
    server.setGeneratedSeatDeliverySink(seat_adapter.sink());
    seat_sink_installed = true;
    try seat_adapter.publish();
    seat_published = true;
    var wayring_outputs: WayringOutput = undefined;
    try wayring_outputs.init(
        std.testing.allocator,
        &protocol_server,
        server.wayringOutputLayout().?,
        &compositor,
    );
    var outputs_live = true;
    defer if (outputs_live) wayring_outputs.deinit();
    server.generatedCursorShape().setForceFallback(true);
    var cursor_shape: WayringCursorShape = undefined;
    cursor_shape.init(
        std.testing.allocator,
        &protocol_server,
        &seat_adapter,
        server.generatedCursorShape(),
        server.generatedSeatRequestSink(),
    );
    var cursor_shape_live = true;
    defer if (cursor_shape_live) {
        cursor_shape.unpublish();
        cursor_shape.deinit();
    };
    try cursor_shape.publish();

    const Lifecycle = struct {
        clients: *WayringClients,
        outputs: *WayringOutput,
        cursor_shape: *WayringCursorShape,
        compositor: *WayringCompositor,
        seat: *WayringSeatAdapter,
        ids: [2]ClientRegistry.Id = undefined,
        accepted_count: usize = 0,

        fn accepted(context: *anyopaque, client: *wayring.server.Client) !void {
            const self: *@This() = @ptrCast(@alignCast(context));
            const client_id = try self.clients.register(client);
            errdefer self.clients.unregister(client);
            try self.seat.trackClient(client);
            std.debug.assert(self.accepted_count < self.ids.len);
            self.ids[self.accepted_count] = client_id;
            self.accepted_count += 1;
        }

        fn destroy(context: *anyopaque, client: *wayring.server.Client) void {
            const self: *@This() = @ptrCast(@alignCast(context));
            self.cursor_shape.destroyClientResources(client);
            self.seat.destroyClientResources(client);
            self.outputs.destroyClientResources(client);
            self.compositor.destroyClientResources(client);
            if (self.clients.id(client) != null) self.clients.unregister(client);
        }
    };
    var lifecycle: Lifecycle = .{
        .clients = &clients,
        .outputs = &wayring_outputs,
        .cursor_shape = &cursor_shape,
        .compositor = &compositor,
        .seat = &seat_adapter,
    };
    const host = try WayringHost.create(
        std.testing.allocator,
        server.eventLoop(),
        &protocol_server,
        runtime_directory,
        .{
            .context = &lifecycle,
            .accepted = Lifecycle.accepted,
            .destroy_resources = Lifecycle.destroy,
        },
    );
    var host_live = true;
    defer if (host_live) host.destroy() catch {};

    const raw_command_fd = linux.eventfd(0, linux.EFD.CLOEXEC);
    if (linux.errno(raw_command_fd) != .SUCCESS) return error.EventFdFailed;
    const command_fd: std.posix.fd_t = @intCast(raw_command_fd);
    defer _ = linux.close(command_fd);
    var client: WayringSeatClient = .{
        .runtime_directory = runtime_directory,
        .display_name = host.displayName(),
        .command_fd = command_fd,
    };
    const thread = try std.Thread.spawn(.{}, WayringSeatClient.run, .{&client});
    var joined = false;
    defer if (!joined) {
        client.shutdown();
        thread.join();
    };

    try waitForWayringSeatStage(server, host, &client, .ready);
    try std.testing.expectEqual(@as(usize, 1), lifecycle.accepted_count);
    try std.testing.expectEqual(@as(usize, 1), server.client_registry.len());
    try std.testing.expectEqual(@as(usize, 2), compositor.surfaceCount());
    try std.testing.expectEqual(@as(usize, 2), server.headless_surface_forest.len());
    const root = server.headless_surface_forest.rootAt(0).?.id;

    keyboardEnter(output, &.{30});
    pointerMotion(output, 1, 0.25, 0.25);
    pointerMotion(output, 2, 0.75, 0.75);
    pointerButton(output, 3, linux_button_left, .pressed);
    pointerFrame(output);
    try signalWayringCommand(command_fd);
    try waitForWayringSeatStage(server, host, &client, .shape_ready);
    const shape_info = server.seat.cursorInfo() orelse return error.GeneratedShapeMissing;
    const shape_source = switch (shape_info) {
        .shape => |shape| shape.buffer.source_cache orelse return error.GeneratedShapeCacheMissing,
        .surface, .generated => return error.UnexpectedCursorOwner,
    };
    try std.testing.expectEqual(@as(i32, 0), shape_info.shape.x);
    try std.testing.expectEqual(@as(i32, 0), shape_info.shape.y);
    const previous_cursor_frames = output.frame_statistics.frames_presented;
    try renderPendingWayringFrame(server, host, previous_cursor_frames);
    const cursor_target = switch (output.backend.acquire().?) {
        .pixels => |pixels| pixels,
        else => return error.ExpectedCpuHeadlessTarget,
    };
    try std.testing.expectEqual(@as(u32, 0xff00_0000), cursor_target.pixels[0]);
    try std.testing.expectEqual(@as(u32, 0xffff_ffff), cursor_target.pixels[5]);

    try signalWayringCommand(command_fd);
    try waitForWayringSeatStage(server, host, &client, .stale_shape_ignored);
    switch (server.seat.cursorInfo() orelse return error.GeneratedShapeMissing) {
        .shape => |shape| try std.testing.expectEqual(shape_source, shape.buffer.source_cache.?),
        .surface, .generated => return error.UnexpectedCursorOwner,
    }

    try signalWayringCommand(command_fd);
    try waitForWayringSeatStage(server, host, &client, .cursor_ready);
    switch (server.seat.cursorInfo() orelse return error.GeneratedCursorMissing) {
        .generated => |cursor| {
            try std.testing.expectEqual(@as(i32, -1), cursor.x);
            try std.testing.expectEqual(@as(i32, -1), cursor.y);
        },
        .surface, .shape => return error.UnexpectedCursorOwner,
    }

    try signalWayringCommand(command_fd);
    try waitForWayringSeatStage(server, host, &client, .cursor_cleared);
    try std.testing.expect(server.seat.cursorInfo() == null);

    touchDown(output, 4, 7, 0.5, 0.5);
    try signalWayringCommand(command_fd);
    try waitForWayringSeatStage(server, host, &client, .cursor_and_late_touch_ready);

    keyboardModifiers(output, 1, 2, 4, 3);
    keyboardKey(output, 5, 30, .repeated);
    keyboardKey(output, 6, 30, .released);
    pointerButton(output, 7, linux_button_left, .released);
    pointerFrame(output);
    pointerMotion(output, 8, 3, 3);
    pointerFrame(output);
    pointerMotion(output, 9, 0.25, 0.25);
    pointerFrame(output);
    server.applyMatureKeyboardFocus(null);
    try std.testing.expect(server.focusGeneratedSurface(root));
    touchShape(output, 7, 2, 1);
    touchOrientation(output, 7, 0.5);
    touchMotion(output, 10, 7, 0.75, 0.75);
    touchFrame(output);
    touchUp(output, 11, 7);
    touchFrame(output);
    touchDown(output, 12, 8, 0.5, 0.5);
    touchCancel(output);
    touchFrame(output);
    try signalWayringCommand(command_fd);
    try waitForWayringSeatStage(server, host, &client, .resources_released);
    try std.testing.expectEqual(@as(usize, 1), server.client_registry.len());
    try std.testing.expectEqual(@as(usize, 2), compositor.surfaceCount());
    try std.testing.expect(server.seat.generatedKeyboardFocus() != null);
    try std.testing.expect(server.seat.pointerFocus().?.generated != null);

    try signalWayringCommand(command_fd);
    try waitForWayringSeatStage(server, host, &client, .disconnected);
    thread.join();
    joined = true;
    try waitForWayringDisconnect(server, host, &compositor);
    try std.testing.expectEqual(@as(usize, 0), server.client_registry.len());
    try std.testing.expect(server.seat.generatedKeyboardFocus() == null);
    try std.testing.expect(server.seat.pointerFocus() == null);
    if (server.seat.cursorInfo()) |cursor| switch (cursor) {
        .generated => return error.StaleGeneratedCursor,
        .surface, .shape => {},
    };
    try std.testing.expect(!server.seat.touchSequenceActive());

    const raw_reconnect_fd = linux.eventfd(0, linux.EFD.CLOEXEC);
    if (linux.errno(raw_reconnect_fd) != .SUCCESS) return error.EventFdFailed;
    const reconnect_fd: std.posix.fd_t = @intCast(raw_reconnect_fd);
    defer _ = linux.close(reconnect_fd);
    var reconnect: WayringSeatClient = .{
        .runtime_directory = runtime_directory,
        .display_name = host.displayName(),
        .command_fd = reconnect_fd,
        .registry_only = true,
    };
    const reconnect_thread = try std.Thread.spawn(.{}, WayringSeatClient.run, .{&reconnect});
    var reconnect_joined = false;
    defer if (!reconnect_joined) {
        reconnect.shutdown();
        reconnect_thread.join();
    };
    try waitForWayringSeatStage(server, host, &reconnect, .registry_ready);
    try std.testing.expectEqual(@as(usize, 2), lifecycle.accepted_count);
    try std.testing.expectEqual(lifecycle.ids[0].index, lifecycle.ids[1].index);
    try std.testing.expect(lifecycle.ids[0].generation != lifecycle.ids[1].generation);
    try std.testing.expectEqual(@as(usize, 1), server.client_registry.len());
    try signalWayringCommand(reconnect_fd);
    try waitForWayringSeatStage(server, host, &reconnect, .disconnected);
    reconnect_thread.join();
    reconnect_joined = true;
    try waitForWayringDisconnect(server, host, &compositor);
    try std.testing.expect(host.failure() == null);
    try std.testing.expectEqual(@as(usize, 0), server.client_registry.len());

    try host.destroy();
    host_live = false;
    cursor_shape.unpublish();
    cursor_shape.deinit();
    cursor_shape_live = false;
    wayring_outputs.deinit();
    outputs_live = false;
    seat_adapter.unpublish();
    seat_published = false;
    server.clearGeneratedSeatDeliverySink(&seat_adapter);
    seat_sink_installed = false;
    seat_adapter.clearCursorListener();
    cursor_listener_installed = false;
    seat_adapter.deinit();
    seat_adapter_live = false;
    clients.deinit();
    clients_live = false;
    compositor.deinit();
    compositor_live = false;
    protocol_server.deinit();
    protocol_server_live = false;
    try std.testing.expectEqual(registry_baseline, server.surface_registry.len());
    server.destroy();
    server_live = false;
}
